# cross_view) เดิมเชื่อค่า height_px ที่มาจาก "direct" fit เสมอ โดยไม่สนใจว่า fit นั้นมีจุดข้อมูล
# (n_samples) มากพอจะเชื่อถือได้หรือไม่ - พบว่าไฟล์ AA05-03 BACK idx4 (คอลัมน์ขวาสุด) วัดความสูงได้
