# _detect_hidden_behind_split - พบจริงจาก RD01-01 false-positive vs EE03-01 true-positive)
_HIDDEN_BEHIND_DOWN_MIN_SNR = 15.0  # อยู่กึ่งกลาง (geometric mean) ระหว่าง RD01-01=4.2 (ต้อง
