# กลไกนี้) มี "4 สี SKU ปะปนกัน" ที่ BACK idx5 - ดังนั้นเกณฑ์ >=4 ยังคง flag EC04-02 ได้ถูกต้อง
# เหมือนเดิมทุกประการ ในขณะที่ตัดกรณี 3 สีของ EB66-01 ออกไป (ห่างกันพอดี 1 สี แยก 2 กรณีนี้ได้)
