# jump ได้เองอยู่แล้วโดยไม่ต้อง suppress จากภายนอกเลย)
# FIX: เพิ่มเงื่อนไข AND - suppress เฉพาะเมื่อมี jump จริง "และ" n_samples ของคอลัมน์นั้นต่ำกว่า
# เกณฑ์นี้ด้วย (บ่งชี้ว่าข้อมูลที่เหลือหลังกรอง jump ไม่พอจะเชื่อถือได้จริง เหมือนกับหลักการเดียวกับ
# v25.84's _APEX_PARTIAL_CUT_MIN_SAMPLES) - ถ้า n_samples สูงพอ (>=25, เกณฑ์เดียวกับ
# STEP_DOWN_MIN_RELIABLE_SAMPLES ที่ใช้ทั่วระบบอยู่แล้ว) ให้เชื่อว่า robust-fit จัดการได้เอง ไม่ต้อง
# suppress เพิ่มเติม - ยืนยันแยกแยะ 2 กรณีนี้ได้ถูกต้อง 100% (EA03-01 n=3 < 25 -> suppress ตามเดิม,
# AC03-02 n=57 >= 25 -> ไม่ suppress อีกต่อไป)
_INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES = 25


def _recheck_stack_height_via_color(view_result, x_range, expected_color,
                                     margin=_RECHECK_COLOR_MARGIN_PX,
                                     min_points=_RECHECK_COLOR_MIN_POINTS,
                                     max_resid_std=_RECHECK_COLOR_MAX_RESID_STD):
    """ตรวจสอบซ้ำ (recheck) ความสูงของคอลัมน์ที่ตำแหน่ง x_range โดยกรองเฉพาะ pixel ที่สีตรงกับ
    expected_color เท่านั้น (สแกนทั้งความกว้างคอลัมน์ หาจุดบนสุดที่สีตรงในแต่ละ x แล้ว fit เส้นตรง
    ทนทาน - เทคนิคเดียวกับ _scan_full_column ใน detect_step_down_topface_jump) คืนค่า
    (height_px, n_points, resid_std) ถ้า fit น่าเชื่อถือ หรือ None ถ้าไม่พอจะเชื่อผล (fail-safe)
    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก AB03-04)"""
    region = view_result.get("region")
    cargo_mask = view_result.get("cargo_mask")
    local_floor_y = view_result.get("local_floor_y")
    if region is None or cargo_mask is None or local_floor_y is None:
        return None
    norm_expected = _stack_color_normalize(np.array(expected_color, dtype=np.float64))
    if norm_expected is None:
        return None
    x0, x1 = x_range
    lo = max(0, x0 + margin)
    hi = min(region.shape[1], x1 - margin)
    xs, ys = [], []
    for x in range(lo, hi):
        col_ys = np.nonzero(cargo_mask[:, x])[0]
        if len(col_ys) == 0:
            continue
        best_y = None
        for y in col_ys:
            pixel = region[y, x]
            if is_arrow_color(pixel):
                continue
            cur = _stack_color_normalize(pixel)
            if cur is None:
                continue
            if float(np.sqrt(np.sum((cur - norm_expected) ** 2))) <= _STACK_COLOR_MATCH_HUE_TOL:
                if best_y is None or y < best_y:
                    best_y = int(y)
        if best_y is not None:
            xs.append(x)
            ys.append(best_y)
    if len(xs) < min_points:
        return None
    fit = _robust_local_line_fit(xs, ys)
    if fit is None or fit["resid_std"] > max_resid_std:
        return None
    xm = (x0 + x1) // 2
    top_y = fit["a"] * xm + fit["b"]
    if xm < 0 or xm >= len(local_floor_y) or local_floor_y[xm] < 0:
        return None
    floor_y = float(local_floor_y[xm])
    h = floor_y - top_y
    if h <= 0:
        return None
    return h, len(fit["xs"]), fit["resid_std"]


def _robust_local_line_fit(xs, ys, mad_floor=2.0, n_iter=3):
    """Fit เส้นตรง y=a*x+b แบบทนทานต่อ outlier (label/ลูกศร) โดยใช้ iterative
    MAD-based rejection - mad_floor ป้องกันกรณีข้อมูลเรียบสมบูรณ์แบบ (MAD~0)"""
    xs = np.asarray(xs, dtype=float)
    ys = np.asarray(ys, dtype=float)
    if len(xs) < 3:
        if len(xs) == 0:
            return None
        return {"a": 0.0, "b": float(np.mean(ys)), "resid_std": 0.0, "xs": xs, "ys": ys}
    a, b = 0.0, float(np.mean(ys))
    for _ in range(n_iter):
        if len(xs) < 3:
            break
        A = np.vstack([xs, np.ones_like(xs)]).T
        a, b = np.linalg.lstsq(A, ys, rcond=None)[0]
        resid = ys - (a * xs + b)
        mad = max(mad_floor, np.median(np.abs(resid - np.median(resid))))
        keep = np.abs(resid) < 3 * mad
        if keep.sum() < 3 or keep.sum() == len(xs):
            break
        xs, ys = xs[keep], ys[keep]
    resid = ys - (a * xs + b)
    return {"a": float(a), "b": float(b), "resid_std": float(resid.std()), "xs": xs, "ys": ys}


def detect_isometric_apex(cargo_top_y, local_floor_y, start_x, end_x, search_margin_ratio=0.15,
                           smooth_window=11, slope_thresh=0.15):
    """หาตำแหน่ง 'จุดยอด (apex)' ของ silhouette กองกล่องในมุมมอง isometric - ก่อนจุดยอด
    cargo_top_y คือขอบบน-หลัง (ขนานพื้น, height ถูกต้อง) หลังจุดยอดกลายเป็นขอบบน-หน้า (เอียง
    คนละทิศ, height ผิดเพี้ยนเป็นระบบ) ยืนยันด้วยภาพจริงและ cross-view ในไฟล์ทดสอบ

    v25.21 FIX (Critical - "Apex Hijack by Elevated Stack"):
    เดิมใช้ argmin(cargo_top_y) ซึ่งเลือกจุด y ต่ำสุด (= กล่องสูงสุดในภาพ) เป็น apex
    -> กล่องที่ซ้อนสูงผิดปกติ (เช่น สีแดงชั้น 3 ใน AE02-01/02) ถูกเลือกเป็น apex แทน
    -> eff_b1 = min(b1, apex_x) ทำให้ stack ทั้งหมดที่อยู่ทางขวาของกล่องนั้น
       ถูกตัด xs_top=[] -> height_px=None ทั้งหมด -> carry-forward ให้ค่าเท่ากัน
       -> STEP_DOWN_RISK ตรวจไม่พบเลย

    FIX: ใช้ slope-change detection แทน argmin()
    apex จริงของตู้ isometric = จุดที่ slope ของ cargo_top_y เปลี่ยนจาก
    "ลาดลงทางขวา (negative)" เป็น "ลาดขึ้นทางขวา (positive)" ในช่วงยาวพอ (V-shape จริง)
    กล่องสูงผิดปกติสร้าง "dip" สั้นๆ เท่านั้น ไม่ใช่ V-shape ยาว -> ตรวจแยกได้
    ถ้าไม่พบ V-shape -> คืน None (ไม่ตัด data = ปลอดภัยกว่าการตัดผิดพลาด)

    regression-verified: ไฟล์ที่ cargo มีลักษณะ slope คงที่ (ไม่มี V-shape ชัดเจน)
    จะได้ apex=None ไม่ตัด data -> ไม่กระทบผลลัพธ์เดิม
    """
    span = end_x - start_x
    if span <= 0:
        return None
    search_start = start_x + int(span * search_margin_ratio)
    xs = np.arange(search_start, min(end_x + 1, len(cargo_top_y)))
    if len(xs) == 0:
        return None
    vals = cargo_top_y[xs]
    valid_mask = vals >= 0
    if np.sum(valid_mask) < 20:
        return None

    xs_v = xs[valid_mask]
    ys_v = vals[valid_mask].astype(float)

    # smooth ก่อน detect slope-change (ลด noise จากขอบกล่องและ label text)
    half = smooth_window // 2
    smoothed = np.empty(len(ys_v))
    for i in range(len(ys_v)):
        lo, hi = max(0, i - half), min(len(ys_v), i + half + 1)
        smoothed[i] = float(np.median(ys_v[lo:hi]))

    n = len(smoothed)
    if n < 20:
        return None

    # หา V-shape: ต้องมี left slope negative + right slope positive ด้วย window ใหญ่พอ
    # (กล่องสูงผิดปกติสร้าง dip สั้น ~window_size เท่านั้น ไม่ใช่ V ยาวเต็ม half span)
    best_score = -1.0
    best_idx = None
    min_window = max(n // 8, 5)   # ต้องมี slope ยาวพอ (>= 1/8 ของ span) ทั้งสองข้าง

    for mid in range(min_window, n - min_window):
        left_win = min(mid, n // 4)
        right_win = min(n - mid - 1, n // 4)
        if left_win < min_window or right_win < min_window:
            continue
        left_slope = (smoothed[mid] - smoothed[mid - left_win]) / max(left_win, 1)
        right_slope = (smoothed[mid + right_win] - smoothed[mid]) / max(right_win, 1)
        if left_slope < -slope_thresh and right_slope > slope_thresh:
            score = (-left_slope) + right_slope
            if score > best_score:
                best_score = score
                best_idx = mid

    if best_idx is None:
        return None  # ไม่พบ V-shape จริง -> ไม่ตัด data (ปลอดภัยกว่า)
    return int(xs_v[best_idx])


def compute_stack_heights_px(seams, start_x, end_x, cargo_top_y, margin=6, local_floor_y=None):
    """คำนวณความสูง (px) ต่อ 1 ตั้ง โดย fit เส้นตรงทนทาน (robust local line) ให้กับ
    cargo_top_y ภายในแต่ละตั้งเอง (แก้บั๊กความชันธรรมชาติจากมุมมอง isometric) แล้วประเมิน
    ความสูงที่ตำแหน่งกึ่งกลางตั้ง เทียบกับ local floor (แก้บั๊กพื้นตู้รูปตัว V)

    v25.2 FIX: ตัดข้อมูลที่อยู่ "หลังจุดยอด isometric" (apex) ออกจากการคำนวณ - สำหรับตั้งที่
    อยู่หลัง apex ทั้งตั้ง (วัดเองไม่ได้เลย) จะคืนค่า height_px=None ก่อน ให้ cross-view
    reconciliation เติมค่าจากอีกมุมมองก่อน แล้วค่อย carry-forward เป็นทางเลือกสุดท้าย"""
    boundaries = [start_x] + sorted(seams) + [end_x]
    results = []

    def _floor_at(x):
        if local_floor_y is not None and 0 <= x < len(local_floor_y) and local_floor_y[x] >= 0:
            return local_floor_y[x]
        return None

    apex_x = detect_isometric_apex(cargo_top_y, local_floor_y, start_x, end_x)

    for i in range(len(boundaries) - 1):
        b0 = boundaries[i] + margin
        b1 = boundaries[i + 1] - margin
        eff_b1 = b1
        # v25.72 FIX (สำคัญ - พบจริงจาก AB03-04 หลัง v25.71 เพิ่ม blanket apex_fallback guard):
        # เดิม eff_b1 = min(b1, apex_x) แบบไม่มีเงื่อนไข - ถ้า apex_x <= b0 (คอลัมน์นี้ทั้งคอลัมน์
        # อยู่ "หลัง apex" ทั้งหมด ไม่มีส่วนใดก่อน apex เลย) จะได้ eff_b1 <= b0 -> ช่วง
        # range(b0, eff_b1) ว่างเปล่าเสมอ -> ทุกครั้งต้องเข้า apex_cut_fallback branch (ใช้ [b0,b1]
        # เต็มช่วง) แต่ผลลัพธ์ตัวเลขที่ได้เหมือนกับการ "ไม่มี apex logic เลย" (apex_x=None) ทุก
        # ประการ (n_samples = b1-b0 พอดี ไม่ใช่ค่าคงที่ผิดปกติแบบ ED84/ED85 ที่ n=67 ซ้ำกันข้าม
        # ไฟล์) - แต่กลับถูกติดป้าย "apex_fallback" อย่างผิดพลาด ทำให้ v25.71 blanket-guard (ที่ออกแบบ
        # มาสำหรับกรณี apex อยู่ "กลางคอลัมน์" ตัดข้อมูลจนเหลือน้อยผิดปกติ) ไปกรอง exclude กรณีนี้ด้วย
        # ทั้งที่เป็นการวัดที่เชื่อถือได้เต็มรูปแบบ (ยืนยันจาก AB03-04: idx2 (กล่องน้ำเงิน ASI1A-AJ
        # ชั้นเดียว, x=1110-1240) มี apex_x=1000 ซึ่งอยู่ก่อนคอลัมน์นี้ทั้งหมด (apex_x <= b0=1116)
        # -> n_samples=118 = ความกว้างคอลัมน์เป๊ะ ไม่ใช่ค่าคงที่แปลกๆ - ถูกกรองออกผิดพลาด ทำให้พลาด
        # STEP_DOWN_RISK จริงระหว่าง idx1 (เขียว/ฟ้า สูง) กับ idx2 (น้ำเงิน เตี้ย) ไป
        # FIX: cut ด้วย apex เฉพาะเมื่อ apex_x ตกอยู่ "ภายใน" ช่วงคอลัมน์นี้จริง (b0 < apex_x < b1)
        # เท่านั้น - ถ้า apex_x <= b0 (ทั้งคอลัมน์อยู่หลัง apex) หรือ apex_x >= b1 (ทั้งคอลัมน์อยู่
        # ก่อน apex, ไม่ต้องตัดอยู่แล้วเดิมก็ไม่เปลี่ยน) ให้ใช้ [b0,b1] เต็มช่วงตั้งแต่รอบแรกเลย
        # (ไม่ต้องผ่าน apex_cut_fallback branch อีกต่อไป) -> height_source ได้ "direct" ถูกต้องตาม
        # ความเป็นจริงของข้อมูล ไม่กระทบตัวเลขความสูงที่คำนวณได้เลย (ค่าเหมือนเดิมทุกประการ เปลี่ยน
        # แค่ label ความน่าเชื่อถือ) - ไม่กระทบกรณี apex อยู่กลางคอลัมน์จริง (b0<apex_x<b1) ที่ยังคง
        # ตัดข้อมูลแล้วอาจ fallback เป็น apex_fallback เหมือนเดิมทุกประการ (เช่น ED84/ED85 ที่ยืนยัน
        # แล้วว่าเป็น geometric artifact จริง - n_samples คงที่ผิดธรรมชาติข้ามไฟล์)
        apex_mid_cut = apex_x is not None and b0 < apex_x < b1
        if apex_mid_cut:
            eff_b1 = apex_x

        xs_top, ys_top = [], []
        for x in range(max(0, b0), max(0, eff_b1)):
            if x < len(cargo_top_y) and cargo_top_y[x] >= 0:
                xs_top.append(x)
                ys_top.append(cargo_top_y[x])

        # v25.21 FIX: ถ้า apex-cut ทำให้ xs_top=[] (eff_b1 <= b0 เพราะ apex_x น้อยกว่า b0)
        # -> fallback ใช้ cargo_top_y ทั้ง stack โดยไม่ตัด apex (ยอมรับ noise จาก isometric
        # slope แต่ดีกว่า height=None ที่ทำให้ carry-forward ให้ค่าเท่ากันหมด -> ไม่พบ STEP_DOWN)
        # ตัวอย่างที่ fix: AE02-01 BACK กล่องแดงชั้น 3 อยู่ฝั่งซ้าย -> apex_x เล็ก -> stack
        # ทุกตัวทางขวา xs_top=[] -> height=None -> carry-forward -> ไม่พบ STEP_DOWN
        apex_cut_fallback = False
        if len(xs_top) < 3 and b1 > b0:
            # ใช้ช่วงเต็ม [b0..b1] ไม่ตัด apex (fallback)
            xs_top, ys_top = [], []
            for x in range(max(0, b0), max(0, b1)):
                if x < len(cargo_top_y) and cargo_top_y[x] >= 0:
                    xs_top.append(x)
                    ys_top.append(cargo_top_y[x])
            apex_cut_fallback = True

        top_fit = _robust_local_line_fit(xs_top, ys_top) if xs_top else None

        height_px = None
        n_samples = 0
        height_source = "direct"
        if top_fit is not None and len(xs_top) >= 3:
            eff_mid = (max(0, b0) + (b1 if apex_cut_fallback else eff_b1)) / 2.0
            top_at_mid = top_fit["a"] * eff_mid + top_fit["b"]
            floor_at_mid = _floor_at(int(eff_mid))
            if floor_at_mid is not None:
                height_px = floor_at_mid - top_at_mid
                n_samples = len(top_fit["xs"])
                if apex_cut_fallback:
                    height_source = "apex_fallback"
                elif apex_mid_cut:
                    # v25.76 NEW (สำคัญ - พบจริงจาก AB03-04 ที่ผู้ใช้ระบุ "ตำแหน่งฟ้าท้ายสุด
                    # ยังมีกรอบแดง คือกรอบซ้ายสุด", 31-Aug-2026): เดิม (v25.72) เมื่อ apex ตัด
                    # ข้อมูลกลางคอลัมน์จริง (apex_mid_cut=True, b0<apex_x<b1) แต่ยังเหลือจุด>=3
                    # จุด จะไม่เข้า apex_cut_fallback branch เลย (apex_cut_fallback=False) ทำให้
                    # ถูกติดป้าย "direct" เหมือนคอลัมน์ปกติทุกประการ โดยไม่คำนึงว่า eff_mid ที่ใช้
                    # ประเมินความสูง (คำนวณจาก [b0, eff_b1=apex_x] ที่ถูกตัดแล้ว) อาจอยู่ใกล้ apex
                    # (จุดสูงสุดของเส้นโค้ง isometric) มากผิดปกติ แทนที่จะอยู่ที่ "จุดกึ่งกลางจริง"
                    # ของคอลัมน์ (ซึ่งควรใช้ [b0,b1] เต็มช่วงเดิม ก่อนตัด apex) - ยืนยันด้วยข้อมูล
                    # จริง AB03-04 FRONT idx1 (x=955-1110, กล่องฟ้า TEP1A-AJ ติดกับกล่องน้ำเงิน):
                    # apex_x=1000 ตัดข้อมูลเหลือ n_samples=39 จาก 143px ที่มีอยู่ (coverage=27.3%)
                    # eff_mid ที่ใช้จริง=980 (ใกล้ apex=1000 มาก) แทนที่จะเป็นจุดกึ่งกลางจริงของ
                    # คอลัมน์ (~1032) ทำให้วัดความสูงได้ 284.5px (ใกล้ยอด/จุดสูงสุดของเส้นโค้ง) สูง
                    # กว่าเพื่อนบ้าน idx0 (x=805-955, กล่องฟ้าเดียวกัน SKU เดียวกัน, eff_mid=880
                    # อยู่กลางคอลัมน์ตัวเองจริง n_samples=138/150=92% coverage) ที่วัดได้ 243.3px
                    # ถึง 14.5% - ทำให้ detect_tail_stepdown flag ผิดพลาดว่ากล่องฟ้าเดียวกันสูงต่ำ
                    # ต่างกัน ทั้งที่ floor_jump ระหว่างทั้งคู่วัดได้แค่ 4.8px (แทบไม่มี - ยืนยันว่า
                    # เป็นพื้นเดียวกันจริง ไม่ใช่คนละแถว/คนละระดับ) และทั้งคู่เป็น SKU เดียวกันเป๊ะ
                    # (TEP1A-AJ ยืนยันจากภาพ + ข้อความบนกล่องซ้ำกัน)
                    # ROOT CAUSE ที่แท้จริง: eff_mid คำนวณจาก eff_b1 (ช่วงที่ถูกตัด apex แล้ว) ทำให้
                    # จุดประเมินความสูงเลื่อนไปใกล้ apex (จุดสูงสุดของเส้นโค้ง isometric ที่เกิดจาก
                    # มุมกล้อง ไม่ใช่ความสูงกล่องจริง) แทนที่จะเป็นจุดกึ่งกลางจริงของคอลัมน์ - ยิ่ง
                    # apex ตัดข้อมูลออกมาก (coverage ต่ำ) ยิ่งเลื่อนจุดประเมินเข้าใกล้ apex มาก
                    # ทำให้ค่าที่วัดได้เอนเอียงสูงขึ้นเป็นระบบ (ไม่ใช่แค่ noise สุ่ม)
                    # FIX: คำนวณ "coverage fraction" (n_samples เทียบกับความกว้างเต็มของคอลัมน์
                    # ก่อนตัด apex, b1-b0) - ถ้าต่ำกว่าเกณฑ์ (_APEX_CUT_MIN_COVERAGE_FRACTION=35%,
                    # แนวคิดเดียวกับ Plateau Span Coverage Guard เดิมของระบบ คือ "ต้องมีข้อมูล
                    # ครอบคลุมเพียงพอจึงจะเชื่อว่าเป็นตัวแทนที่แท้จริงของคอลัมน์") ให้ติดป้าย
                    # "apex_partial_cut" (ระดับความน่าเชื่อถือเดียวกับ apex_fallback) แทน "direct"
                    # - ไม่กระทบตัวเลขความสูงที่คำนวณได้เลย (ค่าเหมือนเดิมทุกประการ เปลี่ยนแค่
                    # label) - ไม่กระทบกรณี apex ตัดข้อมูลแล้วยังเหลือ coverage สูง (>=35%) ซึ่งยัง
                    # คงเชื่อถือได้ตามปกติ (ยังคง "direct" เหมือนเดิม)
                    full_width = max(1, b1 - b0)
                    coverage_frac = n_samples / full_width
                    if coverage_frac < _APEX_CUT_MIN_COVERAGE_FRACTION:
                        height_source = "apex_partial_cut"

        if height_px is None:
            height_source = "unreliable_post_apex"

        results.append({
            "stack_idx": i,
            "x_range": (boundaries[i], boundaries[i + 1]),
            "n_samples": n_samples,
            "height_px": height_px,
            "height_source": height_source,
            "apex_x": apex_x,
        })
    return results


# v25.90 NEW: ดู docstring เต็มที่จุดใช้งานจริงใน detect_step_down_hidden_behind (FIX #3)
# สำหรับหลักฐาน+เหตุผล (พบจริงจาก EB66-01: hidden_height สูงกว่า median คอลัมน์อื่นแค่ 10.3%
