#   floor : 350  352  358  360 | 439  439  439  439   <- กระโดด 79px ที่ x=964 พอดี
#   h     : 130  133  141  144 | 225  226  228  229   <- "jump" ทั้งหมดมาจาก floor ล้วนๆ
#
