# ขอบเขต: hidden_behind ทิศทาง 'up' เท่านั้น - ไม่แตะ pairwise / cross_view / tail_stepdown /
# กรอบส้มทุกชนิด และไม่แตะทิศทาง 'down' (มี SNR + floor-stability guard ของ v25.70 อยู่แล้ว)
