#    การยกเกณฑ์ถึง 0.76 จะเสี่ยงตัดของจริงทิ้งในไฟล์อื่นที่ยังไม่ได้ทดสอบ
#    จำกัดเฉพาะทิศทาง 'up' เท่านั้น (ทั้ง 2 จุดที่ผิดเป็น 'up' ทั้งคู่)
#    และเฉพาะเมื่อ "นิ่งทั้ง 2 ฝั่ง" จึงจะถือว่าเป็นแถวเรียบเสมอกันจริง
