_HB_UP_MIN_EDGE_STD = 0.60   # เส้นยอดฝั่งซ้ายต้องขรุขระอย่างน้อยเท่านี้ (กล่องสูงต่ำจริง)
# (ทิศทาง 'up') สำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01) - ตั้งค่าให้สูงกว่า noise ปกติของขอบกล่อง
