# อื่นเหลือให้เป็น 'plateau' อ้างอิงได้เลยแม้แต่คอลัมน์เดียว) ทำให้ Edge-Column Global Consensus
# Guard (v25.68, ต้องการ plateau อย่างน้อย 2 คอลัมน์ไม่นับตัวเป้าหมาย) ใช้งานไม่ได้เลยในกรณีนี้
# ยืนยันด้วยข้อมูลจริงระดับ pixel: cargo_top_y (เส้นขอบบนกองสินค้า) ราบเรียบต่อเนื่องสนิทตลอดทั้ง
# ช่วงวัตถุ (BACK: 291->366px, FRONT เช่นกัน - ไม่มี jump คมชัดที่ seam เลย ยืนยันด้วย
# _has_internal_sharp_jump()=False ทั้งคู่) แต่ local_floor_y (เส้นพื้น) กลับมีความชันต่อเนื่อง
# ราบรื่นเช่นกัน (577px ลดหลั่นลงเหลือ 513px ตลอดความกว้างวัตถุ) ทำให้ "ความสูงที่วัดได้"
# (floor-top) ต่างกันไปตามตำแหน่ง x ที่ใช้ประเมิน (eff_mid ของแต่ละคอลัมน์) - เป็นความเอนเอียงจาก
# มุมมอง isometric ธรรมชาติของวัตถุที่ลอยตัวอยู่โดดเดี่ยวในตู้เปล่า (ไม่มี apex ให้ detect_
# isometric_apex ตรวจพบเลย เพราะวัตถุแคบเกินไป/ไม่มี V-shape ในช่วงแคบๆ ของตัวมันเอง - apex_x=None
# ทั้งคู่) ไม่ใช่ความแตกต่างทางกายภาพจริงของกล่อง SKU เดียวกันที่สูงเท่ากันจริง
# FIX: เพิ่มเงื่อนไขตรวจสอบใหม่ - ถ้าวิวนี้มี "รวมทั้งหมดเพียง 2 คอลัมน์" (ไม่มี plateau ใดๆ ให้
# อ้างอิงได้เลยแม้แต่คอลัมน์เดียว, ต่างจาก Edge-Column Guard เดิมที่ยังพอมี 1+ คอลัมน์เหลือ) และ
# ทั้งคู่เป็น height_source=="direct" ให้ตรวจสอบด้วย _has_internal_sharp_jump (เทคนิคเดียวกับที่
# ใช้แยกแยะ jump จริงจาก isometric slope ต่อเนื่องใน AC03-02/EA03-01 - เชื่อถือได้มากกว่า
# _edge_outlier_has_genuine_seam_jump ซึ่งใช้ window-median scan ที่เสี่ยงถูกความชันธรรมชาติ
# หลอกได้ในบางกรณี) ครอบคลุมทั้งช่วงของทั้ง 2 คอลัมน์รวมกัน - ถ้าไม่พบ jump คมชัดจริง (False) ให้
# ถือว่าเป็นวัตถุความสูงสม่ำเสมอจริง ไม่ flag ความเสี่ยง
# ขอบเขตการแก้ (แคบมาก ปลอดภัยสูง): ทำงานเฉพาะไฟล์ที่มีคอลัมน์รวมทั้งวิวเพียง 2 คอลัมน์เท่านั้น
# (เงื่อนไขนี้พบได้ยาก เฉพาะไฟล์ที่บรรทุกเบาบางมากและกล่องรวมเป็นก้อนเดียว) ไม่กระทบไฟล์ที่มี
# คอลัมน์ตั้งแต่ 3 ขึ้นไปเลย (ยังคงใช้ Edge-Column Guard เดิมตามปกติ)
# ข้อจำกัดที่ต้องบอกตรงไปตรงมา: ยืนยันด้วยข้อมูลจริงจากไฟล์เดียว (EB73-01) เท่านั้น - ยังไม่ได้
# regression-test ย้อนกับไฟล์ calibration เดิมทั้งหมด (ไม่มีไฟล์เหล่านั้นให้ทดสอบในรอบนี้) แต่ประเมิน
# ความเสี่ยงแล้วว่าปลอดภัยสูง เพราะเงื่อนไข "รวมทั้งวิวมีแค่ 2 คอลัมน์" เป็นเงื่อนไขที่แคบมาก
# (พบเฉพาะไฟล์บรรทุกเบาบางมากผิดปกติ) แนะนำให้รัน regression เต็มรูปแบบก่อนใช้งานจริง
def _isolated_pair_no_genuine_jump(records_same_view, view_result):
    """True ถ้าวิวนี้มีทั้งหมดเพียง 2 คอลัมน์ (ไม่มี plateau ใดๆ ให้อ้างอิงได้เลยแม้แต่คอลัมน์
    เดียว - ต่างจาก Edge-Column Global Consensus Guard เดิมที่ยังต้องการอย่างน้อย 2 คอลัมน์อื่น)
    และไม่มี genuine sharp jump (single-pixel step, ตรวจด้วย _has_internal_sharp_jump) ระหว่าง
    คอลัมน์ทั้ง 2 ทั่วทั้งช่วงรวม - ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01)
    """
    valid = [r for r in records_same_view if not r.get("is_corner_duplicate")]
    if len(valid) != 2:
        return False
    valid = sorted(valid, key=lambda r: r["x_range"][0])
    a, b = valid[0], valid[1]
    if a.get("height_source") != "direct" or b.get("height_source") != "direct":
        return False
    if view_result is None:
        return False
    cty = view_result.get("cargo_top_y")
    if cty is None:
        return False
    lo = min(a["x_range"][0], b["x_range"][0])
    hi = max(a["x_range"][1], b["x_range"][1])
    if _has_internal_sharp_jump(cty, (lo, hi)):
        return False
    # v25.90 FIX #4 (สำคัญ - พบจริงจาก EB63-01 ที่ผู้ใช้ยืนยันว่า "มีความเสี่ยง" แต่ v25.89
    # รายงาน SAFE, 10-Sep-2026): guard นี้ (v25.89, สร้างขึ้นเพื่อแก้ EB73-01) ใช้สัญญาณเดียวคือ
    # _has_internal_sharp_jump ตัดสินใจ suppress ทั้งคู่ - พบว่าเข้มงวดเกินไปสำหรับ EB63-01 ซึ่งมี
    # ลายเซ็นภายนอกเหมือน EB73-01 ทุกประการ (บรรทุกเบาบางมาก 6.9%, SKU เดียว API1A สีน้ำเงินล้วน
    # ทั้งไฟล์, Phase 1B นับได้แค่ 2 คอลัมน์รวมทั้งวิว) แต่เป็นความเสี่ยงจริง 100%:
    # BACK idx0=115.9px vs idx1=59.5px -> drop=48.7% (กล่องวางนอนแบนอยู่ข้างกล่องตั้งสูง - ยืนยัน
    # ด้วยภาพจริงชัดเจนมาก) และที่สำคัญ _edge_outlier_has_genuine_seam_jump(idx1,idx0)=True
    # (พบ jump จริงที่ seam) ในขณะที่ EB73-01 ไม่พบ jump จากตัวตรวจจับใดเลย
    # ROOT CAUSE: _has_internal_sharp_jump ตรวจเฉพาะ "single-pixel step >=35px" ซึ่งจับไม่ได้เมื่อ
    # รอยต่อระหว่างกล่อง 2 ใบเป็นแนวทแยงตามธรรมชาติของภาพ isometric (ความสูงเปลี่ยนแบบค่อยเป็น
    # ค่อยไปตลอดแนวทแยง ไม่กระโดดใน 1 pixel) - แต่ _edge_outlier_has_genuine_seam_jump (window-
    # median scan รอบ seam) จับกรณีนี้ได้ เพราะเปรียบเทียบ "ระดับความสูงเฉลี่ย" 2 ฝั่งแทน
    # FIX: ต้องให้ตัวตรวจจับ jump "ทั้ง 2 ตัวเห็นตรงกันว่าไม่มี jump" จึงจะ suppress (เดิมใช้ตัวเดียว)
    # - เป็นรูปแบบเดียวกับที่ v25.89 ใช้อยู่แล้วใน apex-affected guard (ใช้ 2 ตัวตรวจสอบร่วมกัน)
    # การแก้นี้ "แคบลงเสมอ" (suppress ยากขึ้น) จึงไม่มีทางสร้าง false-negative ใหม่ในไฟล์ใดเลย
    # ข้อจำกัดที่ต้องบอกตรงไปตรงมา: ไม่มีไฟล์ EB73-01 ให้ regression-test ในรอบนี้ - ถ้า EB73-01
    # มี seam-jump ตรวจพบด้วย (ซึ่ง CHANGELOG v25.89 ไม่ได้ระบุค่าไว้) กรอบเดิมอาจกลับมา แนะนำให้
    # รัน regression กับ EB73-01 ยืนยันก่อนใช้งานจริง
    if _edge_outlier_has_genuine_seam_jump(view_result, a, b) is True:
        return False
    return True


def _is_edge_measurement_outlier(records_same_view, target_idx,
                                  min_plateau_size=_EDGE_OUTLIER_MIN_PLATEAU_SIZE,
                                  plateau_max_spread_ratio=_EDGE_OUTLIER_PLATEAU_MAX_SPREAD_RATIO,
                                  deviation_threshold=_EDGE_OUTLIER_DEVIATION_THRESHOLD,
                                  view_result=None):
    """True ถ้า target_idx เป็นคอลัมน์ริมสุดจริงของแถว (idx==0 หรือ idx==max) และความสูงของมัน
    เบี่ยงเบนจาก 'plateau' ของคอลัมน์อื่นที่นิ่งมาก (เชื่อถือได้ + spread ต่ำ) เกิน threshold -
    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก EB66-01/EC10-03/EC19-01)"""
    valid = [r for r in records_same_view if not r.get("is_corner_duplicate")]
    if not valid:
        return False
    all_idxs = [r["idx"] for r in valid]
    min_idx, max_idx = min(all_idxs), max(all_idxs)
    if target_idx != min_idx and target_idx != max_idx:
        return False  # ไม่ใช่คอลัมน์ริมสุดจริง - guard นี้ใช้ไม่ได้
    by_idx = {r["idx"]: r for r in valid}
    target = by_idx.get(target_idx)
    if target is None or target.get("height_px") is None:
        return False
    plateau_heights = []
    for r in valid:
        if r["idx"] == target_idx:
            continue
        if r.get("height_px") is None:
            continue
        # v25.76 FIX (สำคัญ - พบ regression จริงจาก AB05-01 ระหว่างทดสอบ): เดิมรับเฉพาะ
        # height_source in ("direct","cross_view_filled") เข้า plateau - หลังเพิ่ม label ใหม่
        # "apex_partial_cut" (v25.76) คอลัมน์ที่เคยถูกนับเป็นส่วนหนึ่งของ plateau (เพราะเคยได้
        # label "direct" มาก่อน) กลับถูกตัดออกจาก plateau ไปด้วย ทำให้ plateau เหลือจุดไม่พอ
        # (< min_plateau_size) -> Edge-Column Global Consensus Guard ใช้ไม่ได้อีกต่อไป -> เกิด
        # regression ที่ AB05-01 BACK (STEP_DOWN_RISK pairwise idx0 กลับมา flag ผิดพลาดอีกครั้ง
        # ทั้งที่เคยถูกแก้ไปแล้วตั้งแต่ v25.72) - FIX: รับ "apex_partial_cut" เข้า plateau ด้วย
        # (ยังคงเป็นค่าที่วัดได้จริง เพียงแต่มีโอกาสเอนเอียงสูงกว่าจริงเล็กน้อยจากตำแหน่งประเมินใกล้
        # apex - ใช้เป็นหลักฐาน "ความนิ่งของกลุ่ม" ได้ตามปกติ ไม่กระทบการตรวจจับ isometric-bias
        # เดิมที่ guard นี้ออกแบบมา)
        if r.get("height_source") not in ("direct", "cross_view_filled", "apex_partial_cut"):
            continue
        plateau_heights.append(r["height_px"])
    if len(plateau_heights) < min_plateau_size:
        return False
    # v25.83 NEW (สำคัญ - พบจริงจาก ED85-01, 31-Aug-2026 - ผู้ใช้ระบุว่า FRONT view วาดกรอบตรง
    # กล่องสีม่วง TGT1G ทั้งที่ไม่ควรวาด): เดิม plateau_heights ด้านบนรวมคอลัมน์ "ทุกสี" ปนกันหมด
    # (ไม่แยกแยะ SKU) - พบว่าไฟล์ ED85-01 มี idx0 (ริมสุดจริง, สีม่วง TGT1G) วัดได้ 253.3px ต่ำกว่า
    # เพื่อนบ้านสีม่วงเดียวกัน (idx1-4: 308.3/351.5/345.9/317.0px) มาก - แต่ plateau ที่คำนวณจาก
    # "ทุกสีปนกัน" (รวม idx5=teal/idx6=cyan ที่มีความสูงต่างจากม่วงจริงเพราะเป็นคนละ SKU) ทำให้
    # p_spread สูงเกิน 10% (วัดได้จริง 55%) จน guard เดิมไม่ trigger เลย ทั้งที่กลุ่มสีม่วงเพียว ๆ
    # (ไม่รวม idx5/6) เองมี spread แค่ 13.0% (ใกล้เคียง 10% มาก - น่าเชื่อถือกว่าการปนสีมาก)
    # ROOT CAUSE: Phase 1B เก็บ stack_expected_colors ไว้อยู่แล้ว (ยืนยันแน่ชัดว่าคอลัมน์ใดเป็น
    # SKU/สีเดียวกัน) แต่ guard นี้ไม่เคยใช้ข้อมูลนี้เลย - การเทียบข้าม SKU (ม่วงเทียบฟ้า/เขียว)
    # ไม่สมเหตุสมผลทางกายภาพอยู่แล้ว เพราะกล่องคนละ SKU มีสิทธิ์สูงต่ำต่างกันจริงได้ปกติ (ไม่ใช่
    # หลักฐานของ "ความนิ่ง" ที่ควรใช้ตัดสิน isometric bias เลย)
    # FIX: ถ้า view_result มี stack_expected_colors และ target มีสีที่รู้แน่ชัด (ไม่ใช่ None) ให้
    # ลองกรอง plateau เฉพาะคอลัมน์ที่มีสีเดียวกับ target ก่อน (same-color plateau) - ถ้าจำนวนพอ
    # (>= เกณฑ์ขั้นต่ำ) ให้ใช้ชุดนี้แทนที่ all-color plateau เดิม พร้อมใช้เกณฑ์ spread ที่ผ่อนปรน
    # กว่าเล็กน้อย (_EDGE_OUTLIER_SAME_COLOR_MAX_SPREAD_RATIO=15% แทน 10%) เพราะเป็นหลักฐานที่
    # น่าเชื่อถือกว่ามาก (ยืนยันแล้วว่าเป็น SKU เดียวกันจริงจาก Phase 1B ไม่ใช่แค่ "บังเอิญนิ่ง")
    # - ถ้าไม่มีข้อมูลสี หรือ same-color plateau มีจุดไม่พอ ให้ fallback ไปใช้ all-color plateau
    # เดิมทุกประการ (ปลอดภัยสำหรับไฟล์อื่นที่ไม่เจอปัญหานี้)
    same_color_plateau_used = False
    if view_result is not None:
        expected_colors = view_result.get("stack_expected_colors")
        if expected_colors is not None and target_idx < len(expected_colors):
            target_color = expected_colors[target_idx]
            if target_color is not None:
                same_color_heights = []
                for r in valid:
                    if r["idx"] == target_idx or r.get("height_px") is None:
                        continue
                    if r.get("height_source") not in ("direct", "cross_view_filled", "apex_partial_cut"):
                        continue
                    r_idx_local = r["idx"]
                    if r_idx_local >= len(expected_colors):
                        continue
                    if expected_colors[r_idx_local] == target_color:
                        same_color_heights.append(r["height_px"])
                if len(same_color_heights) >= _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM:
                    plateau_heights = same_color_heights
                    same_color_plateau_used = True
    if same_color_plateau_used:
        plateau_max_spread_ratio = _EDGE_OUTLIER_SAME_COLOR_MAX_SPREAD_RATIO
    # v25.71 NEW (สำคัญ - พบจริงจาก ED85-01/02/03 ที่ผู้ใช้ระบุ, 30-Aug-2026): เดิมคำนวณ
    # p_spread จาก min-max ดิบของ plateau_heights ทั้งหมด - พบว่าคอลัมน์ที่ "ติดกับ" คอลัมน์ริมสุด
    # (idx=1, ไม่ใช่ตัวริมสุดเอง) อาจได้รับผลกระทบจาก isometric distortion ในทิศทางเดียวกัน
    # (เบากว่า) ทำให้ raw min-max spread สูงเกิน threshold แม้ "แกนหลัก" ของ plateau (คอลัมน์ที่
    # เหลือ ไม่รวม idx=1) จะนิ่งมากจริง (spread แค่ 2.7% ในไฟล์ทดสอบ) - ยืนยันด้วยข้อมูลจริง
    # ED85-01/02/03: idx=1 มีความสูง 308.1-308.3px "เหมือนกันเป๊ะ" ข้าม 3 ไฟล์ (สัญญาณเดียวกับ
    # apex_fallback n=67 ที่เคยพิสูจน์แล้วว่าเป็น geometric artifact ไม่ใช่ความสูงจริง)
    # FIX: ใช้ median + MAD-based iterative outlier rejection (เทคนิคเดียวกับ
    # _robust_local_line_fit ที่ใช้ทั่วระบบอยู่แล้ว) ตัด "แกนนอก" (ค่าที่เบี่ยงเบนจาก median มาก)
    # ออกก่อนคำนวณ spread - ทำให้ guard ตรวจจับ "แกนหลักที่นิ่งจริง" ได้แม่นยำขึ้น โดยไม่ต้องขยับ
    # threshold ไปเรื่อยๆ แบบไม่มีจุดจบ (ยืนยันว่าไม่กระทบไฟล์เดิมที่ plateau นิ่งอยู่แล้วเพราะการ
    # trim จะไม่ตัดอะไรออกเลยถ้าไม่มี outlier จริง)
    # v25.71 NEW: แยกเกณฑ์ขั้นต่ำเป็น 2 ระดับ - min_plateau_size (=3 เดิม) ใช้เป็นเงื่อนไข "ก่อน
    # เริ่ม trim" (ต้องมีจุดดิบเพียงพอก่อนถึงจะลองใช้ guard นี้เลย - ไม่ลดมาตรฐานเดิม) ส่วน
    # _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM (=2) ใช้เป็นเกณฑ์ขั้นต่ำ "หลัง trim" เท่านั้น -
    # อนุญาตให้ trim เหลือน้อยกว่าเดิมได้ถ้าจุดที่เหลือ "นิ่งจริง" (ยืนยันจาก ED85-01: มีแค่ 3 จุด
    # ดิบ trim ออกได้ 1 จุด (outlier) เหลือ 2 จุดที่นิ่งมาก - ต้องอนุญาตให้ trim ลงมาที่ 2 ได้ ไม่งั้น
    # จะติดเงื่อนไข "keep.sum()<min_plateau_size" เดิมที่บล็อกไม่ให้ trim เมื่อไฟล์มีคอลัมน์น้อย)
    arr = np.array(plateau_heights, dtype=float)
    for _ in range(3):  # iterative trimming (เหมือน _robust_local_line_fit, n_iter=3)
        if len(arr) < _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM:
            break
        med = np.median(arr)
        mad = np.median(np.abs(arr - med))
        mad = max(mad, 2.0)  # mad_floor กันกรณีข้อมูลเรียบสมบูรณ์แบบ (MAD~0)
        keep = np.abs(arr - med) < 2.5 * mad
        if keep.sum() < _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM or keep.sum() == len(arr):
            break
        arr = arr[keep]
    if len(arr) < _EDGE_OUTLIER_MIN_PLATEAU_SIZE_AFTER_TRIM:
        return False
    p_median = float(np.median(arr))
    if p_median <= 0:
        return False
    p_spread = (arr.max() - arr.min()) / p_median
    if p_spread > plateau_max_spread_ratio:
        return False  # plateau ไม่นิ่งพอจะเป็นหลักฐานอ้างอิงได้ - ปลอดภัยไว้ก่อน ไม่ suppress
    deviation = abs(target["height_px"] - p_median) / p_median
    if deviation < deviation_threshold:
        return False
    # v25.72 NEW: ก่อน suppress จริง ตรวจสอบว่ามี "seam jump" คมชัดระหว่าง target กับเพื่อนบ้าน
    # ที่ใกล้ที่สุดหรือไม่ - ถ้ามี แสดงว่าเป็นความแตกต่างทางกายภาพจริง ไม่ใช่ isometric bias
    # (ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล พบจริงจาก AC03-02)
    if view_result is not None:
        neighbor_idx = target_idx + 1 if target_idx == min_idx else target_idx - 1
        neighbor_rec = by_idx.get(neighbor_idx)
        if neighbor_rec is not None:
            has_jump = _edge_outlier_has_genuine_seam_jump(view_result, target, neighbor_rec)
            if has_jump:
                return False  # jump จริงที่ seam - ไม่ suppress ปล่อยให้ flag ตามปกติ
    return True


# v26.02 NEW: ทางออกฉุกเฉินของ apex guard เมื่อ "ตัวเตี้ยเชื่อถือได้ แต่ตัวอ้างอิงไม่ได้"
# ดู docstring เต็มที่จุดใช้งานจริงใน detect_step_down_pairwise (FIX #2) สำหรับหลักฐาน+เหตุผล
# (พบจริงจาก GC06 BACK ตู้ที่ 2 - ผู้ใช้ยืนยันเองว่า "กองเตี้ยกว่าเพื่อนบ้าน")
_APEX_GUARD_OVERRIDE_MIN_DEVIATION = 0.40   # ต่ำกว่า plateau เกินนี้ = ความเอนเอียงอธิบายไม่ได้
_APEX_GUARD_OVERRIDE_MAX_SPREAD = 0.12      # plateau ต้องนิ่งจริง (GC06 วัดได้ 6.6%)
_APEX_GUARD_OVERRIDE_MIN_PLATEAU = 3        # ต้องมีคอลัมน์อ้างอิงอย่างน้อยเท่านี้


def _apex_guard_plateau_override(records, shorter_rec, view_result):
    """v26.02: คืน dict ถ้าควร "ข้าม" apex guard (ตัวเตี้ยเชื่อถือได้ + เตี้ยกว่า plateau
    ที่นิ่งอย่างสุดขั้ว) หรือ None ถ้าไม่เข้าเงื่อนไข - ดู docstring เต็มด้านบน"""
    if shorter_rec.get("height_source") not in ("direct", "cross_view_filled"):
        return None
    if shorter_rec.get("n_samples", 0) < STEP_DOWN_MIN_RELIABLE_SAMPLES:
        return None
    h = shorter_rec.get("height_px")
    if not h or h <= 0:
        return None
    others = [r["height_px"] for r in records
              if r["idx"] != shorter_rec["idx"] and r.get("height_px")
              and not r.get("is_corner_duplicate")
              and r.get("height_source") in ("direct", "cross_view_filled",
                                             "apex_partial_cut", "cross_view_corrected")]
    if len(others) < _APEX_GUARD_OVERRIDE_MIN_PLATEAU:
        return None
    arr = np.array(others, dtype=float)
    for _ in range(3):
        if len(arr) < _APEX_GUARD_OVERRIDE_MIN_PLATEAU:
            break
        med = np.median(arr)
        mad = max(float(np.median(np.abs(arr - med))), 2.0)
        keep = np.abs(arr - med) < 2.5 * mad
        if keep.sum() < _APEX_GUARD_OVERRIDE_MIN_PLATEAU or keep.sum() == len(arr):
            break
        arr = arr[keep]
    if len(arr) < _APEX_GUARD_OVERRIDE_MIN_PLATEAU:
        return None
    plateau = float(np.median(arr))
    if plateau <= 0:
        return None
    spread = (float(arr.max()) - float(arr.min())) / plateau
    if spread > _APEX_GUARD_OVERRIDE_MAX_SPREAD:
        return None
    deviation = 1.0 - (h / plateau)
    if deviation < _APEX_GUARD_OVERRIDE_MIN_DEVIATION:
        return None
    return {"plateau": plateau, "spread": spread, "deviation": deviation,
            "n_plateau": int(len(arr))}


# ============================================================================
# v26.15 NEW: LARGE-BOX TAIL NOTCH GUARD (กรอบส้มปลายกล่องใหญ่แถวเดียว)
# ============================================================================
# ที่มา (ผู้ใช้แจ้ง 16-Sep-2026): "กรอบที่ผิดคือ ... กับ ประเภทกล่องใหญ่วางเรียง 1
# ตรงท้ายตู้ ดันไปวาดกรอบ" (พร้อมภาพที่แสดงกรอบส้มเล็กๆ ที่ปลายสุดใกล้เส้นมิติ 1019 mm)
#
# ROOT CAUSE: detect_silhouette_notch_risk ตรวจ "รอยบาก" จากเส้นยอดสินค้า (cargo_top_y)
# โดยไม่รู้จักโครงสร้างการวางเลย - ที่ปลายสุดของกองกล่องใหญ่ที่วางเรียงแถวเดียว เส้นยอด
# จะลาดลงตามธรรมชาติของมุมมอง isometric (geometric taper ของ silhouette ปลายแถว) บวกกับ
# เส้นมิติ/ลูกศรกำกับที่วาดทับ ทำให้เกิด local peak ที่ find_peaks จับได้ และพื้นที่ใต้จุดนั้น
# เป็นพื้นหลัง/ผนังตู้จริง (ผ่านเกณฑ์สี) -> วาดกรอบส้มออกมา
# แต่ในทางกายภาพ: "กล่องใหญ่วางเรียงแถวเดียว" = ไม่มีแถวนอก-แถวใน = ไม่มีโพรงภายในให้
# สินค้าล้มเข้าไปได้เลยโดยโครงสร้าง (หลักการเดียวกับที่ผู้ใช้เคยระบุไว้ใน v26.06 สำหรับ
# กรอบแดง cross_view และใน v26.01 เงื่อนไขที่ 2 ของ tailzone)
#
# FIX: ระงับกรอบส้ม silhouette_notch เฉพาะเมื่อครบทุกเงื่อนไข (แคบมาก):
#   (1) view นี้เป็น "กล่องใหญ่วางแถวเดียว" (ใช้ _is_large_box_single_row เดิมของ v26.06
#       ทุกประการ - side face <= 1 และผิวบนต่อคอลัมน์ <= 1)
#   (2) และตำแหน่งรอยบากอยู่ใน "โซนปลายสุด" ของกองสินค้า (หัวหรือท้าย)
# ไม่กระทบรอยบากกลางกอง (ซึ่งเป็นโพรงจริงที่ต้อง flag) และไม่กระทบไฟล์ที่มีกล่องเล็กวาง
# นอก+ใน เลยแม้แต่ไฟล์เดียว (ไม่เข้าเงื่อนไขที่ 1 ตั้งแต่ต้น)
_LARGEBOX_TAIL_NOTCH_SPAN_FRAC = 0.22   # โซนปลายสุดหัว/ท้าย ฝั่งละ 22% ของความยาวสินค้า


def _suppress_largebox_tail_notch(risks, view_result, records, view_label):
    """v26.15: ระงับกรอบส้ม silhouette_notch ที่ปลายสุดของกองกล่องใหญ่วางเรียงแถวเดียว
    (ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล - ผู้ใช้ระบุโดยตรง)"""
    if view_result is None or not records:
        return risks
    has_notch = any(r.get("subtype") == "silhouette_notch"
                    and (r.get("mark_view") or r.get("view")) == view_label
                    for r in risks)
    if not has_notch:
        return risks
    if not _is_large_box_single_row(view_result, records, view_label):
        return risks
    sx, ex = view_result.get("start_x"), view_result.get("end_x")
    if sx is None or ex is None or (ex - sx) <= 0:
        return risks
    span = ex - sx
    edge = max(1, int(span * _LARGEBOX_TAIL_NOTCH_SPAN_FRAC))
    lo_end, hi_start = sx + edge, ex - edge
    out = []
    for r in risks:
        if (r.get("subtype") != "silhouette_notch"
                or (r.get("mark_view") or r.get("view")) != view_label):
            out.append(r)
            continue
        nx = r.get("notch_x")
        if nx is None:
            mx = r.get("mark_x_range")
            nx = (mx[0] + mx[1]) // 2 if mx else None
        if nx is not None and (nx <= lo_end or nx >= hi_start):
            side = "หัวตู้" if nx <= lo_end else "ท้ายตู้"
            print(f"[LARGEBOX_TAIL] {view_label} ระงับกรอบส้มที่ x={nx} ({side}) "
                  f"- เป็นกล่องใหญ่วางเรียงแถวเดียว (ไม่มีแถวนอก-แถวใน) และอยู่ในโซน"
                  f"ปลายสุด x<={lo_end} หรือ x>={hi_start} (สินค้า {sx}-{ex}) "
                  f"-> ไม่มีโพรงภายในให้สินค้าล้มเข้าไปได้ (ดู FIX v26.15)")
            continue
        out.append(r)
    return out


# ============================================================================
# v26.15 NEW: GAP-CONTAMINATED COLUMN GUARD (กรอบแดงจากคอลัมน์ที่ปนช่องว่างระหว่างตู้)
# ============================================================================
# ที่มา (ผู้ใช้แจ้ง 16-Sep-2026): "กรอบแดงตรง front 7.3 ดันไปวาดกรอบ ไร้สาระ
# งานก็ปกติดีตรงบริเวณนั้นๆ"
#
# ROOT CAUSE (ยืนยันด้วยการวัดพิกัดจริงจากไฟล์ชุด 12 ไฟล์): Phase 1B แบ่งคอลัมน์จากสี
# front-face เท่านั้น ไม่รู้จัก "ช่องว่างระหว่างตู้" ของรถพ่วง -> คอลัมน์ปลายตู้ถูกขยาย
# คร่อมช่องว่างเข้าไป ทำให้ "ความสูงที่วัดได้" ถูกเจือจางด้วยพื้นที่ว่าง (ไม่ใช่ความสูงของ
# กองสินค้าจริง) เมื่อค่าที่ผิดนี้ถูกนำไปเทียบข้าม view -> flag ผิดที่ตำแหน่งที่สินค้าปกติดี
# วัดจริงจากไฟล์ชุดเดียวกับที่ผู้ใช้ทดสอบ:
#   CE02-ALL  BACK idx3 x=(822,958) ช่องว่างกินพื้นที่คอลัมน์ 60% -> h=65.2px
#             (เพื่อนบ้านในตู้เดียวกัน 172-177px) -> เทียบ FRONT idx3 (177.4px)
#             -> drop 63% -> วาดกรอบแดงกลางตู้ที่กล่องสูงเท่ากันทั้งแถว
#   CC05-all  BACK idx3 กิน 52% (h=112.2) | FRONT idx3 กิน 38% (h=164.4) -> drop 32%
#   CE01-all  BACK idx4 กิน 41% (h=203.0) | FRONT idx5 กิน 30% (h=143.1) -> drop 30%
# ยืนยันแยกได้ขาด (วัดครบ 11 ไฟล์ dual-view - ไม่มีค่าใดคาบเกี่ยวกัน):
#   คอลัมน์ที่ทำให้เกิด flag ผิด : 60%, 52%, 41%, 38%, 30%
#   คอลัมน์ที่ไม่ทำให้เกิดปัญหา  : 25%, 19%, 16%, 12%, 11%, 11%
#   -> เกณฑ์ 30% อยู่กึ่งกลางพอดี
#
# หมายเหตุสำคัญ: v26.13 แก้ปัญหานี้แค่ "ตัดกรอบไม่ให้คร่อม 2 ตู้" (post-processing) ซึ่งทำให้
# กรอบอยู่ในตู้เดียวถูกต้อง แต่ "ตัวความเสี่ยงเองยังผิดอยู่" เพราะเกิดจากค่าความสูงที่เจือจาง
# ตั้งแต่ต้นทาง - รอบนี้แก้ที่ต้นเหตุ (ไม่ให้ค่าที่เจือจางถูกนำไปเทียบตั้งแต่แรก)
#
# ขอบเขตแคบมาก (จำกัดเฉพาะจุดที่ผู้ใช้ระบุว่าผิดเท่านั้น):
#   - ระงับเฉพาะ subtype "cross_view" (การเทียบข้าม view ซึ่งเป็นต้นตอของกรอบแดงที่ 7.3)
#   - pairwise / tail_stepdown / hidden_behind ไม่ถูกแตะเลย (เทียบภายใน view เดียวกัน)
#   - EMPTY_SPACE_RISK (กรอบส้ม) ไม่ถูกแตะเลยแม้แต่จุดเดียว
#   - รถตู้เดียว (ไม่มีช่องว่างระหว่างตู้) ไม่ได้รับผลกระทบเลยแม้แต่ไฟล์เดียว
_GAP_CONTAMINATED_MAX_FRAC = 0.30


def _col_gap_fraction(view_result, x_range):
    """v26.15: สัดส่วนของคอลัมน์ที่ตกอยู่ใน 'ช่องว่างระหว่างตู้' (0.0 = ไม่คร่อมเลย)"""
    if view_result is None:
        return 0.0
    gaps = view_result.get("_inter_container_gaps")
    if not gaps:
        return 0.0
    x0, x1 = int(x_range[0]), int(x_range[1])
    w = max(1, x1 - x0)
    ov = 0
    for g0, g1 in gaps:
        ov += max(0, min(x1, g1) - max(x0, g0))
    return ov / w


def _is_gap_contaminated(view_result, rec):
    """v26.15: True ถ้าความสูงของคอลัมน์นี้ถูกเจือจางด้วยช่องว่างระหว่างตู้จนเชื่อถือไม่ได้
    (ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล - พบจริงจาก CE02/CC05/CE01)"""
    frac = _col_gap_fraction(view_result, rec.get("x_range", (0, 0)))
    if frac >= _GAP_CONTAMINATED_MAX_FRAC:
        h = rec.get("height_px")
        print(f"[GAP_COL] {rec.get('view')} idx={rec.get('idx')} x={rec.get('x_range')} "
              f"ถูกช่องว่างระหว่างตู้กินพื้นที่ {frac:.0%} (เกณฑ์ >="
              f"{_GAP_CONTAMINATED_MAX_FRAC:.0%}) -> ความสูงที่วัดได้ "
              f"({round(h, 1) if h else '-'}px) ถูกเจือจาง ไม่น่าเชื่อถือพอจะเทียบข้าม view "
              f"(ดู FIX v26.15)")
        return True
    return False


def detect_step_down_pairwise(records, view_label, view_result=None):
    """เปรียบเทียบตั้งข้างเคียงในview เดียวกัน - ข้าม record ที่ is_corner_duplicate=True
    (ตรวจจากเส้น rail ทางเรขาคณิตจริง ไม่ hardcode ชื่อ view)"""
    risks = []
    local_floor_y = view_result.get("local_floor_y") if view_result else None
    for i in range(len(records) - 1):
        a, b = records[i], records[i + 1]
        if a.get("is_corner_duplicate") or b.get("is_corner_duplicate"):
            continue
        if a["height_px"] is None or b["height_px"] is None:
            continue
        taller_rec = a if a["height_px"] >= b["height_px"] else b
        shorter_rec = b if taller_rec is a else a
        taller_h = taller_rec["height_px"]
        shorter_h = shorter_rec["height_px"]
        # v26.31: SAME-BOX-SIZE GUARD (ดู docstring เต็มที่ _SAMEBOX_MIN_FH_RATIO)
        _fr = _same_box_size_pair(view_result, a, b)
        if _fr is not None and _fr >= _SAMEBOX_MIN_FH_RATIO:
            print(f"[SAMEBOX] pairwise {view_label} idx={a.get('idx')}/{b.get('idx')} "
                  f"กล่อง 2 ฝั่งขนาดเท่ากัน (fh_ratio={_fr:.3f} >= "
                  f"{_SAMEBOX_MIN_FH_RATIO}) = วางเรียงระดับเดียวกัน ไม่ใช่ขั้น -> ไม่ flag")
            continue
        # v25.55 FIX#3 (จุดเสี่ยงที่ 1): ถ้าทั้งคู่ได้ค่าจาก carry-forward (height_source=None
        # หลัง fill_missing_heights หรือ "carried_forward_same_view") แสดงว่าค่าที่เปรียบ
        # เทียบกันเป็นค่าเดียวกันที่ propagate มาจากตั้งเดียว ไม่ใช่การวัดอิสระ 2 ครั้ง -
        # drop_ratio ที่ได้จะเหมือนกันหรือใกล้กันมากผิดธรรมชาติ (ยืนยันจาก log EB66-01:
        # pairwise idx=1 และ tail_stepdown idx=0 มี drop_ratio=0.23156868... เหมือนกันทุกหลัก
        # พร้อม height_source=None ทั้งคู่) → ไม่ flag ทั้งคู่เพราะไม่มีหลักฐานที่น่าเชื่อถือ
        src_a = a.get("height_source")
        src_b = b.get("height_source")
        _unreliable_sources = (None, "carried_forward_same_view")
        if src_a in _unreliable_sources and src_b in _unreliable_sources:
            continue
        if (shorter_rec.get("height_source") == "direct"
                and shorter_rec.get("n_samples", 999) < STEP_DOWN_MIN_RELIABLE_SAMPLES):
            continue
        if (shorter_rec.get("height_source") == "cross_view_corrected"
                and shorter_rec.get("cross_view_conflict_ratio", 0.0)
                > STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
            continue
        # v25.89 NEW: Isolated-2-Column No-Plateau Guard - ดู docstring เต็มที่
        # _isolated_pair_no_genuine_jump สำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01) - ครอบคลุม
        # กรณีที่ Edge-Column Global Consensus Guard ด้านล่างใช้งานไม่ได้เลย (ต้องการ plateau
        # อย่างน้อย 2 คอลัมน์อื่น แต่ไฟล์นี้มีคอลัมน์รวมทั้งวิวแค่ 2 คอลัมน์ ไม่เหลือ plateau เลย)
        if _isolated_pair_no_genuine_jump(records, view_result):
            continue
        # v25.68 NEW: Edge-Column Global Consensus Guard - ดู docstring เต็มด้านบนสำหรับ
        # หลักฐาน+เหตุผล (พบจริงจาก EB66-01/EC10-03/EC19-01)
        if _is_edge_measurement_outlier(records, shorter_rec["idx"], view_result=view_result):
            continue
        # v25.72 NEW (สำคัญ - พบจริงจาก AB05-01): เดิม Edge-Column Global Consensus Guard เช็ค
        # เฉพาะฝั่ง "เตี้ยกว่า" (shorter_rec) ว่าเป็น edge-column ที่วัดต่ำผิดปกติหรือไม่ (เช่น
        # EB66-01/EC10-03/EC19-01 ที่ขอบแถวถูกวัดเตี้ยกว่าจริง) - แต่ไม่เคยตรวจสอบฝั่ง "สูงกว่า"
        # (taller_rec) เลยว่าอาจเป็น edge-column ที่วัด "สูงเกินจริง" แทน (ทิศทางตรงข้าม) - พบจริง
        # จาก AB05-01 BACK: กล่อง TNC1A-F2 ทั้ง 3 ตั้งสูงเท่ากันจริง (ยืนยันด้วยภาพ, กล่อง SKU
        # เดียวกันทั้งไฟล์ วางเรียงสม่ำเสมอ) แต่ idx0 (คอลัมน์ริมสุด/หัวตู้) วัดได้ 329.78px สูงกว่า
        # idx1(257.5px)/idx2(248.25px) มาก (plateau 2 ตั้งที่เหลือ spread แค่ 3.7% นิ่งมาก) -
        # เมื่อ idx0 กลายเป็น "taller_rec" ในคู่เปรียบเทียบ (idx0 vs idx1) มันถูกใช้เป็นฝั่ง "อ้างอิง
        # ความสูงที่ถูกต้อง" ทำให้ idx1 (ซึ่งจริงๆ สูงปกติ ตรงกับ plateau) ถูกเข้าใจผิดว่า "เตี้ยกว่า"
        # 21.9% ทั้งที่ตัวมันเองไม่ได้ผิดปกติเลย - ต้นเหตุที่แท้จริงคือ idx0 (ไม่ใช่ idx1)
        # FIX: ตรวจสอบ taller_rec ด้วยกฎเดียวกัน (ไม่ว่าจะเป็นตัวที่ถูก mark หรือไม่) - ถ้า
        # taller_rec เป็น edge-column ที่เบี่ยงเบนจาก plateau ของคอลัมน์อื่นเกินเกณฑ์เช่นกัน แสดงว่า
        # "ค่าอ้างอิง" ที่ใช้เปรียบเทียบทั้งคู่ไม่น่าเชื่อถือ ไม่ควร flag ความเสี่ยงจากคู่นี้เลย
        if _is_edge_measurement_outlier(records, taller_rec["idx"], view_result=view_result):
            continue
        # v25.82 NEW (สำคัญ - พบจริงจาก AC03-02, ผู้ใช้ขอให้ตรวจสอบ "back view วาดกรอบไม่ตรง
        # column") - ดู docstring เต็มที่ _has_internal_sharp_jump สำหรับหลักฐาน+เหตุผล: ถ้าฝั่งใด
        # ฝั่งหนึ่ง (taller/shorter) มีรอยกระโดดคมชัดของ cargo_top_y อยู่ลึกกลางคอลัมน์ตัวเอง (ไม่ใช่
        # ใกล้ขอบ) แสดงว่า Phase 1B พลาด seam จริงระหว่างกล่อง 2 ใบสีเดียวกันที่สูงต่างกัน ทำให้ค่า
        # height_px ที่วัดได้เป็นค่าผสม (blend) ของ 2 ความสูงจริง ไม่น่าเชื่อถือพอจะ flag/วาดกรอบ
        # v25.85 FIX (สำคัญ - พบจริงจาก AC03-02, ดู docstring เต็มที่
        # _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES): เพิ่มเงื่อนไข AND n_samples ต่ำ - ไม่ใช่แค่มี
        # jump ก็ suppress ทันทีเหมือน v25.82 เดิม (ซึ่งทำให้ AC03-02 BACK idx7(n=57)/idx8 ความ
        # เสี่ยงจริงถูกระงับผิดพลาด ทั้งที่ robust-fit จัดการ jump ได้เองแล้วเมื่อ n_samples สูงพอ)
        if view_result is not None:
            cty_check = view_result.get("cargo_top_y")
            if cty_check is not None and (
                    (shorter_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                     and _has_internal_sharp_jump(cty_check, shorter_rec["x_range"]))
                    or (taller_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                        and _has_internal_sharp_jump(cty_check, taller_rec["x_range"]))):
                continue
        # v25.77 NEW (สำคัญ - พบจริงจาก AA05-02/AA05-04 หลังทดสอบ v25.76, 31-Aug-2026): เดิม
        # Edge-Column Global Consensus Guard (บรรทัดด้านบน) เช็คแค่คอลัมน์ "ริมสุดของทั้งแถว"
        # (idx==0/max) แต่ไม่ครอบคลุมคู่เปรียบเทียบที่เป็น "คอลัมน์กลาง" ที่บังเอิญคร่อมโซน apex
        # พอดี - ดู docstring เต็มที่ _pair_is_apex_affected สำหรับหลักฐาน+เหตุผล (พบจริงจาก
        # AA05-02/AA05-04: คู่ idx2(283.25px)/idx3(221.82px) ทั้งคู่เป็นสีเขียวเดียวกัน SKU
        # เดียวกัน สูงเท่ากันจริง แต่ apex_x=970 คร่อมโซนนี้พอดี ทำให้ idx3 วัดต่ำกว่าจริงจาก
        # ความชัน isometric ต่อเนื่อง ไม่ใช่ apex ตัดข้อมูลของตัวเอง - guard เดิมทั้งหมดจึงไม่จับ)
        # FIX: ถ้าคู่นี้อยู่ในโซนอิทธิพลของ apex (apex_x ตกอยู่ในช่วง x-range รวมของทั้งคู่) ให้
        # ตรวจสอบเพิ่มเติมด้วย _edge_outlier_has_genuine_seam_jump (ฟังก์ชันเดียวกับที่ Edge-
        # Column Guard ใช้อยู่แล้ว) - ถ้าไม่พบ jump จริงที่ seam (คืนค่า False ชัดเจน) ให้ไม่ flag
        # (ปลอดภัยกว่าเพราะเป็นการเปลี่ยนแปลงราบเรียบต่อเนื่องจาก isometric slope ไม่ใช่ step
        # จริง) - ถ้าตรวจไม่ได้ (None) หรือพบ jump จริง (True) ให้ผ่านตามปกติ (ไม่ suppress โดย
        # ไม่มีหลักฐาน - เช่น AC03-02/AB03-04 ที่ต้องยังคง flag ถูกต้องเหมือนเดิม)
        # v25.77 FIX (สำคัญ - พบ regression จริงจาก AB03-04 ระหว่างทดสอบ): เดิมใช้ guard ใหม่นี้
        # กับทุกคู่ที่ apex-affected โดยไม่สนใจว่าฝั่งใดมี height_source ที่ไม่น่าเชื่อถืออยู่แล้ว
        # (apex_fallback/apex_partial_cut) - พบว่า AB03-04's idx1 (apex_partial_cut, ปนเปื้อน
        # จากปรากฏการณ์ "isometric roof-overhang bleed" ที่หลังคาของกล่องสูงยื่นล้ำมาทับโซน
        # ใกล้ seam) ทำให้ pixel ดิบที่ _edge_outlier_has_genuine_seam_jump ใช้ตรวจสอบ (ไม่กรอง
        # สี) เห็นการเปลี่ยนแปลง "ค่อยเป็นค่อยไป" ที่ seam (คนละสาเหตุกับ AA05-02 แต่ให้ผลลัพธ์
        # เดียวกันคือ False) ทั้งที่เป็นความเสี่ยงจริงที่ยืนยันแล้ว (ผู้ใช้ยืนยันด้วยภาพ 57.4%)
        # FIX: จำกัดให้ guard ใหม่นี้ทำงานเฉพาะเมื่อทั้ง 2 ฝั่งมี height_source == "direct" เท่านั้น
        # (ไม่มีฝั่งใดติดป้าย apex_fallback/apex_partial_cut อยู่แล้ว) - เพราะกรณีที่มีป้ายเหล่านี้
        # ติดอยู่แล้ว มี guard เฉพาะทาง (_APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO แบบ threshold-
        # gated) ดูแลอยู่แล้วอย่างเหมาะสมกว่า ไม่ควรให้ guard ใหม่นี้มาซ้อนทับ/ขัดแย้งกัน
        _both_sides_direct = (taller_rec.get("height_source") == "direct"
                               and shorter_rec.get("height_source") == "direct")
        if (_both_sides_direct and view_result is not None
                and _pair_is_apex_affected(view_result, a, b)):
            has_genuine_jump = _edge_outlier_has_genuine_seam_jump(view_result, shorter_rec, taller_rec)
            if has_genuine_jump is False:
                continue
            # v25.89 NEW (สำคัญ - พบจริงจาก EC26-01 ที่ผู้ใช้แนบ 2-Sep-2026, ผู้ใช้ยืนยันด้วยภาพ
            # ว่า "ตั้งกล่องน้ำเงินและตำแหน่งติดกัน" (ADVSE สีเดียวกัน SKU เดียวกัน) ปกติปลอดภัย
            # แต่ pairwise_floor_jump ยัง flag อยู่): ยืนยันด้วยข้อมูลจริงระดับ pixel ว่า
            # _edge_outlier_has_genuine_seam_jump คืน True ผิดพลาด (window-median scan ถูก
            # ความชันธรรมชาติที่ชันขึ้นใกล้ apex หลอก - ช่วง scan ±40px รอบ seam ไปครอบคลุมโซนที่
            # floor ลาดชันตามธรรมชาติของภาพ isometric ใกล้ apex พอดี ทำให้ median ของหน้าต่างซ้าย/
            # ขวาต่างกันมาก ทั้งที่ cargo_top_y ดิบ (per-pixel) ราบเรียบต่อเนื่องสนิทตลอดช่วง ไม่มี
            # jump คมชัดที่จุดใดเลย - ยืนยันด้วย _has_internal_sharp_jump()=False) - ต่างจาก
            # AC03-02/AB03-04 (ที่ guard นี้ถูกออกแบบมาใช้งานถูกต้อง) ซึ่งมี jump คมชัดจริงแบบ
            # single-pixel step (>=35px ภายใน 1px) ที่ has_internal_sharp_jump ตรวจพบได้เช่นกัน
            # FIX: เพิ่มการตรวจสอบซ้ำด้วย _has_internal_sharp_jump (เชื่อถือได้มากกว่าเพราะดู
            # per-pixel step แทน window-median) - ถ้า _edge_outlier_has_genuine_seam_jump บอกว่า
            # "มี jump จริง" (True) แต่ _has_internal_sharp_jump ไม่พบ jump คมชัดจริงเลยในช่วงรวม
            # ของคู่นี้ ให้เชื่อ _has_internal_sharp_jump แทน (เข้มงวดกว่า, พิสูจน์แล้วว่าแยกแยะ
            # true/false positive ได้แม่นยำใน AC03-02/EA03-01) แล้ว suppress - ไม่กระทบ AC03-02/
            # AB03-04 เดิมเพราะทั้งคู่มี genuine single-pixel jump จริง (has_internal_sharp_jump
            # จะคืน True เช่นกัน ผ่านเงื่อนไขนี้ไปได้ตามปกติ)
            cty_apex_check = view_result.get("cargo_top_y")
            if cty_apex_check is not None:
                lo_ab = min(a["x_range"][0], b["x_range"][0])
                hi_ab = max(a["x_range"][1], b["x_range"][1])
                if not _has_internal_sharp_jump(cty_apex_check, (lo_ab, hi_ab)):
                    continue
        # v25.83 NEW (สำคัญ - พบจริงจาก ED85-01, ดู docstring เต็มที่ _pair_is_apex_residual_zone
        # สำหรับหลักฐาน+เหตุผล): ต่างจาก guard ด้านบน (v25.77) ที่จำกัดเฉพาะ _both_sides_direct -
        # กรณีนี้ taller_rec (idx5) มี height_source="cross_view_corrected" (ไม่ใช่ "direct") จึง
        # ไม่ผ่านเงื่อนไขเดิม แต่ seam-jump verification ตรวจสอบ pixel ดิบ (cargo_top_y) ของ view
        # นี้เองโดยตรง ไม่ได้ขึ้นกับว่า height_px ที่ใช้จริงถูกแก้ไขมาจาก cross-view หรือไม่ - จึงยัง
        # คงแม่นยำในการยืนยัน "ความจริงทางเรขาคณิต" ได้เหมือนเดิม (ต่างจาก apex_partial_cut ที่ต้อง
        # ระวังเพราะ pixel ดิบเองอาจปนเปื้อนจาก roof-overhang bleed - คนละสาเหตุกับ cross_view_
        # corrected ซึ่งเป็นแค่การเลือกใช้ค่าจากอีก view เท่านั้น ไม่กระทบ pixel ดิบของ view นี้เอง)
        # FIX: ผ่อนคลายเงื่อนไขให้ยอมรับ "cross_view_corrected"/"cross_view_filled" เพิ่มจาก
        # "direct" เดิม (ยังคงกัน apex_fallback/apex_partial_cut ออกเสมอทั้ง 2 ฝั่ง เพราะมีความเสี่ยง
        # pixel ปนเปื้อนโดยเฉพาะตามที่ AB03-04 พิสูจน์ไว้) และตรวจสอบเงื่อนไข apex เพิ่มเติมด้วย
        # _pair_is_apex_residual_zone (ครอบคลุมกรณี 'ทั้งคู่อยู่ฝั่งเดียวกันของ apex' ที่
        # _pair_is_apex_affected เดิมไม่ครอบคลุม)
        _reliable_sources = ("direct", "cross_view_corrected", "cross_view_filled")
        _both_sides_reliable = (taller_rec.get("height_source") in _reliable_sources
                                 and shorter_rec.get("height_source") in _reliable_sources)
        if (_both_sides_reliable and view_result is not None
                and (_pair_is_apex_affected(view_result, a, b)
                     or _pair_is_apex_residual_zone(view_result, a, b))):
            has_genuine_jump2 = _edge_outlier_has_genuine_seam_jump(view_result, shorter_rec, taller_rec)
            if has_genuine_jump2 is False:
                continue
            # v25.89 NEW: mirror จากจุดเดียวกันด้านบน (_both_sides_direct block) - ดู docstring
            # เต็มที่นั่นสำหรับหลักฐาน+เหตุผล (พบจริงจาก EC26-01)
            cty_apex_check2 = view_result.get("cargo_top_y")
            if cty_apex_check2 is not None:
                lo_ab2 = min(a["x_range"][0], b["x_range"][0])
                hi_ab2 = max(a["x_range"][1], b["x_range"][1])
                if not _has_internal_sharp_jump(cty_apex_check2, (lo_ab2, hi_ab2)):
                    continue
        threshold = taller_h * (1 - STEP_DOWN_PAIRWISE_DROP_RATIO)
        floor_jump = None
        # v25.71 NEW (สำคัญ - พบจริงจาก ED84/ED85-01/02/03, 30-Aug-2026): เดิมไม่มี reliability
        # guard ใดๆ เลยสำหรับ height_source="apex_fallback" (guard ที่มีอยู่เดิมเช็คแค่ n_samples
        # เมื่อ height_source=="direct" เท่านั้น) ทั้งที่ docstring ของ compute_stack_heights_px
        # เองระบุไว้ชัดเจนแล้วว่า apex_fallback คือค่าที่วัดจากช่วง "หลังจุดยอด isometric" ซึ่ง
        # "เอียงคนละทิศ, height ผิดเพี้ยนเป็นระบบ" (ไม่ใช่แค่ noise สุ่ม แต่เป็น bias ที่รู้ทิศทาง
        # อยู่แล้ว) - ยืนยันด้วยข้อมูลจริงข้าม 4 ไฟล์ที่ไม่เกี่ยวข้องกันเลย (ED84, ED85-01/02/03):
        # ทุกไฟล์มี apex_fallback ที่คอลัมน์ริมสุดของ view ได้ n_samples=67 "เหมือนกันเป๊ะ" (ต่าง
        # SKU/ขนาดกล่องกันคนละไฟล์ - เป็นไปไม่ได้ทางสถิติที่จะบังเอิญเท่ากันขนาดนี้ถ้าเป็นการวัด
        # กล่องจริง) พิสูจน์ว่าเป็น artifact ทางเรขาคณิตที่ผูกกับตำแหน่ง apex คงที่ของ container
        # (scale/มุมกล้องเดียวกัน) ไม่ใช่ความสูงกล่องจริง - เกิดปัญหาซ้ำในทั้ง detect_step_down_
        # pairwise, detect_step_down_crossview, และ detect_tail_stepdown (ทุกกลไกที่ไม่เคยตรวจ
        # source นี้มาก่อน)
        # FIX: ถ้าฝั่งที่ "เตี้ยกว่า" (จะถูกใช้เป็นหลักฐาน flag ความเสี่ยง) เป็น apex_fallback ให้
        # ไม่ flag เลย (เฉพาะ subtype='pairwise' ที่ใช้ threshold เทียบความสูงตรงๆ เท่านั้น -
        # ไม่กระทบ subtype='pairwise_floor_jump' ด้านล่างซึ่งมีหลักฐานอิสระคนละตัว คือ floor_jump
        # ที่วัดจากพื้นตู้ ไม่ใช่ยอดกล่อง จึงไม่ได้รับผลกระทบจาก apex bias นี้)
        if shorter_rec.get("height_source") == "apex_fallback":
            continue
        # v25.83 NEW (สำคัญ - พบจริงจาก ED85-02/ED85-03, 31-Aug-2026 - ผู้ใช้ระบุว่า FRONT view
        # วาดกรอบตรงกล่องสีม่วง TGT1G ทั้งที่ไม่ควรต้องวาด): เดิม guard ด้านบน (v25.71) เช็คเฉพาะ
        # shorter_rec (ฝั่งที่จะถูก flag ว่า "เตี้ยกว่า") ว่าเป็น apex_fallback หรือไม่ - แต่ไม่เคย
        # ตรวจสอบ taller_rec (ฝั่งที่ใช้เป็น "ค่าอ้างอิงความสูงกว่า" สำหรับคำนวณ drop_ratio) เลย
        # ทั้งที่ apex_fallback เป็นค่าที่ระบบเองยืนยันแล้วว่า "เอียงคนละทิศ, height ผิดเพี้ยนเป็น
        # ระบบ" ไม่ว่าจะถูกใช้เป็นฝั่งไหนก็ตาม - ยืนยันด้วยข้อมูลจริง ED85-02/03: FRONT idx7
        # (x_range กว้างเท่าคอลัมน์ปกติ, height_source="apex_fallback", h=306.3px/307.3px) ถูกใช้
        # เป็น taller_rec เทียบกับ idx8 (h=177.2px, direct) ได้ drop_ratio=42.1%/42.3% เกินเกณฑ์
        # 20% มาก - ทำให้เกิด STEP_DOWN_RISK ที่วาดกรอบคร่อมตำแหน่งกล่องผิดพลาด (ไม่มีหลักฐานอื่น
        # ยืนยันว่า idx7 สูงจริง 306px - อาจเป็นค่าที่เอนเอียงจาก apex bias เดียวกับที่ v25.71
        # พิสูจน์ไว้แล้ว ทำให้ไม่ควรเชื่อว่าเป็น "ค่าอ้างอิงที่ถูกต้อง" สำหรับคำนวณ drop_ratio)
        # FIX: เพิ่มการตรวจสอบ taller_rec ด้วยเงื่อนไขเดียวกัน - ถ้า taller_rec เป็น apex_fallback
        # เช่นกัน ไม่ flag ความเสี่ยงจากคู่นี้เลย (ค่าอ้างอิงไม่น่าเชื่อถือพอจะใช้ตัดสิน)
        if taller_rec.get("height_source") == "apex_fallback":
            continue
        # v25.76 NEW (สำคัญ - พบจริงจาก AB03-04 ที่ผู้ใช้ระบุ "ตำแหน่งฟ้าท้ายสุด ยังมีกรอบแดง
        # คือกรอบซ้ายสุด" หลังทดสอบ v25.75, 31-Aug-2026): เดิม guard ด้านบนเช็คเฉพาะ
        # height_source=="apex_fallback" (กรณี apex ตัดข้อมูลจนเหลือ<3จุด ต้อง fallback ใช้ช่วง
        # เต็ม) แต่ไม่เคยครอบคลุมกรณี "apex ตัดข้อมูลกลางคอลัมน์จริง (>=3 จุดเหลือ แต่ coverage
        # ต่ำ)" ซึ่งได้ label ใหม่ "apex_partial_cut" (v25.76 - ดู docstring เต็มที่
        # compute_stack_heights_px ใกล้ตัวแปร apex_mid_cut) - ทิศทางของความเอนเอียงที่ยืนยันแล้ว
        # คือ "อาจสูงเกินจริง" (eff_mid ถูกเลื่อนเข้าใกล้ apex/จุดสูงสุดของเส้นโค้ง isometric มาก
        # ขึ้นเมื่อ coverage ยิ่งต่ำ) - ถ้าถูกใช้เป็น taller_rec (ค่าอ้างอิง "สูงกว่า") ความเอนเอียง
        # นี้จะทำให้ drop_ratio ที่คำนวณได้ "สูงเกินจริง" ไปด้วย เสี่ยง false-positive เมื่อ
        # drop_ratio ที่แท้จริงอยู่ในโซนก้ำกึ่ง (ยืนยันจาก AB03-04: idx1(apex_partial_cut,taller)
        # vs idx0(shorter) drop=14.5% - เกิดจากความเอนเอียงล้วนๆ ควร suppress)
        # ROOT CAUSE ที่ต้องระวัง (พบระหว่างทดสอบ): ถ้า suppress "เสมอ" ทุกครั้งที่ taller_rec
        # เป็น apex_partial_cut โดยไม่ดู drop_ratio เลย จะไปกระทบคู่อื่นที่ apex_partial_cut ยังคง
        # เป็นค่าอ้างอิงที่ถูกต้องเพียงพอ (ยืนยันจาก AB03-04 เช่นกัน: idx1(apex_partial_cut,
        # taller) vs idx2(shorter,navy) drop=57.4% - เป็นความเสี่ยงจริงที่ผู้ใช้ยืนยันแล้ว ไม่ควร
        # suppress เพราะความเอนเอียงระดับ ~15-20% ไม่มีทางอธิบาย drop สูงถึง 57% ได้)
        # FIX: จำกัดการ suppress เฉพาะเมื่อ drop_ratio อยู่ในโซนก้ำกึ่งที่ความเอนเอียงอาจอธิบายได้
        # จริง (ต่ำกว่า _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO=0.25) - ถ้า drop_ratio สูงเกิน
        # เกณฑ์นี้ ให้เชื่อว่าเป็นความเสี่ยงจริง ไม่ suppress (ปลอดภัยสำหรับทั้ง 2 กรณีที่ยืนยัน
        # แล้วจาก AB03-04)
        _drop_check = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
        if (taller_rec.get("height_source") == "apex_partial_cut"
                and _drop_check < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
            continue
        # v25.84 NEW (สำคัญ - พบจริงจาก EA03-01, ดู docstring เต็มที่ _APEX_PARTIAL_CUT_MIN_SAMPLES
        # สำหรับหลักฐาน+เหตุผล): guard ด้านบน (v25.76) ใช้แค่ drop_ratio ตัดสินใจ - ไม่ครอบคลุมกรณีที่
        # apex_partial_cut มี n_samples ต่ำผิดปกติมาก (3 จุด เทียบปกติ 41-47 จุด) จนค่าที่วัดได้ไม่มี
        # ความหมายทางกายภาพเลย แม้ drop_ratio จะสูงกว่าเกณฑ์เดิมก็ตาม (เพราะ drop_ratio คำนวณจากค่าที่
        # ผิดพลาดตั้งแต่ต้น ไม่ใช่สัญญาณที่เชื่อถือได้อีกต่อไป) - ตรวจสอบทั้ง taller/shorter เพราะฝั่ง
        # ใดก็ตามที่ n_samples ต่ำขนาดนี้ไม่ควรถูกใช้เป็นค่าอ้างอิงหรือเป้าหมายเลย
        if (taller_rec.get("height_source") == "apex_partial_cut"
                and taller_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
            # v26.02 FIX #2 (ผู้ใช้แจ้ง "gc06 back view ไม่มีการวิเคราะห์วาดกรอบเลย"):
            # guard นี้ (v25.84) ตัดสินจาก "คอลัมน์อ้างอิง (ตัวสูงกว่า)" ว่าไม่น่าเชื่อถือ
            # แล้วทิ้งทั้งคู่ - แต่ถ้า "ตัวที่เตี้ย" เองวัดได้น่าเชื่อถือเต็มที่ และเตี้ยกว่า
            # plateau ของคอลัมน์อื่นที่นิ่งมากอย่างสุดขั้ว การทิ้งไปทั้งคู่ทำให้พลาดความเสี่ยง
            # จริงที่ชัดเจนที่สุดในไฟล์ ยืนยันด้วย pixel จริงจาก GC06 BACK ตู้ที่ 2:
            #   idx8(183px, apex_partial_cut, n=11) <-> idx9(76.1px, direct, n=39) drop=58.4%
            #   plateau ของคอลัมน์อื่น = [195,196,183,183] spread=6.6% (นิ่งมาก)
            #   idx9 ต่ำกว่า plateau median 59.8% -> ความเอนเอียงจากการวัดอธิบายไม่ได้
            # FIX: ถ้าตัวที่เตี้ยเชื่อถือได้ (direct/cross_view_filled และ n>=เกณฑ์ปกติ) และ
            # เบี่ยงเบนจาก plateau ที่นิ่งเกิน _APEX_GUARD_OVERRIDE_MIN_DEVIATION ให้ flag ต่อ
            # โดยไม่ต้องพึ่งคอลัมน์อ้างอิงที่ไม่น่าเชื่อถือ (ใช้ plateau เป็นตัวอ้างอิงแทน)
            # ขอบเขตแคบมาก: ต้องผ่านครบทั้ง 4 เงื่อนไข จึงไม่กระทบไฟล์ที่ guard เดิมคุ้มครองอยู่
            # (EA03-01 ที่ guard นี้สร้างขึ้นมาแก้: shorter เป็น apex_partial_cut n=3 ไม่ใช่
            #  direct จึงไม่เข้าเงื่อนไขนี้เลย ยังคงถูก suppress เหมือนเดิมทุกประการ)
            _ov = _apex_guard_plateau_override(records, shorter_rec, view_result)
            if not _ov:
                continue
            print(f"[APEX_GUARD_OVERRIDE] {view_label} idx={shorter_rec['idx']} "
                  f"h={shorter_h:.1f} เตี้ยกว่า plateau({_ov['plateau']:.1f}px "
                  f"spread={_ov['spread']:.1%}) ถึง {_ov['deviation']:.1%} "
                  f"-> ข้าม apex guard (ตัวอ้างอิง n={taller_rec.get('n_samples')} ไม่น่าเชื่อถือ "
                  f"แต่ตัวเตี้ยเชื่อถือได้ n={shorter_rec.get('n_samples')})")
        if (shorter_rec.get("height_source") == "apex_partial_cut"
                and shorter_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
            continue
        # v25.74 NEW: Multi-Color Merge Recheck Guard - mirror จาก detect_step_down_crossview
        # ทุกประการ (ดู docstring เต็มที่ _recheck_stack_height_via_color สำหรับหลักฐาน+เหตุผล -
        # พบจริงจาก AB03-04) - ใช้ view_result เดียวกันของทั้งคู่เพราะเป็น pairwise (view เดียวกัน)
        pairwise_recheck_suppressed = False
        if view_result is not None:
            expected_colors = view_result.get("stack_expected_colors")
            def _expected_color_of_pw(rec):
                if expected_colors is None or rec["idx"] >= len(expected_colors):
                    return None
                return expected_colors[rec["idx"]]
            taller_color_pw = _expected_color_of_pw(taller_rec)
            shorter_color_pw = _expected_color_of_pw(shorter_rec)
            if shorter_color_pw is None and taller_color_pw is not None:
                recheck = _recheck_stack_height_via_color(
                    view_result, shorter_rec["x_range"], taller_color_pw)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (recheck_h / taller_h) if taller_h > 0 else 0
                    print(f"[RECHECK_PAIRWISE] view={view_label} shorter idx={shorter_rec['idx']} "
                          f"multi-color merge - recheck สี {taller_color_pw} ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n},resid={recheck_resid:.2f}) เทียบเดิม={shorter_h:.1f}px "
                          f"-> recheck_drop={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_PAIRWISE_DROP_RATIO:
                        pairwise_recheck_suppressed = True
            elif taller_color_pw is None and shorter_color_pw is not None:
                recheck = _recheck_stack_height_via_color(
                    view_result, taller_rec["x_range"], shorter_color_pw)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (shorter_h / recheck_h) if recheck_h > 0 else 0
                    print(f"[RECHECK_PAIRWISE] view={view_label} taller idx={taller_rec['idx']} "
                          f"multi-color merge - recheck สี {shorter_color_pw} ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n},resid={recheck_resid:.2f}) เทียบเดิม={taller_h:.1f}px "
                          f"-> recheck_drop={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_PAIRWISE_DROP_RATIO:
                        pairwise_recheck_suppressed = True
        if pairwise_recheck_suppressed:
            continue
        if shorter_h < threshold:
            drop_ratio = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
            risks.append({
                "risk_type": "STEP_DOWN_RISK", "subtype": "pairwise", "view": view_label,
                "mark_view": view_label,
                "mark_stack_idx": taller_rec["idx"], "mark_x_range": taller_rec["x_range"],
                "taller_height_px": taller_h, "shorter_height_px": shorter_h,
                "drop_ratio": drop_ratio, "pair_indices": (a["idx"], b["idx"]),
                # v25.57 NEW: เก็บ height_source/n_samples ของฝั่ง shorter (ตัวที่ตัดสินใจ flag
                # หรือไม่) ไว้จริงใน risk dict เพื่อให้ debug print ตรวจสอบได้ (เดิม print เห็น
                # None เสมอเพราะ key นี้ไม่เคยถูกใส่)
                "height_source": shorter_rec.get("height_source"),
                "n_samples": shorter_rec.get("n_samples"),
            })
        elif local_floor_y is not None:
            drop_ratio_check = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
            if drop_ratio_check >= 0.125:
                x0a, x1a = a["x_range"]
                x0b, x1b = b["x_range"]
                if x1a <= x0b:
                    floor_jump = _p1b_compute_floor_jump(local_floor_y, x0a, x1a, x1b)
                elif x1b <= x0a:
                    floor_jump = _p1b_compute_floor_jump(local_floor_y, x0b, x1b, x1a)
                if floor_jump is not None and floor_jump >= STEP_DOWN_FLOOR_JUMP_MIN_PX:
                    risks.append({
                        "risk_type": "STEP_DOWN_RISK", "subtype": "pairwise_floor_jump",
                        "view": view_label, "mark_view": view_label,
                        "mark_stack_idx": shorter_rec["idx"], "mark_x_range": shorter_rec["x_range"],
                        "taller_height_px": taller_h, "shorter_height_px": shorter_h,
                        "drop_ratio": drop_ratio_check, "pair_indices": (a["idx"], b["idx"]),
                        "floor_jump_px": floor_jump,
                        # v25.57 NEW: ดูหมายเหตุเดียวกับ subtype 'pairwise' ด้านบน
                        "height_source": shorter_rec.get("height_source"),
                        "n_samples": shorter_rec.get("n_samples"),
                    })
    return risks


def detect_step_down_hidden_behind(view_result, records, view_label):
    """v25.23 NEW: STEP_DOWN_RISK (hidden_behind) - ตรวจกล่องแถวหลัง (ข้ามความกว้างตู้) ที่
    ซ่อนอยู่หลังกล่องแถวหน้าในคอลัมน์เดียวกัน แต่สูงกว่าจนหลังคาโผล่พ้นขึ้นมา (top-face
    bleed-through) - คนละกลไกจาก pairwise/cross_view เดิม (ซึ่งเทียบระหว่างคอลัมน์ ไม่ใช่
    ภายในคอลัมน์เดียวกัน) ใช้ _detect_hidden_behind_split เป็นตัวตรวจจับ (ดู docstring
    ที่นั่นสำหรับหลักฐาน+เกณฑ์เต็ม) ข้ามคอลัมน์ที่เป็น is_corner_duplicate=True เสมอ (เข้ากับ
    กฎเดิมทั้ง 3 ข้อ - ไม่ flag บริเวณมุมกล้องที่รู้อยู่แล้วว่านับซ้ำ)

    วาด marker เฉพาะ 'โซนที่กล่องซ่อนหลังโผล่ให้เห็น' (จาก split_x ถึงขอบคอลัมน์) ไม่ใช่ทั้ง
    คอลัมน์ เพื่อความแม่นยำของตำแหน่งกรอบ (คำนวณ abs_box ตรงที่นี่เลย แทนการพึ่ง
    risk_abs_box+stack_heights เดิม เพราะ 'ตั้ง' นี้ไม่ได้มี index ของตัวเองใน stack_heights)

    v25.70 NEW (สำคัญ - พบจริงจาก EE03-01, ดู docstring เต็มที่ _detect_hidden_behind_split
    สำหรับหลักฐาน+เหตุผล): รองรับทิศทาง 'down' เพิ่มเติม (ฝั่งซ้าย/ก่อน split สูงกว่า) นอกเหนือ
    จากทิศทาง 'up' เดิม (ฝั่งขวา/หลัง split สูงกว่า) - ทั้ง 2 ทิศทาง mark 'ฝั่งที่สูงกว่า' เสมอ
    (ตรงกับหลักการเดียวกับ STEP_DOWN_RISK subtype อื่นทั้งหมดที่ mark กองสูงกว่าเป็นแหล่งเสี่ยง
    ล้มทับกองเตี้ยกว่า) - ทิศทาง 'up': mark จาก split_x ถึง x1 (พฤติกรรมเดิมทุกประการ) | ทิศทาง
    'down': mark จาก x0 ถึง split_x แทน (ฝั่งที่สูงกว่าอยู่ก่อน split)"""
    risks = []
    hidden_behind = view_result.get("hidden_behind", {})
    ox, oy = view_result["crop_origin_x"], view_result["crop_origin_y"]
    local_floor_y = view_result["local_floor_y"]
    for idx, info in hidden_behind.items():
        if idx >= len(records):
            continue
        parent = records[idx]
        if parent.get("is_corner_duplicate"):
            continue
        split_x, x1 = info["split_x"], info["x1"]
        x0 = info.get("x0", split_x)  # v25.70: fallback=split_x กันพังถ้า key ไม่มี (เผื่อ
        # เรียกจากที่อื่นที่ยังไม่ได้อัพเดต - ไม่ควรเกิดขึ้นจริงเพราะแก้ที่เดียวกันแล้ว)
        hidden_h = info["hidden_height"]
        direction = info.get("direction", "up")  # v25.70 NEW: default='up' รักษาพฤติกรรมเดิม
        # v25.90 FIX #3 (สำคัญ - พบจริงจาก EB66-01 ที่ผู้ใช้ยืนยันว่า "ไม่มีความเสี่ยง" แต่ v25.89
        # flag STEP_DOWN_RISK/hidden_behind ที่ FRONT idx=2, 10-Sep-2026): ทิศทาง 'up' (v25.23 เดิม)
        # แทบไม่มี guard ใดๆ เลย (ต่างจากทิศทาง 'down' ที่ v25.70 เพิ่ม SNR + floor-stability ไว้)
        # ยืนยันด้วยข้อมูล pixel จริง: split_x=841 มี jump=75px, left_std=0.37, right_std=0.73
        # (นิ่งมากทั้ง 2 ฝั่ง), floor jump=1.8px (นิ่ง), cargo_bottom jump=2.5px (นิ่ง), สี 2 ฝั่ง
        # ต่างกัน (ม่วง->เหลือง) - ผ่าน guard เดิมทุกข้อ แต่ตรวจสอบภาพจริงระดับ pixel พบว่าเป็น
        # "depth-offset artifact" ล้วนๆ: ฝั่งซ้ายของ split คือ "หลังคา (top face) ของกล่องแถวหน้า"
        # (TVI1A-BN ฟ้า) ที่สิ้นสุดพอดี และฝั่งขวาคือ "หลังคาของกล่องแถวหลัง" (TAI1A-D1 เหลือง) ที่
        # เริ่มต้น - ในมุมมอง isometric แถวหลังถูกวาดสูงกว่าบนหน้ากระดาษเสมอแม้จะสูงเท่ากันจริง
        # หลักฐานยืนยันว่าทั้งคู่สูงเท่ากันจริง: เหนือทั้ง 2 ฝั่งคือรางเพดานตู้ (olive) ติดกันสนิท
        # ไม่มีช่องว่างสีขาวเลย + BACK view ของไฟล์เดียวกันแสดงหลังคาเป็นระนาบเรียบต่อเนื่องทั้งคัน
        # ROOT CAUSE เชิงกายภาพ: hidden_behind จะเป็น "อันตราย" ก็ต่อเมื่อกล่องที่ซ่อนอยู่ข้างหลัง
        # "โผล่สูงพ้นระดับหลังคาสินค้าทั่วไป" จริง (เช่น AE02-01 ที่มีกล่องแดงซ้อนเป็นชั้นที่ 3 สูง
        # กว่าทุกกองอย่างชัดเจน) - ถ้าความสูงที่วัดได้ของฝั่งที่ "ซ่อนอยู่" เสมอกับระดับหลังคาปกติ
        # ของทั้งวิวอยู่แล้ว แสดงว่าไม่มีอะไรโผล่พ้นขึ้นมาเลย เป็นแค่ความเอนเอียงจากมุมมองเชิงลึก
        # ยืนยันตัวเลข EB66-01 FRONT: hidden_height=337.0 เทียบ median ความสูงของคอลัมน์อื่นในวิว
        # เดียวกัน (ไม่รวมคอลัมน์นี้เอง) = 305.5 -> สูงกว่าแค่ 10.3% (เสมอระดับหลังคาปกติ ไม่ได้โผล่)
        # FIX: เพิ่ม guard เฉพาะทิศทาง 'up' - ถ้า hidden_height ไม่ได้สูงกว่า median ของคอลัมน์อื่น
        # เกิน _HIDDEN_BEHIND_UP_MIN_EXCESS_RATIO ให้ถือว่าเป็น depth-offset artifact ไม่ flag
        # (ไม่กระทบทิศทาง 'down' เดิมเลย และไม่กระทบกรณีที่กล่องโผล่สูงพ้นจริงซึ่งจะสูงกว่า median
        # มากกว่านี้มาก - ชั้นกล่องเพิ่ม 1 ชั้นตามปกติคิดเป็น ~25-35% ของความสูงกองทั้งหมด)
        if direction == "up":
            # v26.21: UNBROKEN ISOMETRIC ROOF-LINE GUARD
            # (ดู docstring + หลักฐาน pixel เต็มที่ _HB_ISO_ROOF_SLOPE)
            _cty_g = view_result.get("cargo_top_y")
            if _cty_g is not None:
                _cty_g = np.asarray(_cty_g, int)
                _off = _HB_ISO_ROOF_EDGE_OFFSET_PX

                def _roof_win(_a, _b):
                    # clip เข้าคอลัมน์ Phase1B เสมอ - ห้ามให้ล้ำไปโดนช่องว่างระหว่างตู้
                    _a = max(_a, x0, 0)
                    _b = min(_b, x1, len(_cty_g))
                    _xs = [x for x in range(_a, _b) if _cty_g[x] >= 0]
                    return _xs, [float(_cty_g[x]) for x in _xs]

                _lx, _ly = _roof_win(split_x - _HB_ISO_ROOF_WIN_PX - _off, split_x - _off)
                _rx, _ry = _roof_win(split_x + _off, split_x + _HB_ISO_ROOF_WIN_PX + _off)
                if len(_lx) >= _HB_ISO_ROOF_MIN_PTS and len(_rx) >= _HB_ISO_ROOF_MIN_PTS:
                    _lfit = _robust_local_line_fit(_lx, _ly)
                    if _lfit is not None:
                        _lslope = float(_lfit.get("a", 0.0))
                        _lresid = float(_lfit.get("resid_std", 999.0))
                        _lmx, _lmy = float(np.median(_lx)), float(np.median(_ly))
                        _rmx, _rmy = float(np.median(_rx)), float(np.median(_ry))
                        _expected = _lmy + _HB_ISO_ROOF_SLOPE * (_rmx - _lmx)
                        _excess = _expected - _rmy   # >0 = ยอดฝั่งขวาลอยเหนือเส้น = สูงกว่าจริง
                        if (abs(_lslope - _HB_ISO_ROOF_SLOPE) <= _HB_ISO_ROOF_SLOPE_TOL
                                and _lresid <= _HB_ISO_ROOF_MAX_RESID
                                and _excess <= _HB_ISO_ROOF_MAX_EXCESS_PX):
                            print(f"[HB_ISO_ROOF] view={view_label} idx={idx} split_x={split_x} "
                                  f"เส้นยอดฝั่งซ้าย slope={_lslope:.3f} resid_std={_lresid:.2f} "
                                  f"(= เส้น isometric สะอาด) และยอดฝั่งขวาสูงกว่าเส้นเพียง "
                                  f"{_excess:.1f}px (เกณฑ์ {_HB_ISO_ROOF_MAX_EXCESS_PX}) "
                                  f"-> หลังคาต่อเนื่องเป็นระนาบเดียว ไม่มีกล่องโผล่พ้นจริง "
                                  f"(jump {info['jump_px']:.1f}px มาจาก floor artifact) ไม่ flag")
                            continue
            others = [r.get("height_px") for r in records
                      if r.get("idx") != idx and r.get("height_px")
                      and r.get("height_source") in ("direct", "cross_view_filled",
                                                     "cross_view_corrected", "apex_partial_cut")]
            if len(others) >= 2:
                med_other = float(np.median(others))
                if med_other > 0 and hidden_h <= med_other * (1 + _HIDDEN_BEHIND_UP_MIN_EXCESS_RATIO):
                    print(f"[HIDDEN_BEHIND_UP_GUARD] view={view_label} idx={idx} "
                          f"hidden_h={hidden_h:.1f} <= median_other({med_other:.1f})*"
                          f"{1 + _HIDDEN_BEHIND_UP_MIN_EXCESS_RATIO:.2f} -> depth-offset artifact "
                          f"(กล่องหลังไม่ได้โผล่พ้นระดับหลังคาปกติ) ไม่ flag")
                    continue

        if direction == "down":
            mark_x0, mark_x1 = x0, split_x
        else:
            mark_x0, mark_x1 = split_x, x1
        # v25.70 NEW (สำคัญ - พบจริงจาก EE03-01): เดิม mark_x0/mark_x1 อาจแคบมาก (พบจริง 10px
        # เท่านั้น) เพราะ boundary ของ Phase 1B (x0/x1 ของคอลัมน์) วางคลาดเคลื่อนจากตำแหน่ง split
        # จริงเล็กน้อย ทำให้กรอบที่วาดได้เป็นเส้นบางแนวตั้งแทบมองไม่เห็น แทนที่จะเป็นกรอบสี่เหลี่ยม
        # ชัดเจนเหมือนกรอบคอลัมน์ทั่วไป - ใช้หลักการเดียวกับที่แก้ silhouette_notch ไปแล้ว (v25.69):
        # ถ้าความกว้างที่คำนวณได้ต่ำกว่าเกณฑ์ขั้นต่ำ ให้ pad สมมาตรทั้ง 2 ฝั่งจนถึงเกณฑ์นี้ (จำกัด
        # ไม่ให้เกินขอบเขตของ view เพื่อไม่ให้กรอบล้นออกไปนอกภาพ)
        if (mark_x1 - mark_x0) < _NOTCH_BOX_MIN_WIDTH_PX:
            pad = (_NOTCH_BOX_MIN_WIDTH_PX - (mark_x1 - mark_x0)) / 2.0
            view_sx = view_result.get("start_x", mark_x0)
            view_ex = view_result.get("end_x", mark_x1)
            mark_x0 = max(view_sx, int(round(mark_x0 - pad)))
            mark_x1 = min(view_ex, int(round(mark_x1 + pad)))
        xm = (mark_x0 + mark_x1) // 2
        floor_y_local = local_floor_y[xm] if 0 <= xm < len(local_floor_y) and local_floor_y[xm] >= 0 else None
        if floor_y_local is None:
            continue
        top_y_local = floor_y_local - hidden_h
        # v26.16 NEW: BOX-SUPPORT GUARD - กรอบต้องมี "สินค้าจริง" รองรับที่ขอบบนของมัน
        # (ดู docstring + หลักฐานตัวเลขที่ _HIDDEN_BEHIND_MIN_TOP_SUPPORT)
        _cm_sup = view_result.get("cargo_mask")
        if _cm_sup is not None:
            _by0 = int(max(0, top_y_local))
            _by1 = int(min(_cm_sup.shape[0], floor_y_local))
            _band = max(_HIDDEN_BEHIND_TOP_BAND_MIN_PX,
                        int((_by1 - _by0) * _HIDDEN_BEHIND_TOP_BAND_FRAC))
            _bx0 = int(max(0, mark_x0))
            _bx1 = int(min(_cm_sup.shape[1], mark_x1))
            _sub = _cm_sup[_by0:min(_by0 + _band, _by1), _bx0:_bx1]
            if _sub.size:
                _support = float(_sub.mean())
                if _support < _HIDDEN_BEHIND_MIN_TOP_SUPPORT:
                    print(f"[HB_BOX_SUPPORT] view={view_label} idx={idx} แถบบนของกรอบมีสินค้า "
                          f"{_support:.3f} < {_HIDDEN_BEHIND_MIN_TOP_SUPPORT} -> กรอบลอยเหนือ "
                          f"กองสินค้า (ความสูงที่วัดได้ไม่มี pixel รองรับ) ไม่ flag")
                    continue
        abs_box = (ox + mark_x0, oy + top_y_local, ox + mark_x1, oy + floor_y_local)
        risks.append({
            "risk_type": "STEP_DOWN_RISK", "subtype": "hidden_behind", "view": view_label,
            "mark_view": view_label, "mark_stack_idx": idx, "mark_x_range": (mark_x0, mark_x1),
            "taller_height_px": hidden_h, "shorter_height_px": info["front_height"],
            "drop_ratio": 1 - (info["front_height"] / hidden_h) if hidden_h > 0 else 0,
            "jump_px": info["jump_px"], "abs_box": abs_box,
        })
    return risks


def _overlapping_records(target_pos_range, other_records, min_overlap_ratio=CROSSVIEW_MIN_OVERLAP_RATIO):
    t0, t1 = target_pos_range
    t_width = max(1e-6, t1 - t0)
    matches = []
    for rec in other_records:
        r0, r1 = rec["pos_range"]
        r_width = max(1e-6, r1 - r0)
        inter = max(0.0, min(t1, r1) - max(t0, r0))
        smaller = min(t_width, r_width)
        if smaller > 0 and (inter / smaller) >= min_overlap_ratio:
            matches.append(rec)
    return matches
  
def _dedup_overlapping_stepdown_risks(risks):
    """v25.57 NEW: ถ้า 'pairwise'/'pairwise_floor_jump' (จาก detect_step_down_pairwise) และ
    'tail_stepdown' (จาก detect_tail_stepdown) flag คู่ column (view, pair_indices - ไม่สน
    ลำดับ) เดียวกัน ให้เก็บเฉพาะ pairwise/pairwise_floor_jump ไว้ (ตัด tail_stepdown ที่ซ้ำซ้อน
    ทิ้ง) - ดู docstring ที่จุดเรียกใช้ใน run_full_analysis_on_image สำหรับหลักฐาน+เหตุผลเต็ม
    (พบจริงจาก log EB66-01 29-Aug-2026)
    """
    def _pair_key(r):
        pi = r.get("pair_indices")
        if pi is None:
            return None
        return (r.get("view") or r.get("mark_view"), tuple(sorted(pi)))

    pairwise_keys = {
        _pair_key(r) for r in risks
        if r.get("risk_type") == "STEP_DOWN_RISK"
        and r.get("subtype") in ("pairwise", "pairwise_floor_jump")
        and _pair_key(r) is not None
    }
    # v25.79 NEW (สำคัญ - พบจริงจาก EA02-01 31-Aug-2026, ผู้ใช้ระบุว่า EA02-01 ควรถูกตรวจจับ
    # เหมือนไฟล์ทั่วไป ไม่ควรมีกรอบซ้ำซ้อน): เดิม dedup ด้านบนจับคู่เฉพาะ tail_stepdown vs
    # pairwise ผ่าน (view, pair_indices) เท่านั้น - แต่ detect_step_down_crossview ก็สามารถ
    # flag "คอลัมน์เดียวกันเป๊ะ" ซ้ำกับ pairwise ได้เช่นกัน (คนละกลไก คนละหลักฐาน แต่ชี้ตำแหน่ง
    # เดียวกัน) ยืนยันจาก log จริง: EA02-01 FRONT idx=1 ถูก flag ทั้งจาก pairwise (pair_indices=
    # (0,1), drop=34.6%, เทียบกับ idx0 ข้างเคียง) และจาก cross_view (drop=43.2%, เทียบกับ BACK
    # ตำแหน่งเดียวกัน) พร้อมกัน โดยทั้งคู่ mark_x_range=(860,1028) เหมือนกันเป๊ะ (ตำแหน่งวาดกรอบ
    # ซ้อนทับกันสนิท) - cross_view ไม่มี key "pair_indices"/"view" เหมือน tail_stepdown เลย
    # (มีแค่ mark_view+mark_stack_idx) จึง dedup เดิมจับไม่ได้ ทำให้นับ hazardCount เกินจริง +
    # วาดกรอบซ้อนกัน 2 ครั้งที่ตำแหน่งเดียวกัน (ผู้ใช้เห็นเป็น "สร้างกฎใหม่เกินความจำเป็น")
    # FIX: เพิ่มรอบ dedup ที่ 2 - ถ้า cross_view มี (mark_view, mark_stack_idx) ตรงกับ pairwise/
    # pairwise_floor_jump ตัวใดตัวหนึ่งเป๊ะ ให้ตัด cross_view ทิ้ง (เก็บ pairwise ไว้แทน ตาม
    # หลักการเดียวกับ tail_stepdown - pairwise คือหลักฐานโดยตรงจากเพื่อนบ้านจริงในวิวเดียวกัน
    # น่าเชื่อถือกว่า cross_view ซึ่งอาศัยการเทียบข้าม view ที่มีโอกาสคลาดเคลื่อนจาก scale/
    # reconcile สูงกว่า) - ไม่กระทบ cross_view ที่ไม่มี pairwise คู่ตรงกัน (เช่น EA02-01 idx=2
    # ซึ่งเป็นตำแหน่งอื่น ยังคง flag ตามปกติ)
    def _mark_key(r):
        return (r.get("mark_view") or r.get("view"), r.get("mark_stack_idx"))

    pairwise_mark_keys = {
        _mark_key(r) for r in risks
        if r.get("risk_type") == "STEP_DOWN_RISK"
        and r.get("subtype") in ("pairwise", "pairwise_floor_jump")
    }

    result = []
    for r in risks:
        if (r.get("risk_type") == "STEP_DOWN_RISK" and r.get("subtype") == "tail_stepdown"
                and _pair_key(r) in pairwise_keys):
            print(f"[DEDUP_STEPDOWN] ตัด tail_stepdown ซ้ำกับ pairwise ที่ view={r.get('view')} "
                  f"pair_indices={r.get('pair_indices')} ออก (เก็บ pairwise ไว้แทน)")
            continue
        if (r.get("risk_type") == "STEP_DOWN_RISK" and r.get("subtype") == "cross_view"
                and _mark_key(r) in pairwise_mark_keys):
            print(f"[DEDUP_STEPDOWN] ตัด cross_view ซ้ำกับ pairwise ที่ mark_view/idx="
                  f"{_mark_key(r)} ออก (เก็บ pairwise ไว้แทน)")
            continue
        result.append(r)
    return result


def _dedup_stepdown_corrupted_by_adjacent_notch(risks, records_front, records_back):
    """v25.79 NEW (สำคัญ - พบจริงจาก EA10-01 31-Aug-2026): เดิม detect_step_down_pairwise/
    detect_step_down_crossview ไม่เคยตรวจสอบว่า "ฝั่งเตี้ยกว่า" ของคู่เปรียบเทียบ มีขอบ x_range
    ที่ตรงพอดีกับตำแหน่ง notch_x ของ EMPTY_SPACE_RISK/silhouette_notch ที่ตรวจพบแล้วในวิวเดียวกัน
    หรือไม่ - พบว่า EA10-01 BACK idx=4(taller,350.1px)/idx=5(shorter,269.4px) ถูก flag เป็น
    STEP_DOWN_RISK pairwise (drop=23.1%) ทั้งที่ตรวจสอบภาพจริงแล้วพบว่ากล่องทั้งแถว (TSE1A-D1)
    สูงเท่ากันสนิททุกตั้ง เห็นเป็นผนังเรียบราบต่อเนื่องไม่มี step-down จริงเลย - ความผิดปกติเดียว
    ที่มีจริงคือรอยบากเล็ก (silhouette_notch, notch_x=1080, ลึก 38px) ซึ่งตรงกับขอบซ้าย (x_range
    เริ่มที่ 1080) ของ idx=5 พอดีเป๊ะ - แสดงว่ารอยบากเดียวกันนี้ "ปนเปื้อน" ค่าที่วัดได้ของ idx=5
    (บาง sample ในคอลัมน์ที่สุ่มวัดความสูงไปเจอพื้นหลัง/สีโครงสร้างตู้ที่รอยบากเผยออกมา แทนที่จะ
    เจอยอดกล่องจริง ทำให้ average/median ของคอลัมน์ถูกลากลงต่ำกว่าความจริง) ไม่ใช่กล่องเตี้ยกว่าจริง
    ROOT CAUSE: EMPTY_SPACE_RISK/silhouette_notch กับ STEP_DOWN_RISK เป็นคนละกลไกที่ทำงานอิสระ
    ต่อกันสนิท (ไม่เคยแชร์ข้อมูลกัน) แต่ตรวจจับ "ปรากฏการณ์ภาพเดียวกัน" (รอยบากที่ขอบคอลัมน์) จาก
    คนละมุมมอง - silhouette_notch ตีความถูกต้องว่าเป็นรอยบาก/ช่องว่างเล็กๆ (ไม่ใช่กล่องเตี้ยเต็ม
    ความกว้างคอลัมน์) ในขณะที่ pairwise/cross_view เข้าใจผิดว่าทั้งคอลัมน์เตี้ยกว่าจริง เพราะวัด
    ความสูงแบบ column-wide โดยไม่รู้ว่ามีรอยบากแทรกอยู่บางส่วนของคอลัมน์นั้น
    FIX: หลังคำนวณ risks ทั้งหมดแล้ว (มี EMPTY_SPACE_RISK/silhouette_notch ครบแล้ว) - สำหรับ
    STEP_DOWN_RISK subtype pairwise/pairwise_floor_jump ที่มี pair_indices ครบ ให้หา x_range ของ
    "ฝั่งเตี้ยกว่า" (index ใน pair_indices ที่ไม่ใช่ mark_stack_idx) จาก records แล้วเช็คว่ามี
    silhouette_notch ในวิวเดียวกันที่ notch_x ตกอยู่ในช่วง x_range นั้น (±5px กันขอบพอดี) หรือไม่ -
    ถ้าใช่ ให้ตัด STEP_DOWN_RISK ทิ้ง (เก็บ EMPTY_SPACE_RISK ไว้แทน เพราะเป็นตัวแทนที่ถูกต้องกว่า
    ของปรากฏการณ์เดียวกัน - ระบุ "รอยบาก/ช่องว่างเฉพาะจุด" แทน "กล่องทั้งตั้งเตี้ยกว่า" ที่คลาดเคลื่อน)
    ขอบเขตการแก้ (ปลอดภัย ไม่กระทบไฟล์อื่น): ตรวจสอบแล้วในชุดไฟล์ทดสอบทั้งหมด (AA05-02/04,
    AB03-04, AB05-01, AC03-02, EA02-01/02, EA03-01, EA10-01, EC07-02) มีเพียง EA10-01 เท่านั้นที่
    มีทั้ง STEP_DOWN_RISK(pairwise) และ EMPTY_SPACE_RISK(silhouette_notch) อยู่ในวิวเดียวกัน (BACK)
    พร้อมกัน - ไฟล์อื่นที่มี silhouette_notch (AA05-02/04, AB05-01) ไม่มี STEP_DOWN_RISK คู่กันเลย
    ในวิวเดียวกัน (safe by construction) และ EA02-01 ที่มีทั้งคู่ notch อยู่คนละวิว (BACK) กับ
    STEP_DOWN_RISK (FRONT) จึงไม่ตรงเงื่อนไข view เดียวกัน ไม่ถูกกระทบเช่นกัน
    """
    notches = [r for r in risks if r.get("risk_type") == "EMPTY_SPACE_RISK"
               and r.get("subtype") == "silhouette_notch" and r.get("notch_x") is not None]
    if not notches:
        return risks

    def _x_range_of(view_label, idx):
        records = records_front if view_label == "FRONT" else records_back
        for rec in records:
            if rec["idx"] == idx:
                return rec.get("x_range")
        return None

    result = []
    for r in risks:
        if (r.get("risk_type") == "STEP_DOWN_RISK"
                and r.get("subtype") in ("pairwise", "pairwise_floor_jump")):
            view_label = r.get("mark_view") or r.get("view")
            pair_indices = r.get("pair_indices")
            taller_idx = r.get("mark_stack_idx")
            shorter_idx = None
            if pair_indices:
                others = [i for i in pair_indices if i != taller_idx]
                if others:
                    shorter_idx = others[0]
            if shorter_idx is not None:
                shorter_range = _x_range_of(view_label, shorter_idx)
                if shorter_range is not None:
                    matched = next(
                        (n for n in notches
                         if (n.get("mark_view") == view_label)
                         and (shorter_range[0] - 5 <= n["notch_x"] <= shorter_range[1] + 5)),
                        None)
                    if matched is not None:
                        print(f"[DEDUP_NOTCH_CORRUPT] ตัด {r.get('subtype')} ซ้ำกับ "
                              f"silhouette_notch ที่ view={view_label} shorter_idx={shorter_idx} "
                              f"notch_x={matched['notch_x']} ออก (เก็บ EMPTY_SPACE_RISK ไว้แทน "
                              f"เนื่องจากรอยบากเดียวกันปนเปื้อนค่าความสูงที่วัดได้ของฝั่งเตี้ยกว่า)")
                        continue
        result.append(r)
    return result


# ============================================================================
# v25.96 NEW: TAIL-STEPDOWN CROSS-VIEW CONFIRMATION (CASE 3 - ตามกฎที่ผู้ใช้กำหนดเอง
# "ถ้า FRONT/BACK ขัดแย้งกันรุนแรงที่ตำแหน่งเดียวกัน -> ไม่ flag")
# ============================================================================
# อาการ: tail_stepdown ถูก flag ที่ BACK แต่ผู้ใช้ยืนยันว่าท้ายรถปลอดภัยจริงทั้ง 2 ไฟล์
#   EC09  BACK idx=1 drop=39.1%  (กล่องใหญ่ KAP1A 4 ใบเหมือนกันหมด ซ้อน 2x2)
#   EB91  BACK idx=4 drop=30.3%
# หลักฐานที่วัดได้จริง (pos_range ของ FRONT/BACK ใช้ระบบพิกัดเดียวกัน เทียบตรงได้):
#   EC09: ตำแหน่งท้าย pos=(0.536,1.000)
#         BACK  idx=1 h=146.9px  src=direct n=85
#         FRONT idx=0 h=253.8px  src=direct n=122  <-- ขัดแย้งกันรุนแรง 42.1%
#         และ FRONT เองเห็นว่า idx0=253.8 vs idx1=242.5 ต่างกันเพียง 4.5% = สูงเท่ากัน
#         -> BACK วัดผิดฝั่งเดียว (n_samples ต่ำกว่ามาก 58/85 เทียบ FRONT 122/133)
#   EB91: ตำแหน่งท้าย pos=(0.791,1.000)
#         BACK  idx=4 h=226.1px  src=direct
#         FRONT idx=0 h=226.1px  src=cross_view_corrected  <-- "เท่ากันเป๊ะ" แต่เป็นค่าที่
#         ถูกแก้มาจาก BACK เองอยู่แล้ว (circular) ไม่ใช่การยืนยันอิสระ -> ใช้ยืนยันไม่ได้
# FIX (ตามกฎที่ผู้ใช้กำหนด): tail_stepdown จะถูก flag ก็ต่อเมื่อ "อีก view ยืนยันอย่างอิสระ"
#   - ต้องมี record ของอีก view ที่ตำแหน่งทับซ้อนกัน และ height_source เป็นการวัดอิสระ
#     (ไม่ใช่ cross_view_corrected ซึ่งเป็นค่าที่ derive มาจาก view ที่กำลังตรวจอยู่)
#   - ถ้าอีก view วัดได้ "สูงกว่าอย่างมีนัยสำคัญ" (>= _TAIL_CROSSVIEW_CONTRADICT_RATIO)
#     ที่ตำแหน่งเดียวกัน = ขัดแย้งรุนแรง -> ไม่ flag
#   - ถ้าไม่มีการยืนยันอิสระเลย (อีก view เป็น cross_view_corrected หรือไม่มี record ทับซ้อน)
#     -> ไม่ flag (ปลอดภัยไว้ก่อน - ไม่มีหลักฐานอิสระสนับสนุน)
# ขอบเขต: กระทบ "เฉพาะ subtype tail_stepdown" เท่านั้น กลไกอื่นไม่ถูกแตะเลยแม้แต่ตัวเดียว
#   -> EC05-01 (hidden_behind BACK idx=2 drop=42.4%) = จุดเสี่ยงจริงที่ยืนยันแล้ว ไม่ได้รับ
#      ผลกระทบเลย (คนละ subtype) + ตรวจสอบซ้ำแล้วว่า FRONT ที่ตำแหน่งเดียวกัน (idx0 h=321.0)
#      "เห็นตรงกันเป๊ะ" กับ BACK idx2 (h=321.0) จึงไม่เข้าเงื่อนไขขัดแย้งอยู่แล้ว
#   -> EB91 FRONT silhouette_notch (ช่องว่างกลางรถ) = ความเสี่ยงจริงที่ผู้ใช้ยืนยัน
#      ("กลางรถยังคงมีช่องว่าง บริเวณนั้นไม่ปลอดภัย") ไม่ได้รับผลกระทบเลย (คนละ subtype
#      และคนละตำแหน่ง - กลางรถ ไม่ใช่ท้ายรถ)
_TAIL_CROSSVIEW_CONTRADICT_RATIO = 1.20   # อีก view สูงกว่า >=20% = ขัดแย้งรุนแรง
_TAIL_CROSSVIEW_MIN_POS_OVERLAP = 0.25    # ต้องทับซ้อนตำแหน่งกันอย่างน้อย 25%
_TAIL_CROSSVIEW_DERIVED_SOURCES = ("cross_view_corrected",)


def _tail_stepdown_crossview_confirmed(risk, records_front, records_back):
    """v25.96: True ถ้าอีก view "ยืนยันอย่างอิสระ" ว่ากองท้ายเตี้ยจริง
    (ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล)"""
    view = risk.get("mark_view") or risk.get("view")
    other = records_front if view == "BACK" else records_back
    other = [r for r in (other or []) if not r.get("is_corner_duplicate")]
    tail_h = risk.get("tail_height_px")
    pos = risk.get("pos_range")
    if pos is None:
        return True          # ไม่มีข้อมูลตำแหน่ง -> คงพฤติกรรมเดิม (ไม่เปลี่ยนผล)
    if not other or not tail_h or tail_h <= 0:
        print(f"[TAIL_XVIEW] {view} idx={risk.get('mark_stack_idx')} "
              f"-> ไม่มี record ของอีก view ให้ยืนยัน = ไม่ flag")
        return False
    p0, p1 = pos
    best = None
    for r in other:
        q0, q1 = r["pos_range"]
        inter = max(0.0, min(p1, q1) - max(p0, q0))
        span = max(1e-6, min(p1 - p0, q1 - q0))
        if inter / span < _TAIL_CROSSVIEW_MIN_POS_OVERLAP:
            continue
        if best is None or inter > best[0]:
            best = (inter, r)
    if best is None:
        print(f"[TAIL_XVIEW] {view} idx={risk.get('mark_stack_idx')} "
              f"-> อีก view ไม่มีคอลัมน์ทับซ้อนตำแหน่งนี้ = ไม่มีการยืนยันอิสระ = ไม่ flag")
        return False
    rec = best[1]
    src = rec.get("height_source")
    oh = rec.get("height_px")
    if src in _TAIL_CROSSVIEW_DERIVED_SOURCES:
        print(f"[TAIL_XVIEW] {view} idx={risk.get('mark_stack_idx')} -> อีก view "
              f"(idx={rec['idx']} h={oh:.1f}) เป็น {src} ซึ่ง derive มาจาก view นี้เอง "
              f"(circular) ใช้ยืนยันอิสระไม่ได้ = ไม่ flag")
        return False
    if not oh or oh <= 0:
        print(f"[TAIL_XVIEW] {view} idx={risk.get('mark_stack_idx')} "
              f"-> อีก view ไม่มีค่าความสูงที่ใช้ได้ = ไม่ flag")
        return False
    ratio = oh / tail_h
    if ratio >= _TAIL_CROSSVIEW_CONTRADICT_RATIO:
        print(f"[TAIL_XVIEW] {view} idx={risk.get('mark_stack_idx')} ขัดแย้งรุนแรง: "
              f"view นี้วัด {tail_h:.1f}px แต่อีก view (idx={rec['idx']} src={src}) "
              f"วัดได้ {oh:.1f}px (สูงกว่า {(ratio-1)*100:.1f}%) = ไม่ flag")
        return False
    print(f"[TAIL_XVIEW] {view} idx={risk.get('mark_stack_idx')} ยืนยันอิสระผ่าน: "
          f"{tail_h:.1f}px vs อีก view {oh:.1f}px (src={src}) -> คง flag ไว้")
    return True


def detect_tail_stepdown(records, view_label, view_result=None):
    """ตรวจ step-down โซนท้ายตู้ (pos > TAIL_STEPDOWN_REAR_POS_MIN)

    v25.54 FIX: เพิ่ม 2 guards ป้องกัน false-positive จากตู้เต็ม (EA07-01):

    Guard 1 — min col width: tail_rec ต้องมีความกว้าง (x_range) >= TAIL_STEPDOWN_MIN_COL_WIDTH px
    เพราะ col ที่แคบผิดปกติ (เช่น 57px ใน EA07-01 FRONT idx=0) มักเกิดจาก column boundary
    ที่ phase1b ตัดผิด หรือ orphaned col ที่แทรกเข้ามา ค่าความสูงจึงไม่น่าเชื่อถือ
    ยืนยัน: col ปกติในไฟล์ทดสอบกว้าง 80-130px, col ที่ผิดปกติ EA07-01 กว้าง 57px

    Guard 2 — height source: ถ้า tail_rec มาจาก cross_view_corrected ให้ต้องการ
    drop_ratio >= TAIL_STEPDOWN_DROP_RATIO_STRICT (เข้มกว่าปกติ) เพราะค่า cross_view_corrected
    มีความไม่แน่นอนสูงกว่า direct measurement
    ยืนยัน: EA07-01 BACK idx=6 เป็น cross_view_corrected, drop_ratio=22% ซึ่งในภาพจริงสูงเท่ากัน

    v25.57 FIX (สำคัญ - พบจริงจาก log EA07-01/EB66-01 วันที่ 29-Aug-2026, ไฟล์ที่ผู้ใช้ยืนยัน
    ว่าเป็น "เต็มตู้ ไม่มีความเสี่ยง" แต่ยัง flag ผิดอยู่หลัง v25.56): เดิม detect_tail_stepdown
    ไม่มี guard "unreliable height source" ที่ detect_step_down_pairwise มี (เพิ่มไปตั้งแต่
    v25.55 FIX#3 เพื่อแก้ปัญหา carry-forward ทำให้ drop_ratio เหมือนกันเป๊ะระหว่าง 2 กลไก) -
    ทำให้ 2 ฟังก์ชันนี้ (pairwise/pairwise_floor_jump กับ tail_stepdown) ยังคงสามารถ flag
    "คู่ column เดียวกัน" ซ้ำซ้อนกันได้จากค่าความสูงที่ไม่น่าเชื่อถือชุดเดียวกัน (ยืนยันจาก log จริง:
    EB66-01 FRONT idx=1(pairwise)/idx=0(tail_stepdown) ได้ drop_ratio=0.23156868... เหมือนกันเป๊ะ
    ทั้ง 2 subtype - เข้าเกณฑ์เดียวกับที่ v25.55 เคยพบใน pairwise ล้วนๆ มาก่อน แต่ครั้งนี้เกิดใน
    tail_stepdown ที่ไม่เคยมี guard นี้มาก่อน) เพิ่ม guard เดียวกันเข้าไปที่นี่ (mirror จาก
    detect_step_down_pairwise ทุกประการ) รวมถึง n_samples guard ที่ pairwise มีแต่ tail_stepdown
    ไม่เคยมี (STEP_DOWN_MIN_RELIABLE_SAMPLES) - เพื่อความสอดคล้องกันระหว่าง 2 กลไกที่ตรวจจับ
    รูปแบบเดียวกัน (step-down ระหว่าง 2 คอลัมน์ติดกัน) ไม่ควรมีมาตรฐานความน่าเชื่อถือต่างกัน
    """
    # v26.16 FIX (false-negative ที่ผู้ใช้วงกลมบนภาพ CC28-01, 17-Sep-2026: "บริเวณที่กล่อง
    # สูงต่ำ ต้องมีการวาดกรอบ แต่กลไกตรวจจับไม่พบ"):
    # ROOT CAUSE ที่ยืนยันด้วยตัวเลขจริง: คอลัมน์ท้ายสุดของ CC28-01 กว้าง 62px ซึ่งต่ำกว่า
    # เกณฑ์ตายตัว 70px จึงถูก Guard 1 ตัดทิ้งก่อนจะได้เทียบความสูงเลย ทั้งที่เป็นคอลัมน์จริง
    # (ความสูง 237.8px vs คอลัมน์ถัดไป 292.4px = drop 18.7% ซึ่งเกินเกณฑ์ 12% ของกลไกนี้)
    # ปัญหาของเกณฑ์ตายตัว: 70px เหมาะกับไฟล์ที่คอลัมน์ปกติกว้าง 80-130px (ตามที่ v25.54 วัดไว้)
    # แต่ CC28-01 เป็นรถพ่วง 2 ตู้ที่เห็นคอลัมน์ทั้งคันย่อส่วนลง - คอลัมน์ปกติของไฟล์นี้กว้าง
    # median เพียง 73.5px ทำให้ 62px = 84% ของคอลัมน์ปกติ (ไม่ใช่คอลัมน์ผิดปกติแต่อย่างใด)
    # เทียบกับเคสที่ v25.54 ตั้งเกณฑ์นี้ขึ้นมาแก้ (EA07-01 FRONT idx0 = 57px เทียบคอลัมน์ปกติ
    # ~100px = 57%) -> เปลี่ยนเป็นเกณฑ์ "สัมพัทธ์กับคอลัมน์ปกติของไฟล์นั้นเอง" ที่ 70% พร้อม
    # พื้นขั้นต่ำสัมบูรณ์ 40px กันคอลัมน์เศษ: CC28-01 ผ่าน (62 >= 51.5) | EA07-01 ยังถูกตัด
    # (57 < 70.0) = รักษาเจตนาเดิมของ Guard 1 ไว้ครบ
    TAIL_STEPDOWN_MIN_COL_WIDTH_ABS = 40  # px พื้นขั้นต่ำสัมบูรณ์ (คอลัมน์เศษ/artifact)
    TAIL_STEPDOWN_MIN_COL_WIDTH_FRAC = 0.70  # เทียบ median ความกว้างคอลัมน์ของวิวนี้
    TAIL_STEPDOWN_DROP_RATIO_STRICT = 0.25  # เกณฑ์เข้มสำหรับ cross_view_corrected

    risks = []
    valid = [r for r in records if (not r.get("is_corner_duplicate")
             and r.get("height_px") is not None
             and (r.get("height_px") or 0) > 0)]
    if len(valid) < 2:
        return risks
    valid = sorted(valid, key=lambda r: (r["pos_range"][0] + r["pos_range"][1]) / 2.0)
    tail_rec = max(valid, key=lambda r: r["pos_range"][1])
    if tail_rec["pos_range"][1] < TAIL_STEPDOWN_REAR_POS_MIN:
        return risks
    tail_idx = valid.index(tail_rec)
    if tail_idx == 0:
        return risks

    # v25.54 Guard 1 (v26.16: เปลี่ยนเป็นเกณฑ์สัมพัทธ์ - ดูเหตุผล+ตัวเลขด้านบน)
    x0t, x1t = tail_rec["x_range"]
    _widths = [float(r["x_range"][1] - r["x_range"][0]) for r in valid
               if r.get("x_range") and (r["x_range"][1] - r["x_range"][0]) > 0]
    _med_w = float(np.median(_widths)) if len(_widths) >= 3 else 100.0
    _min_w = max(TAIL_STEPDOWN_MIN_COL_WIDTH_ABS, _med_w * TAIL_STEPDOWN_MIN_COL_WIDTH_FRAC)
    if (x1t - x0t) < _min_w:
        print(f"[TAIL_STEPDOWN] {view_label} คอลัมน์ท้าย x={tail_rec['x_range']} "
              f"กว้าง {x1t - x0t}px < เกณฑ์ {_min_w:.1f}px "
              f"(median คอลัมน์ของวิวนี้ {_med_w:.1f}px) -> ไม่เชื่อค่าความสูง ไม่ flag")
        return risks

    inner_rec = valid[tail_idx - 1]

    # v25.57 NEW Guard 0: ถ้าทั้ง tail_rec และ inner_rec มาจากแหล่งที่ไม่น่าเชื่อถือ (carry-
    # forward/ยังไม่มีการวัดอิสระ) ทั้งคู่ -> ไม่ flag (mirror จาก detect_step_down_pairwise
    # v25.55 FIX#3 - ดู docstring ด้านบนสำหรับหลักฐาน)
    src_tail = tail_rec.get("height_source")
    src_inner = inner_rec.get("height_source")
    _unreliable_sources = (None, "carried_forward_same_view")
    if src_tail in _unreliable_sources and src_inner in _unreliable_sources:
        return risks

    # v26.31: SAME-BOX-SIZE GUARD (ดู docstring เต็มที่ _SAMEBOX_MIN_FH_RATIO)
    _fr = _same_box_size_pair(view_result, tail_rec, inner_rec)
    if _fr is not None and _fr >= _SAMEBOX_MIN_FH_RATIO:
        print(f"[SAMEBOX] tail_stepdown {view_label} idx={tail_rec.get('idx')} "
              f"กล่อง 2 ฝั่งขนาดเท่ากัน (fh_ratio={_fr:.3f} >= "
              f"{_SAMEBOX_MIN_FH_RATIO}) = วางเรียงระดับเดียวกัน ไม่ใช่ขั้น -> ไม่ flag")
        return risks

    tail_h = float(tail_rec["height_px"])
    inner_h = float(inner_rec["height_px"])
    if inner_h <= 0:
        return risks
    drop_ratio = (inner_h - tail_h) / inner_h
    if drop_ratio < TAIL_STEPDOWN_DROP_RATIO:
        return risks

    # v25.54 Guard 2: cross_view_corrected ต้อง drop_ratio สูงกว่า threshold ปกติ
    if (tail_rec.get("height_source") == "cross_view_corrected"
            and drop_ratio < TAIL_STEPDOWN_DROP_RATIO_STRICT):
        return risks

    # v25.57 NEW Guard 3 (mirror STEP_DOWN_MIN_RELIABLE_SAMPLES จาก pairwise/cross_view):
    # ถ้า tail_rec (ฝั่งที่ "เตี้ยกว่า" ที่จะถูก mark) เป็น direct fit แต่มี n_samples ต่ำกว่า
    # เกณฑ์ขั้นต่ำ (จุดข้อมูลน้อยเกินจะเชื่อถือได้ - เช่น apex ตัดข้อมูลออกไปมาก) ไม่ flag
    if (tail_rec.get("height_source") == "direct"
            and tail_rec.get("n_samples", 999) < STEP_DOWN_MIN_RELIABLE_SAMPLES):
        return risks
    # v25.57 NEW Guard 4 (mirror STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
    if (tail_rec.get("height_source") == "cross_view_corrected"
            and tail_rec.get("cross_view_conflict_ratio", 0.0)
            > STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
        return risks

    # v25.89 NEW: mirror จาก detect_step_down_pairwise/crossview - ดู docstring เต็มที่
    # _isolated_pair_no_genuine_jump สำหรับหลักฐาน+เหตุผล (พบจริงจาก EB73-01 - ไฟล์ที่มีคอลัมน์
    # รวมทั้งวิวแค่ 2 คอลัมน์ ทำให้ tail_stepdown เปรียบเทียบ pair เดียวกับที่ pairwise เพิ่งถูก
    # suppress ไป แต่ tail_stepdown เป็นฟังก์ชันแยก ไม่ได้รับผลจาก guard ของ pairwise เลย)
    if _isolated_pair_no_genuine_jump(records, view_result):
        return risks
    # v25.68 NEW: Edge-Column Global Consensus Guard - ดู docstring เต็มที่
    # _is_edge_measurement_outlier สำหรับหลักฐาน+เหตุผล (พบจริงจาก EC10-03/EB66-01)
    if _is_edge_measurement_outlier(records, tail_rec["idx"], view_result=view_result):
        return risks
    # v25.82 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
    # _has_internal_sharp_jump สำหรับหลักฐาน+เหตุผล (พบจริงจาก AC03-02)
    # v25.85 FIX: mirror จาก detect_step_down_pairwise - เพิ่มเงื่อนไข AND n_samples ต่ำ (ดู
    # docstring เต็มที่ _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES สำหรับหลักฐาน+เหตุผล)
    if view_result is not None:
        cty_check = view_result.get("cargo_top_y")
        if cty_check is not None and (
                (tail_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                 and _has_internal_sharp_jump(cty_check, tail_rec["x_range"]))
                or (inner_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                    and _has_internal_sharp_jump(cty_check, inner_rec["x_range"]))):
            return risks
    # v25.72 NEW (สำคัญ - พบจริงจาก AB05-01, mirror จุดเดียวกันใน detect_step_down_pairwise):
    # เดิมเช็คแค่ tail_rec (ฝั่งเตี้ยกว่า) ว่าเป็น edge-outlier หรือไม่ - แต่ inner_rec (ฝั่งอ้างอิง
    # "สูงกว่า") ก็อาจเป็น edge-column ที่วัดสูงเกินจริงได้เช่นกัน (inner_rec อาจเป็น idx=0 หรือ
    # idx สุดท้ายได้เช่นกันในไฟล์ที่มีตั้งน้อย) - ถ้า inner_rec เองเป็น edge-outlier ค่าอ้างอิงที่ใช้
    # เปรียบเทียบไม่น่าเชื่อถือ ไม่ควร flag
    if _is_edge_measurement_outlier(records, inner_rec["idx"], view_result=view_result):
        return risks

    # v25.71 NEW: apex_fallback reliability guard - ดู docstring เต็มที่จุดเดียวกันใน
    # detect_step_down_pairwise สำหรับหลักฐาน+เหตุผล (พบจริงจาก ED84/ED85-01/02/03) - เพิ่มไว้
    # เพื่อความสอดคล้องกันทั้ง 3 กลไก แม้กรณี ED85 ที่พบจริงจะไม่ได้เกิดจาก apex_fallback ที่นี่
    # โดยตรงก็ตาม (tail_rec ที่นั่นเป็น direct source - ยังเป็นข้อจำกัดที่เหลืออยู่ - ดู CHANGELOG)
    if tail_rec.get("height_source") == "apex_fallback":
        return risks
    # v25.76 NEW (สำคัญ - พบจริงจาก AB03-04 ที่ผู้ใช้ระบุ "ตำแหน่งฟ้าท้ายสุด ยังมีกรอบแดง คือ
    # กรอบซ้ายสุด" หลังทดสอบ v25.75, 31-Aug-2026): เดิม guard ด้านบนเช็คเฉพาะ tail_rec ว่าเป็น
    # apex_fallback หรือไม่ (ไม่เคยเช็ค inner_rec เลย ทั้งที่ inner_rec คือ "ค่าอ้างอิงความสูงกว่า"
    # ที่ใช้ตัดสินว่า tail_rec เตี้ยกว่าจริงหรือไม่) - พบจริงจาก AB03-04 FRONT: tail_rec=idx0
    # (x=805-955, height_source="direct", n=138/150=92% coverage - เชื่อถือได้เต็มที่) แต่
    # inner_rec=idx1 (x=955-1110, apex_x=1000 ตัดข้อมูลกลางคอลัมน์เหลือ n=39/143=27% coverage -
    # ต่ำกว่าเกณฑ์ _APEX_CUT_MIN_COVERAGE_FRACTION=35% ได้ label ใหม่ "apex_partial_cut" - v25.76)
    # ทำให้ inner_rec วัดความสูงได้ 284.5px (สูงเกินจริง เพราะจุดประเมิน eff_mid=980 อยู่ใกล้ apex/
    # จุดสูงสุดของเส้นโค้ง isometric มากผิดปกติ แทนที่จะเป็นจุดกึ่งกลางจริงของคอลัมน์ ~1032) ทำให้
    # tail_rec (243.3px, ถูกต้องจริง) ถูกเข้าใจผิดว่า "เตี้ยกว่า" 14.5% ทั้งที่เป็นกล่อง SKU
    # เดียวกัน (TEP1A-AJ) สูงเท่ากันจริง (ยืนยันจาก floor_jump ระหว่างทั้งคู่=4.8px แทบไม่มี -
    # พื้นเดียวกันจริง ไม่ใช่คนละแถว) - ต้นเหตุที่แท้จริงคือ inner_rec (ไม่ใช่ tail_rec)
    # FIX: เช็ค inner_rec ด้วยเงื่อนไขเดียวกัน (apex_fallback) ก่อนเชื่อว่าเป็นค่าอ้างอิงที่
    # น่าเชื่อถือ - ถ้าไม่น่าเชื่อถือ ไม่ flag (ปลอดภัยกว่าการเชื่อค่าที่มาจากการประเมินใกล้ apex
    # มากผิดปกติ)
    if inner_rec.get("height_source") == "apex_fallback":
        return risks
    # v25.76 FIX (สำคัญ - พบ regression จริงระหว่างทดสอบ): เดิม suppress "เสมอ" ทันทีที่พบ
    # apex_partial_cut ฝั่งใดฝั่งหนึ่ง โดยไม่ดู drop_ratio เลย - ปลอดภัยสำหรับ AB03-04 (drop=
    # 14.5%) แต่มีความเสี่ยงทางทฤษฎีที่จะ suppress คู่อื่นที่ inner_rec เป็น apex_partial_cut
    # จริงแต่ drop_ratio สูงมากจนความเอนเอียงอธิบายไม่ได้ (mirror หลักการเดียวกับที่แก้ใน
    # detect_step_down_pairwise - ดู docstring เต็มที่นั่นสำหรับหลักฐาน+เหตุผล) - จำกัดการ
    # suppress เฉพาะโซนก้ำกึ่ง (drop_ratio < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO=0.25)
    if (inner_rec.get("height_source") == "apex_partial_cut"
            and drop_ratio < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
        return risks
    if (tail_rec.get("height_source") == "apex_partial_cut"
            and drop_ratio < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
        return risks
    # v25.84 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
    # _APEX_PARTIAL_CUT_MIN_SAMPLES สำหรับหลักฐาน+เหตุผล (พบจริงจาก EA03-01)
    if (inner_rec.get("height_source") == "apex_partial_cut"
            and inner_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
        return risks
    if (tail_rec.get("height_source") == "apex_partial_cut"
            and tail_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
        return risks

    risks.append({
        "risk_type": "STEP_DOWN_RISK",
        "subtype": "tail_stepdown",
        "view": view_label,
        "mark_view": view_label,
        "mark_stack_idx": tail_rec["idx"],
        "mark_x_range": tail_rec["x_range"],
        "drop_ratio": float(drop_ratio),
        "tail_height_px": tail_h,
        "inner_height_px": inner_h,
        "tail_idx": tail_rec["idx"],
        "inner_idx": inner_rec["idx"],
        # v25.96: เก็บ pos_range ไว้เพื่อใช้เทียบตำแหน่งข้าม view (ดู _tail_stepdown_crossview_confirmed)
        "pos_range": tail_rec.get("pos_range"),
        # v25.57 NEW: เก็บ height_source/n_samples จริงไว้ใน risk dict เอง (ไม่ใช่แค่ใน
        # record) เพื่อให้ debug print เห็นค่าจริง (เดิม risk.get('height_source') คืน None
        # เสมอเพราะไม่เคยถูกใส่ไว้ในนี้เลย - ดู Fix ที่ [RISK] print statement)
        "height_source": src_tail,
        "n_samples": tail_rec.get("n_samples"),
        "pair_indices": (inner_rec["idx"], tail_rec["idx"]),
    })
    return risks

# ============================================================================
# v25.96 NEW: SINGLE-STACK SPARSE LOAD GUARD (CASE 2 - ผู้ใช้ยืนยัน "EC16 ปลอดภัย")
# ============================================================================
# อาการ: EC16-01 ถูก flag 2 จุดที่ FRONT ตำแหน่งเดียวกันเป๊ะ (mark_x=(998,1229) ทั้งคู่)
#   STEP_DOWN_RISK/cross_view  FRONT idx=0 drop=43.3%
#   EMPTY_SPACE_RISK/color_anomaly FRONT idx=0
# ROOT CAUSE (วัดได้จริง): ไฟล์นี้บรรทุกเบาบางสุดขีด - Cargo 3.2 m3 = 7.6%, Unused Floor
# 236.2 in, มีกล่องเพียง 4 ใบ -> Phase 1B นับได้ "คอลัมน์เดียวทั้ง 2 view" (pos=(0.000,1.000))
#   FRONT idx=0 h=224.9px src=apex_partial_cut n=67
#   BACK  idx=0 h=127.5px src=direct          n=65
# ทั้ง 2 view วัด "กองเดียวกันใบเดียวกัน" แต่ได้ค่าต่างกัน 43.3% -> cross_view flag
# ทำไมนี่จึงเป็น false-positive เชิงโครงสร้าง ไม่ใช่แค่ threshold ตึงไป:
#   cross_view โดยนิยามคือ "กองเดียวกันวัดได้ไม่ตรงกันระหว่าง 2 มุมกล้อง" ซึ่งเมื่อมีกอง
#   เพียงกองเดียวในตู้ มันคือ "ความคลาดเคลื่อนของการวัด" ล้วนๆ ไม่ใช่ "ขั้นบันไดทางกายภาพ"
#   เพราะไม่มีกองอื่นให้ลดระดับลงไปหาเลย - ไม่มี step ก็ไม่มี step-down ได้โดยนิยาม
#   และกลไกป้องกันทุกตัวของระบบใช้ไม่ได้พร้อมกันหมดในสถานการณ์นี้:
#     - ไม่มี plateau ให้เทียบ (ต้องมี >=2 คอลัมน์)
#     - Edge-Column Global Consensus Guard ใช้ไม่ได้ (คอลัมน์เดียวเป็นทั้ง idx=0 และ idx=max)
#     - ไม่มีเพื่อนบ้านให้ทำ consensus
#   ส่วน color_anomaly เกิดเพราะกล่อง 4 ใบเป็น 4 SKU คนละสี (1PRTA/NFCTA/NSW1B/TBASI) วางรวม
#   ในคอลัมน์เดียว -> เข้าเกณฑ์ REAR_COLOR_ANOMALY_MIN_COLORS=4 พอดี ทั้งที่เป็นการวางปกติของ
#   ของเบ็ดเตล็ดจำนวนน้อย ไม่ได้บ่งชี้ช่องว่างใดๆ
# FIX: เมื่อ "ทั้ง 2 view มีคอลัมน์ที่ใช้งานได้ <= 1 คอลัมน์" ให้ระงับ cross_view และ
# color_anomaly (2 กลไกที่ต้องพึ่งการเปรียบเทียบระหว่างกอง) - กลไกอื่นที่ตรวจจากภายในกองเอง
# (hidden_behind, silhouette_notch ฯลฯ) ยังทำงานตามปกติทุกประการ ไม่ถูกแตะเลย
_SINGLE_STACK_GUARD_MAX_COLS = 1


def _is_single_stack_sparse_load(records_front, records_back):
    """v25.96: True เมื่อทั้ง 2 view มีคอลัมน์ใช้งานได้ <=1 (ดู docstring ด้านบน)"""
    def n_valid(recs):
        return len([r for r in (recs or []) if not r.get("is_corner_duplicate")])
    nf, nb = n_valid(records_front), n_valid(records_back)
    if nf <= _SINGLE_STACK_GUARD_MAX_COLS and nb <= _SINGLE_STACK_GUARD_MAX_COLS:
        print(f"[SINGLE_STACK_GUARD] โหลดเบาบางกองเดียว (FRONT={nf} BACK={nb} คอลัมน์) "
              f"-> ระงับ cross_view + color_anomaly (ไม่มีกองอื่นให้เทียบ = ไม่มี step-down "
              f"ทางกายภาพได้โดยนิยาม)")
        return True
    return False


# v26.12 NEW (ผู้ใช้แจ้ง 16-Sep-2026 พร้อมไฟล์จริง 12 ไฟล์: "กรอบแดง กรอบส้ม - วาดผิดจุด"):
# ROOT CAUSE (ยืนยันด้วยการวัดครบทั้ง 12 ไฟล์): cross_view จับคู่ "ตำแหน่งความยาวเดียวกัน"
# ระหว่าง FRONT<->BACK ด้วย pos_range (สัดส่วนตำแหน่ง) เท่านั้น โดยไม่เคยตรวจสอบเลยว่า
# "ทั้ง 2 view แบ่งคอลัมน์ได้ละเอียดพอๆ กันหรือไม่" - เมื่อ view หนึ่งแบ่งหยาบกว่าอีก view
# มาก คอลัมน์กว้างของฝั่งที่หยาบจะ "ทับซ้อน" กับคอลัมน์ของอีกฝั่งหลายคอลัมน์พร้อมกัน ทำให้
# ถูกนำไปเทียบซ้ำๆ กับทุกคอลัมน์ -> flag ผิดพร้อมกันทั้งแถว
# วัดยืนยันจาก TC51-03 (6WH Truck, สินค้าเพียง 9 ใบ, โหลด 45.7%):
#   FRONT แบ่งได้ 7 คอลัมน์ | BACK แบ่งได้เพียง 3 คอลัมน์ (ratio 0.43)
#   BACK idx2 กว้างถึง 387px (= 61% ของความยาวสินค้าทั้งหมด) แต่วัดความสูงได้เพียง 55.0px
#   (เพราะคอลัมน์กว้างนี้รวม "พื้นที่ว่างท้ายรถ" เข้าไปด้วย ค่าที่วัดได้จึงไม่ใช่ความสูงของ
#    กองสินค้าใดกองหนึ่งโดยเฉพาะ)
#   -> ถูกนำไปเทียบกับ FRONT idx0,1,2,3,4 ทุกตัว (ทับซ้อนหมดเพราะกว้างมาก)
#   -> drop 78%,82%,85%,85%,85% -> flag 5 จุดรวดติดกันทั้งแถว (ทั้งที่สินค้าสูงเท่ากันจริง)
#   ทั้ง 5 คู่ชี้ไปที่ B2 ตัวเดียวกันหมด = ลายเซ็นของ "คอลัมน์เดียวทับหลายคอลัมน์"
#
# ยืนยันว่าแยกได้ขาดจากไฟล์ที่ทำงานถูกต้อง (วัดครบ 11 ไฟล์ที่เป็น dual-view):
#   ไฟล์            F    B   col_ratio   width_ratio ของคู่ที่ flag
#   TC51-03         7    3      0.43     2.85-10.75   <-- ผิดปกติทั้ง 2 สัญญาณ
#   ------------------------------------------------------------------
#   CC33-all       14   15      1.07     -
#   CB15-all       11   11      1.00     1.06
#   CE01-all       12   12      1.00     1.08-1.47
#   CE02-ALL        8    8      1.00     1.38-1.60
#   CC05-all        8    8      1.00     1.00
#   CC07-all        5    5      1.00     1.11
#   CC40-02         7    7      1.00     2.41 (ไม่ถูก flag อยู่แล้ว - guard อื่นกรองไว้)
#   CC19/CD11/Empty 3-7 3-7     1.00     -
#   -> col_ratio: ผิดปกติ 0.43 vs ปกติ 1.00-1.07 (แยกขาด 2.3 เท่า)
#   -> width_ratio: ผิดปกติ 2.85+ vs ปกติ 1.00-1.60 (แยกขาด 1.8 เท่า)
#
# FIX: ระงับเฉพาะ "คู่ที่พิสูจน์ได้ว่าจับคู่ผิด" (ไม่ปิดทั้งไฟล์) โดยต้องเข้าเงื่อนไขครบทั้ง 2 ข้อ:
#   (1) ทั้ง 2 view แบ่งคอลัมน์ไม่สมดุลกันอย่างรุนแรง (col_ratio นอกช่วง 0.70-1.43)
#   (2) และคู่นั้นมีความกว้างต่างกันตั้งแต่ 2.5 เท่าขึ้นไป (คอลัมน์กว้างทับคอลัมน์แคบหลายตัว)
# เงื่อนไข AND ทำให้ไม่กระทบไฟล์ที่ col_ratio ปกติแต่บังเอิญมีคู่กว้างต่างกัน (เช่น CC40-02
# ที่มี width_ratio 2.41 แต่ col_ratio=1.00 -> ไม่เข้าเงื่อนไขเลย)
# ขอบเขต: ปิดเฉพาะ subtype "cross_view" เท่านั้น - pairwise / hidden_behind / tail_stepdown
# ทำงานครบทุกกลไก (เป็นการเทียบภายใน view เดียวกัน ไม่ได้รับผลจากการจับคู่ข้าม view เลย)
_XVIEW_COL_RATIO_LO = 0.70   # ต่ำกว่านี้ = BACK แบ่งหยาบกว่า FRONT มาก
_XVIEW_COL_RATIO_HI = 1.43   # สูงกว่านี้ = FRONT แบ่งหยาบกว่า BACK มาก (1/0.70)
_XVIEW_MAX_WIDTH_RATIO = 2.5  # คู่ที่กว้างต่างกันเกินนี้ = คอลัมน์กว้างทับหลายคอลัมน์


def _xview_column_granularity_mismatch(records_front, records_back):
    """v26.12: True ถ้า 2 view แบ่งคอลัมน์ไม่สมดุลกันอย่างรุนแรง (ดู docstring เต็มด้านบน
    สำหรับหลักฐาน+เหตุผล - พบจริงจาก TC51-03)"""
    nf = len([r for r in (records_front or []) if not r.get("is_corner_duplicate")])
    nb = len([r for r in (records_back or []) if not r.get("is_corner_duplicate")])
    if nf < 2 or nb < 2:
        return False
    ratio = nb / nf
    bad = ratio < _XVIEW_COL_RATIO_LO or ratio > _XVIEW_COL_RATIO_HI
    if bad:
        print(f"[XVIEW_GRANULARITY] FRONT {nf} คอลัมน์ vs BACK {nb} คอลัมน์ "
              f"(ratio={ratio:.2f} นอกช่วง {_XVIEW_COL_RATIO_LO}-{_XVIEW_COL_RATIO_HI}) "
              f"-> 2 view แบ่งคอลัมน์ไม่สมดุลกัน การจับคู่ตำแหน่งข้าม view ไม่น่าเชื่อถือ "
              f"(ดู FIX v26.12)")
    return bad


def detect_step_down_crossview(records_front, records_back, front_result=None, back_result=None):
    """เปรียบเทียบตำแหน่งจริงเดียวกันระหว่าง FRONT<->BACK ด้วยเกณฑ์เดียว (20%) - ข้าม
    record ที่ is_corner_duplicate=True เสมอ (ตรวจจากเส้น rail ทางเรขาคณิตจริง)"""
    risks = []
    seen_pairs = set()
    # v25.89 NEW (สำคัญ - พบจริงจาก EB73-01): ดู docstring เต็มที่ _isolated_pair_no_genuine_jump
    # สำหรับหลักฐาน+เหตุผล - คำนวณล่วงหน้าครั้งเดียวต่อวิว (ไม่ใช่ต่อคู่) ว่าวิวนี้เป็นกรณี "รวม
    # ทั้งวิวมีแค่ 2 คอลัมน์ ไม่มี plateau ให้อ้างอิง และไม่มี genuine jump จริง" หรือไม่ - ถ้าใช่
    # แสดงว่าค่าความสูงรายคอลัมน์ของวิวนี้ไม่น่าเชื่อถือพอจะใช้เปรียบเทียบข้าม view ได้ (พิสูจน์แล้ว
    # ว่าเป็นวัตถุความสูงสม่ำเสมอจริง ความต่างที่วัดได้เป็นความเอนเอียงจาก isometric slope)
    front_isolated_uniform = _isolated_pair_no_genuine_jump(records_front, front_result)
    back_isolated_uniform = _isolated_pair_no_genuine_jump(records_back, back_result)
    # v26.12: ตรวจครั้งเดียวต่อการเรียก - 2 view แบ่งคอลัมน์สมดุลกันหรือไม่
    # (ดู docstring เต็มที่ _xview_column_granularity_mismatch - พบจริงจาก TC51-03)
    _granularity_bad = _xview_column_granularity_mismatch(records_front, records_back)

    def _compare(rec_a, records_b_all, view_a_label, view_b_label):
        if rec_a.get("is_corner_duplicate"):
            return
        matches = _overlapping_records(rec_a["pos_range"], records_b_all)
        for rec_b in matches:
            if rec_b.get("is_corner_duplicate"):
                continue
            if rec_a["height_px"] is None or rec_b["height_px"] is None:
                continue
            key = tuple(sorted([(view_a_label, rec_a["idx"]), (view_b_label, rec_b["idx"])]))
            if key in seen_pairs:
                continue
            seen_pairs.add(key)
            taller_rec = rec_a if rec_a["height_px"] >= rec_b["height_px"] else rec_b
            shorter_rec = rec_b if taller_rec is rec_a else rec_a
            taller_h = taller_rec["height_px"]
            shorter_h = shorter_rec["height_px"]

            # v26.15: คอลัมน์ที่คร่อมช่องว่างระหว่างตู้ -> ความสูงถูกเจือจาง ไม่นำมาเทียบ
            # (ดู docstring เต็มที่ _GAP_CONTAMINATED_MAX_FRAC - แก้กรอบแดงที่ FRONT 7.3)
            _vr_a = front_result if rec_a["view"] == "FRONT" else back_result
            _vr_b = front_result if rec_b["view"] == "FRONT" else back_result
            if _is_gap_contaminated(_vr_a, rec_a) or _is_gap_contaminated(_vr_b, rec_b):
                continue

            # v26.12: ถ้า 2 view แบ่งคอลัมน์ไม่สมดุลกัน "และ" คู่นี้กว้างต่างกันมาก
            # (คอลัมน์กว้างของฝั่งที่แบ่งหยาบ กำลังทับคอลัมน์แคบของอีกฝั่งหลายตัว)
            # ให้ถือว่าการจับคู่ตำแหน่งคู่นี้ไม่น่าเชื่อถือ - ไม่ flag
            # (ดู docstring เต็มที่ _xview_column_granularity_mismatch - พบจริงจาก TC51-03)
            if _granularity_bad:
                _wa = rec_a["x_range"][1] - rec_a["x_range"][0]
                _wb = rec_b["x_range"][1] - rec_b["x_range"][0]
                _wr = max(_wa, _wb) / max(1, min(_wa, _wb))
                if _wr >= _XVIEW_MAX_WIDTH_RATIO:
                    print(f"[XVIEW_GRANULARITY] ข้ามคู่ {rec_a['view']}idx{rec_a['idx']}"
                          f"(w={_wa}) <-> {rec_b['view']}idx{rec_b['idx']}(w={_wb}) "
                          f"กว้างต่างกัน {_wr:.1f} เท่า (เกณฑ์ {_XVIEW_MAX_WIDTH_RATIO}) "
                          f"= คอลัมน์กว้างทับหลายคอลัมน์ จับคู่ตำแหน่งไม่ได้")
                    continue
            # v25.89 NEW: ถ้าฝั่งใดฝั่งหนึ่งมาจากวิวที่พิสูจน์แล้วว่า "รวมทั้งวิวมีแค่ 2 คอลัมน์
            # และไม่มี genuine jump จริง" (isolated uniform object) ไม่เชื่อถือค่าความสูงรายคอลัมน์
            # ของวิวนั้นพอจะเปรียบเทียบข้าม view ได้ - ไม่ flag (ดู docstring เต็มที่
            # _isolated_pair_no_genuine_jump, พบจริงจาก EB73-01)
            if ((taller_rec["view"] == "FRONT" and front_isolated_uniform)
                    or (taller_rec["view"] == "BACK" and back_isolated_uniform)
                    or (shorter_rec["view"] == "FRONT" and front_isolated_uniform)
                    or (shorter_rec["view"] == "BACK" and back_isolated_uniform)):
                continue
            # v25.48 NEW: เกณฑ์เดียวกับ pairwise - ดู STEP_DOWN_MIN_RELIABLE_SAMPLES
            if (shorter_rec.get("height_source") == "direct"
                    and shorter_rec.get("n_samples", 999) < STEP_DOWN_MIN_RELIABLE_SAMPLES):
                continue
            if (shorter_rec.get("height_source") == "cross_view_corrected"
                    and shorter_rec.get("cross_view_conflict_ratio", 0.0)
                    > STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO):
                continue
            # v25.71 NEW: apex_fallback reliability guard - ดู docstring เต็มที่จุดเดียวกันใน
            # detect_step_down_pairwise สำหรับหลักฐาน+เหตุผล (พบจริงจาก ED84/ED85-01/02/03)
            if shorter_rec.get("height_source") == "apex_fallback":
                continue
            # v25.83 NEW: mirror จาก detect_step_down_pairwise - เดิมเช็คแค่ shorter_rec ไม่เคย
            # เช็ค taller_rec (ค่าอ้างอิง) เลย - ดู docstring เต็มที่จุดเดียวกันใน
            # detect_step_down_pairwise สำหรับหลักฐาน+เหตุผล (พบจริงจาก ED85-02/03)
            if taller_rec.get("height_source") == "apex_fallback":
                continue
            # v25.76 NEW (สำคัญ - เพิ่มความสอดคล้องกับ pairwise/tail_stepdown หลังพบ AB03-04):
            # เดิมไม่เคยเช็ค "apex_partial_cut" (v25.76 - label ใหม่สำหรับกรณี apex ตัดข้อมูล
            # กลางคอลัมน์จนเหลือ coverage ต่ำ แม้จะยังมี>=3จุด) เลยทั้ง 2 ฝั่ง - เพิ่มเข้าไปเพื่อ
            # ความสอดคล้องกัน (ดู docstring เต็มที่ compute_stack_heights_px/detect_step_down_
            # pairwise สำหรับหลักฐาน+เหตุผลเต็ม) - จำกัดเฉพาะโซนก้ำกึ่ง (drop_ratio ต่ำ) เท่านั้น
            # เหมือน pairwise/tail_stepdown เพื่อไม่ suppress คู่ที่ drop_ratio สูงมากจนความ
            # เอนเอียงอธิบายไม่ได้ (ป้องกัน regression แบบเดียวกับที่เคยพบใน pairwise)
            _drop_check_cv = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
            if (taller_rec.get("height_source") == "apex_partial_cut"
                    and _drop_check_cv < _APEX_PARTIAL_CUT_MAX_TRUSTED_DROP_RATIO):
                continue
            # v25.84 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
            # _APEX_PARTIAL_CUT_MIN_SAMPLES สำหรับหลักฐาน+เหตุผล (พบจริงจาก EA03-01)
            if (taller_rec.get("height_source") == "apex_partial_cut"
                    and taller_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
                continue
            if (shorter_rec.get("height_source") == "apex_partial_cut"
                    and shorter_rec.get("n_samples", 999) < _APEX_PARTIAL_CUT_MIN_SAMPLES):
                continue
            # v25.72 NEW (สำคัญ - เพิ่มความสอดคล้องกับ pairwise/tail_stepdown หลังพบ AB05-01):
            # เดิม detect_step_down_crossview ไม่เคยเรียก Edge-Column Global Consensus Guard เลย
            # (v25.68 เพิ่มไว้แค่ pairwise/tail_stepdown เท่านั้น) ทั้งที่เป็นปัญหาเดียวกันได้ - ถ้า
            # ฝั่งใดฝั่งหนึ่ง (ไม่ว่าเตี้ยกว่าหรือสูงกว่า) เป็น edge-column ที่เบี่ยงเบนจาก plateau
            # ของคอลัมน์อื่นในวิวเดียวกันมาก ให้ไม่เชื่อการเปรียบเทียบข้าม view นี้เช่นกัน (เลือก
            # records_same_view ให้ตรงกับ view ของแต่ละฝั่งเอง)
            taller_view_records = records_front if taller_rec["view"] == "FRONT" else records_back
            shorter_view_records = records_front if shorter_rec["view"] == "FRONT" else records_back
            taller_vr = front_result if taller_rec["view"] == "FRONT" else back_result
            shorter_vr = front_result if shorter_rec["view"] == "FRONT" else back_result
            if (_is_edge_measurement_outlier(taller_view_records, taller_rec["idx"], view_result=taller_vr)
                    or _is_edge_measurement_outlier(shorter_view_records, shorter_rec["idx"], view_result=shorter_vr)):
                continue
            # v25.82/85 NEW: mirror จาก detect_step_down_pairwise - ดู docstring เต็มที่
            # _has_internal_sharp_jump และ _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES สำหรับหลักฐาน+
            # เหตุผล (พบจริงจาก AC03-02/EA03-01) - v25.85 เพิ่มเงื่อนไข AND n_samples ต่ำ
            taller_cty = taller_vr.get("cargo_top_y") if taller_vr else None
            shorter_cty = shorter_vr.get("cargo_top_y") if shorter_vr else None
            if ((taller_cty is not None
                 and taller_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                 and _has_internal_sharp_jump(taller_cty, taller_rec["x_range"]))
                    or (shorter_cty is not None
                        and shorter_rec.get("n_samples", 999) < _INTERNAL_JUMP_MAX_RELIABLE_N_SAMPLES
                        and _has_internal_sharp_jump(shorter_cty, shorter_rec["x_range"]))):
                continue
            # v25.74 NEW: Multi-Color Merge Recheck Guard - ดู docstring เต็มที่
            # _recheck_stack_height_via_color สำหรับหลักฐาน+เหตุผล (พบจริงจาก AB03-04) - ถ้าฝั่งใด
            # ฝั่งหนึ่งของคู่เปรียบเทียบ เป็นคอลัมน์ที่ P1B รู้อยู่แล้วว่าเป็น multi-color merge
            # (stack_expected_colors[idx] is None) และอีกฝั่งมีสีคาดหวังที่รู้แน่ชัด ให้ recheck
            # ความสูงของฝั่งที่กำกวมด้วยสีของอีกฝั่ง (สมมติฐาน: ทั้งคู่ควรเป็นกล่อง SKU เดียวกันที่
            # ตำแหน่งเดียวกันจริง เห็นจาก 2 มุมกล้อง) - ถ้า recheck สำเร็จและให้ผลต่างกันน้อยกว่า
            # เกณฑ์ ให้ไม่ flag (ปฏิเสธว่าเป็นความเสี่ยงปลอมจาก isometric roof-overhang bleed)
            def _expected_color_of(rec, vr):
                colors = vr.get("stack_expected_colors") if vr else None
                if colors is None or rec["idx"] >= len(colors):
                    return None
                return colors[rec["idx"]]
            taller_color = _expected_color_of(taller_rec, taller_vr)
            shorter_color = _expected_color_of(shorter_rec, shorter_vr)
            recheck_suppressed = False
            if shorter_color is None and taller_color is not None and shorter_vr is not None:
                recheck = _recheck_stack_height_via_color(
                    shorter_vr, shorter_rec["x_range"], taller_color)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (recheck_h / taller_h) if taller_h > 0 else 0
                    print(f"[RECHECK_CROSSVIEW] shorter_rec view={shorter_rec['view']} "
                          f"idx={shorter_rec['idx']} multi-color merge ตรวจพบ - recheck ด้วยสี "
                          f"{taller_color} (จาก taller_rec) ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n}, resid={recheck_resid:.2f}) เทียบ P1B เดิม="
                          f"{shorter_h:.1f}px -> recheck_drop_ratio={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_CROSSVIEW_DROP_RATIO:
                        recheck_suppressed = True
            elif taller_color is None and shorter_color is not None and taller_vr is not None:
                recheck = _recheck_stack_height_via_color(
                    taller_vr, taller_rec["x_range"], shorter_color)
                if recheck is not None:
                    recheck_h, recheck_n, recheck_resid = recheck
                    recheck_drop = 1 - (shorter_h / recheck_h) if recheck_h > 0 else 0
                    print(f"[RECHECK_CROSSVIEW] taller_rec view={taller_rec['view']} "
                          f"idx={taller_rec['idx']} multi-color merge ตรวจพบ - recheck ด้วยสี "
                          f"{shorter_color} (จาก shorter_rec) ได้ h={recheck_h:.1f}px "
                          f"(n={recheck_n}, resid={recheck_resid:.2f}) เทียบ P1B เดิม="
                          f"{taller_h:.1f}px -> recheck_drop_ratio={recheck_drop:.1%}")
                    if recheck_drop < STEP_DOWN_CROSSVIEW_DROP_RATIO:
                        recheck_suppressed = True
            if recheck_suppressed:
                continue
            threshold = taller_h * (1 - STEP_DOWN_CROSSVIEW_DROP_RATIO)
            if shorter_h < threshold:
                drop_ratio = 1 - (shorter_h / taller_h) if taller_h > 0 else 0
                risks.append({
                    "risk_type": "STEP_DOWN_RISK", "subtype": "cross_view",
                    "mark_view": taller_rec["view"],
                    "mark_stack_idx": taller_rec["idx"], "mark_x_range": taller_rec["x_range"],
                    "taller_height_px": taller_h, "shorter_height_px": shorter_h,
                    "drop_ratio": drop_ratio, "pos_range": taller_rec["pos_range"],
                    # v25.57 NEW: ดูหมายเหตุเดียวกับ pairwise ด้านบน
                    "height_source": shorter_rec.get("height_source"),
                    "n_samples": shorter_rec.get("n_samples"),
                })

    for rec_a in records_front:
        _compare(rec_a, records_back, "FRONT", "BACK")
    for rec_b in records_back:
        _compare(rec_b, records_front, "BACK", "FRONT")

    merged = {}
    for r in risks:
        key = (r["mark_view"], r["mark_stack_idx"])
        if key not in merged or r["drop_ratio"] > merged[key]["drop_ratio"]:
            merged[key] = r
    return list(merged.values())


