# FIX ที่ถูกต้อง: จำกัดเฉพาะสี "wall panel" (ผนังด้านข้างเท่านั้น - พื้นผิวเดียวที่ต้องการวัด
# ความสูงเพดานจริง) ไม่ใช้สีอื่นทั้งหมด (rail/floor-tile/rear-wall เป็นคนละพื้นผิว/มุมเอียง) -
