# ด้วย empty_fraction=0.45 (<0.60) - แสดงว่าการลด threshold นี้ไม่กระทบ EB66-01 แม้แต่จุดเดียว
# (จุดที่ถูกปฏิเสธ ถูกปฏิเสธด้วยหลักฐานสี ไม่ใช่ด้วย prominence)
# v26.07 FIX (ผู้ใช้ชี้จุดด้วยลูกศรบนภาพ BACK view ของ EA10-01, 15-Sep-2026:
# "เมื่อลากเส้นแล้ว พบว่าบริเวณภายในที่ลูกศรชี้ เกิดสีขาว ทั้งๆที่ถ้ามีกล่องวางสูง
#  จะไม่มีทางเกิดสีขาวได้"):
# ROOT CAUSE (ยืนยันด้วย pixel จริง): จุดที่ผู้ใช้ชี้คือ BACK view x=789 ซึ่งวัดได้:
#   สแกนคอลัมน์ x=789 ตั้งแต่ y=132 ถึง y=303 (171 pixel):
#     (255,255,255): 169 px  <- ขาวล้วน
#     (254,254,254):   1 px  <- ขาวล้วน
#     (9,11,11):       1 px  <- เส้นขอบ
#   -> empty_frac = 1.00 (100% ขาวบริสุทธิ์ ไม่มีสีกล่องเลยแม้แต่ pixel เดียว)
#   ตรงตามที่ผู้ใช้ระบุทุกประการ ("ถ้ามีกล่องวางสูง จะไม่มีทางเกิดสีขาวได้")
# แต่ถูกปฏิเสธตั้งแต่ "ด่านแรก" (find_peaks) ก่อนที่ด่านตรวจสีจะได้ทำงานเลย:
#   prominence = 11.0 px  เทียบเกณฑ์เดิม 12 px  -> ขาดอีกเพียง 1.0 px
# ทำไม prominence ถึงตื้นผิดปกติ: BACK ของไฟล์นี้แบ่งได้เพียง 4 คอลัมน์สำหรับกล่อง 19 ใบ
# (กล่องเล็กถูกรวมเป็นกองเดียว) ความสูง [271.0, 271.7, 272.1, 271.0] spread เพียง 0.4%
# ทำให้รอยบากจริงถูก median_filter(size=9) เกลี่ยจนตื้นลงเหลือ 11px พอดี
# หมายเหตุสำคัญ: FRONT ของไฟล์เดียวกันได้ 0 candidate ทุกระดับ (ลดถึง prominence=2 ก็ไม่เจอ)
# เพราะเส้นยอดลาดเรียบต่อเนื่องไม่มีแอ่งเลย -> BACK เป็น view เดียวที่มองเห็นช่องว่างนี้
#
# FIX: ลดเกณฑ์ 12 -> 10 (ต่ำกว่าค่าที่วัดได้จริง 11.0 เล็กน้อยเพื่อให้มี margin)
# ทำไมจึงปลอดภัย (เหตุผลเชิงโครงสร้าง ไม่ใช่การเดา): prominence เป็นเพียง "ด่านคัดกรอง
# เบื้องต้น" เท่านั้น - ด่านตัดสินจริงคือ empty_fraction (>=60% ต้องเป็นพื้นหลังขาว/สี
# โครงสร้างตู้) ซึ่งไม่ได้ถูกผ่อนปรนเลยแม้แต่น้อย ยืนยันจาก EB66-01 (ไฟล์ที่ผู้ใช้ยืนยันว่า
# "ไม่มีความเสี่ยง"): มีรอยบากที่ FRONT x=837 prominence=34px (สูงกว่าเกณฑ์เดิม 12 อยู่แล้ว
# มาก!) แต่ถูกปฏิเสธด้วย empty_fraction=0.45 (<0.60) - แสดงว่าจุดที่ถูกปฏิเสธ ถูกปฏิเสธ
# ด้วย "หลักฐานสี" ไม่ใช่ด้วย prominence -> การลด threshold นี้ไม่กระทบ EB66-01 เลย
# ประวัติการปรับค่านี้ (บันทึกไว้เพื่อความต่อเนื่อง):
#   v25.64 ตั้งต้น 15 -> v25.90 ลดเป็น 12 (แก้ EB08-01 prominence=13, EB63-01=12 ที่มี
#   empty_fraction=0.88/1.00 แต่ถูกตัดทิ้งเพราะตื้นกว่า 15) -> v26.07 ลดเป็น 10 (เคสนี้)
#   ทั้ง 3 เคสมีรูปแบบเดียวกันทุกประการ: empty_fraction สูงมาก (0.88-1.00) แต่ prominence
#   ตื้นกว่าเกณฑ์เพียงเล็กน้อย เพราะเป็นไฟล์ที่บรรทุกเต็มคัน (กล่องรอบข้างสูงใกล้เคียงกัน
#   ช่องว่างจึงไม่ลึกมาก แต่ยังเป็นพื้นที่ว่างจริงที่สินค้าล้มเข้าไปได้)
_NOTCH_MIN_PROMINENCE_PX = 10
_NOTCH_MIN_DISTANCE_PX = 20
_NOTCH_MIN_EMPTY_FRACTION = 0.6

# v25.69 NEW (สำคัญ - ตามคำสั่งผู้ใช้ 30-Aug-2026 หลังตัดสินใจให้ silhouette_notch มาแทนที่
# REAR_EMPTY_RISK/length_mismatch ทั้งหมด): เดิมกรอบ marker ของ silhouette_notch แคบมาก
# (กว้างคงที่ 40px = x_notch±20 โดยไม่สนใจความกว้างจริงของรอยบากที่ตรวจพบ) ทำให้ดูเป็นเส้นบางๆ
# ไม่ชัดเจนเทียบกับกรอบคอลัมน์ปกติ (STEP_DOWN_RISK) ที่กว้างเท่าคอลัมน์จริง (~80-150px ในภาพ
# ทดสอบทั้งหมด) - ผู้ใช้ระบุให้ปรับกรอบให้ "มองเห็นได้ชัดเหมือนกรอบคอลัมน์"
# FIX: ใช้ความกว้างจริงของรอยบาก (จาก left_bases/right_bases ที่ scipy.signal.find_peaks คำนวณ
# ให้แล้ว - คือขอบเขตจริงของ "หุบเขา" ในกราฟก่อนจะกลับสู่ระดับ baseline ทั้ง 2 ฝั่ง) แทนความกว้าง
# คงที่ 40px เดิม - ถ้าความกว้างจริงยังแคบกว่าเกณฑ์ขั้นต่ำ (_NOTCH_BOX_MIN_WIDTH_PX) ให้ pad
# เพิ่มสมมาตรทั้ง 2 ฝั่งจนถึงเกณฑ์นี้ (ให้ใกล้เคียงขนาดกรอบคอลัมน์ทั่วไป ไม่เล็กจนสังเกตยาก) - ไม่
# เปลี่ยนแนวตั้ง (baseline_y ถึง y_notch) เพราะเป็นขอบเขตที่ยืนยันแล้วด้วยการ sample สีจริงว่าเป็น
# พื้นที่ว่าง/โครงสร้างตู้ 100% (ขยายลงต่ำกว่า y_notch จะไปทับกับกล่องสินค้าจริงที่มีอยู่ - ไม่ใช่
# พื้นที่เสี่ยง ควรหลีกเลี่ยง)
_NOTCH_BOX_MIN_WIDTH_PX = 70  # ใกล้เคียงความกว้างคอลัมน์ขั้นต่ำที่พบจริงในไฟล์ทดสอบ (~80px)


def detect_silhouette_notch_risk(view_result, view_label):
    """ตรวจจับรอยบากในเส้นขอบบนกองสินค้า (cargo_top_y) ที่เผยพื้นหลัง/สีโครงสร้างตู้กลางแถว
    (ไม่ใช่ปลายสุด) - ดู docstring เต็มด้านบน"""
    cty = view_result.get("cargo_top_y")
    region = view_result.get("region")
    sx, ex = view_result.get("start_x"), view_result.get("end_x")
    if cty is None or region is None or sx is None or ex is None or (ex - sx) < 40:
        return []
    xs = np.arange(sx, ex)
    vals = np.array([float(cty[x]) if 0 <= x < len(cty) and cty[x] >= 0 else np.nan for x in xs])
    valid_mask = ~np.isnan(vals)
    if valid_mask.sum() < 20:
        return []
    if not np.all(valid_mask):
        vals = np.interp(np.arange(len(vals)), np.where(valid_mask)[0], vals[valid_mask])
    smoothed = median_filter(vals, size=9)
    peaks, props = find_peaks(smoothed, prominence=_NOTCH_MIN_PROMINENCE_PX,
                               distance=_NOTCH_MIN_DISTANCE_PX)
    risks = []
    for i, p in enumerate(peaks):
        prom = float(props["prominences"][i])
        left_base_idx = int(props["left_bases"][i])
        right_base_idx = int(props["right_bases"][i])
        x_notch = int(xs[p])
        y_notch = int(round(smoothed[p]))
        baseline_y = int(min(vals[left_base_idx], vals[right_base_idx]))
        if y_notch <= baseline_y:
            continue
        colors_sampled = []
        for yy in range(baseline_y, y_notch, 3):
            if 0 <= yy < region.shape[0] and 0 <= x_notch < region.shape[1]:
                colors_sampled.append(region[yy, x_notch])
        if not colors_sampled:
            continue
        n_empty = sum(
            1 for c in colors_sampled
            if (int(c[0]) > 230 and int(c[1]) > 230 and int(c[2]) > 230)
            or _p1b_is_structural_container_color(c)
        )
        frac_empty = n_empty / len(colors_sampled)
        if frac_empty < _NOTCH_MIN_EMPTY_FRACTION:
            continue
        # v25.69 NEW: ใช้ความกว้างจริงของรอยบาก (left_base ถึง right_base) แทน x_notch±20 เดิม
        # แล้ว pad ให้ถึงขั้นต่ำ _NOTCH_BOX_MIN_WIDTH_PX ถ้ายังแคบกว่า - ทำให้กรอบชัดเจนเหมือน
        # กรอบคอลัมน์ปกติ (ดู docstring เต็มด้านบน)
        x_left_natural = int(xs[left_base_idx])
        x_right_natural = int(xs[right_base_idx])
        natural_width = x_right_natural - x_left_natural
        if natural_width < _NOTCH_BOX_MIN_WIDTH_PX:
            pad = (_NOTCH_BOX_MIN_WIDTH_PX - natural_width) / 2.0
            x0_mark = max(sx, int(round(x_left_natural - pad)))
            x1_mark = min(ex, int(round(x_right_natural + pad)))
        else:
            x0_mark = max(sx, x_left_natural)
            x1_mark = min(ex, x_right_natural)
        ox, oy = view_result["crop_origin_x"], view_result["crop_origin_y"]
        abs_box = (ox + x0_mark, oy + baseline_y, ox + x1_mark, oy + y_notch)
        risks.append({
            "risk_type": "EMPTY_SPACE_RISK", "subtype": "silhouette_notch",
            "mark_view": view_label, "mark_stack_idx": None,
            "mark_x_range": (x0_mark, x1_mark), "pos_range": None,
            "abs_box": abs_box,
            "notch_x": x_notch, "prominence_px": prom, "empty_fraction": frac_empty,
            "reason": (f"พบรอยบากในเส้นขอบบนกองสินค้าที่ x={x_notch} (ลึก {prom:.0f}px) "
                       f"เผยพื้นหลัง/สีโครงสร้างตู้ {frac_empty:.0%} บ่งชี้กล่องเตี้ยกว่า/ไม่มี"
                       f"กล่องแถวหน้ามาบัง เสี่ยงพื้นที่ว่างกลางคัน"),
        })
    return risks


def detect_rear_empty_risk(records_front, records_back, front_result, back_result):
    """REAR_EMPTY_RISK - ตรวจสีของ "ตั้งท้ายสุดจริง" ของแต่ละ view (ข้าม corner_duplicate
    เสมอ) - ถ้ามี SKU ปะปนกันผิดปกติ (>=3 สีเด่น) มักบ่งชี้สินค้าที่วางไม่เป็นระเบียบ/มีช่องว่าง
    ใกล้ประตูท้ายตู้ (ยืนยันจาก EC04-02 BACK idx ท้ายสุด ต้อง flag)

    v25.69 REMOVED (สำคัญ - ตามคำสั่งผู้ใช้ 30-Aug-2026): เดิมมีกลไก A (length_mismatch -
    เทียบ length_px/extended-length ระหว่าง FRONT<->BACK) เป็นกลไกหลักคู่กับกลไก B
    (color_anomaly) - ผู้ใช้ระบุว่า detect_silhouette_notch_risk (v25.64, "กรอบมุมทแยง")
    ทำหน้าที่แทนกลไก A ได้ดีกว่า เพราะ:
      1) ตรวจจับพื้นที่ว่างได้จริงจากรูปทรงเรขาคณิต (รอยบากในเส้นขอบบนกองสินค้า) โดยตรง
         ไม่ต้องอาศัยการเปรียบเทียบความยาวรวมทาง pixel ที่มีความไม่แน่นอนสูง (bias เชิงระบบที่
         แปรผันตามรุ่นรถ/ระดับบรรทุก - ยืนยันจาก EA07-01/EB66-01=6.3%, EC10-03=10.4%,
         EC19-01=12.2%, EB73-01=16.6% - ไม่มีค่าคงที่ให้ calibrate ได้แม่นยำ)
      2) ครอบคลุมกว้างกว่า - ตรวจพื้นที่ว่างได้ "ทุกตำแหน่งภายใน FRONT/BACK view" ไม่จำกัดแค่
         โซนท้ายรถ (ตำแหน่งตั้งสุดท้ายก่อนประตู) เหมือนกลไก A/B เดิม
      3) วาง marker ตรงตำแหน่งพื้นที่ว่างจริงโดยตรง (จาก notch_x ที่ตรวจพบ) แม่นยำกว่าการ mark
         ทั้งคอลัมน์ท้ายสุด (ซึ่งอาจไม่ใช่ตำแหน่งที่มีปัญหาจริงเป๊ะ)
    ลบกลไก A (length_mismatch) และ _p1b_extended_length_for_rear_check ที่เกี่ยวข้องออก
    ทั้งหมด (เก็บ REAR_GAP_MIN_PX/REAR_GAP_MIN_RATIO ไว้เป็น dead-constant เพื่อลด diff -
    ไม่ได้ใช้งานแล้ว) - เหลือกลไก B (color_anomaly) ไว้เป็นกลไกเสริมที่ตรวจจากสัญญาณคนละมิติ
    (SKU สีปะปนกัน ไม่ใช่ความยาว) และปรับ Guard 1 เดิม (ที่เคยพึ่งพา _partial_gap_px จากกลไก A
    เพื่อยืนยันว่ามี partial length gap จริง) ให้ยังคงทำงานได้อิสระโดยคำนวณ gap จาก length_px
    ดิบ (Phase 2, ไม่ผ่าน extended-length) โดยตรงแทน - ไม่กระทบผลลัพธ์เดิมของกลไก B เพราะใช้
    เกณฑ์ตัวเลขเดียวกัน (>=15px) เพียงแต่เปลี่ยนแหล่งข้อมูลจาก extended เป็น raw
    """
    risks = []

    # --- กลไก B: color-anomaly ที่ตั้งท้ายสุดจริงของแต่ละ view ---
    # v25.54 FIX: เพิ่ม 2 guards ป้องกัน false-positive จากตู้ที่กล่อง SKU ต่างชนิดวางชิดกัน
    # ตามปกติ (เช่น EA07-01 ที่มีหลาย SKU ในคอลัมน์ท้าย แต่ไม่มีช่องว่างจริง):
    #
    # Guard 1 — ต้องมี partial length gap ยืนยัน: กลไก B จะ flag ก็ต่อเมื่อมีช่องว่างความยาว
    #   >= REAR_COLOR_NEEDS_GAP_MIN_PX เพราะ color_anomaly เพียงอย่างเดียวไม่เพียงพอ — ไฟล์ที่
    #   กล่องเต็มตู้ก็อาจมี SKU หลายสีในคอลัมน์ท้ายตามธรรมชาติ ยืนยันจาก EC04-02: gap=17px
    #   ยังเข้าเกณฑ์นี้ได้ (>15px) ในขณะที่ EA07-01: gap=9px ไม่เข้าเกณฑ์ → ไม่ flag ถูกต้อง
    #   v25.69: เปลี่ยนแหล่งข้อมูล gap จาก extended-length (กลไก A ที่ถูกลบ) เป็น length_px
    #   ดิบจาก Phase 2 โดยตรง (ไม่กระทบตัวเลขที่เคย verify ไว้ - ทั้ง 2 ไฟล์ ground-truth
    #   (EC04-02=17px, EA07-01=9px) วัดจาก raw length_px ได้ค่าเดียวกันกับที่เคย verify ไว้)
    #
    # Guard 2 — dominant color ต้องไม่ครอบงำมากเกิน (REAR_COLOR_MAX_DOMINANT_FRAC):
    #   ถ้า 1 สีมี fraction >= 0.70 ของ pixel ทั้งหมด แสดงว่า col นั้นเป็นกล่องใบเดียวเป็นหลัก
    #   สีรองที่เหลือเป็น shading/shadow/outline ของกล่องใบนั้น ไม่ใช่ SKU อื่นจริง
    #   ยืนยัน EA07-01 BACK: (128,128,0)=71.5% → 1 SKU ครอบงำ สีรองเป็น shading → false-positive
    #   ยืนยัน EC04-02 BACK: TEM1A มี 4 สีต่างฝั่งต่างกัน ไม่มีสีใดครอบงำ >= 70%
    REAR_COLOR_NEEDS_GAP_MIN_PX = 15     # gap ขั้นต่ำ (px) ที่กลไก B ต้องการ
    REAR_COLOR_MAX_DOMINANT_FRAC = 0.70  # ถ้า dominant > นี้ = 1 SKU + shading ไม่ใช่ multi-SKU

    front_len_raw = front_result.get("length_px") or 0
    back_len_raw = back_result.get("length_px") or 0
    _partial_gap_px = abs(front_len_raw - back_len_raw) if (front_len_raw and back_len_raw) else 0

    for records, result, label in [(records_front, front_result, "FRONT"),
                                    (records_back, back_result, "BACK")]:
        rear_rec = _rearmost_record(records)
        if rear_rec is None:
            continue
        clusters = _dominant_color_clusters(result["region"], result["cargo_mask"], rear_rec["x_range"])
        if len(clusters) < REAR_COLOR_ANOMALY_MIN_COLORS:
            continue

        # v25.54 Guard 1: ต้องมี partial length gap ยืนยัน
        if _partial_gap_px < REAR_COLOR_NEEDS_GAP_MIN_PX:
            continue

        # v25.54 Guard 2: dominant color ต้องไม่ครอบงำมากเกิน
        total_pixels = sum(cnt for _, cnt in clusters)
        if total_pixels > 0:
            dominant_frac = clusters[0][1] / total_pixels
            if dominant_frac >= REAR_COLOR_MAX_DOMINANT_FRAC:
                continue

        risks.append({
            "risk_type": "EMPTY_SPACE_RISK", "subtype": "color_anomaly",
            "mark_view": label,
            "mark_stack_idx": rear_rec["idx"], "mark_x_range": rear_rec["x_range"],
            "pos_range": rear_rec["pos_range"], "n_colors": len(clusters),
            "reason": (f"ตั้งสุดท้ายก่อนประตูท้ายตู้ฝั่ง {label} พบสี SKU ปะปนกัน {len(clusters)} สี "
                       f"บ่งชี้สินค้าที่วางไม่เป็นระเบียบ/มีช่องว่างใกล้ประตูท้ายตู้"),
        })

    # v25.69 REMOVED: cross-view voting logic เดิม (v25.55 FIX#3) ออกแบบมาเพื่อแก้ความขัดแย้ง
    # ระหว่าง length_mismatch กับ color_anomaly (subtype ต่างกัน) - ตอนนี้เหลือแค่ color_anomaly
    # subtype เดียว (ไม่มีทางมี subtype ต่างกันในกลุ่ม REAR_EMPTY_RISK อีกต่อไป) จึง logic นี้
    # กลายเป็น dead code ทั้งหมด (เงื่อนไข len(subtypes)>1 ไม่มีทางเป็นจริงได้อีกแล้ว) - ลบออก

    return risks


# ============================================================================
# v25.92 NEW: ยกเว้นกรอบส้ม (EMPTY_SPACE_RISK) ที่ช่องว่าง "ระหว่างตู้" ของรถ 2 ตู้ต่อ 1 view
# ============================================================================
# ปัญหาที่แก้ (ผู้ใช้แจ้ง 11-Sep-2026 พร้อมแนบไฟล์ CC19-all opt2.pdf): "ไฟล์ประเภท 2 ตู้ ต่อ
# view ขอให้ยกเว้นการจับกรอบส้มระหว่างตู้ cargo เนื่องจากเป็นประเภทรถ full trailer มี 2 ตู้"
#
# ยืนยันด้วยการรันโค้ดจริง + ตรวจสอบภาพ marked: CC19 (TTKAFT Double Trailer) ถูก flag
# EMPTY_SPACE_RISK/silhouette_notch 2 จุด (FRONT notch_x=894, BACK notch_x=871) ซึ่งตรงกับ
# "ช่องว่างระหว่างตัวตู้ 2 ตู้" พอดีเป๊ะทั้ง 2 จุด ไม่ใช่พื้นที่ว่างในตู้เดียวกัน
#
# ยืนยันด้วยข้อมูลเชิงเรขาคณิตระดับ pixel (วัดจริงจากไฟล์):
#   FRONT: กองสินค้าแยกเป็น 2 ก้อนชัดเจน x=[529,897] (กว้าง 368px) และ x=[964,1297] (333px)
#          คั่นด้วยช่องว่างไร้สินค้า x=[897,964] กว้าง 67px - ช่องว่างนี้เป็น "พื้นหลังขาวล้วน
#          80%" (ไม่มีพื้นตู้/ผนังตู้อยู่เลย)
#   BACK : กอง x=[604,872] (268px) และ x=[972,1307] (335px) คั่นด้วยช่องว่าง x=[872,960]
#          กว้าง 88px - พื้นหลังขาวล้วน 88%
# จุดสำคัญที่แยกแยะได้ชัดเจน: ถ้าเป็น "พื้นที่ว่างในตู้เดียวกัน" (ความเสี่ยงจริงที่ต้อง flag)
# พื้นตู้/ผนังตู้จะยังคงถูกวาดต่อเนื่องผ่านช่องว่างนั้นเสมอ (ไม่ใช่พื้นหลังขาว) - แต่ช่องว่าง
# ระหว่าง 2 ตู้ของรถพ่วงเป็น "การแยกกันทางกายภาพจริง" จึงไม่มีโครงสร้างตู้ใดๆ อยู่เลย
#
# FIX (ออกแบบให้ปลอดภัยที่สุด - ใช้ 3 เงื่อนไขร่วมกันแบบ AND ไม่ใช่เงื่อนไขเดียว):
#   (1) ต้องยืนยันจาก "ข้อความประเภทรถ" ใน PDF ก่อนเสมอ (_detect_multi_container_vehicle)
#       CC19 = "TTKAFT (Double Trailer) (1 / 1)" ชัดเจน / ไฟล์ตู้เดียวเป็น "(Truck)"/"(SideBay)"
#       -> เป็นด่านหลัก เพราะเป็นข้อมูลที่ผู้ผลิตไฟล์ระบุมาโดยตรง ไม่ใช่การอนุมานจากภาพ
#   (2) ต้องพบช่องว่างที่ "แยกกองสินค้าออกเป็น 2 ก้อนใหญ่จริง" ทางเรขาคณิต
#       (_find_inter_container_gaps) และช่องว่างนั้นต้องเป็นพื้นหลังว่างจริง (ไม่มีโครงสร้างตู้)
#   (3) จำกัดจำนวนช่องว่างที่ยกเว้นได้ = (จำนวนตู้ - 1) เท่านั้น โดยเลือก "ช่องที่กว้างที่สุด"
#       -> รถ 2 ตู้ ยกเว้นได้แค่ 1 ช่องต่อ view เท่านั้น ช่องว่างอื่นที่เหลือยังคงถูก flag
#       ตามปกติทุกประการ (เป็นความเสี่ยงจริงภายในตู้ใดตู้หนึ่ง)
# ผลกระทบจำกัดอยู่ที่ EMPTY_SPACE_RISK (กรอบส้ม) เท่านั้นตามที่ผู้ใช้ระบุ - STEP_DOWN_RISK
# (กรอบแดง) ไม่ถูกแตะเลยแม้แต่จุดเดียว

_MULTI_CONTAINER_KEYWORDS = {
    "double trailer": 2,
    "full trailer": 2,
    "triple trailer": 3,
}

# เกณฑ์เรขาคณิตของ "ช่องว่างระหว่างตู้" (คาลิเบรตจากค่าที่วัดได้จริงใน CC19 ที่ matrix_scale=3)
# v25.96 FIX (CASE 1 - ผู้ใช้แจ้ง "รถตู้ 2 ใบ กรอบส้มผิด คร่อมกลางทั้ง 2 ตู้" พร้อมภาพ GC06):
# ROOT CAUSE ที่วัดได้จริง - ไม่ได้อยู่ที่ logic การยกเว้น (ที่แก้ไปแล้วใน v25.95) แต่อยู่ที่
# "ด่านแรกสุด" คือเกณฑ์ความกว้างช่องว่างนี้เอง:
#   _detect_multi_container_vehicle -> (2, 'TTKAFT (Double Trailer) (1/1)')  <-- ตรวจถูกต้อง
#   _find_inter_container_gaps      -> []                                     <-- ว่างเปล่า!
# วัดช่องว่างจริงของ GC06 ด้วย pixel: FRONT x=911-931 = 20px | BACK x=906-936 = 30px
# ทั้งคู่ "ต่ำกว่าเกณฑ์เดิม 40px" -> ถูกปฏิเสธตั้งแต่ต้นทาง -> ไม่มี gap ให้ตัวยกเว้นใช้เลย
# ทำไม GC06 ช่องว่างแคบกว่า CC19 (ที่ใช้คาลิเบรตเดิม 67px/88px): GC06 บรรทุก 67.0 m3 ยาว
# 16,940mm (ยาวกว่า CC19 มาก) -> ภาพถูกบีบ scale ลงเพื่อให้พอดีหน้ากระดาษ -> ทุกระยะในภาพ
# หดตามสัดส่วน ช่องว่างทางกายภาพเท่าเดิมแต่วัดเป็น pixel ได้น้อยลง
# FIX: เปลี่ยนจากค่าคงที่เป็น "สัดส่วนของความยาวตู้ในภาพ" (scale-invariant) โดยมีพื้นล่าง
# กันช่องว่างจิ๋วจาก noise - ใช้ค่าที่เล็กกว่าระหว่าง (ค่าคงที่เดิม, สัดส่วน) เพื่อให้ครอบคลุม
# ทั้งภาพที่ scale ปกติและภาพที่ถูกบีบ
# ความปลอดภัย: ด่านนี้ไม่ได้ทำงานลำพัง - ต้องผ่านครบทุกข้อจึงถือว่าเป็นช่องว่างระหว่างตู้
#   (1) รถถูกระบุว่าเป็นหลายตู้จากข้อความใน PDF (n_containers>=2) - ด่านที่เข้มที่สุด
#   (2) มีกองสินค้าใหญ่ >= _INTER_CONTAINER_MIN_CLUSTER_PX ขนาบทั้ง 2 ฝั่ง
#       (GC06 วัดได้ 345px/381px >> 80px ผ่านสบาย)
#   (3) ภายในช่องต้องไร้พื้นตู้/ผนังตู้ >= _INTER_CONTAINER_MIN_EMPTY_FRAC
# รถตู้เดียว (n_containers=1) ไม่ได้รับผลกระทบจากการแก้นี้เลยแม้แต่ไฟล์เดียว (return [] ทันที)
_INTER_CONTAINER_MIN_GAP_ABS_PX = 15      # พื้นล่างกันช่องว่างจิ๋วจาก noise/เส้นขอบ
_INTER_CONTAINER_MIN_GAP_SPAN_FRAC = 0.012  # 1.2% ของความยาวตู้ในภาพ (GC06 span~1290px
# -> 15.5px ซึ่งต่ำกว่าช่องว่างจริง 20px/30px | CC19 span ใหญ่กว่า -> เกณฑ์สูงขึ้นตามสัดส่วน)
_INTER_CONTAINER_MIN_GAP_PX = 40      # (คงไว้เป็นเพดานบน) ช่องว่างขั้นต่ำ (วัดจริง 67px/88px
# เพื่อรองรับไฟล์ที่ตู้ 2 ใบวางชิดกันกว่านี้ แต่ยังสูงพอจะไม่ไปจับรอยต่อระหว่างกล่องปกติ)
_INTER_CONTAINER_MIN_CLUSTER_PX = 80  # กองสินค้าแต่ละฝั่งของช่องว่างต้องกว้างอย่างน้อยเท่านี้
# (วัดจริง 268-368px - ตั้งต่ำไว้มากเพื่อรองรับกรณีตู้ที่บรรทุกน้อย)
_INTER_CONTAINER_MAX_CARGO_COL = 3    # คอลัมน์ที่ถือว่า "ไม่มีสินค้า" (เผื่อ noise/anti-alias)
_INTER_CONTAINER_MIN_EMPTY_FRAC = 0.5 # ช่องว่างต้องเป็นพื้นหลัง/ไร้โครงสร้างตู้อย่างน้อย 50%
# (วัดจริง 0.80/0.88 - ตั้งไว้ 0.50 ให้มี margin กว้าง แต่ยังกรองกรณีที่มีพื้นตู้ต่อเนื่องอยู่จริง
# ซึ่งบ่งชี้ว่าเป็น "พื้นที่ว่างในตู้เดียวกัน" = ความเสี่ยงจริงที่ต้องคง flag ไว้)
_INTER_CONTAINER_MATCH_TOL_PX = 40
# v26.17 NEW: BRIDGE FRAGMENTED EMPTY RUNS (ผู้ใช้แจ้ง 17-Sep-2026: "กรอบส้มวาดคร่อม
# และกรอบแดง อาจมีผิดผสมเข้ามา" พร้อมไฟล์ CB15-04)
# ROOT CAUSE ที่ยืนยันด้วย pixel จริง (ค่านับสินค้าต่อคอลัมน์ใน FRONT view ของ CB15-04):
#   x=906..912 : 136,121,121,121,118,117,116   <- ท้ายกองสินค้าตู้ที่ 1 (สีชมพู)
#   x=913..930 : 1,0,1,0,1,3,3,5,5,2,1,1,2,5,1,0,0,0  <- ช่องว่างระหว่างตู้จริง
#   x=931..    : 98,101,102,103,...            <- หัวกองสินค้าตู้ที่ 2 (สีแดง)
# ค่า 1-5 px ในช่วงช่องว่างมาจาก "ลูกศร/เส้นบอกระยะสีแดง" ของเส้นมิติ 7.3/8.2 ที่วาดพาดผ่าน
# ช่องว่างพอดี (ตัวอย่างสีที่วัดได้: (255,64,64) (254,62,58) (170,33,23) (148,65,65)) ซึ่งผ่าน
# เกณฑ์ vivid_cargo_mask จึงถูกนับเป็น "สินค้า" - บางคอลัมน์ได้ 5 px ซึ่งเกินเกณฑ์
# _INTER_CONTAINER_MAX_CARGO_COL = 3
# ผลที่เกิด: ช่องว่างเดียวยาว 18px ถูกฉีกเป็น 3 ท่อน (913-920 = 7px | 922-926 = 4px |
# 927-931 = 4px) ทุกท่อนสั้นกว่าเกณฑ์ _min_gap = 15px -> FRONT gaps = [] (ว่างเปล่า)
# ผลกระทบลูกโซ่: กลไกทุกตัวที่พึ่ง gaps ตายหมดทั้งวิวพร้อมกัน ->
#   _suppress_inter_container_empty_space_risks / _clip_risks_at_container_gaps /
#   _is_gap_contaminated / _suppress_container_entry_column_stepdown / _analyse_per_container
# = ต้นเหตุเดียวของทั้ง "กรอบส้มคร่อม 2 ตู้" และ "กรอบแดงในช่องว่าง" ที่ผู้ใช้แจ้ง
# (ยืนยันเพิ่ม: log เดิมพิมพ์ "[PER_CONTAINER] แบ่งตู้ไม่สมมาตร (FRONT=0 BACK=2)" = FRONT
#  หาช่องไม่เจอ ส่วน BACK ซึ่งไม่มีเส้นมิติพาดผ่าน หาเจอปกติ x=[906,929] empty_frac=0.90)
#
# FIX: "เชื่อมท่อนที่ถูกฉีก" (bridging) - รวม 2 ท่อนว่างที่อยู่ติดกัน เมื่อคอลัมน์ที่คั่นอยู่
# ระหว่างท่อนมีสินค้าน้อยมาก (<= _INTER_CONTAINER_BRIDGE_MAX_CARGO_COL) และช่วงที่คั่นสั้น
# (<= _INTER_CONTAINER_BRIDGE_MAX_WIDTH_PX)
# *** ปลอดภัยโดยการออกแบบ: เป็นการ "รวมท่อน" เท่านั้น ไม่เคยขยายขอบนอกของท่อนใดเลย ***
#   -> ไฟล์/วิวที่ช่องว่างต่อเนื่องอยู่แล้ว (เช่น BACK ของไฟล์นี้) ได้ผลเหมือนเดิมทุก pixel
#   -> ไฟล์ที่ไม่มีช่องว่างเลย (รถตู้เดียว) ไม่เข้าเส้นทางนี้ตั้งแต่ต้น (n_containers < 2)
# เกณฑ์ที่ใช้ vs ค่าจริงที่วัดได้: สินค้าในคอลัมน์คั่น สูงสุด 5 px (เกณฑ์ 8) เทียบกับกอง
# สินค้าจริงข้างเคียง 98-136 px = ห่างกัน 12-17 เท่า | ความกว้างที่คั่น 1-2 px (เกณฑ์ 10)
_INTER_CONTAINER_BRIDGE_MAX_CARGO_COL = 8
_INTER_CONTAINER_BRIDGE_MAX_WIDTH_PX = 10    # ระยะเผื่อเวลาจับคู่ notch_x กับขอบช่องว่าง (วัดจริง
# notch_x อยู่ห่างจากขอบช่องว่างเพียง 1-3px - ตั้ง 40px ให้เผื่อไฟล์อื่นที่อาจคลาดเคลื่อนกว่านี้)


def _detect_multi_container_vehicle(pdf_bytes):
    """v25.92 NEW: ตรวจว่าเป็นรถประเภท "หลายตู้ต่อ 1 view" หรือไม่ จากข้อความประเภทรถใน PDF
    (เช่น "TTKAFT (Double Trailer) (1 / 1)") - ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล
    คืนค่า (n_containers: int, desc: str) - n_containers=1 หมายถึงรถตู้เดียวตามปกติ"""
    doc = None
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        for idx in range(len(doc)):
            try:
                text = doc[idx].get_text("text")
            except Exception:
                continue
            low = text.lower()
            for kw, n in _MULTI_CONTAINER_KEYWORDS.items():
                if kw in low:
                    desc = kw
                    for line in text.splitlines():
                        if kw in line.lower():
                            desc = line.strip()[:80]
                            break
                    print(f"[MULTI_CONTAINER] พบประเภทรถหลายตู้: '{desc}' "
                          f"-> n_containers={n} (จากหน้า index {idx})")
                    return n, desc
        return 1, ""
    except Exception as e:
        print(f"[MULTI_CONTAINER] ตรวจประเภทรถไม่สำเร็จ ({e}) -> ถือว่าเป็นรถตู้เดียว (fail-safe)")
        return 1, ""
    finally:
        if doc is not None:
            try:
                doc.close()
            except Exception:
                pass


def _find_inter_container_gaps(view_result, n_containers):
    """v25.92 NEW: หาช่องว่าง "ระหว่างตู้" ในวิวนี้ - คืนค่า list ของ (x0, x1) มากสุด
    (n_containers - 1) ช่อง โดยเรียงตามความกว้างจากมากไปน้อย (ดู docstring เต็มด้านบน)

    เงื่อนไขที่ช่องว่างต้องผ่านครบทุกข้อจึงจะถือว่าเป็น "ระหว่างตู้":
      - กว้างอย่างน้อย _INTER_CONTAINER_MIN_GAP_PX
      - มีกองสินค้าขนาดใหญ่พอ (_INTER_CONTAINER_MIN_CLUSTER_PX) ขนาบอยู่ทั้ง 2 ฝั่ง
      - ภายในช่องเป็นพื้นหลัง/ไร้โครงสร้างตู้ อย่างน้อย _INTER_CONTAINER_MIN_EMPTY_FRAC
        (ถ้ามีพื้นตู้/ผนังตู้วาดต่อเนื่องผ่านช่องนั้น = พื้นที่ว่างในตู้เดียวกัน = ความเสี่ยงจริง)
    """
    if n_containers < 2:
        return []
    cargo_mask = view_result.get("cargo_mask")
    region = view_result.get("region")
    sx, ex = view_result.get("start_x"), view_result.get("end_x")
    if cargo_mask is None or region is None or sx is None or ex is None or (ex - sx) < 60:
        return []

    col_cargo = cargo_mask.sum(axis=0)
    empty = col_cargo[sx:ex] <= _INTER_CONTAINER_MAX_CARGO_COL

    # v26.17: เชื่อมท่อนว่างที่ถูกเส้นมิติ/ลูกศรฉีกออกจากกัน (ดู docstring ที่
    # _INTER_CONTAINER_BRIDGE_MAX_CARGO_COL สำหรับ root cause + หลักฐาน pixel จริง)
    _negligible = col_cargo[sx:ex] <= _INTER_CONTAINER_BRIDGE_MAX_CARGO_COL
    _n_bridged = 0
    _i = 0
    _len = len(empty)
    while _i < _len:
        if not empty[_i]:
            _i += 1
            continue
        _j = _i
        while _j < _len and empty[_j]:
            _j += 1
        # _j = ตำแหน่งแรกหลังท่อนว่างนี้ -> มองไปข้างหน้าว่ามีท่อนว่างถัดไปใกล้ๆ หรือไม่
        _k = _j
        while (_k < _len and (_k - _j) < _INTER_CONTAINER_BRIDGE_MAX_WIDTH_PX
               and _negligible[_k] and not empty[_k]):
            _k += 1
        if _k > _j and _k < _len and empty[_k]:
            empty[_j:_k] = True          # เชื่อม: คอลัมน์คั่นมีสินค้าน้อยมากทุกคอลัมน์
            _n_bridged += (_k - _j)
            continue                      # เดินต่อจากตำแหน่งเดิม (ท่อนถูกรวมแล้ว)
        _i = _j + 1
    if _n_bridged:
        print(f"[INTER_CONTAINER] เชื่อมท่อนว่างที่ถูกเส้นมิติ/ลูกศรฉีก {_n_bridged} คอลัมน์ "
              f"(สินค้าในคอลัมน์คั่น <= {_INTER_CONTAINER_BRIDGE_MAX_CARGO_COL}px, "
              f"ช่วงคั่น <= {_INTER_CONTAINER_BRIDGE_MAX_WIDTH_PX}px) - ดู FIX v26.17")

    def _runs(flags):
        out, st = [], None
        for i, f in enumerate(flags):
            if f and st is None:
                st = i
            elif not f and st is not None:
                out.append((st + sx, i + sx))
                st = None
        if st is not None:
            out.append((st + sx, len(flags) + sx))
        return out

    # v25.96: เกณฑ์ความกว้างแบบ scale-invariant (ดู docstring ที่ _INTER_CONTAINER_MIN_GAP_ABS_PX)
    _min_gap = max(_INTER_CONTAINER_MIN_GAP_ABS_PX,
                   min(_INTER_CONTAINER_MIN_GAP_PX,
                       int((ex - sx) * _INTER_CONTAINER_MIN_GAP_SPAN_FRAC)))
    gaps = [g for g in _runs(empty) if (g[1] - g[0]) >= _min_gap]
    clusters = [c for c in _runs(~empty) if (c[1] - c[0]) >= _INTER_CONTAINER_MIN_CLUSTER_PX]
    if not gaps or len(clusters) < 2:
        return []

    validated = []
    for g0, g1 in gaps:
        left = [c for c in clusters if c[1] <= g0 + 2]
        right = [c for c in clusters if c[0] >= g1 - 2]
        if not left or not right:
            continue
        band = region[:, g0:g1]
        is_white = (band > 240).all(axis=2)
        is_struct = np.zeros(is_white.shape, dtype=bool)
        for sc in _STRUCTURAL_CONTAINER_COLORS:
            d = np.abs(band.astype(int) - np.array(sc, dtype=int))
            is_struct |= (d[:, :, 0] <= _STRUCTURAL_COLOR_TOL) & \
                         (d[:, :, 1] <= _STRUCTURAL_COLOR_TOL) & \
                         (d[:, :, 2] <= _STRUCTURAL_COLOR_TOL)
        empty_frac = float(is_white.mean())
        struct_frac = float(is_struct.mean())
        if empty_frac < _INTER_CONTAINER_MIN_EMPTY_FRAC:
            print(f"[INTER_CONTAINER] ปฏิเสธช่องว่าง x=[{g0},{g1}] w={g1-g0} "
                  f"empty_frac={empty_frac:.2f} < {_INTER_CONTAINER_MIN_EMPTY_FRAC} "
                  f"(struct_frac={struct_frac:.2f}) -> มีโครงสร้างตู้ต่อเนื่อง = "
                  f"พื้นที่ว่างในตู้เดียวกัน ไม่ใช่ช่องระหว่างตู้")
            continue
        validated.append((g0, g1, g1 - g0, empty_frac))

    if not validated:
        return []

    # เลือกเฉพาะช่องที่กว้างที่สุด จำนวนไม่เกิน (n_containers - 1) ช่อง
    validated.sort(key=lambda t: -t[2])
    chosen = validated[:max(0, n_containers - 1)]
    for g0, g1, w, ef in chosen:
        print(f"[INTER_CONTAINER] ยืนยันช่องว่างระหว่างตู้ x=[{g0},{g1}] w={w} "
              f"empty_frac={ef:.2f}")
    return [(g0, g1) for g0, g1, _w, _ef in chosen]


def _suppress_inter_container_empty_space_risks(risks, view_result, view_label, n_containers):
    """v25.92 NEW: ตัด EMPTY_SPACE_RISK (กรอบส้ม) ที่ตกอยู่ในช่องว่าง "ระหว่างตู้" ออก
    (ไม่แตะ STEP_DOWN_RISK กรอบแดงเลย ตามที่ผู้ใช้ระบุ) - ดู docstring เต็มด้านบน"""
    if n_containers < 2:
        return risks
    gaps = _find_inter_container_gaps(view_result, n_containers)
    if not gaps:
        return risks

    tol = _INTER_CONTAINER_MATCH_TOL_PX
    kept = []
    for r in risks:
        if (r.get("risk_type") != "EMPTY_SPACE_RISK"
                or (r.get("mark_view") or r.get("view")) != view_label):
            kept.append(r)
            continue
        # v25.95 FIX (ผู้ใช้แจ้ง 12-Sep-2026 พร้อมภาพ GC06-02 TTKAFT Double Trailer:
        # "กรอบส้มค่อมระหว่างตู้ ต้องไม่มีทั้ง front view กับ back view"): เดิม (v25.92) จับคู่
        # ด้วย "จุดอ้างอิงจุดเดียว" (notch_x หรือจุดกึ่งกลางของ mark_x_range) ว่าตกอยู่ในช่องว่าง
        # หรือไม่ - พบว่ากรอบส้มที่ "คร่อม" ช่องว่างระหว่างตู้ (กว้างกว่าตัวช่องว่างมาก) จะมีจุด
        # กึ่งกลางตกอยู่ "นอก" ช่องว่างได้ง่าย (เพราะกรอบกินพื้นที่ของตู้ทั้ง 2 ฝั่งไปด้วย)
        # -> หลุดการยกเว้น -> ยังวาดกรอบคร่อมระหว่างตู้อยู่
        # FIX: เปลี่ยนเป็น overlap-based - ถ้ากรอบ "ทับซ้อน" กับช่องว่างระหว่างตู้อย่างมีนัยสำคัญ
        # (>=30% ของความกว้างช่องว่าง) หรือจุดอ้างอิงตกอยู่ในช่องว่าง ให้ยกเว้นทั้งคู่
        # เป็นการ "ขยายการยกเว้น" ให้ครอบคลุมขึ้นเท่านั้น (เข้มขึ้น ไม่ผ่อนปรน) จึงไม่มีทาง
        # ทำให้กรอบส้มที่เคยถูกยกเว้นอยู่แล้วกลับมาปรากฏใหม่ได้เลย
        mx = r.get("mark_x_range")
        ref_x = r.get("notch_x")
        if ref_x is None and mx:
            ref_x = (mx[0] + mx[1]) // 2
        hit = None
        for g0, g1 in gaps:
            if ref_x is not None and (g0 - tol) <= ref_x <= (g1 + tol):
                hit = (g0, g1); break
            if mx:
                # v26.15 FIX (ผู้ใช้แจ้ง 16-Sep-2026: "กรอบที่ผิดคือ คร่อมทั้งสองตู้
                # ประเภทรถพ่วง"): เดิมยกเว้นเฉพาะเมื่อกรอบทับช่องว่าง >=30% ของความกว้าง
                # ช่องว่าง - แต่กรอบส้มที่ "คร่อม" ช่องว่างทั้งช่อง (ขอบซ้ายอยู่ก่อนช่อง
                # ขอบขวาอยู่หลังช่อง) มักกว้างกว่าตัวช่องว่างมาก ทำให้สัดส่วนที่คำนวณได้
                # อาจไม่ถึงเกณฑ์ -> หลุดการยกเว้น -> ถูกส่งต่อไปที่ _clip_risks_at_container_gaps
                # ซึ่ง "ตัดกรอบให้เหลือฝั่งเดียว" แทนที่จะลบทิ้ง -> ยังเหลือกรอบส้มผิดอยู่
                # ROOT CAUSE เชิงความหมาย: กรอบส้มที่คร่อมช่องว่างระหว่างตู้ มี "จุดกำเนิด"
                # มาจากช่องว่างทางกายภาพระหว่าง 2 ตู้ (ไม่ใช่โพรงภายในกองสินค้า) จึงต้อง
                # ปฏิเสธทั้ง risk ไม่ใช่แค่ย่อขนาดกรอบ
                # FIX: เพิ่มเงื่อนไข "คร่อมทั้งช่อง" เป็นอีกกรณีที่ยกเว้นทันที
                if mx[0] < g0 and mx[1] > g1:
                    hit = (g0, g1); break
                inter = max(0, min(mx[1], g1) - max(mx[0], g0))
                if inter >= 0.3 * max(1, g1 - g0):
                    hit = (g0, g1); break
        if hit is not None:
            print(f"[INTER_CONTAINER] ยกเว้นกรอบส้ม {r.get('subtype')} view={view_label} "
                  f"mark_x={mx} ref_x={ref_x} เพราะทับช่องว่างระหว่างตู้ "
                  f"x=[{hit[0]},{hit[1]}] (รถ {n_containers} ตู้)")
            continue
        kept.append(r)
    return kept


# ============================================================================
# v25.97 NEW: PER-CONTAINER ANALYSIS (ผู้ใช้สั่ง "gc06 วิเคราะห์แต่ละตู้แยกกันเหมือนตู้เดี่ยว")
# ============================================================================
# ปัญหาที่แก้: กลไก STEP_DOWN ทั้งหมดตั้งอยู่บนสมมติฐาน "1 view = 1 ตู้" แต่รถพ่วง (TTKAFT
# Double Trailer) มี 2 ตู้ในภาพเดียว -> start_x/end_x/apex/pos_range/edge-column ถูกคำนวณ
# รวม 2 ตู้เป็นก้อนเดียว ทำให้:
#   (1) pos_range ผิดความหมาย - "ท้ายรถ" (pos>=0.85) ไปตกกลางตู้ใบที่ 2 ส่วนท้ายจริงของตู้
#       ใบที่ 1 อยู่ที่ pos~0.5 จึงไม่เคยถูกมองว่าเป็นท้ายเลย
#   (2) Edge-Column Global Consensus Guard คุ้มครองเฉพาะ idx=0 และ idx=max ของทั้ง view
#       -> "ปลายตู้ใบที่ 1" และ "หัวตู้ใบที่ 2" ถูกมองเป็นคอลัมน์กลาง ทั้งที่เป็นขอบจริง
#       ทางกายภาพ -> ไม่ได้รับการป้องกันจาก isometric edge-bias เลย
#   (3) plateau/median ถูกคำนวณข้ามตู้ - ตู้ที่โหลดสูงไปกลบตู้ที่โหลดต่ำ
#   (4) apex ถูกตรวจเจอ 2 อัน (ตู้ละ 1) แต่ฟังก์ชันคืนค่าได้ตัวเดียว -> apex_x ผิดตำแหน่ง
# ผลที่วัดได้จริงกับ GC06-02: กรอบแดง 2 จุดที่ FRONT (cross_view idx=0 drop=67.6%,
# hidden_behind idx=4 drop=34.8%) เกาะอยู่ที่ปลายตู้ใบที่ 1 / ขอบช่องว่างพอดี
#
# FIX: ก่อนวิเคราะห์ ให้ "ตัดตู้" ด้วย _find_inter_container_gaps (ซึ่งตั้งแต่ v25.96 ตรวจ
# ช่องว่างแคบของ GC06 ได้แล้ว) แล้วสร้าง sub-view ของแต่ละตู้ที่มี start_x/end_x เป็นของตัวเอง
# จากนั้นคำนวณ records ใหม่ต่อตู้ (normalize pos_range ภายในตู้นั้น) แล้ววิเคราะห์แยกกัน
# เหมือนตู้เดี่ยวทุกประการ สุดท้ายรวมผลกลับมาพร้อม map ตำแหน่งกลับสู่พิกัดภาพเดิม
#
# ขอบเขตความปลอดภัย (สำคัญ): ทำงาน "เฉพาะเมื่อ" ครบทุกเงื่อนไข
#   (1) n_containers >= 2 จากข้อความใน PDF (ด่านที่เข้มที่สุด - รถตู้เดียวไม่เข้าเส้นทางนี้เลย)
#   (2) พบช่องว่างระหว่างตู้จริงในภาพ (ผ่าน _find_inter_container_gaps ครบทุกเกณฑ์)
#   (3) แต่ละตู้ต้องมี records อย่างน้อย _PER_CONTAINER_MIN_RECORDS คอลัมน์
# ถ้าข้อใดไม่ผ่าน -> คืน None แล้ว fallback ไปใช้เส้นทางเดิมทั้งหมด (ไม่มีการเปลี่ยนพฤติกรรม)
_PER_CONTAINER_MIN_RECORDS = 2


def _split_records_by_container(records, gaps):
    """v25.97: แบ่ง records ออกเป็นกลุ่มตามตู้ โดยใช้ช่องว่างระหว่างตู้เป็นเส้นแบ่ง
    คืน list ของ (container_idx, [records ของตู้นั้น]) - normalize pos_range ใหม่ภายในตู้"""
    if not records or not gaps:
        return None
    bounds = sorted((g0 + g1) / 2.0 for g0, g1 in gaps)
    groups = {}
    for r in records:
        x0, x1 = r["x_range"]
        cx = (x0 + x1) / 2.0
        ci = sum(1 for b in bounds if cx > b)
        groups.setdefault(ci, []).append(r)
    out = []
    for ci in sorted(groups):
        grp = sorted(groups[ci], key=lambda r: r["x_range"][0])
        xs = min(r["x_range"][0] for r in grp)
        xe = max(r["x_range"][1] for r in grp)
        span = max(1, xe - xs)
        new = []
        for r in grp:
            r2 = dict(r)
            a, b = r["x_range"]
            # normalize ตำแหน่งใหม่ "ภายในตู้นี้" (0.0 = หัวตู้, 1.0 = ท้ายตู้)
            r2["pos_range"] = ((a - xs) / span, (b - xs) / span)
            r2["_orig_pos_range"] = r.get("pos_range")
            r2["_container_idx"] = ci
            new.append(r2)
        out.append((ci, new))
    return out


def _analyse_per_container(front, back, records_front, records_back, n_containers):
    """v25.97: วิเคราะห์แต่ละตู้แยกกันเหมือนตู้เดี่ยว แล้วรวมผล
    คืน list ของ risks หรือ None ถ้าไม่เข้าเงื่อนไข (ให้ fallback ไปเส้นทางเดิม)
    (ดู docstring เต็มด้านบนสำหรับเหตุผล+ขอบเขตความปลอดภัย)"""
    if not n_containers or n_containers < 2:
        return None
    gaps_f = _find_inter_container_gaps(front, n_containers) if front else []
    gaps_b = _find_inter_container_gaps(back, n_containers) if back else []
    if not gaps_f and not gaps_b:
        print("[PER_CONTAINER] รถระบุว่าหลายตู้ แต่หาช่องว่างในภาพไม่พบ -> ใช้เส้นทางเดิม")
        return None
    sf = _split_records_by_container(records_front, gaps_f)
    sb = _split_records_by_container(records_back, gaps_b)
    if not sf or not sb or len(sf) != len(sb):
        print(f"[PER_CONTAINER] แบ่งตู้ไม่สมมาตร (FRONT={len(sf) if sf else 0} "
              f"BACK={len(sb) if sb else 0}) -> ใช้เส้นทางเดิม")
        return None
    for _ci, g in sf + sb:
        if len(g) < _PER_CONTAINER_MIN_RECORDS:
            print(f"[PER_CONTAINER] ตู้ที่ {_ci} มีเพียง {len(g)} คอลัมน์ "
                  f"(<{_PER_CONTAINER_MIN_RECORDS}) -> ใช้เส้นทางเดิม")
            return None

    print(f"[PER_CONTAINER] แบ่งได้ {len(sf)} ตู้ -> วิเคราะห์แยกกันเหมือนตู้เดี่ยว")
    all_risks = []
    for (ci, rf), (_cj, rb) in zip(sf, sb):
        print(f"[PER_CONTAINER] === ตู้ที่ {ci + 1}/{len(sf)}: "
              f"FRONT {len(rf)} คอลัมน์ x=[{rf[0]['x_range'][0]},{rf[-1]['x_range'][1]}] | "
              f"BACK {len(rb)} คอลัมน์ x=[{rb[0]['x_range'][0]},{rb[-1]['x_range'][1]}]")
        sub = []
        single = _is_single_stack_sparse_load(rf, rb)
        # v26.06: กล่องใหญ่วางแถวเดียว -> ไม่ให้ cross_view จับ (ดู _is_large_box_single_row)
        large_box = (_is_large_box_single_row(front, rf, "FRONT")
                     and _is_large_box_single_row(back, rb, "BACK"))
        sub += detect_step_down_pairwise(rf, "FRONT", view_result=front)
        sub += detect_step_down_pairwise(rb, "BACK", view_result=back)
        if not single and not large_box:
            sub += detect_step_down_crossview(rf, rb, front_result=front, back_result=back)
        _tail = (detect_tail_stepdown(rf, "FRONT", view_result=front)
                 + detect_tail_stepdown(rb, "BACK", view_result=back))
        sub += [r for r in _tail if _tail_stepdown_crossview_confirmed(r, rf, rb)]
        if not single:
            sub += detect_rear_empty_risk(rf, rb, front, back)
        for r in sub:
            r["_container_idx"] = ci
            # คืน pos_range เดิม (พิกัดทั้ง view) ไว้ใน key แยก เผื่อ downstream ต้องใช้
            r["container_pos_range"] = r.get("pos_range")
        print(f"[PER_CONTAINER]     -> ตู้ที่ {ci + 1} พบ {len(sub)} จุด")
        all_risks += sub

    # hidden_behind ทำงานที่ระดับ "ภายในคอลัมน์เดียว" (ไม่เปรียบเทียบข้ามคอลัมน์)
    # จึงไม่ได้รับผลกระทบจากการแบ่งตู้ - เรียกครั้งเดียวกับทั้ง view ตามเดิม
    all_risks += detect_step_down_hidden_behind(front, records_front, "FRONT")
    all_risks += detect_step_down_hidden_behind(back, records_back, "BACK")

    # v26.01: ตรวจเขตท้ายรถของทั้ง view (ไม่ผูกกับ idx จึงไม่ต้องแบ่งตู้)
    all_risks += detect_tailzone_wall_exposure(front, records_front, "FRONT")
    return all_risks


# ============================================================================
# v26.01 NEW: TAIL-ZONE WALL EXPOSURE (แก้ false-negative ที่ค้างมาตั้งแต่ v25.93)
# ============================================================================
# แนวทางมาจากผู้ใช้โดยตรง หลังผมล้มเหลว 6 ครั้งติดต่อกัน:
#   "สามเหลี่ยมที่วาดให้ดู เกิดจากมุมของกล่องตัวในลากมาหามุมของกล่องตัวนอก และภายใน
#    สามเหลี่ยมไม่ปรากฏสีกล่องใดๆ จึงแน่ชัดว่ามีความเสี่ยงจากพื้นที่ช่องว่างบริเวณจุดนั้น"
#   "มองให้เหมือนคนมอง อย่ามัวแต่ลากเส้น idx กับวัด px รถมันเอียง ค่า px เชื่อถือไม่ได้"
#   "ผนังมีเส้นแบ่งเป็นช่วงๆ ... พิสูจน์ว่าสีในสามเหลี่ยมมีสีผนังมากกว่าสีกล่องใดๆ
#    เพื่อยืนยันว่าเป็นโพรงสูงต่ำ"
#   "กลไกใหม่ ใช้จับประเภท เป็นกล่องเล็ก วางด้านนอกกับด้านใน เหมือนกับ cross pair"
#
# ใช้ 2 เงื่อนไขร่วมกันแบบ AND (ทั้งคู่มาจากคำอธิบายของผู้ใช้ตรงๆ):
#
# เงื่อนไขที่ 1 - "ผนังโผล่ในเขตท้ายรถ" (สามเหลี่ยมที่ไม่มีสีกล่อง):
#   ถ้าวางเต็ม -> กล่องบังผนังไว้ -> เห็นผนังน้อยมาก
#   ถ้ามีโพรง  -> ผนังด้านหลังโผล่ -> เห็นผนังมากขึ้นชัดเจน
#   วัดจริง (FRONT, เขตปลายซ้าย 20% แรก): ปลอดภัยเต็มตู้ 1.4-1.7% (เกาะกลุ่มแน่นมาก)
#                                          เสี่ยงจริง    4.1-10.4%
#   -> เกณฑ์ 3.0% อยู่กึ่งกลาง (margin 1.8 เท่าจากฝั่งปลอดภัย)
#   ยืนยันนิยามผู้ใช้ถูกต้อง 100%: EC51-01 (ผู้ใช้ลากสามเหลี่ยมให้ดูว่า "มีผิวกล่องปรากฏ")
#   วัดได้ 1.5% | EC52-02 ("ไม่มีสีกล่องใดๆ") วัดได้ 4.1% = สูงกว่า 2.7 เท่า ทั้งที่
#   สัดส่วนกล่องใกล้เคียงกัน (52.7% vs 61.3%) -> ตัวแปรที่แยกได้คือ "ผนังโผล่" ไม่ใช่ "ปริมาณกล่อง"
#
# เงื่อนไขที่ 2 - "เป็นกล่องเล็กวางนอก+ใน" (ตามที่ผู้ใช้ระบุขอบเขตการใช้งาน):
#   ผู้ใช้ชี้ความต่างที่ชี้ขาด: "EC05-01 เป็นกล่องเล็ก วางด้านนอกกับด้านใน" (เสี่ยง)
#                              "EB91-01 เป็นกล่องใหญ่กินพื้นที่เต็มด้านนอกกับด้านใน" (ปลอดภัย)
#   -> กล่องใหญ่กินเต็มความลึก = ไม่มีทางเกิดโพรงระหว่างแถวได้เลยโดยโครงสร้าง
#   สัญญาณที่วัดได้: "จำนวนผิวบน (top face) ที่มองเห็นทั้งวิว"
#     กล่องเล็กวาง 2 แถว -> เห็นผิวบนหลายชิ้น (ทั้งแถวนอกและแถวใน)
#     กล่องใหญ่เต็มลึก   -> เห็นผิวบนน้อยชิ้น (1 กอง = 1 ผิวบน)
#   วัดจริง: เสี่ยง  EC05-01=6  EC52-02=6  EC58-02=4   (+GC06 รถ2ตู้=12)
#            ปลอดภัย EC09=3  EB91-01=2  EC16-01=2  EC20-02=1  EC51-01/EC01-04/EC19-01=0
#   -> เกณฑ์ >=4 แยกได้ขาด 100% (ไม่มีค่าใดคาบเกี่ยวกันเลย)
#
# ผลรวมของ 2 เงื่อนไข (ยืนยันด้วยข้อมูลจริงทุกไฟล์ที่ผู้ใช้เคยยืนยันสถานะไว้):
#   ไฟล์        ผนัง%   ผิวบน  ผล      สถานะจริง (ผู้ใช้ยืนยัน)
#   EC58-02     10.4      4    FLAG    เสี่ยง (cyan เตี้ย 1 ชั้น)        ตรวจพบถูกต้อง
#   EC05-01      6.6      6    FLAG    เสี่ยง (โพรงใหญ่ท้ายรถ)          ตรวจพบถูกต้อง
#   EC52-02      4.1      6    FLAG    เสี่ยง (โพรงสูงต่ำ)              ตรวจพบถูกต้อง
#   -----------------------------------------------------------------------------
#   EC09        37.9      3    ผ่าน    ปลอดภัย (กล่องใหญ่ KAP1A)        เงื่อนไขที่ 2 กรอง
#   EC16-01     52.2      2    ผ่าน    ปลอดภัย (โหลดเบามาก 4 กล่อง)     เงื่อนไขที่ 2 กรอง
#   EB91-01      6.9      2    ผ่าน    ปลอดภัย (กล่องใหญ่เต็มลึก)       เงื่อนไขที่ 2 กรอง
#   EC20-02      3.1      1    ผ่าน    เต็มตู้ 95.1%                    เงื่อนไขที่ 2 กรอง
#   EC51-01      1.5      0    ผ่าน    ปลอดภัย (เต็มตู้)                เงื่อนไขที่ 1 กรอง
#   EC01-04      1.7      0    ผ่าน    ปลอดภัย (เต็มตู้)                เงื่อนไขที่ 1 กรอง
#   EC19-01     ~1.5      0    ผ่าน    ปลอดภัย (เต็มตู้)                เงื่อนไขที่ 1 กรอง
#   *** false-positive = 0 | true-positive = 3/3 ***
#
# *** FRONT view เท่านั้น (ผู้ใช้กำหนดเป็นเงื่อนไขโดยตรง) ***
# สอดคล้องกับหลักฐานเชิงเทคนิค: BACK view มี artifact เชิงระบบที่ให้ค่าซ้ำข้ามไฟล์ที่ไม่
# เกี่ยวข้องกันเลย (v25.98: EB90-01/02/03+EC20-01 ได้ 334/256/78 เท่ากันเป๊ะ |
# interior-void: EC51-01=16,557px vs EC51-03=16,556px ต่างกัน 1px)
#
# วิธีที่ล้มเหลวมาก่อน 6 ครั้ง (บันทึกไว้เพื่อไม่ให้ลองซ้ำ - ทั้งหมดพยายามอนุมานความลึก
# จากภาพ 2 มิติ ซึ่ง cargo_top_y ทิ้งข้อมูลนั้นไปตั้งแต่ต้นทางแล้ว):
#   1. v25.94 Roof-Facet Ladder (เทียบ facet ข้ามคอลัมน์) -> edge-column bias, FP 4 ไฟล์
#   2. Step spacing 78px -> EC01-04 ปลอดภัยมี 5 จุด ~ EC52-02 เสี่ยง 6 จุด แยกไม่ได้
#   3. ระยะว่างใต้เพดาน (roofline fit) -> FRONT fit ไม่ได้เลยทั้ง 5 ไฟล์
#   4. เดินขึ้นจากพื้นหาแถวนอก -> ตัวอักษร SKU ตัดเส้นทาง ค่าแกว่ง 33-345px
#   5. v25.98 Dual top-face gap (top-to-top) -> วัดความสูง parallelogram (ค่าคงที่เรนเดอร์)
#   6. Triangle band height -> EC05-01 ปลอดภัย(86px) > EC52-02 เสี่ยง(71px) แยกไม่ได้
_TAILZONE_WALL_MIN_PCT = 3.0        # ผนังโผล่เกินนี้ = มีโพรง (เต็มตู้วัดได้ 1.4-1.7%)
_TAILZONE_MIN_TOPFACES = 4          # ผิวบนที่เห็นทั้งวิว >= นี้ = กล่องเล็กวางนอก+ใน
_TAILZONE_SPAN_FRAC = 0.20          # เขตท้ายรถ = 20% แรกของความยาวสินค้า (ซ้ายสุดของ FRONT)
_TAILZONE_MIN_WIDTH_PX = 60
_TAILZONE_ROOF_PERCENTILE = 8
_TAILZONE_MIN_SAMPLES = 500
_TAILZONE_ZONE_TOP_MARGIN_PX = 40   # v26.02: เผื่อเหนือยอดสินค้าในเขต (ดู FIX #1)
_TAILZONE_WALL_ROW_MIN_PX = 3       # v26.02: แถวที่มีผนัง >= นี้ ถือว่าเป็นแถวผนังจริง
_TAILZONE_TOPLINE_MIN_POINTS = 10   # v26.05: จุดขั้นต่ำสำหรับ fit เส้นยอดลาดเอียง (ดู FIX)
_TAILZONE_TOPLINE_MARGIN_PX = 8     # v26.05: เผื่อใต้เส้น fit เล็กน้อย กัน anti-alias ที่ขอบ
_TAILZONE_TOPLINE_MAX_RESID = 3.0   # v26.05: resid_std เกินนี้ = เส้นยอดเป็นขั้นบันได
# (fit เชื่อถือไม่ได้ และตัวมันเองคือสัญญาณของความสูงไม่เท่ากัน) -> ไม่ตัดพื้นที่ใดทิ้ง
# วัดจริง 20 ไฟล์: เรียบ <=0.54 | ขั้นบันได >=11.84 -> แยกขาด 22 เท่า (ดู FIX ใน detector)
_TAILZONE_TF_MIN_ASPECT = 1.25      # parallelogram ผิวบนต้องกว้างกว่าสูง
_TAILZONE_TF_MIN_WIDTH_FRAC = 0.55
_TAILZONE_TF_MIN_AREA = 600
_TAILZONE_TF_MIN_COLOR_PX = 700
# v26.16 NEW: เงื่อนไขที่ 3 - "เขตท้ายรถต้องมีพื้นที่ว่างจริง (silhouette แหว่ง)"
# ที่มา: ผู้ใช้ชี้ด้วยลูกศรบนภาพจริง 17-Sep-2026 (CD11-02, CC20-02) ว่ากรอบส้มท้ายรถ 2 จุดนี้
# "วาดเกินมา บริเวณนั้นปลอดภัย"
# ROOT CAUSE: เงื่อนไขเดิม 2 ข้อ (ผนังโผล่ >= 3% และผิวบน >= 4) ยังผ่านได้ในกรณีที่ "กองเต็ม
# แต่เตี้ยกว่าความสูงตู้ทั้งคัน" - ผนัง/รางที่นับได้มาจากผนังตู้ที่อยู่เหนือกองสินค้าตลอดแนว
# (ไม่ใช่โพรงเฉพาะจุดท้ายรถ) ยืนยันด้วยภาพ: CD11 กล่องน้ำเงินขนาดเท่ากันทั้งหมดวางเต็มทั้งนอก
# และใน | CC20 กล่อง KAPI-A แดงวางเต็มบล็อก 2 แถว สูงเท่ากันหมด
# หลักฐานเชิงตัวเลข (สัดส่วน pixel พื้นหลังสีขาว = นอกเงาของตู้/กองสินค้า ในเขตท้ายรถเดียวกัน
# กับที่ใช้วัดผนัง):
#   จุดที่ผู้ใช้ชี้ว่าผิด : CD11 = 7.6% | CC20 = 16.8%
#   จุดที่ผู้ใช้ไม่ได้ทัก : CC19 = 27.5% | CC05 = 30.8% | CE01 = 35.0%
#   -> เกณฑ์ 22.0% อยู่กึ่งกลาง (ห่างฝั่งผิด 1.31 เท่า / ฝั่งถูก 1.25 เท่า)
# เหตุผลเชิงกายภาพ: "โพรงสูงต่ำ" ที่ท้ายรถทำให้เส้นเงารอบนอกของกองสินค้าแหว่งลงไป เขตสแกน
# สี่เหลี่ยมจึงกินพื้นหลังสีขาวนอกเงาเข้ามาด้วยเสมอ - ถ้าเขตนั้นถูก "สินค้า + โครงตู้" ปิดทึบ
# เกือบหมด (ขาว < 22%) แปลว่าไม่มีรอยแหว่งที่ท้ายรถเลย
# *** ข้อจำกัดที่ต้องบอกตรงๆ: เกณฑ์นี้ปรับเทียบจาก 5 ไฟล์ที่มีข้อมูลจริงในรอบนี้เท่านั้น
#     (2 ผิด / 3 ถูก) ยังไม่ได้ทวนกับชุดไฟล์ EC05-01/EC52-02/GC06 ที่ใช้ตั้งเกณฑ์ v26.01 ***
_TAILZONE_MIN_WHITE_PCT = 22.0


def _count_visible_top_faces(view_result, records):
    """v26.01: นับ 'ผิวบน' (top face) ที่มองเห็นได้ทั้งวิว - ตัวชี้วัดว่าเป็นกล่องเล็กวาง
    หลายแถวตามความลึก (เห็นหลายผิวบน) หรือกล่องใหญ่กินเต็มความลึก (เห็นน้อย/ไม่เห็นเลย)
    ดู docstring เต็มด้านบน 'เงื่อนไขที่ 2' สำหรับหลักฐาน+เหตุผล (แนวทางจากผู้ใช้)"""
    reg = view_result.get("region")
    if reg is None or not records:
        return 0
    n = 0
    for rec in records:
        if rec.get("is_corner_duplicate"):
            continue
        x0, x1 = rec["x_range"]
        colw = max(1, x1 - x0)
        lo, hi = x0 + 6, x1 - 6
        if hi <= lo:
            continue
        sub = reg[:, lo:hi].reshape(-1, 3)
        if sub.size == 0:
            continue
        try:
            cols, cnts = np.unique(sub, axis=0, return_counts=True)
        except Exception:
            continue
        for i in np.argsort(-cnts)[:10]:
            c = tuple(int(q) for q in cols[i])
            if int(cnts[i]) < _TAILZONE_TF_MIN_COLOR_PX:
                continue
            if _p1b_is_structural_container_color(c):
                continue
            if max(c) < 50 or min(c) > 240:
                continue
            mk = ((reg[:, :, 0] == c[0]) & (reg[:, :, 1] == c[1]) & (reg[:, :, 2] == c[2]))
            mk[:, :lo] = False
            mk[:, hi:] = False
            lab, nn = ndimage.label(mk, structure=np.ones((3, 3), int))
            if nn == 0:
                continue
            for li, sl in enumerate(ndimage.find_objects(lab), start=1):
                if sl is None:
                    continue
                ys_, xs_ = sl
                w = xs_.stop - xs_.start
                h = ys_.stop - ys_.start
                area = int((lab[sl] == li).sum())
                if area < _TAILZONE_TF_MIN_AREA or h <= 0:
                    continue
                if (w / h) >= _TAILZONE_TF_MIN_ASPECT and w >= _TAILZONE_TF_MIN_WIDTH_FRAC * colw:
                    n += 1
    return n


def detect_tailzone_wall_exposure(view_result, records, view_label):
    """v26.01 NEW: ตรวจ 'โพรงสูงต่ำ' ที่ท้ายรถ - FRONT view เท่านั้น
    (ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล - แนวทางมาจากผู้ใช้โดยตรง)"""
    if view_result is None or view_label != "FRONT":
        return []
    reg = view_result.get("region")
    cm = view_result.get("cargo_mask")
    cty = view_result.get("cargo_top_y")
    lfy = view_result.get("local_floor_y")
    sx, ex = view_result.get("start_x"), view_result.get("end_x")
    if reg is None or cm is None or cty is None or lfy is None:
        return []
    if sx is None or ex is None or (ex - sx) < _TAILZONE_MIN_WIDTH_PX:
        return []
    cty = np.asarray(cty, int)
    lfy = np.asarray(lfy, float)

    # v26.27 FIX#2: PER-CONTAINER ROOF REFERENCE (พบจริงจาก CD08-all front view)
    #  อาการ: ตู้ซ้ายของรถพ่วง 2 ตู้ (TTKAFT Double Trailer) ถูกวาดกรอบส้ม
    #  tailzone_wall_exposure ทั้งที่กล่องในตู้นั้นสูงสม่ำเสมอกันทั้งตู้
    #
    #  ROOT CAUSE (วัดค่าจริงจาก log): roof_y ถูกคำนวณจาก percentile ของ cargo_top_y
    #  ตลอดช่วง [start_x, end_x] ซึ่งกินทั้ง 2 ตู้รวมกัน  แต่ตู้ขวาของไฟล์นี้บรรทุกสูงกว่า
    #  ตู้ซ้ายมาก (กล่องน้ำเงิน 3 ชั้น เทียบกล่องเขียว 2 ชั้น) roof_y จึงถูกดึงขึ้นไปอยู่ที่
    #  ระดับหลังคาของ "ตู้ขวา"  พอเอามาเป็นเพดานของโซนหัวรถซึ่งอยู่ใน "ตู้ซ้าย" จึงนับ
    #  ช่องว่างเหนือกองของตู้ซ้าย (ที่ว่างตามปกติเพราะตู้สูง 2400mm แต่ของสูงแค่ ~1016mm)
    #  รวมเข้าเป็น "พื้นหลังว่าง" ด้วย  วัดได้ 26.2% เกินเกณฑ์ 22.0% ไปเล็กน้อย -> FLAG ผิด
    #  (กล่อง=67.6% ผนัง=6.2% ซึ่งบ่งชี้ว่าโซนนี้มีสินค้าวางเต็มอยู่แล้วจริง)
    #
    #  FIX: ถ้าเป็นรถหลายตู้ ให้คิด roof_y จากเฉพาะ "ตู้ที่โซนนั้นอยู่" (ตู้แรก) เท่านั้น
    #  ใช้ช่องว่างระหว่างตู้ที่ระบบคำนวณไว้แล้วใน _inter_container_gaps เป็นตัวตัดขอบ
    #  ไม่กระทบรถตู้เดียวเลย (ไม่มี gap -> ใช้ช่วงเดิมทั้งหมดเหมือนเดิมทุกประการ)
    _roof_ex = ex
    _gaps = view_result.get("_inter_container_gaps") or []
    for _g0, _g1 in _gaps:
        if sx < _g0 < ex:
            _roof_ex = min(_roof_ex, int(_g0))
            break
    if _roof_ex - sx < _TAILZONE_MIN_WIDTH_PX:
        _roof_ex = ex
    vals = [cty[x] for x in range(sx, _roof_ex) if 0 <= x < len(cty) and cty[x] >= 0]
    if len(vals) < 20:
        return []
    roof_y = int(np.percentile(vals, _TAILZONE_ROOF_PERCENTILE))
    if _roof_ex != ex:
        print(f"[TAILZONE] รถหลายตู้ -> คิดระดับหลังคาจากตู้แรกเท่านั้น "
              f"x=[{sx},{_roof_ex}] (เดิมใช้ทั้งคัน x=[{sx},{ex}]) roof_y={roof_y}")

    span = ex - sx
    zx0 = sx
    zx1 = min(sx + max(_TAILZONE_MIN_WIDTH_PX, int(span * _TAILZONE_SPAN_FRAC)),
              reg.shape[1], ex)
    if zx1 <= zx0:
        return []
    floors = [lfy[x] for x in range(zx0, zx1) if 0 <= x < len(lfy) and lfy[x] >= 0]
    if not floors:
        return []
    floor_y = int(np.median(floors))
    if floor_y <= roof_y:
        return []

    # v26.02 FIX #1 (ผู้ใช้แจ้ง "gc06 - กรอบส้มสูงเกินไป"): เดิมใช้ roof_y ซึ่งคำนวณจาก
    # percentile ของ "ทั้ง view" เป็นขอบบนของเขตสแกน - พบว่าในรถที่บางช่วงโหลดสูงกว่าช่วงอื่น
    # มาก (โดยเฉพาะรถ 2 ตู้ที่ตู้หนึ่งโหลดสูงกว่าอีกตู้) roof_y จะเป็นยอดของ "ตู้ที่สูงที่สุด"
    # ไม่ใช่ยอดของเขตท้ายรถที่กำลังตรวจ ทำให้เขตสแกน (และกรอบที่วาด) สูงเกินจริงมาก
    # ยืนยันด้วย pixel จริงจาก GC06: roof_y ทั้ง view = 86 แต่ยอดสินค้าจริงในเขตท้าย = 324
    # (ต่ำกว่า 238px) -> กรอบสูง 513px ทั้งที่บริเวณที่เห็นผนังจริงมีแค่ y=320..580 (260px)
    # FIX: จำกัดขอบบนของเขตสแกนด้วย "ยอดสินค้าสูงสุดที่พบในเขตนั้นเอง" (เผื่อ margin เล็กน้อย
    # ให้ครอบคลุมผนังที่อยู่เหนือยอดสินค้าขึ้นไปได้) - ทำให้ทั้งการวัดและกรอบตรงกับบริเวณจริง
    zone_tops = [cty[x] for x in range(zx0, zx1)
                 if 0 <= x < len(cty) and cty[x] >= 0]
    if zone_tops:
        zone_top = int(min(zone_tops))
        roof_y = max(roof_y, zone_top - _TAILZONE_ZONE_TOP_MARGIN_PX)
    if floor_y <= roof_y:
        return []

    # v26.05 FIX (ผู้ใช้แจ้ง "กรอบส้ม FRONT VIEW ทำไมถึงปรากฏ ทั้งๆที่กล่องวางเต็มความสูง"
    # พร้อมภาพ EB66-01, 13-Sep-2026):
    # ROOT CAUSE (ยืนยันด้วย pixel จริง): เขตสแกนเป็น "สี่เหลี่ยมแนวตั้ง" แต่ยอดสินค้าใน
    # FRONT view ลาดเอียงตามมุม isometric อย่างชัน - วัดได้จาก EB66-01 เขต x=[606,730]:
    # cargo_top_y ไล่จาก 410 (x=606) ขึ้นไป 261 (x=726) ต่างกัน 149px ในขณะที่ขอบบนของเขต
    # ถูกตั้งที่ zone_top-40 = 219 (ค่าเดียวทั้งเขต) -> มุมบนซ้ายของสี่เหลี่ยมลอยอยู่
    # "เหนือเส้นลาดของสินค้า" ถึง 191px พื้นที่สามเหลี่ยมตรงนั้นมองเห็นรางผนังตู้ตามธรรมชาติ
    # ไม่ใช่โพรงแต่อย่างใด (สีที่นับได้เป็น (179,179,90) = รางผนังตู้ 100% กระจายตัวสม่ำเสมอ
    # ตลอด x=606-728 คือแถบแนวนอนของราง ไม่ใช่ก้อนโพรงเฉพาะจุด)
    #
    # ความพยายามแก้ครั้งแรกที่ล้มเหลว (บันทึกไว้เพื่อไม่ให้ลองซ้ำ): ใช้ cargo_top_y
    # "รายคอลัมน์" เป็นเส้นตัด -> แก้ EB66-01 ได้ (4.4%->0.4%) แต่ over-correct ลบ
    # true-positive ที่ผู้ใช้ยืนยันแล้วไป 3 ไฟล์ (EC05-01 8.2%->0.2%, EC52-02 5.1%->1.5%,
    # GC06 10.4%->2.9%) เพราะ cargo_top_y วัด "ยอดของแถวใน (แถวไกล)" ไม่ใช่ "ยอดของแถวนอก
    # ที่เตี้ย" (จุดบอดเดิมที่ยืนยันไว้ตั้งแต่ v25.97 - interior void ที่เส้นเงารอบนอกมองไม่เห็น)
    # -> โพรงจริงอยู่ "ใต้ยอดแถวใน" แต่ cargo_top_y ที่ตำแหน่งนั้นสูงกว่า ทำให้ pixel ผนัง
    # ในโพรงถูกตัดทิ้งไปด้วย (EC05-01 เหลือผนังใต้ยอดเพียง 18 จุด จาก 799 จุด)
    #
    # FIX ที่ใช้จริง (แนวทางที่ผู้ใช้เลือก): fit "เส้นยอดสินค้าแบบลาดเอียง" (robust line fit
    # จาก cargo_top_y ทั้งเขต) แล้วตัดเฉพาะ pixel ที่อยู่เหนือ "เส้นตรงเส้นเดียว" นั้น -
    # ต่างจากการตัดรายคอลัมน์ตรงที่เส้นตรงจะ "เฉลี่ยผ่านกลาง" ความขรุขระของ cargo_top_y
    # (ซึ่งกระโดดตามแถวใน/แถวนอกสลับกัน) จึงตัดเฉพาะสามเหลี่ยมมุมบนที่เป็น artifact ของ
    # เขตสี่เหลี่ยมจริงๆ โดยไม่ตัดพื้นที่โพรงที่อยู่ระหว่างยอดแถวนอก(เตี้ย)กับยอดแถวใน(สูง) ทิ้ง
    #
    # *** เงื่อนไขสำคัญที่ทำให้ FIX นี้ใช้ได้จริง (ผู้ใช้วาดสามเหลี่ยม EC05-01 มายืนยัน):
    # ตัด "เฉพาะเมื่อเส้น fit เชื่อถือได้จริง" เท่านั้น ***
    # ปัญหาของการตัดเสมอ: เมื่อเส้นยอดสินค้าเป็น "ขั้นบันได" (มีกล่องเตี้ยข้างหนึ่ง กล่องสูง
    # อีกข้าง) เส้นตรงที่ fit ได้จะลากผ่าน "กลาง" ขั้นบันไดนั้น แล้วตัดพื้นที่โพรงจริงทิ้งไปด้วย
    # ยืนยันด้วย pixel จริงจาก EC05-01 เขต x=[689,796]:
    #   cargo_top_y: x=689..729 -> 325,319,315,309,305  (กล่องม่วง TGT1G-D1 เตี้ย)
    #                x=739..789 -> 248,243,237,233,222  (กล่องข้างๆ สูงกว่า)
    #   -> มี "ขั้น" กระโดด 57px ที่ x=729->739 -> fit ได้ slope=-1.229 resid_std=13.1
    #   -> เส้น fit ลากจาก y=335 (x=689) ลงไป y=204 (x=796) ตัดผ่านกลางโพรงพอดี
    #   -> ผนังที่มองเห็นเพราะกล่องม่วงเตี้ย (x=689-737, y=263-311, สี (179,179,90) = รางตู้)
    #      ถูกตัดทิ้ง 590 จาก 799 จุด -> wall 8.2% เหลือ 2.3% -> หลุดเกณฑ์ (false-negative)
    #
    # FIX: ตัดเฉพาะเมื่อ resid_std ต่ำ (เส้นยอดเรียบเป็นเส้นตรงตามมุม isometric จริงๆ) -
    # ถ้า resid_std สูง แปลว่าเส้นยอดเป็นขั้นบันได ซึ่ง "ตัวมันเองคือสัญญาณของความสูงไม่เท่ากัน"
    # อยู่แล้ว จึงไม่มีเหตุผลใดที่จะเอาเส้นตรงที่ fit ไม่ลงไปตัดข้อมูลทิ้ง
    # ยืนยันด้วย resid_std จริงครบ 20 ไฟล์ (แยกขาด 22 เท่า ไม่มีค่าใดคาบเกี่ยวกันเลย):
    #   เส้นยอดเป็นขั้นบันได (ไม่ตัด): EC58-02=27.69 | EC05-01=13.07 | GC06=11.84
    #   เส้นยอดเรียบ (ตัดได้)        : ที่เหลือ 17 ไฟล์ สูงสุดเพียง 0.54 (EB90-01/02/03)
    #                                  EB66-01=0.34 | EC52-02=0.30 | EC51-01=0.41
    #   -> เกณฑ์ 3.0 อยู่กึ่งกลาง (ห่างจากฝั่งเรียบ 5.6 เท่า, ห่างจากฝั่งขั้นบันได 3.9 เท่า)
    # ผลลัพธ์ที่ได้ (ตรวจครบ 20 ไฟล์ ถูกต้องทั้งหมด 20/20):
    #   EB66-01 (ผู้ใช้แจ้งว่ากล่องเต็มความสูง) resid=0.34 -> ตัด -> 2.4% -> ไม่ติด (แก้แล้ว)
    #   EC05-01 (ผู้ใช้ยืนยันมีโพรง)            resid=13.1 -> ไม่ตัด -> 8.2% -> FLAG
    #   EC58-02 / GC06                          resid สูง  -> ไม่ตัด -> FLAG
    #   EC52-02                                 resid=0.30 -> ตัด -> 4.9% -> ยัง FLAG
    #   ไฟล์ปลอดภัยที่เหลือทั้ง 15 ไฟล์         -> ไม่ติดเหมือนเดิมทุกไฟล์
    _zt_xs = [x for x in range(zx0, zx1) if 0 <= x < len(cty) and cty[x] >= 0]
    _top_fit = (_robust_local_line_fit(_zt_xs, [float(cty[x]) for x in _zt_xs])
                if len(_zt_xs) >= _TAILZONE_TOPLINE_MIN_POINTS else None)
    if _top_fit is not None and _top_fit.get("resid_std", 0) >= _TAILZONE_TOPLINE_MAX_RESID:
        print(f"[TAILZONE] เส้นยอดสินค้าเป็นขั้นบันได (resid_std="
              f"{_top_fit['resid_std']:.1f} >= {_TAILZONE_TOPLINE_MAX_RESID}) "
              f"= มีกล่องสูงต่ำไม่เท่ากันอยู่แล้ว -> ไม่ตัดพื้นที่ใดทิ้ง (ดู FIX v26.05)")
        _top_fit = None
    _slope_txt = "n/a" if _top_fit is None else f"{_top_fit['a']:.3f}"

    n_box = n_wall = n_white = 0
    n_wall_above = 0        # v26.05: ผนังที่อยู่ "เหนือเส้นยอดลาดเอียง" (artifact ของเขตสี่เหลี่ยม)
    wall_rows = []          # v26.02: เก็บแถวที่พบผนังจริง เพื่อใช้กำหนดขอบเขตกรอบ
    for yy in range(roof_y, min(floor_y, reg.shape[0]), 2):
        row_wall = 0
        for xx in range(zx0, zx1, 2):
            if cm[yy, xx]:
                n_box += 1
                continue
            px = reg[yy, xx]
            if _p1b_is_structural_container_color(px):
                if _top_fit is not None:
                    _yline = _top_fit["a"] * xx + _top_fit["b"]
                    if yy < _yline - _TAILZONE_TOPLINE_MARGIN_PX:
                        n_wall_above += 1
                        continue
                n_wall += 1
                row_wall += 1
            elif int(px[0]) > 230 and int(px[1]) > 230 and int(px[2]) > 230:
                n_white += 1
        if row_wall >= _TAILZONE_WALL_ROW_MIN_PX:
            wall_rows.append(yy)
    total = n_box + n_wall + n_white
    if total < _TAILZONE_MIN_SAMPLES:
        return []
    wall_pct = n_wall / total * 100.0
    box_pct = n_box / total * 100.0
    white_pct = n_white / total * 100.0   # v26.16: ดู _TAILZONE_MIN_WHITE_PCT

    n_tf = _count_visible_top_faces(view_result, records)
    ok_wall = wall_pct >= _TAILZONE_WALL_MIN_PCT
    ok_small = n_tf >= _TAILZONE_MIN_TOPFACES
    ok_void = white_pct >= _TAILZONE_MIN_WHITE_PCT   # v26.16 NEW (เงื่อนไขที่ 3)
    print(f"[TAILZONE] {view_label} เขต x=[{zx0},{zx1}] กล่อง={box_pct:.1f}% "
          f"ผนัง={wall_pct:.1f}% (เกณฑ์ {_TAILZONE_WALL_MIN_PCT}%) "
          f"[ตัดผนังเหนือเส้นยอดลาดเอียง {n_wall_above} จุด, slope={_slope_txt}] "
          f"ผิวบนที่เห็น={n_tf} (เกณฑ์ {_TAILZONE_MIN_TOPFACES}) "
          f"พื้นหลังว่าง={white_pct:.1f}% (เกณฑ์ {_TAILZONE_MIN_WHITE_PCT}%) "
          f"-> {'FLAG โพรงสูงต่ำ' if (ok_wall and ok_small and ok_void) else 'ผ่าน'}"
          + ("" if ok_wall else " [ผนังน้อย=วางเต็ม]")
          + ("" if ok_small else " [กล่องใหญ่กินเต็มความลึก]")
          + ("" if ok_void else " [เงาสินค้าไม่แหว่ง=วางเต็มไม่มีโพรง v26.16]"))
    if not (ok_wall and ok_small and ok_void):
        return []

    ox = view_result.get("crop_origin_x", 0)
    oy = view_result.get("crop_origin_y", 0)
    # v26.02 FIX #1: วาดกรอบเฉพาะช่วงที่ "พบผนังจริง" (ไม่ใช่ทั้งความสูงของสินค้า)
    if wall_rows:
        box_y0 = max(roof_y, wall_rows[0] - 6)
        box_y1 = min(floor_y, wall_rows[-1] + 6)
    else:
        box_y0, box_y1 = roof_y, floor_y
    if box_y1 <= box_y0:
        box_y0, box_y1 = roof_y, floor_y
    return [{
        "risk_type": "EMPTY_SPACE_RISK", "subtype": "tailzone_wall_exposure",
        "view": view_label, "mark_view": view_label,
        "mark_stack_idx": None, "mark_x_range": (zx0, zx1), "pos_range": None,
        "abs_box": (ox + zx0, oy + box_y0, ox + zx1, oy + box_y1),
        "wall_pct": round(wall_pct, 1), "box_pct": round(box_pct, 1), "n_top_faces": n_tf,
        "reason": (f"บริเวณท้ายรถมองเห็นผนังตู้โผล่ {wall_pct:.1f}% "
                   f"(เมื่อวางเต็มจะเห็นเพียง ~1.5%) และเป็นการวางกล่องเล็กหลายแถว "
                   f"ตามความลึก (เห็นผิวบน {n_tf} ชิ้น) บ่งชี้ว่ามีโพรง/กองสินค้าเตี้ยกว่า "
                   f"ที่ควร ไม่มีสินค้าบังผนังไว้ เสี่ยงสินค้าล้ม/เลื่อนเข้าไปในช่องว่าง"),
    }]


# ============================================================================
# v26.06 NEW: LARGE-BOX SINGLE-ROW GUARD (ตัดกรอบแดง cross_view ที่กล่องใหญ่แถวเดียว)
# ============================================================================
# แนวทางมาจากผู้ใช้โดยตรง (14-Sep-2026) หลังแนบ RD06-01 พร้อมวงกลม/ลากเส้นบนภาพ:
#   "พิสูจน์ว่าเป็นกล่องชั้นเดียว และเป็นประเภทกล่องใหญ่ (ไม่มีวางด้านนอกกับด้านใน)
#    1. ทั้งภาพปรากฏ side face จำนวน 1 กล่อง"
#   "พิสูจน์ว่า ไม่สูงต่ำต่างระดับ
#    1. แนวโน้มความสูงของทุกกล่อง อยู่แนวโน้มไล่เลี่ยกัน"
#   "เสนอว่าตำแหน่งใดเป็นกล่องใหญ่ side face ที่ไม่ใช่ด้านนอกกับด้านใน
#    ส่วนของ cross-view ไม่ต้องไปจับ"
#
# ROOT CAUSE ของ false-positive ที่ RD06-01 (ยืนยันด้วย pixel จริง):
#   ผู้ใช้ยืนยันว่าไฟล์นี้ปลอดภัย (4 กล่องขนาดเท่ากัน วางเรียง 1 ชั้น) แต่ระบบ flag
#   STEP_DOWN_RISK/cross_view FRONT idx0 drop=54.9%
#   วัดความสูงดิบรายคอลัมน์ (ยังไม่ผ่าน reconcile) พบว่าผู้ใช้ถูกต้อง 100%:
#     BACK : 167.0, 167.0, 167.0, 105.0   <- 3 ตัวแรกเท่ากันเป๊ะ (spread 0.0%)
#     FRONT: 230.0, 235.0, 229.5, 168.0   <- 3 ตัวแรกไล่เลี่ยกัน (spread 2.3%)
#   ปัญหา 2 ชั้นซ้อนกัน:
#   (1) คอลัมน์สุดท้ายของทั้ง 2 view อยู่ "หลัง apex ทั้งคอลัมน์" (FRONT apex=1075 vs
#       idx3 x=(1104,1178) | BACK apex=957 vs idx3 x=(984,1059)) - docstring ของ
#       compute_stack_heights_px เขียนไว้เองว่าข้อมูลหลังจุดยอด isometric "เอียงคนละทิศ,
#       height ผิดเพี้ยนเป็นระบบ" แต่ v25.72 ให้ label="direct" (เชื่อถือได้) จึงไม่มี guard ใด
#       กรองเลย - วัด profile จริงเห็นชัด: BACK x=949->167px ไล่ลงถึง x=1054->77px
#       (เรียวลงต่อเนื่องตาม geometric taper ของ silhouette ปลายแถว ไม่ใช่กล่องเตี้ยจริง)
#   (2) FRONT กับ BACK วัดกล่องใบเดียวกันได้ต่างกัน 38% อย่างเป็นระบบ (230 vs 167 คงที่ทั้งแถว)
#       เพราะกล่องลึกเพียง 745mm (31% ของตู้ 2400mm) ทำให้ local_floor_y ของ FRONT
#       ไปจับเส้นพื้นคนละเส้นกับตำแหน่งที่กล่องวางจริง
#   -> reconcile เอา 2 ค่านี้มาปนกัน (FRONT idx1/idx2 ถูกเขียนทับเป็น 167 แต่ idx0 ยังเป็น
#      232.8) -> เทียบกับ BACK idx3=104.9 -> drop 54.9% -> flag ผิดพลาด
#   ไฟล์นี้เปิดเผยจุดบอดเพราะมีเพียง 4 คอลัมน์ (คอลัมน์ปลายคิดเป็น 25% ของข้อมูล เทียบไฟล์ปกติ
#   7-10 คอลัมน์ที่ปลายแถวเป็นแค่ 10%) จึงไม่เคยเห็นปัญหานี้มาก่อน
#
# FIX (ใช้สัญญาณของผู้ใช้ตรงๆ - จำแนกเป็นราย view ว่า "เป็นกล่องใหญ่วางแถวเดียว" หรือไม่):
#   สัญญาณที่ 1 "ทั้งภาพปรากฏ side face จำนวน 1 กล่อง" -> นับ side face ที่เป็นสีกล่องจริง
#     (ไม่นับสีโครงสร้างตู้) ทั้ง view - กล่องใหญ่วางแถวเดียวจะเห็นด้านข้างแค่ใบปลายสุดเท่านั้น
#     ส่วนการวางนอก+ใน จะเห็นด้านข้างของกล่องหลายใบพร้อมกัน
#   สัญญาณที่ 2 "ตำแหน่งใดเป็นกล่องใหญ่" -> นับ "ผิวบน (top face)" ที่มองเห็นในแต่ละคอลัมน์
#     กล่องใหญ่กินเต็มความลึก = เห็นผิวบนไม่เกิน 1 ชิ้นต่อคอลัมน์
#     กล่องเล็กวางนอก+ใน      = เห็นผิวบนหลายชิ้นในคอลัมน์เดียว (ทั้งแถวนอกและแถวใน)
#   ทั้ง 2 สัญญาณต้องผ่านพร้อมกัน (AND) และต้องเป็นจริง "ทั้ง FRONT และ BACK" จึงจะถือว่า
#   งานนี้เป็นกล่องใหญ่วางแถวเดียวทั้งคัน -> ปิดเฉพาะ cross_view (ตามที่ผู้ใช้ระบุ)
#
# ยืนยันด้วยข้อมูลจริงครบทุกไฟล์ที่มี (แยกได้ขาด ไม่มีค่าใดคาบเกี่ยวกัน):
#   ไฟล์      view   side  ผิวบนต่อคอลัมน์            เข้าเงื่อนไข  สถานะจริง
#   RD06-01   FRONT   0    [0,0,0,0]                  ใช่          ปลอดภัย (ผู้ใช้ยืนยัน)
#   RD06-01   BACK    0    [0,0,0,0]                  ใช่
#   EB91-01   FRONT   0    [1,1,0,0,0,0]              ใช่          ปลอดภัย (กล่องใหญ่เต็มลึก)
#   EB91-01   BACK    0    [0,0,0,0,0]                ใช่
#   ------------------------------------------------------------------------------
#   EB66-01   FRONT   1    [0,0,2,2,0,0,0]  max=2     ไม่          ปลอดภัย (0 จุดอยู่แล้ว)
#   EC05-01   FRONT   8    [1,2,3]          max=3     ไม่          เสี่ยง (กล่องเล็กนอก+ใน)
#   EC05-01   BACK    6    [2,2,0]          max=2     ไม่
#   GC06      FRONT   0    [1,3,2,0,0,0,3,3,0,0] max=3 ไม่         เสี่ยง (รถ 2 ตู้)
#   GC06      BACK    0    [1,2,0,0,2,0,0,0,0,0] max=2 ไม่
#   *** RD06-01 = FP หายไป | EB91-01 ไม่มี cross_view อยู่แล้ว (ไม่กระทบ)
#       EC05-01 / GC06 / EB66-01 ไม่เข้าเงื่อนไขเลย -> จุดเสี่ยงจริงอยู่ครบทุกจุด ***
#
# ขอบเขตแคบมาก (ตามที่ผู้ใช้กำหนด): ปิดเฉพาะ subtype "cross_view" เท่านั้น
#   - pairwise / pairwise_floor_jump / tail_stepdown / hidden_behind ยังทำงานครบทุกกลไก
#     (เป็นการเทียบภายใน view เดียวกัน ไม่ได้รับผลจาก cross-view offset เชิงระบบ)
#   - EMPTY_SPACE_RISK (กรอบส้ม) ไม่ถูกแตะเลยแม้แต่จุดเดียว
_LARGEBOX_MAX_SIDE_FACES = 1      # side face สีกล่องจริงทั้ง view (วัดจริง: ปลอดภัย 0-1 | เสี่ยง 6-8)
_LARGEBOX_MAX_TOPFACES_PER_COL = 1  # ผิวบนสูงสุดต่อคอลัมน์ (วัดจริง: ปลอดภัย 0-1 | เสี่ยง 2-3)
_LARGEBOX_TF_MIN_ASPECT = 1.25    # parallelogram ผิวบนต้องกว้างกว่าสูง (ใช้เกณฑ์เดียวกับ v26.01)
_LARGEBOX_TF_MIN_WIDTH_FRAC = 0.55
_LARGEBOX_TF_MIN_AREA = 600
_LARGEBOX_TF_MIN_COLOR_PX = 700


def _max_topfaces_per_column(view_result, records):
    """v26.06: คืนจำนวนผิวบน (top face) สูงสุดที่พบใน "คอลัมน์ใดคอลัมน์หนึ่ง" ของ view นี้
    - ใช้เกณฑ์เดียวกับ _count_visible_top_faces (v26.01) ทุกประการ ต่างกันแค่นับแยกรายคอลัมน์
    แล้วเอาค่าสูงสุด (แทนการรวมทั้ง view) เพื่อตอบคำถามของผู้ใช้ว่า "ตำแหน่งใดเป็นกล่องใหญ่"
    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล"""
    reg = view_result.get("region") if view_result else None
    if reg is None or not records:
        return 0
    best = 0
    for rec in records:
        if rec.get("is_corner_duplicate"):
            continue
        x0, x1 = rec["x_range"]
        colw = max(1, x1 - x0)
        lo, hi = x0 + 6, x1 - 6
        if hi <= lo:
            continue
        sub = reg[:, lo:hi].reshape(-1, 3)
        if sub.size == 0:
            continue
        try:
            cols, cnts = np.unique(sub, axis=0, return_counts=True)
        except Exception:
            continue
        n = 0
        for i in np.argsort(-cnts)[:10]:
            c = tuple(int(q) for q in cols[i])
            if int(cnts[i]) < _LARGEBOX_TF_MIN_COLOR_PX:
                continue
            if _p1b_is_structural_container_color(c):
                continue
            if max(c) < 50 or min(c) > 240:
                continue
            mk = ((reg[:, :, 0] == c[0]) & (reg[:, :, 1] == c[1]) & (reg[:, :, 2] == c[2]))
            mk[:, :lo] = False
            mk[:, hi:] = False
            lab, nn = ndimage.label(mk, structure=np.ones((3, 3), int))
            if nn == 0:
                continue
            for li, sl in enumerate(ndimage.find_objects(lab), start=1):
                if sl is None:
                    continue
                ys_, xs_ = sl
                w = xs_.stop - xs_.start
                h = ys_.stop - ys_.start
                area = int((lab[sl] == li).sum())
                if area < _LARGEBOX_TF_MIN_AREA or h <= 0:
                    continue
                if (w / h) >= _LARGEBOX_TF_MIN_ASPECT and w >= _LARGEBOX_TF_MIN_WIDTH_FRAC * colw:
                    n += 1
        best = max(best, n)
    return best


def _is_large_box_single_row(view_result, records, view_label):
    """v26.06: True ถ้า view นี้เป็น "กล่องใหญ่วางแถวเดียว" (ไม่มีการวางนอก+ใน)
    ตามสัญญาณ 2 ตัวที่ผู้ใช้ระบุ - ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล"""
    if view_result is None or not records:
        return False
    n_side = view_result.get("n_cargo_side_faces")
    if n_side is None:
        return False   # ไม่มีข้อมูล (เช่น PHASE 1B ล้มเหลว) -> ไม่ตัดสิน (fail-safe ใช้เส้นทางเดิม)
    if n_side > _LARGEBOX_MAX_SIDE_FACES:
        return False
    max_tf = _max_topfaces_per_column(view_result, records)
    ok = max_tf <= _LARGEBOX_MAX_TOPFACES_PER_COL
    print(f"[LARGEBOX] {view_label} side_face={n_side} (เกณฑ์ <={_LARGEBOX_MAX_SIDE_FACES}) "
          f"ผิวบนสูงสุดต่อคอลัมน์={max_tf} (เกณฑ์ <={_LARGEBOX_MAX_TOPFACES_PER_COL}) "
          f"-> {'กล่องใหญ่วางแถวเดียว' if ok else 'มีการวางนอก+ใน/หลายแถว'}")
    return ok


def _analyse_whole_view(front, back, records_front, records_back):
    """v25.97: เส้นทางเดิม (ทั้ง view เป็นตู้เดียว) - แยกออกมาเป็นฟังก์ชันเพื่อให้
    per-container fallback กลับมาใช้ได้ตรงๆ โดยไม่ต้องคัดลอกโค้ด
    *** เนื้อในเหมือน v25.96 ทุกบรรทัด ไม่มีการเปลี่ยนตรรกะใดๆ ***"""
    risks = []
    # v25.96: โหลดเบาบางกองเดียว -> ระงับ cross_view + color_anomaly
    _single_stack = _is_single_stack_sparse_load(records_front, records_back)

    # v26.06: กล่องใหญ่วางแถวเดียวทั้งคัน -> ไม่ให้ cross_view จับ (ตามที่ผู้ใช้ระบุ)
    # ต้องเป็นจริงทั้ง 2 view จึงจะปิด (ดู docstring เต็มที่ _is_large_box_single_row)
    _large_box = (_is_large_box_single_row(front, records_front, "FRONT")
                  and _is_large_box_single_row(back, records_back, "BACK"))
    if _large_box:
        print("[LARGEBOX] ทั้ง FRONT และ BACK เป็นกล่องใหญ่วางแถวเดียว (ไม่มีการวางนอก+ใน) "
              "-> ระงับ cross_view (ความต่างระหว่าง 2 มุมกล้องเป็นความคลาดเคลื่อนของการวัด "
              "ไม่ใช่ขั้นสูงต่ำจริง) - กลไกอื่นยังทำงานครบทุกตัว")

    risks += detect_step_down_pairwise(records_front, "FRONT", view_result=front)
    risks += detect_step_down_pairwise(records_back, "BACK", view_result=back)
    if not _single_stack and not _large_box:
        risks += detect_step_down_crossview(records_front, records_back,
                                            front_result=front, back_result=back)

    # v25.96: tail_stepdown ต้องมีการยืนยันอิสระจากอีก view
    _tail = (detect_tail_stepdown(records_front, "FRONT", view_result=front)
             + detect_tail_stepdown(records_back, "BACK", view_result=back))
    risks += [r for r in _tail
              if _tail_stepdown_crossview_confirmed(r, records_front, records_back)]

    risks += detect_step_down_hidden_behind(front, records_front, "FRONT")
    risks += detect_step_down_hidden_behind(back, records_back, "BACK")
    if not _single_stack:
        risks += detect_rear_empty_risk(records_front, records_back, front, back)

    # v26.01: โพรงสูงต่ำที่ท้ายรถ (FRONT เท่านั้น - ดู detect_tailzone_wall_exposure)
    risks += detect_tailzone_wall_exposure(front, records_front, "FRONT")
    return risks


# ============================================================================
# v26.13 NEW: CLIP RISK BOX AT INTER-CONTAINER GAP (กรอบต้องไม่คร่อม 2 ตู้)
# ============================================================================
# ที่มา (ผู้ใช้แจ้ง 16-Sep-2026 พร้อมไฟล์จริง 12 ไฟล์): "กรอบแดง กรอบส้ม - วาดผิดจุด,
# วาดคล่อม 2 ตู้, วาดคล่อม view"
#
# ROOT CAUSE (ยืนยันด้วยการวัดตำแหน่งจริงครบทุกไฟล์): Phase 1B แบ่งคอลัมน์จาก "สีของ
# front-face" เท่านั้น ไม่เคยรู้จักแนวคิด "ช่องว่างระหว่างตู้" เลย - คอลัมน์ที่อยู่ปลายตู้ใบแรก
# จึงถูกขยายกว้างคร่อมช่องว่างไปจนถึงจุดเริ่มต้นของตู้ใบที่ 2 ได้ (เพราะไม่มีสีอื่นมาคั่น)
# เมื่อคอลัมน์นั้นถูก flag เป็นความเสี่ยง กรอบที่วาดจึงพาดข้ามช่องว่างจากตู้หนึ่งไปอีกตู้หนึ่ง
# วัดยืนยันจากไฟล์จริง:
#   CC05-all FRONT: ช่องว่างระหว่างตู้ x=[897,955] แต่คอลัมน์ idx3 กว้าง x=[813,967]
#                   -> คร่อมทั้งช่อง (ซ้ายเลย 897 / ขวาเลย 955) = กรอบพาด 2 ตู้
#                   ถูก flag 2 จุด (cross_view + tail_stepdown) ที่คอลัมน์เดียวกันนี้
#   CE01-all BACK : ช่องว่าง x=[921,960] แต่คอลัมน์ idx4 กว้าง x=[884,980] -> คร่อมเช่นกัน
# ตรวจครบ 12 ไฟล์ พบเพียง 3 จุดจาก 2 ไฟล์นี้เท่านั้น (ไฟล์อื่นคอลัมน์ไม่คร่อมช่องว่างเลย)
#
# FIX: ตัด (clip) ขอบกรอบให้หยุดที่ขอบช่องว่าง โดยเก็บไว้เฉพาะ "ฝั่งที่กรอบกินพื้นที่มากกว่า"
# (= ตู้ที่ความเสี่ยงนั้นสังกัดอยู่จริง) - ไม่ลบ risk ทิ้ง เพราะความเสี่ยงยังมีจริงในตู้นั้น
# เพียงแต่กรอบเดิมวาดเลยขอบเขตตู้ไป
#   CC05 idx3: ซ้าย 813-897 = 84px | ขวา 955-967 = 12px -> เก็บฝั่งซ้าย -> (813, 897)
#   CE01 idx4: ซ้าย 884-921 = 37px | ขวา 960-980 = 20px -> เก็บฝั่งซ้าย -> (884, 921)
# ทำที่ขั้น post-processing (หลังคำนวณ risks ครบแล้ว) จึงไม่กระทบตรรกะการตรวจจับใดๆ เลย
# และแก้ทั้ง mark_x_range และ abs_box (ถ้ามี) ให้สอดคล้องกัน
_CLIP_GAP_MIN_KEEP_PX = 12   # ฝั่งที่เก็บไว้ต้องกว้างพอจะวาดกรอบได้ (ต่ำกว่านี้ = ตัดทิ้งทั้ง risk)


def _clip_risks_at_container_gaps(risks, front, back, n_containers):
    """v26.13: ตัดกรอบที่คร่อมช่องว่างระหว่างตู้ ให้เหลือเฉพาะฝั่งที่อยู่ในตู้เดียว
    (ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล - พบจริงจาก CC05-all / CE01-all)"""
    if n_containers < 2:
        return risks
    gaps = {}
    for vn, vr in (("FRONT", front), ("BACK", back)):
        gaps[vn] = _find_inter_container_gaps(vr, n_containers) if vr else []
    if not any(gaps.values()):
        return risks
    out = []
    for r in risks:
        mx = r.get("mark_x_range")
        vw = r.get("mark_view") or r.get("view")
        # v26.15: EMPTY_SPACE_RISK (กรอบส้ม) ถูกจัดการด้วยการ "ปฏิเสธทั้ง risk" ใน
        # _suppress_inter_container_empty_space_risks ไปแล้ว (ดู FIX v26.15 ที่นั่น)
        # กรอบส้มที่รอดมาถึงตรงนี้ = ไม่ได้คร่อมช่องว่าง = ถูกต้องอยู่แล้ว ไม่ต้องตัด
        if r.get("risk_type") == "EMPTY_SPACE_RISK":
            out.append(r)
            continue
        if not mx or vw not in gaps or not gaps[vw]:
            out.append(r)
            continue
        x0, x1 = int(mx[0]), int(mx[1])
        clipped = False
        for g0, g1 in gaps[vw]:
            if not (x0 < g0 and x1 > g1):
                continue   # ไม่ได้คร่อมช่องนี้
            left_w = g0 - x0
            right_w = x1 - g1
            if left_w >= right_w:
                nx0, nx1 = x0, g0
            else:
                nx0, nx1 = g1, x1
            if (nx1 - nx0) < _CLIP_GAP_MIN_KEEP_PX:
                print(f"[CLIP_GAP] ตัด {r.get('subtype')} {vw} idx={r.get('mark_stack_idx')} "
                      f"ทิ้ง (เหลือกว้างเพียง {nx1-nx0}px หลังตัดที่ช่องว่าง [{g0},{g1}])")
                clipped = None
                break
            print(f"[CLIP_GAP] {r.get('subtype')} {vw} idx={r.get('mark_stack_idx')} "
                  f"กรอบเดิม x=[{x0},{x1}] คร่อมช่องว่างระหว่างตู้ [{g0},{g1}] "
                  f"-> ตัดเหลือ x=[{nx0},{nx1}] (เก็บฝั่ง{'ซ้าย' if left_w >= right_w else 'ขวา'} "
                  f"ซึ่งกว้างกว่า: {max(left_w, right_w)}px vs {min(left_w, right_w)}px)")
            x0, x1 = nx0, nx1
            clipped = True
        if clipped is None:
            continue
        if clipped:
            r = dict(r)
            r["mark_x_range"] = (x0, x1)
            ab = r.get("abs_box")
            if ab:
                vr = front if vw == "FRONT" else back
                ox = vr.get("crop_origin_x", 0) if vr else 0
                r["abs_box"] = (ox + x0, ab[1], ox + x1, ab[3])
        out.append(r)
    return out



# ============================================================================
# v26.16 NEW: CONTAINER ENTRY-COLUMN GUARD (กรอบแดงที่คอลัมน์แรกของตู้ใบถัดไป)
# ============================================================================
# ที่มา: ผู้ใช้ชี้ด้วยลูกศรบนภาพจริง 17-Sep-2026 (CC05-all, CC19-all opt2) ว่ากรอบแดงที่
# "หัวตู้ใบที่ 2" วาดเกินมา บริเวณนั้นปลอดภัย
# ROOT CAUSE ที่ยืนยันด้วย pixel จริง: ที่ขอบด้านหน้าของตู้ใบถัดไป ผนัง/เสาหัวตู้ (สีโครงสร้าง)
# บังกล่องใบแรกไว้บางส่วน ทำให้ mask ของคอลัมน์นั้นเหลือเพียง "แถบแคบ" ที่เห็นได้ ค่าความสูงที่
# วัดได้จึงต่ำกว่าความจริง (เหมือนกรณีคอลัมน์ปนช่องว่างระหว่างตู้ที่แก้ไปแล้วใน v26.15 แต่คนละ
# ตำแหน่ง: v26.15 แก้คอลัมน์ที่ "คร่อมช่องว่าง" ส่วนรอบนี้คือคอลัมน์ที่ "อยู่ถัดจากช่องว่างทันที")
# วัดจริงจากไฟล์ที่ผู้ใช้แนบ (ระยะจากขอบขวาของช่องว่างระหว่างตู้ ถึงขอบซ้ายของคอลัมน์):
#   CC05-all FRONT idx4 : ช่องว่าง=(897,955) คอลัมน์เริ่ม 967 (ห่าง 12px) drop=0.174 / 0.256
#   CC19-all FRONT idx3 : ช่องว่าง=(897,964) คอลัมน์เริ่ม 931 (คร่อมขอบช่อง) drop=0.165
#   CB15-04  FRONT idx5 : ช่องว่าง=(906,929) คอลัมน์เริ่ม 950 (ห่าง 21px) drop=0.365 <- ของจริง
# -> จำกัดขอบเขตด้วย 2 เงื่อนไขพร้อมกัน เพื่อไม่ให้ไปลบ true positive ที่หัวตู้ (CB15-04):
#   (1) คอลัมน์ที่ถูก mark เริ่มภายใน 60px หลังช่องว่างระหว่างตู้ (= คอลัมน์แรกของตู้ถัดไป)
#   (2) และ drop_ratio < 0.30 (ระดับที่อธิบายได้ด้วยการถูกผนังหัวตู้บังเท่านั้น - ถ้ากล่องเตี้ยกว่า
#       จริงหนึ่งชั้นจะได้ >= 0.33 เสมอตามสัดส่วนกล่อง 3 ชั้น) - CB15-04 (0.365) จึงยังคงอยู่ครบ
# ขอบเขต: เฉพาะ STEP_DOWN_RISK subtype cross_view / hidden_behind และเฉพาะรถหลายตู้เท่านั้น
# (รถตู้เดียวไม่มีช่องว่างระหว่างตู้ -> ไม่ถูกแตะเลยแม้แต่ไฟล์เดียว) และไม่แตะกรอบส้มทุกชนิด
_ENTRY_COLUMN_MAX_GAP_DIST_PX = 60
_ENTRY_COLUMN_MAX_DROP_RATIO = 0.30
_ENTRY_COLUMN_SUBTYPES = ("cross_view", "hidden_behind")


# ============================================================================
# v26.17 NEW: COLUMN-SPANS-TWO-CONTAINERS GUARD (คอลัมน์เดียวคร่อม 2 ตู้)
# ============================================================================
# ที่มา: ผู้ใช้แจ้ง 17-Sep-2026 "กรอบแดง อาจมีผิดผสมเข้ามา" (ไฟล์ CB15-04)
# หลักฐานที่วัดได้หลังแก้ FIX A (FRONT view หาช่องว่างเจอแล้ว):
#   ช่องว่างระหว่างตู้ FRONT = x=[913,931]
#   คอลัมน์ Phase1B idx=4 = x=[872,950]  ->  872 < 913 และ 950 > 931
#   = คอลัมน์เดียวนี้ "กินท้ายตู้ที่ 1 + ช่องว่าง + หัวตู้ที่ 2" ทั้งหมดรวมกัน
#   ความสูงที่ได้ (192.0px, src=cross_view_corrected) จึงเป็นค่าผสมของกองสินค้า 2 ตู้กับ
#   พื้นที่ว่าง = ไม่ใช่ความสูงของกองใดกองหนึ่งจริง
#   ผลที่เกิด: กรอบแดง 2 ใบ (pairwise_floor_jump idx4 และ hidden_behind idx4) ถูกวาดลงบน
#   "ช่องว่างสีขาวระหว่างตู้" ตรงๆ - วัดพื้นขาวในกรอบได้ 42.1% และ 26.7%
#
# ทำไมต้องเป็นกฎใหม่ ไม่ใช้ _is_gap_contaminated เดิม (v26.15):
#   กฎเดิมใช้ "สัดส่วนช่องว่างในคอลัมน์ >= 30%" - เคสนี้วัดได้ 18/78 = 23% จึงลอดผ่าน
#   และกฎเดิมจำกัดเฉพาะ subtype cross_view เท่านั้น แต่ 2 กรอบนี้เป็น pairwise_floor_jump
#   กับ hidden_behind
# กฎใหม่ไม่ต้องจูนเปอร์เซ็นต์ใดๆ เลย ใช้ข้อเท็จจริงเชิงโครงสร้างล้วนๆ: ถ้าคอลัมน์ "ครอบ
# ช่องว่างระหว่างตู้ไว้ทั้งช่อง" แปลว่ามันพาดข้าม 2 ตู้ ซึ่งเป็นไปไม่ได้ทางกายภาพที่จะเป็น
# กองสินค้ากองเดียว -> ค่าความสูงของมันใช้เทียบอะไรไม่ได้เลยทุก subtype
# ขอบเขต: STEP_DOWN_RISK เท่านั้น + รถหลายตู้เท่านั้น (รถตู้เดียวไม่มีช่องว่าง = ไม่ถูกแตะ)
#         ไม่แตะกรอบส้มแม้แต่จุดเดียว (กรอบส้มมีเส้นทางของตัวเองอยู่แล้ว)


def _suppress_column_spanning_two_containers(risks, front, back, n_containers):
    """v26.17: ระงับกรอบแดงที่คอลัมน์อ้างอิงคร่อมช่องว่างระหว่างตู้ทั้งช่อง (ดู docstring ด้านบน)"""
    if n_containers < 2 or not risks:
        return risks
    gaps_by_view = {}
    for label, v in (("FRONT", front), ("BACK", back)):
        if v is None:
            continue
        g = v.get("_inter_container_gaps")
        if g is None:
            try:
                g = _find_inter_container_gaps(v, n_containers)
            except Exception:
                g = []
        gaps_by_view[label] = (g or [], v)
    out = []
    for r in risks:
        if r.get("risk_type") != "STEP_DOWN_RISK":
            out.append(r)
            continue
        label = r.get("mark_view") or r.get("view")
        gaps, v = gaps_by_view.get(label, ([], None))
        idx = r.get("mark_stack_idx")
        if not gaps or v is None or idx is None:
            out.append(r)
            continue
        try:
            cx0, cx1 = v["stack_heights"][idx]["x_range"]
        except Exception:
            out.append(r)
            continue
        hit = None
        for g0, g1 in gaps:
            if cx0 < g0 and cx1 > g1:
                hit = (g0, g1)
                break
        if hit is None:
            out.append(r)
            continue
        print(f"[SPAN2CONT] ระงับ {r.get('subtype')} view={label} idx={idx} "
              f"คอลัมน์ x=[{cx0},{cx1}] ครอบช่องว่างระหว่างตู้ {hit} ไว้ทั้งช่อง "
              f"-> คอลัมน์พาดข้าม 2 ตู้ ความสูงที่วัดได้เป็นค่าผสม ใช้เทียบไม่ได้")
    return out


def _suppress_container_entry_column_stepdown(risks, front, back, n_containers):
    """v26.16: ระงับกรอบแดงที่คอลัมน์แรกของตู้ใบถัดไป (ดู docstring ด้านบน)"""
    if n_containers < 2 or not risks:
        return risks
    gaps_by_view = {}
    for label, v in (("FRONT", front), ("BACK", back)):
        if v is None:
            continue
        g = v.get("_inter_container_gaps")
        if g is None:
            try:
                g = _find_inter_container_gaps(v, n_containers)
            except Exception:
                g = []
        gaps_by_view[label] = (g or [], v)
    out = []
    for r in risks:
        if (r.get("risk_type") != "STEP_DOWN_RISK"
                or r.get("subtype") not in _ENTRY_COLUMN_SUBTYPES):
            out.append(r)
            continue
        label = r.get("mark_view")
        gaps, v = gaps_by_view.get(label, ([], None))
        idx = r.get("mark_stack_idx")
        if not gaps or v is None or idx is None:
            out.append(r)
            continue
        try:
            col_x0 = v["stack_heights"][idx]["x_range"][0]
        except Exception:
            out.append(r)
            continue
        drop = r.get("drop_ratio")
        if drop is None or drop >= _ENTRY_COLUMN_MAX_DROP_RATIO:
            out.append(r)
            continue
        hit = None
        for g0, g1 in gaps:
            if -5 <= (col_x0 - g1) <= _ENTRY_COLUMN_MAX_GAP_DIST_PX or (g0 <= col_x0 <= g1):
                hit = (g0, g1)
                break
        if hit is None:
            out.append(r)
            continue
        print(f"[ENTRY_COL] ระงับ {r.get('subtype')} view={label} idx={idx} "
              f"คอลัมน์เริ่มที่ x={col_x0} ถัดจากช่องว่างระหว่างตู้ {hit} และ "
              f"drop_ratio={drop:.3f} < {_ENTRY_COLUMN_MAX_DROP_RATIO} "
              f"-> ความสูงถูกผนังหัวตู้บัง ไม่ใช่กล่องเตี้ยจริง")
    return out



# ============================================================================
#  v26.25 NEW - BURIED FRONT ROW  (กล่องแถวหน้าที่เตี้ยกว่าแถวหลังจนจมใต้เส้นเงา)
# ----------------------------------------------------------------------------
#  ที่มา (ผู้ใช้แจ้ง 21-Sep-2026 จาก PA01 ครึ่งซ้าย front view): กล่อง SNF1A-T8 เตี้ยกว่า
#  กองข้างหลังอย่างเห็นได้ชัดด้วยตาเปล่า แต่ไม่มีกรอบใดถูกวาดเลย
#
#  ROOT CAUSE เชิงโครงสร้าง (ยืนยันด้วยข้อมูล pixel จริง)
#    กลไกตรวจความเสี่ยงเดิมทั้ง 6 ตัว (pairwise / hidden_behind / silhouette_notch /
#    tail_stepdown / crossview / tailzone) อ่าน "ความสูง" จาก cargo_top_y เหมือนกันหมด
#    ซึ่งเป็น "เส้นเงาบนสุด" (silhouette) - คือต่อ 1 คอลัมน์ x ได้ความสูงเพียง 1 ค่า
#    สมมติฐานที่ซ่อนอยู่คือ "แต่ละตำแหน่ง x มีกองเดียว"
#    แต่ภาพ isometric มีความลึก - ที่ตำแหน่ง x เดียวกันมีกล่องซ้อนกัน 2 แถว (หน้า/หลัง)
#    เมื่อแถวหน้าเตี้ยกว่าแถวหลัง มันจะจมอยู่ใต้เส้นเงาของแถวหลัง "ทั้งใบ" จึงหายไปจาก
#    ข้อมูลที่ระบบใช้ตัดสินโดยสิ้นเชิง
#    วัดจริงจาก PA01 FRONT x=255-720 (ไล่ทีละ 8px): เส้นยอดไต่ขึ้นเรียบสนิท
#    500->641 ไม่มีรอยกระโดดเลยแม้แต่จุดเดียว (เปลี่ยนสูงสุดในหน้าต่าง 6px = ~8px)
#    ขณะที่ hidden_behind ต้องการ >= 20px จึงตรวจได้ 0 คอลัมน์
#
#  ทำไม hidden_behind (v25.23) ไม่ครอบคลุม
#    มันจับทิศ "กลับกัน" คือแถวหลัง *สูงกว่า* จนโผล่พ้นแถวหน้า (เกิดรอยกระโดดในเส้นเงา)
#    ส่วนกรณีแถวหน้า *เตี้ยกว่า* จนจมหาย ไม่เกิดรอยกระโดดใดๆ ในเส้นเงาเลย
#
#  ตัวแยกที่ใช้ - "ความลึกของหลังคา" (roof depth)
#    _p1b_classify_view แยกหน้ากล่องทุกใบเป็น cell พร้อมประเภท roof/front/side อยู่แล้ว
#    แต่ไม่เคยถูกนำมาเทียบกับเส้นเงาเลย  นิยาม:
#         depth = roof_top_y - cargo_top_y(cx ของ roof นั้น)
#    - หลังคาของกองที่ "เป็นเจ้าของเส้นเงา" ณ ตำแหน่งนั้น -> depth ~ 0 เสมอ
#      (รวมถึงกองเตี้ยที่วางเรียงข้างกันตามปกติแบบ staircase ด้วย - หลังคาของมัน
#       *คือ* เส้นเงา ณ ตำแหน่งนั้นเอง จึงไม่ถูก flag)
#    - หลังคาที่อยู่ "ต่ำกว่าเส้นเงามาก" -> มีกล่องสูงกว่าครองตำแหน่ง x นั้นอยู่
#      = กล่องแถวหน้าที่เตี้ยกว่าแถวหลัง ซึ่งเป็นเคสที่ระบบมองไม่เห็นพอดี
#
#  หลักฐานการกระจายตัว (วัดครบทั้ง 19 ไฟล์ที่ผู้ใช้แนบ, depth ของ roof cell ทุกใบ)
#    กลุ่มปกติ   : -55 ถึง +59
#    กลุ่มผิดปกติ: +84 ถึง +334
#    มีช่องว่างระหว่างกันที่ 59-84 ไม่มีค่าใดตกอยู่ตรงกลางเลยแม้แต่ค่าเดียว
#    ตรวจยืนยันด้วยภาพ (PA01 depth=189 drop=29.8%, PC01-01 depth=299/217/130)
#    กรอบชี้ตรงกล่องแถวหน้าที่เตี้ยจริงทุกใบ ไม่มีใบใดตกไปโดนหลังคากองสูงปกติเลย
#
#  ขอบเขตความปลอดภัย - เป็นกลไก "เพิ่ม" ล้วน
#    ไม่แตะกลไกเดิมทั้ง 6 ตัวเลยแม้แต่บรรทัดเดียว อ่านข้อมูลคนละชุด (roof cells ไม่ใช่
#    cargo_top_y โดยตรง) และผ่าน dedup กับกรอบเดิมก่อนเสมอ
#    ผล regression 18 ไฟล์: กรอบเดิมไม่เปลี่ยนเลยแม้แต่ไฟล์เดียว (0/18), HTTP 200 ครบ
#
#  ข้อจำกัดที่ทราบแล้ว (บอกตรงไปตรงมา)
#    กลไกนี้ยังทำงานได้เฉพาะโหมด single_view_page1 เป็นหลัก - ในโหมด dual_view
#    _p1b_classify_view คืน roof cell = 0 เพราะ area_min แบบ auto-calibrate ผูกกับขนาด
#    region ที่ใหญ่กว่า จึงกรองหลังคาทิ้งหมด (ยืนยันจาก PC03-02: roof_cells=0 ทั้ง 2 วิว)
#    เคยทดลองตั้ง area_min=1200 คงที่เพื่อให้ dual_view จับได้ แล้วพบ false positive
#    รุนแรง: เศษขอบกล่องชั้นกลางในกองเดียวกันถูกนับเป็นหลังคา ทำให้เกิดกรอบซ้อนทุกชั้น
#    (PA01 1->5 กรอบ, PC02 0->8 กรอบ ตรวจภาพแล้วผิดชัดเจน) จึงคงค่า auto ไว้ตามเดิม
# ============================================================================
_BURIED_ROOF_MIN_DEPTH_PX = 80      # กึ่งกลางช่องว่าง 59-84 ที่วัดได้จริงจาก 19 ไฟล์
_BURIED_MIN_DROP_RATIO = 0.20       # ใช้เกณฑ์เดียวกับ STEP_DOWN_*_DROP_RATIO เดิมของระบบ
                                    # (ทำหน้าที่ normalize depth ให้เป็นสัดส่วนกับความสูงกอง
                                    #  จึงไม่ขึ้นกับ scale การ render)
_BURIED_MIN_ROOF_AREA = 1500        # กันเศษ cell เล็กที่เกิดจาก noise/ตัวอักษร
# ============================================================================
#  v26.34 - UNSTABLE-BACKING RELAXED-DEPTH  (SC01-01 vs SC01-02, 23-Sep-2026)
# ----------------------------------------------------------------------------
#  ที่มา (ผู้ใช้ชี้จากคู่ไฟล์ SC01-01,04,10 / SC01-02,08): กล่องแถวหน้า TGT1D
#  ในทั้งสองไฟล์มีสภาพเหมือนกันทุกประการด้วยตา - กล่องแถวหลัง HMT1D-S4 ที่ตรวจพบว่า
#  "ซ่อนอยู่" นั้นพิงไม่เต็มหน้าตัด มีพื้นตู้โผล่ใต้กล่องเกินครึ่ง (มองเห็นเป็นแถบเหลือง)
#  แต่ SC01-02 ถูกวาดกรอบ ส่วน SC01-01 ไม่ถูกวาด ทั้งที่ผู้ใช้เห็นว่าควรวาดเหมือนกัน
#
#  ROOT CAUSE (วัดพิกเซลจริงทั้งคู่)
#    ความสูงกองที่ตำแหน่งเดียวกันแทบไม่ต่างกันเลย (335.88 vs 335.85 px)
#    ค่าเดียวที่ต่างคือ "depth" ของ roof cell ที่ตรวจพบว่าจมอยู่:
#      SC01-01,04,10  depth=75px  (< เกณฑ์ 80)  -> ไม่ flag
#      SC01-02,08     depth=80px  (= เกณฑ์ 80)  -> flag
#    ต่างกันเพียง 5px บนฐานความสูง ~335px (1.5%) - เป็น noise ของการวัดภาพ ไม่ใช่
#    ความแตกต่างทางกายภาพจริง แต่เกณฑ์ตัดขาดแบบ hard cutoff ที่ 80 ทำให้ผลต่างกันคนละทาง
#
#  หลักฐานเพิ่มเติมที่ผู้ใช้ชี้ - "ด้านข้างเป็นพื้น ไม่มีกล่องพิงเต็มหน้า"
#    วัดสัดส่วนพื้นตู้ในแถบล่าง (55%-85% ของความสูงกล่อง) ทางขวาของกรอบทั้ง 2 ไฟล์:
#      SC01-01,04,10  floor_frac = 0.558
#      SC01-02,08     floor_frac = 0.582
#    แทบเท่ากัน (ต่าง 2.4%) ยืนยันว่าทั้งคู่มีสภาพเดียวกันจริง - กล่องแถวหลังพิงไม่มั่นคง
#    ยิ่งเพิ่มความเสี่ยงจริง (รองรับไม่เต็ม) ไม่ใช่เหตุผลที่จะลดความเสี่ยงลง
#
#  หลักฐานความปลอดภัย - วัด floor_frac ของทุกจุดที่ depth อยู่ในช่วงใกล้เกณฑ์ (>=40)
#  ทั่วทั้ง 20 ไฟล์ทดสอบ (61 จุด) พบว่าคู่ SC01 (0.558, 0.582) แยกขาดจากจุดอื่นทั้งหมด
#  ซึ่งสูงสุดเพียง 0.241 (AB03-03) - มีช่องว่างกว้างกว่า 2 เท่า ไม่มีจุดใดตกกลาง
#  เลือกเกณฑ์ 0.35 ซึ่งอยู่กึ่งกลางช่องว่างนั้นพอดี
#
#  FIX: ถ้า depth ต่ำกว่าเกณฑ์ปกติแต่ยังอยู่ในช่วงใกล้เคียง (>= 60) และตรวจพบว่า
#  กล่องข้างเคียงที่ "ควรพิงอยู่" กลับมีพื้นตู้โผล่เกินครึ่ง (floor_frac >= 0.35) ให้ถือว่า
#  ผ่านเกณฑ์ depth ได้ เพราะเป็นหลักฐานเสริมว่าโครงสร้างไม่มั่นคงจริง ชดเชยความคลาดเคลื่อน
#  เล็กน้อยของการวัด depth ได้ - ไม่กระทบไฟล์อื่นเพราะไม่มีไฟล์ใดใน 20 ไฟล์ทดสอบมี
#  floor_frac สูงพอจะเข้าเงื่อนไขนี้โดยไม่ตั้งใจ
# ============================================================================
_BURIED_DEPTH_RELAX_MIN = 60        # depth ต่ำสุดที่ยังพิจารณาผ่อนปรนได้ (กันหลังคาที่ตื้นเกินไป)
_BURIED_UNSTABLE_FLOOR_FRAC = 0.35  # สัดส่วนพื้นตู้ขั้นต่ำที่ถือว่า "พิงไม่มั่นคง" (กึ่งกลาง
                                    # ช่องว่าง 0.241-0.558 ที่วัดได้จริงจาก 20 ไฟล์)
_BURIED_UNSTABLE_BAND_LO = 0.55     # แถบที่ใช้วัด floor_frac (55%-85% ของความสูงกล่อง)
_BURIED_UNSTABLE_BAND_HI = 0.85
_BURIED_UNSTABLE_REACH_PX = 40      # ระยะทางขวาของกรอบที่ใช้ตรวจ (กว้างพอเห็นพื้นตู้จริง)


def _buried_unstable_backing_floor_frac(region, roof_top, floor_y, x1):
    """v26.34: สัดส่วนพื้นตู้ (สี R≈G, R-B อยู่ 75-125) ในแถบล่างขวาของกรอบ.

    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจากคู่ SC01-01/SC01-02)
    คืน 0.0 ถ้าคำนวณไม่ได้ (fail-safe - จะไม่ผ่อนปรนเกณฑ์ depth ให้)"""
    h = floor_y - roof_top
    if h <= 0:
        return 0.0
    y0 = int(roof_top + _BURIED_UNSTABLE_BAND_LO * h)
    y1 = int(roof_top + _BURIED_UNSTABLE_BAND_HI * h)
    x0 = int(x1)
    x1b = int(min(region.shape[1], x1 + _BURIED_UNSTABLE_REACH_PX))
    if y1 <= y0 or x1b <= x0:
        return 0.0
    sub = region[y0:y1, x0:x1b].astype(np.int16)
    is_floor = ((np.abs(sub[:, :, 0] - sub[:, :, 1]) <= 8)
                & ((sub[:, :, 0] - sub[:, :, 2]) >= 75)
                & ((sub[:, :, 0] - sub[:, :, 2]) <= 125))
    return float(is_floor.mean()) if is_floor.size else 0.0
# ============================================================================
#  v26.26 - BOX-RELATIVE ROOF GATE  (แก้ให้กลไก BURIED FRONT ROW ทำงานในโหมด dual_view)
# ----------------------------------------------------------------------------
#  อาการ (ผู้ใช้แจ้งจากไฟล์ประเภท "ลงสีมาแล้ว" 8 ไฟล์: SA02-02, SB01-*, SB02-02,
#  SB16-03, SC01-*, SC03-02): ทุกไฟล์ได้ hazardCount = 0 ทั้งที่มีกล่องแถวหน้าเตี้ยกว่า
#  แถวหลังเห็นชัดด้วยตาเปล่า (เช่น SC01-01 กอง TGT1D-OR ฟ้าอ่อนเตี้ยกว่า HMT1D-S4 น้ำเงิน)
#
#  ROOT CAUSE (วัดค่าจริงด้วย debug ทั้ง 8 ไฟล์ -> roof_cells = 0 ทั้ง FRONT และ BACK)
#    v26.25 เรียก _p1b_classify_view โดยไม่ระบุ area_min จึงใช้ auto-calibrate:
#        area_min = 1200 * (h*w) / (400*300)
#    ซึ่งผูกกับ "ขนาด region" ไม่ใช่ "ขนาดกล่องจริง"  โหมด dual_view ครอปภาพกว้างเต็มหน้า
#    (~912x2451) จึงได้ area_min ~ 22,400 สูงกว่าหลังคากล่องจริงทุกใบ (5,000-13,900)
#    หลังคาจึงถูกกรองทิ้งหมดตั้งแต่ต้นทาง ก่อนกลไก BURIED จะได้เห็นข้อมูลด้วยซ้ำ
#      SA02-02  area_min=22,353  หลังคาใหญ่สุด 7,340  -> ผ่าน 0 ใบ
#      SC01-01  area_min=22,426  หลังคาใหญ่สุด 13,852 -> ผ่าน 0 ใบ
#      SC03-02  area_min=22,353  หลังคาใหญ่สุด 5,862  -> ผ่าน 0 ใบ
#
#  ทำไมตั้ง area_min=1200 คงที่เฉย ๆ ไม่ได้ (เคยทดลองแล้วล้มเหลว - บันทึกไว้กันทำซ้ำ)
#    ไฟล์ wireframe จะปล่อยให้ "เศษขอบกล่องชั้นกลางในกองเดียวกัน" ผ่านเข้ามาเป็นหลังคาด้วย
#    เกิดกรอบซ้อนทุกชั้นของกองเดียว (PA01 1 -> 5 กรอบ, PC02 0 -> 8 กรอบ ตรวจภาพแล้วผิดชัด)
#    วัดจริงจาก PA01: เศษเหล่านี้มีพื้นที่ 7,329 / 7,345 / 9,626 / 9,827 px ขณะที่หลังคา
#    กล่องจริงอยู่ที่ 28,340-80,853 px
#
#  ตัวแยกที่ใช้ - เทียบกับ "ขนาดกล่องจริงในภาพนั้นเอง" แทนขนาด region
#    _p1b_classify_view คืน front-face cell มาพร้อมกันอยู่แล้ว ซึ่งสะท้อน "สเกลกล่องจริง"
#    ของภาพนั้น ๆ โดยตรง และไม่ขึ้นกับขนาด region หรือ scale การ render เลย
#        gate = _BURIED_ROOF_FRONT_FRAC * median(area ของ front-face ทั้งวิว)
#    หลักฐานการกระจายตัว (roof area / med_front ครบทั้ง 28 ไฟล์ 43 วิว)
#      เศษขอบกล่องที่ต้องตัด (PA01)     : 0.24, 0.24, 0.31, 0.32
#      หลังคากล่องจริงที่ต้องเก็บ (PA01): 0.92, 0.95, 0.96, 1.29, 1.30, 1.51, 2.64
#      หลังคาจริงในไฟล์ลงสีแล้ว         : SC01-01 0.62-0.70 | SB01 0.65-0.68
#                                         SA02-02 0.27-1.32 | SB16-03 0.24-1.36
#    เลือก 0.45 เพราะอยู่เหนือเศษของ PA01 (สูงสุด 0.32) และต่ำกว่าหลังคาจริงที่เล็กที่สุด
#    ในไฟล์ลงสีแล้ว (SC01-02 = 0.50) โดยมีระยะห่างทั้งสองฝั่ง
#
#  ผล regression 28 ไฟล์ (wireframe 20 + ลงสีแล้ว 8) เทียบ v26.25
#    กลไกเดิมเปลี่ยน 0/28 ไฟล์ | HTTP 200 ครบ 28/28 | buried 12 -> 60 จุด
#    ไฟล์ลงสีแล้วตรวจพบได้ 7/8 ไฟล์ (เดิม 0/8)
# ============================================================================
_BURIED_ROOF_FRONT_FRAC = 0.45      # หลังคาต้องใหญ่อย่างน้อยเท่านี้เทียบ median front-face
_BURIED_ROOF_AREA_MIN_FIXED = 1200  # ค่าเดียวกับที่ _p1b_front_faces ใช้จริง
_BURIED_SELF_XOVERLAP = 0.50        # buried 2 ใบที่ทับแกน x เกินนี้ = กองเดียวกัน
# --- v26.27 FIX#1: ISO ROOF SHAPE GUARD (พบจริงจาก CD11-ALL back view) ----------
#  อาการ: back view ของ CD11 (กล่อง AWTHA-P7 สีน้ำเงิน เรียงสูงสม่ำเสมอ 3 ชั้นทั้งตู้)
#  ถูกวาดกรอบแดง buried_front_row 2 จุด ทั้งที่ไม่มีกล่องแถวหน้าเตี้ยกว่าเลย
#
#  ROOT CAUSE (วัดค่าจริงจาก roof cell ทุกใบของไฟล์นี้)
#    "หน้าบนกล่อง" ในภาพ isometric ถูกวาดด้วยความชันคงที่ (ISO_SLANT = atan(0.5)) เสมอ
#    สัดส่วน h/w ของ bbox จึงอยู่ที่ ~0.50 ทุกใบโดยธรรมชาติของการ render
#      roof จริงของ CD11: w=216 h=108 -> 0.50  | w=216 h=107 -> 0.50 (ทุกใบ 0.49-0.50)
#    แต่ 2 ใบที่ถูก flag ผิดกลับได้:
#      x=[757,903]  w=146 h=122 -> 0.84
#      x=[1052,1197] w=145 h=121 -> 0.83
#    ซึ่งเกือบเป็นสี่เหลี่ยมจัตุรัส = ไม่ใช่หน้าบนกล่องจริง แต่เป็นเศษมุมที่ถูกบัง/ตัดทอน
#    (_p1b_classify_view จัดเป็น 'roof' เพราะเกณฑ์ที่นั่นคือ aspect < 0.85 ซึ่งหลวมเกินไป
#     สำหรับงานนี้ - ทั้ง 2 ใบผ่านมาได้แบบเฉียดฉิว)
#    ยืนยันซ้ำด้วยค่าความสูงที่คำนวณได้: bh = 89 และ 88 px ซึ่งต่ำผิดปกติเมื่อเทียบกับ
#    ความสูงกองจริง (th = 307 และ 234) - กล่องจริงในไฟล์นี้สูงชั้นละ ~100px
#
#  ตัวแยกที่ใช้: บังคับ aspect ของ roof ให้อยู่ในช่วงที่เป็นไปได้ทางเรขาคณิตของ isometric
#  เท่านั้น  ค่ากลางคือ 0.50 เผื่อความคลาดเคลื่อนจากการ render/crop เป็น 0.65
#  (สูงกว่า roof จริงที่วัดได้ทุกใบ 0.50 อยู่ 30% แต่ยังต่ำกว่า 2 ใบที่ผิด 0.83/0.84 ชัดเจน)
_BURIED_ROOF_MAX_ASPECT = 0.65      # h/w ของ bbox หน้าบนกล่อง (isometric จริง ~0.50)
# --- v26.28 FIX: CARGO-FILL GUARD (พบจริงจาก CC04all front view ที่ผู้ใช้ชี้ว่าปลอดภัย) --
#  อาการ: กรอบแดง buried_front_row ถูกวาดที่มุมล่างซ้ายของตู้แรก ทั้งที่ตรงนั้นแทบไม่มี
#  สินค้าอยู่เลย (เป็นพื้นตู้/ขอบล่างที่ว่าง)
#
#  ROOT CAUSE: กลไกนี้เชื่อ "หลังคา" (roof cell) กับ "เส้นพื้น" อย่างเดียว แล้วลากกรอบจาก
#  หลังคาลงไปถึงพื้นโดยไม่เคยตรวจว่าเนื้อที่ในกรอบนั้นมีสินค้าจริงหรือไม่  ถ้า roof cell
#  ที่จับได้เป็นเศษขอบ/เงาที่ลอยอยู่เหนือพื้นที่ว่าง กรอบที่ได้จะครอบพื้นที่ว่างเป็นหลัก
#
#  หลักฐาน (วัดสัดส่วน cargo_mask ภายในกรอบ buried ทุกใบของ 2 ไฟล์ที่ผู้ใช้ชี้)
#      CC04all  FRONT x=[524,651]  fill = 0.202   <-- กรอบผิด (พื้นที่ว่าง 80%)
#      CA03     FRONT x=[760,909]  fill = 0.838
#      CA03     FRONT x=[842,991]  fill = 0.847
#      CA03     BACK  x=[760,895]  fill = 0.884
#  แยกขาดชัดเจน - เลือก 0.55 ซึ่งอยู่กึ่งกลางช่องว่าง 0.20-0.84 พอดี
_BURIED_MIN_CARGO_FILL = 0.55       # สัดส่วน cargo_mask ขั้นต่ำภายในกรอบที่จะวาด
# ============================================================================
#  v26.33 - GREEN-THEME FLOOR/WALL EXCLUSION  (เฉพาะจุดตรวจ cargo-fill เท่านั้น)
# ----------------------------------------------------------------------------
#  อาการ (ผู้ใช้แจ้งจาก PD02-01 front view 23-Sep-2026): "กรอบแดงตรงพื้นที่ว่าง
#  ทำไมต้องไปวาด" - กรอบ buried_front_row ถูกวาดบนพื้นตู้ที่ว่างเปล่า
#
#  ROOT CAUSE: สีเด่นในกรอบ (614,724)-(820,803) คือ (0,255,133) 71% ของกรอบ
#  ถูกนับเป็นสินค้าเต็ม 100% ใน cargo_mask -> cargo_fill=0.827 ผ่าน CARGO-FILL
#  GUARD ของ v26.28 (เกณฑ์ 0.55) ได้ ทั้งที่ (0,255,133) คือ "พื้นตู้" ไม่ใช่สินค้า
#  MaxLoad ใช้เฉดเดียวกับธีมปกติแล้วตัดช่อง R=0 ตามธีมสี:
#      (255,255,133) พื้นตู้  -> (0,255,133)   G,B เหมือนกันเป๊ะ
#      (179,179,90)  ผนังตู้  -> (0,179,90)
#      (255,255,175) ผนังหลัง -> (0,255,175)
#
#  v26.32 (เพิ่มเข้า _p1b_is_structural_container_color) และ v26.33-รุ่นแรก
#  (ตัดออกจาก vivid_cargo_mask ทั้งระบบ) ทั้งสองครั้งถูกทดสอบแล้วพบผลข้างเคียง
#  ไม่พึงประสงค์ เพราะทั้งคู่แตะจุดที่ "ทุกกลไกใช้ร่วมกัน" (cargo_top_y ของทุก
#  คอลัมน์เปลี่ยนไปด้วย ไม่ใช่แค่กรอบที่มีปัญหา) ยืนยันจากภาพจริง: หลังแก้ครั้งก่อน
#  เกิดกรอบใหม่ที่ไม่เคยมีมาก่อนที่ cross_view/tail_stepdown ในไฟล์เดียวกัน
#
#  FIX รอบนี้ (ทางเลือก A ตามที่ผู้ใช้เลือก - ขอบเขตแคบที่สุดเท่าที่เป็นไปได้)
#  ตัดสีธีมเขียวออก "เฉพาะตอนคำนวณ cargo_fill ภายในกรอบที่จะตัดสินใจวาด/ไม่วาด
#  ของ detect_buried_front_row เท่านั้น" - ไม่แตะ vivid_cargo_mask, ไม่แตะ
#  cargo_mask ที่เก็บใน view_result, ไม่แตะ cargo_top_y ไม่กระทบกลไกอื่นใดเลย
#  แม้แต่จุดเดียว เพราะ hazard อื่นทั้งหมดไม่เคยเรียก _buried_true_cargo_fill นี้
#
#  ความปลอดภัย - สแกน 31 ไฟล์ทดสอบ พบเพียง 6 สีเข้าเกณฑ์ ทุกสีเป็นพื้น/ผนังตู้
#  พบใน 6 ไฟล์ธีมเขียวเท่านั้น สีกล่องในไฟล์เดียวกันอยู่นอกเกณฑ์ทั้งหมด:
#      (0,255,0) G-B=255 เกินเพดาน 125 | (0,132,0) G=132 < 170
# ============================================================================
_GREENFLOOR_MAX_R = 30
_GREENFLOOR_MIN_G = 170
_GREENFLOOR_GB_MIN = 75
_GREENFLOOR_GB_MAX = 125


def _buried_true_cargo_fill(region_sub, cargo_mask_sub):
    """v26.33: cargo_fill ที่กันสีพื้น/ผนังตู้ธีมเขียวออก - ใช้เฉพาะใน
    detect_buried_front_row จุดเดียว (ดู docstring เต็มด้านบน) ไม่กระทบ
    cargo_mask ตัวจริงหรือกลไกอื่นใดเลย เพราะเป็นการคำนวณสำเนาเฉพาะกิจ
    ภายในขอบเขตของกรอบที่กำลังตัดสินใจเท่านั้น"""
    if cargo_mask_sub.size == 0:
        return 0.0
    r = region_sub[:, :, 0].astype(np.int16)
    g = region_sub[:, :, 1].astype(np.int16)
    b = region_sub[:, :, 2].astype(np.int16)
    greenfloor = ((r <= _GREENFLOOR_MAX_R) & (g >= _GREENFLOOR_MIN_G)
                  & ((g - b) >= _GREENFLOOR_GB_MIN) & ((g - b) <= _GREENFLOOR_GB_MAX))
    true_cargo = cargo_mask_sub & (~greenfloor)
    return float(true_cargo.mean())
# ============================================================================
#  v26.29 - FLAT-ROW GUARD  (แถวเดียวยาวและราบ = ไม่ใช่ขั้น)
# ----------------------------------------------------------------------------
#  ที่มา (ผู้ใช้ชี้จาก CA03-01 พร้อมวาดเส้นพิสูจน์ 22-Sep-2026):
#  "กล่องน้ำเงิน TRDA8-OB วางเรียง 1 ชั้น ติดกับกล่องม่วง SLC1A-P5 วางเรียง 1 ชั้น
#   คือสูงเท่ากัน" -> ไม่มีความเสี่ยง แต่ v26.28 วาดกรอบแดง buried_front_row 3 จุด
#
#  ROOT CAUSE เชิงหลักการ
#    buried_front_row เทียบ "หลังคาที่เห็น" กับ "เส้นเงาบนสุด ณ ตำแหน่ง x เดียวกัน"
#    แต่เส้นเงานั้น "ขยับได้" ตามสิ่งที่บังอยู่  เมื่อมีกล่องวางซ้อนทับบนแถวเดียวกัน
#    เส้นเงาจะกระโดดขึ้นไปที่ยอดของกล่องที่ซ้อน ระบบจึงเข้าใจว่าแถวล่างเตี้ยกว่าเพื่อนบ้าน
#    ทั้งที่กล่องแถวนั้นทุกใบสูงเท่ากันหมด และของที่สูงกว่าวาง "ทับอยู่ข้างบน" ไม่ใช่
#    "อยู่ข้าง ๆ" -> กองเดียวกันล้มทับตัวเองไม่ได้
#
#  ตัวแยกที่ใช้ - ต่อหลังคาเป็น "สาย" แล้ววัด 2 ค่าคู่กัน
#    ชดเชยความชัน isometric ก่อน (ยอดกล่องจะสูงขึ้นเมื่อเลื่อนไปทางขวาตามความชัน 0.5)
#        lvl = roof_top_y + 0.5 * center_x
#    แล้วต่อ roof cell ที่ lvl ใกล้กัน (<=0.18w) และอยู่ติดกัน (gap <=0.55w) เป็นสายเดียว
#      span/w = ความยาวสาย เทียบความกว้างหลังคา 1 ใบ  -> "ยาว" = แถวเดียวเรียงต่อเนื่อง
#      std/w  = ส่วนเบี่ยงเบนของ lvl ในสาย            -> "ราบ" = ระนาบเดียวจริง
#
#  หลักฐาน (วัดครบทุกจุดที่ถูก flag ใน 4 ไฟล์ที่ผู้ใช้ยืนยันคำตอบแล้ว)
#    ต้องไม่ flag (ผู้ใช้ยืนยันว่าปลอดภัย)
#      CA03 FRONT  span/w=2.12  std/w=0.021
#      CA03 FRONT  span/w=2.12  std/w=0.023
#      CA03 BACK   span/w=3.36  std/w=0.045
#    ต้อง flag (ผู้ใช้ยืนยันว่าเป็นความเสี่ยงจริง)
#      PA01 FRONT  span/w=1.01  std/w=0.052   <- สายสั้น ไม่เข้าเงื่อนไขแรก
#      CB09 FRONT  span/w=1.00  std/w=0.000   <- สายสั้น
#      CB01 BACK   span/w=2.82  std/w=0.064   <- ยาวแต่ขรุขระ (เส้นฟันเลื่อย)
#      CB09 FRONT  span/w=2.33  std/w=0.081   <- ยาวแต่ขรุขระ
#      CB09 FRONT  span/w=2.35  std/w=0.082   <- ยาวแต่ขรุขระ
#      CB01 FRONT  span/w=4.11  std/w=0.069   <- ยาวแต่ขรุขระ
#    ต้องเข้าเงื่อนไข "ทั้ง 2 ข้อพร้อมกัน" จึงข้าม - ฝั่งปลอดภัยสูงสุด 0.045
#    ฝั่งที่ต้อง flag ต่ำสุด 0.064 (เฉพาะกลุ่มสายยาว) จึงเลือกกึ่งกลางที่ 0.055
#
#  เหตุผลเชิงกายภาพ: สายที่ "ยาวและราบ" = หลังคาแถวเดียวกันเรียงต่อเนื่องเป็นระนาบเดียว
#  ของที่สูงกว่าวางซ้อนอยู่ข้างบน ไม่มีขอบให้ร่วง | สายที่ "ขรุขระ" = กองคนละระดับ
#  สลับกันไปมา มีขั้นจริง
# ============================================================================
_BURIED_FLATROW_MIN_SPAN = 2.00     # ความยาวสาย เทียบความกว้างหลังคา 1 ใบ
_BURIED_FLATROW_MAX_STD = 0.055     # ความราบของสาย (std ของ lvl / ความกว้างหลังคา)
_BURIED_FLATROW_LVL_TOL = 0.18      # หลังคาถือว่า "ระดับเดียวกัน" เมื่อ lvl ต่างไม่เกินนี้
_BURIED_FLATROW_GAP_MAX = 0.55      # หลังคาถือว่า "ติดกัน" เมื่อ gap ไม่เกินนี้


def _buried_is_flat_row(roofs, x0, x1, roof_top):
    """v26.29: True ถ้าหลังคานี้เป็นส่วนหนึ่งของ 'แถวเดียวยาวและราบ' (ไม่ใช่ขั้น).

    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก CA03-01 ที่ผู้ใช้ยืนยัน)
    คืน (is_flat, span_w, std_w) - คืน False ถ้าคำนวณไม่ได้ (fail-safe: ยังคง flag ตามเดิม)"""
    w = float(x1 - x0)
    if w <= 0 or not roofs:
        return False, None, None
    _lvl = lambda a, b, y: float(y) + 0.5 * ((float(a) + float(b)) / 2.0)
    me_lvl = _lvl(x0, x1, roof_top)
    tol = _BURIED_FLATROW_LVL_TOL * w
    gap_max = _BURIED_FLATROW_GAP_MAX * w
    chain = [dict(x0=float(x0), x1=float(x1), lvl=me_lvl)]
    pool = [dict(x0=float(r["x0"]), x1=float(r["x1"]),
                 lvl=_lvl(r["x0"], r["x1"], r["y0"])) for r in roofs]
    used, changed = set(), True
    while changed:
        changed = False
        lo = min(c["x0"] for c in chain); hi = max(c["x1"] for c in chain)
        for i, p in enumerate(pool):
            if i in used or abs(p["lvl"] - me_lvl) > tol:
                continue
            if max(lo - p["x1"], p["x0"] - hi) <= gap_max:
                chain.append(p); used.add(i); changed = True
    lo = min(c["x0"] for c in chain); hi = max(c["x1"] for c in chain)
    span_w = (hi - lo) / w
    lv = [c["lvl"] for c in chain]
    std_w = (float(np.std(lv)) / w) if len(lv) > 1 else 0.0
    is_flat = (span_w >= _BURIED_FLATROW_MIN_SPAN
               and std_w <= _BURIED_FLATROW_MAX_STD)
    return is_flat, span_w, std_w
_BURIED_MIN_HEIGHT_PX = 40          # กล่องต้องมีความสูงที่วัดได้จริงพอสมควร
_BURIED_DEDUP_XOVERLAP = 0.50       # ทับกับกรอบเดิมเกินนี้ = ถือว่าเป็นจุดเดียวกัน


def _roof_cells_for_view(region_hires, down_factor=1.0):
    """คืน roof cell ทุกใบในพิกัด local ของ view (สเกลเดียวกับ cargo_top_y).

    ใช้ _p1b_classify_view ตัวเดียวกับที่ PHASE 1B ใช้อยู่แล้วทุกประการ (ไม่ได้เพิ่ม
    การประมวลผลภาพใหม่) - คืน [] ถ้าทำไม่ได้ (fail-safe ไม่ทำให้ pipeline ล้ม)"""
    try:
        # v26.26: ใช้ area_min คงที่เท่ากับที่ _p1b_front_faces ใช้ แล้วไปกรองด้วยเกณฑ์
        # ที่อิง "ขนาดกล่องจริง" ในขั้นถัดไปแทน (ดู _BURIED_ROOF_FRONT_FRAC ด้านบน)
        cells = _p1b_classify_view(region_hires, area_min=_BURIED_ROOF_AREA_MIN_FIXED)
    except Exception as e:
        print(f"[BURIED] แยก roof cell ไม่สำเร็จ ({e}) -> ข้ามกลไกนี้")
        return []
    # v26.26: median ของ front-face = สเกลกล่องจริงของภาพนี้ (ไม่ขึ้นกับขนาด region)
    _fa = sorted(c["area"] for c in cells if c.get("kind") == "front")
    _med_front = float(_fa[len(_fa) // 2]) if _fa else 0.0
    out = []
    for c in cells:
        if c.get("kind") != "roof":
            continue
        out.append({
            "med_front": _med_front,        # v26.26
            "x0": int(c["x"] * down_factor),
            "y0": int(c["y"] * down_factor),
            "x1": int((c["x"] + c["w"]) * down_factor),
            "y1": int((c["y"] + c["h"]) * down_factor),
            "area": int(c["area"]),
            "color": c.get("color"),
        })
    return out


def _front_cells_for_view(region_hires, down_factor=1.0):
    """v26.31: คืน front-face cell ทุกใบในพิกัด local ของ view.

    ใช้ _p1b_classify_view ตัวเดียวกับ PHASE 1B / _roof_cells_for_view ทุกประการ
    (ไม่ได้เพิ่มการประมวลผลภาพใหม่) - คืน [] ถ้าทำไม่ได้ (fail-safe)"""
    try:
        cells = _p1b_classify_view(region_hires, area_min=_BURIED_ROOF_AREA_MIN_FIXED)
    except Exception as e:
        print(f"[BOXSIZE] แยก front cell ไม่สำเร็จ ({e}) -> ข้ามกลไกนี้")
        return []
    out = []
    for c in cells:
        if c.get("kind") != "front":
            continue
        out.append({
            "x0": int(c["x"] * down_factor),
            "x1": int((c["x"] + c["w"]) * down_factor),
            "h": float(c["h"] * down_factor),
        })
    return out


# ============================================================================
#  v26.31 - SAME-BOX-SIZE GUARD  (กล่องขนาดเดียวกัน = วางเรียงระดับเดียวกัน)
# ----------------------------------------------------------------------------
#  ที่มา (ผู้ใช้ยืนยันคำตอบทีละจุดจาก 22 ไฟล์ 22-23 Sep 2026)
#    "กล่องน้ำเงิน TRDA8-OB เรียง 1 ชั้น ติดกับกล่องม่วง SLC1A-P5 เรียง 1 ชั้น
#     คือสูงเท่ากัน" -> ไม่ใช่ขั้น แต่ระบบวาดกรอบแดงให้
#
#  ROOT CAUSE เชิงโครงสร้าง (วัดค่าจริงจาก CA03 FRONT)
#    กลไก pairwise / tail_stepdown เทียบ "ความสูงกองทั้งกอง" (height_px) ซึ่งวัดจาก
#    เส้นเงาบนสุด  เมื่อคอลัมน์ข้างเคียงมีกล่องวางซ้อนอยู่ด้านบน ความสูงที่วัดได้จะเป็น
#    ผลรวมของทั้งตั้ง ไม่ใช่กล่องใบที่อยู่ระดับเดียวกัน
#      idx=0 (น้ำเงิน) H=134.7  กล่อง 1 ใบสูง 114.0 -> 1.18 ชั้น
#      idx=1 (ม่วง)   H=205.1  กล่อง 1 ใบสูง 114.8 -> 1.79 ชั้น  <-- วัดเกินเพราะมีส้มทับ
#    ระบบจึงเห็น drop 34.3% ทั้งที่ระดับล่างสุดของทั้ง 2 คอลัมน์เสมอกันสนิท
#
#  ตัวแยกที่ใช้ - เทียบ "ขนาดกล่อง 1 ใบ" แทน "ความสูงกอง"
#    _p1b_classify_view แยก front-face cell พร้อมความสูงไว้อยู่แล้ว ค่านี้สะท้อนขนาด
#    กล่องจริงและไม่ถูกรบกวนจากกล่องที่วางซ้อนด้านบน
#        fh_ratio = min(face_h_a, face_h_b) / max(face_h_a, face_h_b)
#    ถ้าเข้าใกล้ 1.0 แปลว่าเป็นกล่องขนาดเดียวกัน วางเรียงระดับเดียวกัน = ไม่ใช่ขั้น
#
#  หลักฐาน (ผู้ใช้ยืนยันคำตอบครบ 12 จุด)
#    ต้องไม่ flag (กล่องเสมอกัน)
#      CD34-all   pairwise      FRONT  drop=0.256  fh_ratio=1.000
#      CD12-all   pairwise      FRONT  drop=0.386  fh_ratio=0.995
#      CA03-01    tail_stepdown FRONT  drop=0.343  fh_ratio=0.993
#      CA03-01    tail_stepdown BACK   drop=0.524  fh_ratio=0.982
#      CA03-02,05 tail_stepdown BACK   drop=0.561  fh_ratio=0.919
#    ต้อง flag (กล่องสูงต่ำจริง)
#      CB01-01    pairwise      FRONT  drop=0.319  fh_ratio=0.667
#    ช่องว่างระหว่าง 0.667 กับ 0.919 กว้างมาก เลือก 0.95 ซึ่งอยู่ในช่องว่างนั้น
#    และยังต่ำกว่าจุดที่ต้องตัดทุกจุด ยกเว้น CA03-02,05 (0.919) ที่จงใจไม่ตัด
#
#  ขอบเขตที่จำกัดไว้ (สำคัญ - อย่าขยายโดยไม่มีหลักฐานเพิ่ม)
#    ใช้เฉพาะ pairwise และ tail_stepdown เท่านั้น  จงใจ "ไม่" ใส่ที่
#      - cross_view    : CD08-all (ถูก, 0.996) ชนกับ CD12-all (ผิด, 0.995) ห่างกัน
#                        เพียง 0.001 แยกไม่ได้ด้วยตัวชี้วัดนี้
#      - hidden_behind : ไม่เคยผิดเลยสักจุดในทุกไฟล์ที่ผู้ใช้ยืนยัน (0.873-0.987)
#    ตัวชี้วัดอื่นที่ทดลองแล้วแยกไม่ได้ (บันทึกไว้กันทำซ้ำ)
#      drop / jump_px / med_front / จำนวนชั้น / span+std ของสายหลังคา / สีกล่อง 2 ฝั่ง
# ============================================================================
_SAMEBOX_MIN_FH_RATIO = 0.95   # กล่อง 2 ฝั่งขนาดใกล้กันเกินนี้ = วางเรียงระดับเดียวกัน


def _same_box_size_pair(view_result, rec_a, rec_b):
    """v26.31: คืน fh_ratio ของกล่อง 2 คอลัมน์ (None ถ้าวัดไม่ได้ = fail-safe)."""
    if view_result is None or rec_a is None or rec_b is None:
        return None
    cells = view_result.get("_front_cells")
    if not cells:
        return None

    def face_h(rec):
        xr = rec.get("x_range")
        if not xr:
            return 0.0
        x0, x1 = float(xr[0]), float(xr[1])
        hs = [c["h"] for c in cells
              if min(x1, c["x1"]) - max(x0, c["x0"]) > 0.4 * (c["x1"] - c["x0"])]
        return float(np.median(hs)) if hs else 0.0

    ha, hb = face_h(rec_a), face_h(rec_b)
    if ha <= 0 or hb <= 0:
        return None
    return min(ha, hb) / max(ha, hb)


def _buried_overlap(a0, a1, b0, b1):
    """สัดส่วนการทับกันของสองช่วง เทียบกับช่วงที่สั้นกว่า."""
    lo, hi = max(a0, b0), min(a1, b1)
    span = min(a1 - a0, b1 - b0)
    if span <= 0:
        return 0.0
    return max(0.0, hi - lo) / span


def detect_buried_front_row(view_result, records, view_label):
    """v26.25 NEW: กล่องแถวหน้าที่เตี้ยกว่าแถวหลังจนจมอยู่ใต้เส้นเงาทั้งใบ.

    ดู docstring เต็มด้านบนสำหรับหลักฐาน+เหตุผล (พบจริงจาก PA01 ครึ่งซ้าย front view)
    วาดกรอบครอบ "กล่องแถวหน้าที่เตี้ย" (จากหลังคาของมันลงไปถึงเส้นพื้น) ซึ่งเป็นฝั่งที่
    เสี่ยงถูกกองสูงด้านหลังล้มทับ - คำนวณ abs_box ตรงนี้เลยเหมือน hidden_behind
    (กล่องเหล่านี้ไม่มี index ของตัวเองใน stack_heights เพราะไม่เคยถูกมองเห็นมาก่อน)"""
    risks = []
    roofs = view_result.get("_roof_cells") or []
    if not roofs:
        return risks
    cty = view_result.get("cargo_top_y")
    lfy = view_result.get("local_floor_y")
    if cty is None or lfy is None:
        return risks
    cty = np.asarray(cty, float)
    lfy = np.asarray(lfy, float)
    ox, oy = view_result["crop_origin_x"], view_result["crop_origin_y"]

    # v26.26: เกณฑ์พื้นที่อิงขนาดกล่องจริงของภาพนี้ แทนที่จะอิงขนาด region
    _med_front = float(roofs[0].get("med_front") or 0.0)
    _area_gate = _BURIED_MIN_ROOF_AREA
    if _med_front > 0:
        _area_gate = max(_BURIED_MIN_ROOF_AREA, _med_front * _BURIED_ROOF_FRONT_FRAC)

    for rc in roofs:
        if rc["area"] < _area_gate:
            continue
        # v26.27 FIX#1: หน้าบนกล่อง isometric ต้องมี h/w ~ 0.50 เสมอ (ดู docstring ด้านบน)
        _rw = rc["x1"] - rc["x0"]
        _rh = rc["y1"] - rc["y0"]
        if _rw <= 0 or (_rh / float(_rw)) > _BURIED_ROOF_MAX_ASPECT:
            continue
        cx = (rc["x0"] + rc["x1"]) // 2
        if not (0 <= cx < len(cty) and 0 <= cx < len(lfy)):
            continue
        silh_top = float(cty[cx])
        floor_y = float(lfy[cx])
        if silh_top < 0 or floor_y < 0:
            continue
        roof_top = float(rc["y0"])
        depth = roof_top - silh_top
        if depth < _BURIED_ROOF_MIN_DEPTH_PX:
            # v26.34: ผ่อนปรนเมื่อกล่องข้างเคียงพิงไม่มั่นคง (ดู docstring เต็มด้านบน)
            _reg_rel = view_result.get("region")
            _relaxed = False
            if depth >= _BURIED_DEPTH_RELAX_MIN and _reg_rel is not None:
                _ff = _buried_unstable_backing_floor_frac(_reg_rel, roof_top, floor_y, rc["x1"])
                if _ff >= _BURIED_UNSTABLE_FLOOR_FRAC:
                    _relaxed = True
                    print(f"[BURIED_RELAX] view={view_label} x=[{rc['x0']},{rc['x1']}] "
                          f"depth={depth:.0f}px (< เกณฑ์ {_BURIED_ROOF_MIN_DEPTH_PX}) "
                          f"แต่กล่องข้างเคียงพิงไม่มั่นคง (floor_frac={_ff:.2f} >= "
                          f"{_BURIED_UNSTABLE_FLOOR_FRAC}) -> ผ่อนปรนเกณฑ์ depth ให้ผ่าน")
            if not _relaxed:
                continue                  # หลังคานี้เป็นเจ้าของเส้นเงาเอง ไม่ใช่แถวหน้าที่จม
        buried_h = floor_y - roof_top     # ความสูงจริงของกล่องแถวหน้าที่เตี้ย
        taller_h = floor_y - silh_top     # ความสูงของกองที่ครองเส้นเงา ณ ตำแหน่งเดียวกัน
        if buried_h < _BURIED_MIN_HEIGHT_PX or taller_h <= 0:
            continue
        drop = 1.0 - (buried_h / taller_h)
        if drop < _BURIED_MIN_DROP_RATIO:
            continue
        # v26.29: แถวเดียวยาวและราบ = ของที่สูงกว่าวางซ้อนอยู่ข้างบน ไม่ใช่ขั้น
        _flat, _spn, _sd = _buried_is_flat_row(roofs, rc["x0"], rc["x1"], roof_top)
        if _flat:
            print(f"[BURIED] ข้าม view={view_label} x=[{rc['x0']},{rc['x1']}] "
                  f"เพราะหลังคาต่อเป็นแถวเดียวยาว {_spn:.2f}w และราบ std={_sd:.3f}w "
                  f"(เกณฑ์ span>={_BURIED_FLATROW_MIN_SPAN} และ std<={_BURIED_FLATROW_MAX_STD}) "
                  f"= กล่องแถวนี้สูงเท่ากันหมด ของที่สูงกว่าวางซ้อนอยู่ข้างบน")
            continue
        # v26.28: กรอบต้องมีสินค้าอยู่จริง ไม่ใช่ครอบพื้นที่ว่าง (ดู docstring ด้านบน)
        _cm = view_result.get("cargo_mask")
        _reg = view_result.get("region")
        if _cm is not None:
            _y0 = int(max(0, roof_top)); _y1 = int(min(_cm.shape[0], floor_y))
            _x0 = int(max(0, rc["x0"])); _x1 = int(min(_cm.shape[1], rc["x1"]))
            _sub = _cm[_y0:_y1, _x0:_x1]
            if _sub.size:
                # v26.33: ถ้ามี region ให้ใช้ true_cargo_fill (กันสีพื้น/ผนังธีมเขียว
                # ออกเฉพาะจุดนี้) - fail-safe กลับไปใช้ mean() ตรงๆ ถ้าไม่มี region
                if _reg is not None:
                    _reg_sub = _reg[_y0:_y1, _x0:_x1]
                    _fill = _buried_true_cargo_fill(_reg_sub, _sub)
                else:
                    _fill = float(_sub.mean())
                if _fill < _BURIED_MIN_CARGO_FILL:
                    print(f"[BURIED] ข้าม view={view_label} x=[{rc['x0']},{rc['x1']}] "
                          f"เพราะในกรอบมีสินค้าเพียง {_fill:.1%} "
                          f"(เกณฑ์ {_BURIED_MIN_CARGO_FILL:.0%}) = กรอบครอบพื้นที่ว่าง")
                    continue
        risks.append({
            "risk_type": "STEP_DOWN_RISK", "subtype": "buried_front_row",
            "view": view_label, "mark_view": view_label, "mark_stack_idx": None,
            "mark_x_range": (rc["x0"], rc["x1"]),
            "taller_height_px": taller_h, "shorter_height_px": buried_h,
            "drop_ratio": drop, "roof_depth_px": depth,
            "height_source": "roof_cell", "n_samples": None,
            "abs_box": (ox + rc["x0"], oy + int(roof_top),
                        ox + rc["x1"], oy + int(floor_y)),
        })
        print(f"[BURIED] view={view_label} x=[{rc['x0']},{rc['x1']}] "
              f"roof_top={roof_top:.0f} silhouette_top={silh_top:.0f} "
              f"depth={depth:.0f}px (เกณฑ์ {_BURIED_ROOF_MIN_DEPTH_PX}) "
              f"h={buried_h:.0f} vs กองหลัง={taller_h:.0f} drop={drop:.1%} "
              f"-> กล่องแถวหน้าเตี้ยกว่าแถวหลัง จมใต้เส้นเงา")
    return risks


def _dedup_buried_self(buried):
    """v26.26: ยุบ buried ที่ทับกันเองในแนว x ให้เหลือใบเดียวต่อ 1 กอง.

    ROOT CAUSE ที่ต้องมีขั้นนี้ (วัดจริงจาก PC02/PB01-01 หลังเปิด gate แบบอิงขนาดกล่อง):
    กองสินค้าที่ซ้อนหลายชั้นจะให้ "หลังคาของแต่ละชั้น" ออกมาเป็น roof cell แยกกันหลายใบ
    ซ้อนทับกันในแนว x เดียวกัน (ชั้นบนสุด depth น้อย, ชั้นล่าง ๆ depth มากขึ้นเรื่อย ๆ)
    ถ้าไม่ยุบ จะเกิดกรอบซ้อนกันหลายชั้นบนกองเดียว (PC02 พบ 9 กรอบบนกองเดียวกัน)
    เก็บใบที่ depth "น้อยที่สุด" ไว้ เพราะนั่นคือหลังคาจริงของยอดกองแถวหน้า
    ส่วนใบที่ depth มากกว่าคือชั้นที่อยู่ลึกลงไปในกองเดียวกัน ไม่ใช่กองใหม่"""
    keep = []
    for r in sorted(buried, key=lambda z: z.get("roof_depth_px", 0)):
        b = r["abs_box"]
        if any(_buried_overlap(b[0], b[2], k["abs_box"][0], k["abs_box"][2])
               >= _BURIED_SELF_XOVERLAP for k in keep):
            continue
        keep.append(r)
    return keep


def _dedup_buried_against_existing(risks, view_label):
    """ตัด buried_front_row ที่ทับกับกรอบเดิมในวิวเดียวกันเกินเกณฑ์ออก.

    กลไกเดิมอาจ flag บริเวณเดียวกันไว้แล้วด้วยเหตุผลอื่น - เก็บกรอบเดิมไว้เสมอ
    ตัดของใหม่ทิ้ง เพื่อไม่ให้ hazardCount นับซ้ำและไม่ให้เกิด marker ซ้อนทับกันบนภาพ"""
    keep, dropped = [], 0
    others = [r for r in risks if r.get("subtype") != "buried_front_row"]
    for r in risks:
        if r.get("subtype") != "buried_front_row":
            keep.append(r)
            continue
        b = r.get("abs_box")
        clash = False
        for o in others:
            if o.get("mark_view") != r.get("mark_view"):
                continue
            ob = o.get("abs_box")
            if not (b and ob):
                continue
            # v26.25: ต้องทับกัน "ทั้งแกน x และ y" จึงถือว่าเป็นจุดเดียวกัน - วัดจริงจาก PA01
            # พบว่ากรอบ silhouette_notch (570,602)-(1196,791) ทับแกน x กับกรอบ buried
            # (446,980)-(729,1425) ถึง 0.56 แต่ทับแกน y เพียง 0.00 (คนละครึ่งภาพในแนวตั้ง
            # โดยสิ้นเชิง - notch อยู่ที่ยอดกอง ส่วน buried อยู่ที่กล่องแถวหน้าระดับพื้น)
            # ถ้าดูแกน x อย่างเดียวจะตัดกรอบที่ถูกต้องทิ้งอย่างผิดพลาด
            if (_buried_overlap(b[0], b[2], ob[0], ob[2]) >= _BURIED_DEDUP_XOVERLAP
                    and _buried_overlap(b[1], b[3], ob[1], ob[3]) >= _BURIED_DEDUP_XOVERLAP):
                clash = True
                break
        if clash:
            dropped += 1
            print(f"[BURIED] ตัดกรอบซ้ำกับกลไกเดิมที่ view={view_label} "
                  f"x=[{b[0]},{b[2]}] ออก (เก็บกรอบเดิมไว้แทน)")
        else:
            keep.append(r)
    return keep


def run_full_analysis_on_image(full_img, doc, page_idx=1, pdf_bytes=None, matrix_scale=3):
    # v25.11: PHASE 1B ต้องรู้ทั้ง FRONT และ BACK พร้อมกันก่อน (BACK = ground-truth ตำแหน่ง,
    # FRONT ถูก reconcile กับ BACK) จึงต้องคำนวณคอลัมน์ทั้งคู่ล่วงหน้า ก่อนเรียก
    # process_view_with_height_on_image ต่อ view ตามปกติ - ถ้าล้มเหลว (None) จะ fallback ไป
    # seam-based เดิมโดยอัตโนมัติ (ดู process_view_on_image)
    #
    # v25.15 FIX (Critical - แก้ HTTP 500 บน Cloud Function จริงที่เกิดจาก v25.14): v25.14 แก้
    # Bug#1/#2 (coordinate mismatch) โดยเปลี่ยนทั้ง pipeline หลักให้ render เต็มหน้าที่ scale=4
    # (จากเดิม scale=3) - ทดสอบ local ผ่านหมด แต่พอใช้งานจริงบน Cloud Function พบ HTTP 500 ทุกไฟล์
    # เพราะ scale=4 เต็มหน้าทำให้ทุกขั้นตอนใน pipeline (mask, floor profile, วาด marker, JPEG
    # encode ฯลฯ) ใช้ memory เพิ่มขึ้น ~1.78 เท่าพร้อมกันหมด จนเกิน memory limit ของ Cloud Function
    #
    # แก้โดยกลับไปใช้ full_img ที่ scale=3 สำหรับ pipeline หลักเหมือนเดิม (memory เท่าเดิม) ส่วน
    # PHASE 1B render เฉพาะ "สี่เหลี่ยม region เล็กๆ ของ view" ตรงจาก PDF ที่ scale=4 ผ่าน fitz
    # clip (render_hires_crop) โดยใช้ origin_box เดียวกับที่ get_view_region คำนวณให้ pipeline
    # หลักใช้เป๊ะ - ยังคงแก้ Bug#1 (coordinate mismatch) + Bug#2 (double ensure_safe_crop) ได้ครบ
    # เพราะพิกัด origin อ้างอิงจากกล่องเดียวกัน (ต่างกันแค่ความหนาแน่น pixel ที่แปลงกลับด้วย
    # down_factor คงที่) แต่ไม่ต้อง render เต็มหน้าที่ scale สูงอีกต่อไป (ประหยัด memory มาก)
    try:
        page = doc[page_idx]
        front_region, front_origin, _ = get_view_region(full_img, doc, "front", page_idx=page_idx)
        back_region, back_origin, _ = get_view_region(full_img, doc, "back", page_idx=page_idx)
        front_precrop = (front_region, front_origin)
        back_precrop = (back_region, back_origin)

        front_hi, down_factor = render_hires_crop(page, front_origin, matrix_scale)
        back_hi, _ = render_hires_crop(page, back_origin, matrix_scale)
        phase1b = compute_phase1b_columns({"front": front_hi, "back": back_hi}, down_factor=down_factor)
        # v26.25: เก็บ roof cell ไว้ก่อนคืน memory (ใช้ตรวจกล่องแถวหน้าที่จมใต้เส้นเงา)
        _roofs_front = _roof_cells_for_view(front_hi, down_factor)
        _roofs_back = _roof_cells_for_view(back_hi, down_factor)
        _fronts_front = _front_cells_for_view(front_hi, down_factor)   # v26.31
        _fronts_back = _front_cells_for_view(back_hi, down_factor)     # v26.31
        del front_hi, back_hi  # ปล่อย memory ของ hi-res crop ทันทีหลังใช้เสร็จ
    except Exception as e:
        print(f"PHASE1B hi-res crop ล้มเหลว, fallback ให้ process_view_on_image ครอปเองตามปกติ: {e}")
        phase1b = {"front": None, "back": None}
        front_precrop = None
        back_precrop = None
        _roofs_front = []
        _roofs_back = []
        _fronts_front = []
        _fronts_back = []

    front = process_view_with_height_on_image(
        full_img, doc, "front", page_idx=page_idx, override_cols=phase1b.get("front"),
        precrop=front_precrop)
    back = process_view_with_height_on_image(
        full_img, doc, "back", page_idx=page_idx, override_cols=phase1b.get("back"),
        precrop=back_precrop)

    # v26.06: แนบจำนวน side face (สีกล่องจริง) เข้า view_result เพื่อให้
    # _is_large_box_single_row ใช้ได้ (ดู docstring เต็มที่ _LARGEBOX_MAX_SIDE_FACES)
    front["n_cargo_side_faces"] = phase1b.get("n_side_front")
    back["n_cargo_side_faces"] = phase1b.get("n_side_back")
    front["_roof_cells"] = _roofs_front     # v26.25
    back["_roof_cells"] = _roofs_back       # v26.25
    front["_front_cells"] = _fronts_front   # v26.31
    back["_front_cells"] = _fronts_back     # v26.31
    records_front = build_stack_records(front, "FRONT")
    records_back = build_stack_records(back, "BACK")

    # ลำดับการแก้ไข height: 1) direct 2) cross_view_filled/corrected 3) carried_forward
    reconcile_heights_cross_view(records_front, records_back,
                                  front_result=front, back_result=back)
    fill_missing_heights(sorted(records_front, key=lambda r: r["idx"]))
    fill_missing_heights(sorted(records_back, key=lambda r: r["idx"]))
    for records, view_result in [(records_front, front), (records_back, back)]:
        for rec in records:
            sh = view_result["stack_heights"][rec["idx"]]
            sh["height_px"] = rec["height_px"]
            sh["height_source"] = rec["height_source"]

    risks = []

    # v25.97 NEW: รถหลายตู้ -> วิเคราะห์แต่ละตู้แยกกันเหมือนตู้เดี่ยว (ตามที่ผู้ใช้สั่ง)
    # ดู _analyse_per_container สำหรับเหตุผล+ขอบเขตความปลอดภัย (คืน None = ใช้เส้นทางเดิม)
    _n_cont = 1
    if pdf_bytes is not None:
        try:
            _n_cont = _detect_multi_container_vehicle(pdf_bytes)[0] or 1
        except Exception as _e:
            print(f"[PER_CONTAINER] ตรวจประเภทรถไม่สำเร็จ ({_e}) -> ถือว่าตู้เดียว")
    # v26.15: คำนวณ "ช่องว่างระหว่างตู้" แล้วแนบเข้า view_result ก่อนวิเคราะห์ เพื่อให้
    # cross_view รู้ว่าคอลัมน์ใดถูกช่องว่างเจือจางความสูง (ดู _GAP_CONTAMINATED_MAX_FRAC)
    if _n_cont >= 2:
        try:
            front["_inter_container_gaps"] = _find_inter_container_gaps(front, _n_cont)
            back["_inter_container_gaps"] = _find_inter_container_gaps(back, _n_cont)
        except Exception as _e:
            print(f"[GAP_COL] หาช่องว่างระหว่างตู้ไม่สำเร็จ ({_e}) -> ข้าม guard นี้")
    _pc = None
    if _n_cont >= 2:
        try:
            _pc = _analyse_per_container(front, back, records_front, records_back, _n_cont)
        except Exception as _e:
            print(f"[PER_CONTAINER] วิเคราะห์แยกตู้ล้มเหลว ({_e}) -> ใช้เส้นทางเดิม")
            _pc = None
    if _pc is not None:
        risks += _pc
    else:
        risks += _analyse_whole_view(front, back, records_front, records_back)
    risks += detect_silhouette_notch_risk(front, "FRONT")
    risks += detect_silhouette_notch_risk(back, "BACK")
    # v26.25: กล่องแถวหน้าที่เตี้ยกว่าแถวหลังจนจมใต้เส้นเงา (ดู docstring เต็มด้านบน)
    _buried = (_dedup_buried_self(detect_buried_front_row(front, records_front, "FRONT"))
               + _dedup_buried_self(detect_buried_front_row(back, records_back, "BACK")))
    if _buried:
        risks = _dedup_buried_against_existing(risks + _buried, "FRONT/BACK")
    # v26.15: ระงับกรอบส้มที่ปลายสุดของกองกล่องใหญ่วางเรียงแถวเดียว
    # (ดู docstring เต็มที่ _suppress_largebox_tail_notch - ผู้ใช้ระบุโดยตรง)
    risks = _suppress_largebox_tail_notch(risks, front, records_front, "FRONT")
    risks = _suppress_largebox_tail_notch(risks, back, records_back, "BACK")
    # v25.75 NEW: ลบบรรทัด comment-out ของ detect_step_down_topface_jump ที่ปิดใช้งานถาวร
    # มาตั้งแต่ v25.65 (ฟังก์ชันเองก็ถูกลบไปแล้วในรอบนี้ - ดู docstring เต็มที่จุดที่เคยมีฟังก์ชัน
    # นั้นอยู่ ใกล้ _floor_linearity_anomaly) ตามคำสั่งผู้ใช้ให้ลบกลไกที่ไม่ใช้งานจริงออก
    # v25.57 NEW: dedup ระหว่าง pairwise/pairwise_floor_jump กับ tail_stepdown เมื่อทั้งคู่
    # flag "คู่ column เดียวกัน" (view+pair_indices ตรงกัน) - พบจริงจาก log EB66-01 29-Aug-2026:
    # FRONT pairwise idx=1 และ tail_stepdown idx=0 ได้ drop_ratio=0.23156868... เหมือนกันเป๊ะ
    # เพราะทั้ง 2 กลไกเปรียบเทียบ pair (idx0,idx1) เดียวกันอย่างเป็นอิสระต่อกัน (tail_stepdown
    # เจอเพราะ idx0 เป็นตั้งท้ายสุดพอดี, pairwise เจอเพราะ idx0/idx1 เป็นคู่ติดกัน) - ทำให้เกิด
    # marker ซ้ำซ้อน 2 กรอบสำหรับสถานการณ์ทางกายภาพเดียวกัน (นับ hazardCount เกินจริงด้วย) เก็บ
    # เฉพาะ pairwise/pairwise_floor_jump ไว้ (มี guard ครบชุดเดียวกับ tail_stepdown อยู่แล้วหลัง
    # v25.57 - เลือกอันเดียวพอ ไม่ต้องมี 2 กรอบซ้อนกันสำหรับ edge case เดียวกัน)
    risks = _dedup_overlapping_stepdown_risks(risks)
    # v25.79 NEW: dedup STEP_DOWN_RISK(pairwise) ที่ค่าความสูงฝั่งเตี้ยกว่าถูกปนเปื้อนจาก
    # silhouette_notch ตำแหน่งเดียวกัน - ดู docstring เต็มที่ _dedup_stepdown_corrupted_by_
    # adjacent_notch สำหรับหลักฐาน+เหตุผล (พบจริงจาก EA10-01)
    risks = _dedup_stepdown_corrupted_by_adjacent_notch(risks, records_front, records_back)


# v25.92 NEW: ยกเว้นกรอบส้ม (EMPTY_SPACE_RISK) ที่ช่องว่าง "ระหว่างตู้" ของรถหลายตู้ต่อ view
    # (เช่น full trailer 2 ตู้) - ดู docstring เต็มที่ _suppress_inter_container_empty_space_risks
    # สำหรับหลักฐาน+เหตุผล (พบจริงจาก CC19-all) - ไม่แตะ STEP_DOWN_RISK (กรอบแดง) เลยแม้แต่จุดเดียว
    n_containers = 1
    if pdf_bytes is not None:
        n_containers, _veh_desc = _detect_multi_container_vehicle(pdf_bytes)
    if n_containers >= 2:
        risks = _suppress_inter_container_empty_space_risks(risks, front, "FRONT", n_containers)
        risks = _suppress_inter_container_empty_space_risks(risks, back, "BACK", n_containers)
        # v26.13: ตัดกรอบที่คร่อมช่องว่างระหว่างตู้ ให้อยู่ในตู้เดียว
        # (ดู docstring เต็มที่ _clip_risks_at_container_gaps - พบจริงจาก CC05-all/CE01-all)
        risks = _clip_risks_at_container_gaps(risks, front, back, n_containers)
        # v26.16: ระงับกรอบแดงที่คอลัมน์แรกของตู้ใบถัดไป (ดู _suppress_container_entry_column_stepdown)
        risks = _suppress_container_entry_column_stepdown(risks, front, back, n_containers)
        # v26.17: ระงับกรอบแดงที่คอลัมน์อ้างอิงคร่อม 2 ตู้ (ดู _suppress_column_spanning_two_containers)
        risks = _suppress_column_spanning_two_containers(risks, front, back, n_containers)

    return {
        "front": front, "back": back,
        "records_front": records_front, "records_back": records_back,
        "risks": risks,
    }


class NoCargoDiagramError(Exception):
    """v26.09 NEW: ยกขึ้นเมื่อ "หาไดอะแกรมสินค้าที่วิเคราะห์ได้ไม่พบ" ในไฟล์นี้
    (ไม่ใช่ข้อผิดพลาดของโปรแกรม แต่เป็นลักษณะของไฟล์เอง)

    ที่มา (ผู้ใช้แจ้ง HTTP 500 จาก Cloud Run log 15-Sep-2026): เดิม get_single_view_region
    โยน ValueError ธรรมดาเมื่อหาสินค้าไม่พบ ทำให้ process_request จับรวมกับ error อื่นๆ
    แล้วคืน HTTP 500 - ผู้ใช้เห็นเป็น "โปรแกรมพัง" ทั้งที่จริงคือ "ไฟล์นี้วิเคราะห์ไม่ได้"
    ซึ่งเป็นคนละเรื่องกันโดยสิ้นเชิง และทำให้ WebApp/GAS ฝั่งรับผลไม่ได้รับ JSON ใดๆ เลย

    FIX: แยกเป็น exception เฉพาะ เพื่อให้ process_request คืน HTTP 200 พร้อม status
    ที่อธิบายสาเหตุได้ (ผู้ใช้เห็นข้อความชัดเจนแทนหน้าจอ error) - เป็นการปิดช่องโหว่
    fail-safe ที่ยังไม่ครบวงจรของ v26.08 (ทำ fail-safe ให้ colorizer ไว้แล้ว แต่ปลายทาง
    ยัง crash อยู่ดีเมื่อไฟล์ไม่มีสีให้วิเคราะห์)
    """


def get_single_view_region(full_img, pad=_SINGLE_VIEW_PAD_PX):
    """v25.91 NEW: หากรอบ (region) ของไดอะแกรม isometric บน "หน้าที่ 1" โดยไม่พึ่ง label
    Front/Back เลย (เพราะไฟล์กลุ่มนี้ไม่มี label ดังกล่าวอยู่ในหน้าใดเลย)

    วิธี: ใช้ vivid_cargo_mask (สีสดของกล่องสินค้า) ที่กรอง arrow_mask ออกแล้ว หาขอบเขตจริงของ
    สินค้าในหน้า แล้วขยายกรอบออก pad พิกเซล - ยืนยันด้วยข้อมูลจริงจากทั้ง 3 ไฟล์ที่ผู้ใช้แนบว่า
    ไดอะแกรมถูกแยกออกมาได้สะอาด (สินค้ากระจุกตัวอยู่บริเวณเดียว ไม่มีสีสดอื่นปนในหน้า เพราะ
    ตัวอักษร/ตารางเป็นสีดำ ส่วนพื้นตู้/ผนังตู้เป็นโทนเหลืองอ่อนที่ค่า saturation ต่ำกว่าเกณฑ์
    vivid (0.55) จึงไม่ถูกนับเป็นสินค้า แต่ยังคงถูกนับเป็น struct_mask สำหรับหาเส้นพื้นได้ปกติ)

    pad ต้องกว้างพอให้ครอบคลุม "พื้นตู้ใต้กล่อง" ด้วย เพราะ compute_floor_profile ค้นหาเส้นพื้น
    ได้ลึกสุด 100px ใต้ cargo_bottom_y (ดู _SINGLE_VIEW_PAD_PX) จากนั้นส่งต่อให้ ensure_safe_crop
    ขยายเพิ่มอัตโนมัติถ้าสินค้ายังชนขอบอยู่ (ใช้กลไกเดียวกับ get_view_region ทุกประการ)

    คืนค่า (region, origin_box) เหมือน get_view_region เพื่อให้ส่งต่อเป็น precrop ได้ทันที"""
    cargo = vivid_cargo_mask(full_img) & (~arrow_mask(full_img))
    ys, xs = np.nonzero(cargo)
    if len(xs) < _SINGLE_VIEW_MIN_CARGO_PX:
        # v26.09: ยกเป็น NoCargoDiagramError เพื่อให้ process_request แยกแยะได้ว่าเป็น
        # "ไฟล์ที่วิเคราะห์ไม่ได้" (ไม่ใช่บั๊ก) แล้วคืน HTTP 200 พร้อมคำอธิบายแทนการ crash
        # (ดู docstring เต็มที่ class NoCargoDiagramError)
        raise NoCargoDiagramError(
            f"หน้าที่ 1 ไม่พบไดอะแกรมสินค้า (vivid cargo เพียง {len(xs)}px)")

    H, W, _ = full_img.shape
    x0 = max(0, int(xs.min()) - pad)
    x1 = min(W, int(xs.max()) + pad + 1)
    y0 = max(0, int(ys.min()) - pad)
    y1 = min(H, int(ys.max()) + pad + 1)

    safe_y0, safe_y1, safe_x0, safe_x1 = ensure_safe_crop(full_img, y0, y1, x0, x1, margin=30)
    region = full_img[safe_y0:safe_y1, safe_x0:safe_x1].copy()
    print(f"[SINGLE_VIEW] region x=[{safe_x0},{safe_x1}] y=[{safe_y0},{safe_y1}] "
          f"(cargo bbox x=[{xs.min()},{xs.max()}] y=[{ys.min()},{ys.max()}])")
    return region, (safe_x0, safe_y0, safe_x1, safe_y1)


def compute_phase1b_columns_single(region_hires, down_factor=1.0):
    """v25.91 NEW: PHASE 1B สำหรับ "วิวเดียว" (ไม่มี BACK ให้ reconcile ด้วย)

    ใช้ขั้นตอนเดียวกับฝั่ง FRONT ของ compute_phase1b_columns ทุกประการ ยกเว้น 2 ขั้นที่ผูกกับ
    การมี BACK เป็น ground-truth ซึ่งใช้ไม่ได้ในโหมดนี้:
      - _p1b_drop_side_wall_contaminated_columns : เป็นขั้นตอนของฝั่ง BACK เท่านั้นอยู่แล้ว
      - _p1b_reconcile_with_back                 : ต้องมี BACK เป็นตัวอ้างอิงจำนวน/ตำแหน่งตั้ง
    (จงใจ "ไม่" เอา region เดียวกันไปใส่เป็น BACK หลอกๆ เพื่อให้ reconcile ทำงาน - เพราะขั้นตอน
    เฉพาะของ BACK อาจตัดคอลัมน์ทิ้งจนจำนวน 2 ฝั่งไม่เท่ากัน แล้วไป reconcile ตัดคอลัมน์จริงทิ้ง
    อย่างผิดพลาด ซึ่งอันตรายกว่าการไม่ reconcile เลย)

    คืนค่า list ของคอลัมน์ (พิกัด local ที่ main_scale) หรือ None ถ้าล้มเหลว (fallback ไป
    seam-based เดิมอัตโนมัติใน process_view_on_image)"""
    try:
        fronts, all_cells, _n_dropped = _p1b_front_faces(region_hires)
        if not fronts:
            print("[SINGLE_VIEW] PHASE1B: ไม่พบ front-face -> fallback seam-based")
            return None

        cx_tol = _p1b_compute_adaptive_cx_tol(fronts)
        cols = _p1b_cluster_columns(fronts, cx_tol=cx_tol)
        if not cols:
            print("[SINGLE_VIEW] PHASE1B: cluster ไม่ได้เลย -> fallback seam-based")
            return None

        cols, _dropped = _p1b_merge_corner_artifact_columns(cols, all_cells)
        cols, n_roof_merges = _p1b_merge_columns_by_overlapping_roofs(cols, all_cells)
        cols = _p1b_merge_near_duplicate_cols(cols, tol=5.0)

        orphaned = _p1b_find_orphaned_roof_columns(cols, all_cells)
        if orphaned:
            print(f"[SINGLE_VIEW] PHASE1B orphaned-roof columns: {len(orphaned)}")
            cols = sorted(cols + orphaned, key=lambda c: c["cx"])

        print(f"[SINGLE_VIEW] PHASE1B: {len(cols)} cols "
              f"(roof_merges={n_roof_merges}), cx={[round(c['cx'], 1) for c in cols]}")
        return [_p1b_scale_col(c, down_factor) for c in cols]
    except Exception as e:
        print(f"[SINGLE_VIEW] PHASE1B ล้มเหลว, fallback seam-based เดิม: {e}")
        return None


def run_single_view_analysis_on_image(full_img, doc, page_idx=_SINGLE_VIEW_PAGE_IDX,
                                       matrix_scale=3, pdf_bytes=None):
    """v25.91 NEW: วิเคราะห์ "หน้าที่ 1 หน้าเดียว" ตามกฎที่ผู้ใช้กำหนด (ใช้เมื่อไม่มีหน้าใดเป็น
    ไดอะแกรม Front/Back แบบบนล่าง/ซ้ายขวาเลย) - คืนค่าโครงสร้างเดียวกับ
    run_full_analysis_on_image เพื่อให้ process_request/risk_abs_box ใช้งานต่อได้โดยไม่ต้องแก้

    v25.92 UPDATE (ผู้ใช้ยืนยันเพิ่มเติม 11-Sep-2026: "หน้าที่ 1 เป็น front view ใช้การวิเคราะห์
    ตามระบบได้"): เดิม v25.91 ปิด detect_tail_stepdown ไว้เพราะยังไม่แน่ใจว่าทิศทางหัว/ท้ายตู้ของ
    หน้าที่ 1 ตรงกับ FRONT view มาตรฐานหรือไม่ (ไม่มี label Front/Back ให้ยืนยัน) - เมื่อผู้ใช้
    ยืนยันแล้วว่าหน้าที่ 1 เป็น front view จริงและใช้การวิเคราะห์ตามระบบปกติได้ จึง "เปิดใช้งาน"
    detect_tail_stepdown เพิ่ม โดยใช้ทิศทางเดียวกับ FRONT view มาตรฐานทุกประการ
    (build_stack_records ใช้ flip_position=True สำหรับ FRONT อยู่แล้ว - ไม่ต้องแก้อะไรเพิ่ม)

    กลไกตรวจจับที่ "เปิดใช้" ในโหมดนี้ (4 กลไก):
      - detect_step_down_pairwise      (เทียบตั้งข้างเคียงในวิวเดียวกัน)
      - detect_step_down_hidden_behind (กล่องแถวหลังโผล่พ้น/ซ่อนอยู่ ภายในคอลัมน์เดียวกัน)
      - detect_silhouette_notch_risk   (รอยบาก/พื้นที่ว่างในเส้นขอบบนกองสินค้า)
      - detect_tail_stepdown           (v25.92 NEW - เปิดตามที่ผู้ใช้ยืนยันว่าหน้าที่ 1 เป็น
                                        front view ใช้การวิเคราะห์ตามระบบได้)

    กลไกที่ "ปิด" ในโหมดนี้ พร้อมเหตุผลที่ตรวจสอบแล้ว (บอกตรงไปตรงมา ไม่ใช่การละเลย):
      - detect_step_down_crossview : ต้องมี 2 view เทียบกัน - ไม่มี BACK ให้เทียบ (ใช้ไม่ได้จริง)
      - detect_rear_empty_risk     : ต้องใช้ length_px ของทั้ง 2 view คำนวณ gap เป็น Guard 1
                                     (v25.54) - ไม่มี BACK ทำให้ gap=0 เสมอ กลไกถูกบล็อกเองอยู่แล้ว
    """
    page = doc[page_idx]
    region, origin = get_single_view_region(full_img)
    precrop = (region, origin)

    try:
        hi_region, down_factor = render_hires_crop(page, origin, matrix_scale)
        cols = compute_phase1b_columns_single(hi_region, down_factor=down_factor)
        _roofs = _roof_cells_for_view(hi_region, down_factor)   # v26.25
        _fronts = _front_cells_for_view(hi_region, down_factor)  # v26.31
        del hi_region
    except Exception as e:
        print(f"[SINGLE_VIEW] hi-res crop ล้มเหลว, fallback seam-based เดิม: {e}")
        cols = None
        _roofs = []
        _fronts = []

    view = process_view_with_height_on_image(
        full_img, doc, "front", page_idx=page_idx, override_cols=cols, precrop=precrop)

    view["_roof_cells"] = _roofs        # v26.25
    view["_front_cells"] = _fronts      # v26.31
    records = build_stack_records(view, "FRONT")
    fill_missing_heights(sorted(records, key=lambda r: r["idx"]))
    for rec in records:
        sh = view["stack_heights"][rec["idx"]]
        sh["height_px"] = rec["height_px"]
        sh["height_source"] = rec["height_source"]

    risks = []
    risks += detect_step_down_pairwise(records, "FRONT", view_result=view)
    risks += detect_step_down_hidden_behind(view, records, "FRONT")
    risks += detect_silhouette_notch_risk(view, "FRONT")
    # v26.15: ระงับกรอบส้มที่ปลายสุดของกองกล่องใหญ่วางเรียงแถวเดียว
    risks = _suppress_largebox_tail_notch(risks, view, records, "FRONT")
    # v25.92 NEW: เปิด tail_stepdown ตามที่ผู้ใช้ยืนยันว่า "หน้าที่ 1 เป็น front view ใช้การ
    # วิเคราะห์ตามระบบได้" (ดู docstring ด้านบน) - ใช้ทิศทางเดียวกับ FRONT view มาตรฐาน
    risks += detect_tail_stepdown(records, "FRONT", view_result=view)
    # v26.01: โพรงสูงต่ำท้ายรถ (หน้าที่ 1 เป็น front view จึงใช้ได้ตามปกติ)
    risks += detect_tailzone_wall_exposure(view, records, "FRONT")
    # v26.25: กล่องแถวหน้าที่เตี้ยกว่าแถวหลังจนจมใต้เส้นเงา (ดู docstring เต็มด้านบน)
    _buried = _dedup_buried_self(detect_buried_front_row(view, records, "FRONT"))
    if _buried:
        risks = _dedup_buried_against_existing(risks + _buried, "FRONT")

    risks = _dedup_overlapping_stepdown_risks(risks)
    risks = _dedup_stepdown_corrupted_by_adjacent_notch(risks, records, [])


# v25.92 NEW: ยกเว้นกรอบส้มที่ช่องว่างระหว่างตู้ (รองรับกรณีไฟล์รถหลายตู้ที่ไม่มีหน้า
    # Front/Back ด้วย) - ดู docstring เต็มที่ _suppress_inter_container_empty_space_risks
    if pdf_bytes is not None:
        n_containers, _veh_desc = _detect_multi_container_vehicle(pdf_bytes)
        if n_containers >= 2:
            risks = _suppress_inter_container_empty_space_risks(
                risks, view, "FRONT", n_containers)
            # v26.13: ตัดกรอบที่คร่อมช่องว่างระหว่างตู้ (ดู _clip_risks_at_container_gaps)
            risks = _clip_risks_at_container_gaps(risks, view, None, n_containers)
            # v26.16: ดู _suppress_container_entry_column_stepdown
            risks = _suppress_container_entry_column_stepdown(risks, view, None, n_containers)
            # v26.17: ดู _suppress_column_spanning_two_containers
            risks = _suppress_column_spanning_two_containers(risks, view, None, n_containers)

    print(f"[SINGLE_VIEW] n_stacks={view.get('n_stacks')} risks={len(risks)}")
    return {
        "front": view, "back": None,
        "records_front": records, "records_back": [],
        "risks": risks,
    }


def risk_abs_box(risk, result):
    """แปลง mark_x_range (พิกัด local) เป็นพิกัดภาพเต็มหน้า (absolute) สำหรับวาด marker"""
    view_label = risk.get("mark_view") or risk.get("view")
    v = result["front"] if view_label == "FRONT" else result["back"]
    x0, x1 = risk["mark_x_range"]
    stack = v["stack_heights"][risk["mark_stack_idx"]]
    height_px = stack["height_px"]
    xm = (x0 + x1) // 2
    lfy = v["local_floor_y"]
    floor_y_local = lfy[xm] if xm < len(lfy) and lfy[xm] >= 0 else None
    if floor_y_local is None or height_px is None:
        return None
    top_y_local = floor_y_local - height_px
    ox, oy = v["crop_origin_x"], v["crop_origin_y"]
    return (ox + x0, oy + top_y_local, ox + x1, oy + floor_y_local)


