# ============================================================================
#  v29.5 - ROTATION-AWARE PAGE-2 PAIR  (แก้เคส Front บน / Back ล่าง)
# ----------------------------------------------------------------------------
#  อาการ
#    ไฟล์ 2 หน้าแบบ KB03-02 ที่หน้า 2 วาง Front ไว้ด้านบน Back ไว้ด้านล่าง
#    v29.4 ไม่ทับ front ที่ลงสีแล้ว และไม่ลงสี back ให้เลย
#
#  สาเหตุ 2 ชั้น
#    1. v29.4 ตั้ง PAGE2_MODE = "never" ไว้ จึงข้ามหน้า 2 ทั้งหน้าตั้งแต่ต้น
#       เหตุผลเดิมคือคอลัมน์ซ้ายของ back view วาดมาไม่มีเส้นขอบ  แต่ตรวจซ้ำ
#       แล้วพบว่าส่วนที่เหลือของภาพลงสีได้ปกติ (370 regions -> 27 กล่อง)
#       การทิ้งทั้งหน้าจึงเสียมากกว่าได้  ->  กลับไปใช้ "auto"
#    2. _is_classic_pair ของ v29.2 ตัดสินจาก bbox ดิบของ PDF ตรง ๆ
#       แต่หน้าเหล่านี้ตั้ง /Rotate 90 ไว้  (mediabox 612x792 -> แสดงผล 792x612)
#       ในพิกัดดิบภาพทั้งคู่อยู่ "แถวเดียวกัน ซ้าย-ขวา" (y0 = 328.6 ทั้งคู่)
#       แต่บนจอที่หมุนแล้วมันคือ "บน-ล่าง"  โค้ดเดิมบังเอิญผ่านเงื่อนไขแถว
#       แต่ถ้าไฟล์ไหนไม่หมุน แล้ววางซ้อนกันบน-ล่างจริง ๆ จะตกเงื่อนไขทันที
#
#  วิธีแก้
#    ย้ายการตัดสินทั้งหมดไปทำใน "พิกัดที่ผู้ใช้เห็นจริง" โดยคูณ bbox ด้วย
#    page.rotation_matrix ก่อน แล้วเรียงตามลำดับการอ่าน (บน->ล่าง, ซ้าย->ขวา)
#    ภาพแรกในลำดับนั้นคือ Front เสมอ ภาพที่สองคือ Back  ไม่ว่าหน้าจะหมุนกี่องศา
#    และรับคู่ได้ทั้งสองผัง
#      - แบบแถว   : y ทับกันมาก, x แยกกัน   (Front ซ้าย  / Back ขวา)
#      - แบบคอลัมน์: x ทับกันมาก, y แยกกัน   (Front บน   / Back ล่าง)
#    ส่วนหน้า By Placement ยังถูกปฏิเสธเหมือนเดิม เพราะมี 6 ภาพและขนาดพิกเซล
#    เล็กกว่า wireframe หน้า 1 ครึ่งหนึ่ง
# ============================================================================

PAGE2_MODE = "auto"          # "auto" = แตะเฉพาะ wireframe pair, "never" = ไม่แตะหน้า 2

MIN_IMG_W, MIN_IMG_H = 350, 200
PAIR_DIM_TOL = 0.02          # ขนาดพิกเซลต้องเท่ากับภาพหน้า 1 (+-2%)
PAIR_OVERLAP_MIN = 0.55      # สัดส่วนการทับกันในแกนที่ใช้จัดเรียง


def _disp_rect(page, bbox):
    """bbox ของภาพในพิกัดที่แสดงผลจริง (รวมผลของ /Rotate)."""
    return fitz.Rect(bbox) * page.rotation_matrix


def _large_images(page):
    """ภาพใหญ่บนหน้า เรียงตามลำดับการอ่านบนจอ: บน->ล่าง แล้วซ้าย->ขวา."""
    infos = []
    for i in page.get_image_info(xrefs=True):
        if i.get("width", 0) <= MIN_IMG_W or i.get("height", 0) <= MIN_IMG_H:
            continue
        r = _disp_rect(page, i["bbox"])
        i["disp"] = (r.x0, r.y0, r.x1, r.y1)
        infos.append(i)
    infos.sort(key=lambda i: (round(i["disp"][1], 1), round(i["disp"][0], 1)))
    return infos


def _page1_wireframe(doc, page):
    """xref + BGR ของภาพ front view บนหน้า 1 (เลือกภาพที่ใหญ่ที่สุด)."""
    best = None
    for info in page.get_images(full=True):
        xref = info[0]
        try:
            raw = doc.extract_image(xref)
        except Exception:
            continue
        img = cv2.cvtColor(np.array(Image.open(io.BytesIO(raw["image"]))),
                           cv2.COLOR_RGB2BGR)
        h, w = img.shape[:2]
        if w <= MIN_IMG_W or h <= MIN_IMG_H:
            continue
        if best is None or w * h > best[1].shape[0] * best[1].shape[1]:
            best = (xref, img)
    return best


def _overlap(a0, a1, b0, b1):
    """สัดส่วนการทับกันของสองช่วง เทียบกับช่วงที่สั้นกว่า."""
    lo, hi = max(a0, b0), min(a1, b1)
    span = min(a1 - a0, b1 - b0)
    if span <= 0:
        return 0.0
    return max(0.0, hi - lo) / span


def _is_classic_pair(imgs, ref_shape):
    """หน้า 2 เป็น front/back wireframe คู่จริงหรือไม่ (รับทั้งแถวและคอลัมน์).

    เงื่อนไขครบทุกข้อ:
      - มีภาพใหญ่ 2 ภาพพอดี              (By Placement มี 6)
      - ขนาดพิกเซลของทั้งคู่เท่ากับภาพ wireframe หน้า 1  (thumbnail เล็กกว่าครึ่ง)
      - เรียงต่อกันเป็นแถว หรือ เป็นคอลัมน์ ในพิกัดที่แสดงผลจริง
    """
    if len(imgs) != 2 or ref_shape is None:
        return False
    rh, rw = ref_shape[:2]
    for i in imgs:
        if abs(i["width"] - rw) > PAIR_DIM_TOL * rw:
            return False
        if abs(i["height"] - rh) > PAIR_DIM_TOL * rh:
            return False
    (ax0, ay0, ax1, ay1), (bx0, by0, bx1, by1) = imgs[0]["disp"], imgs[1]["disp"]
    row = (_overlap(ay0, ay1, by0, by1) >= PAIR_OVERLAP_MIN
           and _overlap(ax0, ax1, bx0, bx1) < 0.25)
    col = (_overlap(ax0, ax1, bx0, bx1) >= PAIR_OVERLAP_MIN
           and _overlap(ay0, ay1, by0, by1) < 0.25)
    return row or col


def _pair_layout(imgs):
    (ax0, ay0, ax1, ay1), (bx0, by0, bx1, by1) = imgs[0]["disp"], imgs[1]["disp"]
    if _overlap(ax0, ax1, bx0, bx1) >= PAIR_OVERLAP_MIN:
        return "Front บน / Back ล่าง"
    return "Front ซ้าย / Back ขวา"


# ============================================================================
# v26.08: WIREFRAME DETECTION + IN-MEMORY DRIVER
# ============================================================================
# เกณฑ์ตรวจจับ: วัด "สัดส่วนพิกเซลสีสด" (vivid_cargo_mask ที่กรองลูกศรออกแล้ว - ตัวเดียว
# กับที่ pipeline วิเคราะห์ใช้จริง) ของหน้าแรกๆ ของ PDF
#   ไฟล์ปกติที่ลงสีมาแล้ว : ไดอะแกรมมีพื้นที่สีสดเป็นสัดส่วนสูง (หลาย % ของหน้า)
#   ไฟล์ wireframe        : เส้นดำบนพื้นขาวล้วน แทบไม่มีพิกเซลสีสดเลย (~0%)
# เลือกเกณฑ์ 0.2% เพราะเป็นค่าที่ห่างจากทั้ง 2 ฝั่งมาก (wireframe ~0% / ไฟล์สีหลาย %)
# หมายเหตุ: ใช้ vivid_cargo_mask ตัวเดียวกับ pipeline จริง จึงเป็นการวัด "สิ่งที่ระบบ
# วิเคราะห์มองเห็นได้จริง" โดยตรง ไม่ใช่การอนุมานทางอ้อม - ถ้าระบบมองไม่เห็นสีสดเลย
# ก็แปลว่าวิเคราะห์ไม่ได้จริง ซึ่งตรงกับนิยามของปัญหาที่ผู้ใช้ระบุพอดี
_WIREFRAME_MAX_VIVID_FRAC = 0.002   # ต่ำกว่านี้ทุกหน้า = wireframe
_WIREFRAME_DETECT_SCALE = 2         # render ย่อสำหรับตรวจเท่านั้น (ประหยัด memory)
_WIREFRAME_DETECT_MAX_PAGES = 3     # ตรวจ 3 หน้าแรกพอ (ไดอะแกรมอยู่หน้า 1-2 เสมอ)
# v26.09 FIX (ผู้ใช้แจ้ง HTTP 500 จาก Cloud Run log 15-Sep-2026 - ยืนยันด้วยการจำลองจริง):
# ROOT CAUSE: เดิมใช้ min_blob_size=60 ซึ่งเล็กเกินไป ทำให้ "ลูกศรกำกับ/เส้นบอกระยะสีแดง"
# ที่มีอยู่ในไฟล์ wireframe ตามปกติ ถูกนับเป็น "สีสดของกล่องสินค้า" -> ระบบตัดสินผิดว่า
# "ไฟล์มีสีอยู่แล้ว" -> ข้ามการลงสีทั้งหมด -> pipeline เจอไฟล์ไร้สี -> ValueError -> HTTP 500
# ยืนยันด้วยการจำลองจริง (เพิ่มลูกศรแดงทีละขั้น วัดค่าที่ระบบเห็น):
#   ลูกศร 0 เส้น -> 0.0000%  (ต่ำกว่าเกณฑ์ 0.2% -> ลงสีถูกต้อง)
#   ลูกศร 3 เส้น -> 0.1574%  (ยังผ่าน)
#   ลูกศร 8 เส้น -> 0.4339%  <-- เกินเกณฑ์แล้ว -> ไม่ลงสี -> HTTP 500
#   ลูกศร 25 เส้น -> 1.3486%
# ไฟล์จริงของผู้ใช้มี 44 SKU -> เส้นบอกระยะ/ลูกศรจำนวนมาก -> เกินเกณฑ์ตั้งแต่ต้น
# ยืนยันซ้ำด้วยเวลาใน log: execution 2,087 ms (การลงสีจริงใช้ 18+ วินาที) = ไม่เคยลงสีเลย
#
# FIX: แยก "สีสดของกล่องสินค้าจริง" ออกจาก "ลูกศร/เส้นบอกระยะ" ด้วยขนาดของ blob -
# หน้ากล่องสินค้าในไดอะแกรมเป็นพื้นที่ทึบขนาดใหญ่ (หลายพันพิกเซล) ส่วนลูกศร/เส้นเป็นเส้นบาง
# (blob เล็กมาก) การยกเกณฑ์ขนาด blob ขั้นต่ำจึงกรองลูกศรออกได้โดยไม่กระทบกล่องจริงเลย
# ทั้งยังสอดคล้องกับหลักการเดิมของระบบ (vivid_cargo_mask มี min_blob_size เป็นพารามิเตอร์
# อยู่แล้วเพื่อกรอง noise - เพียงแต่ค่าที่ใช้ตอนตรวจ wireframe ต่ำเกินไป)
_WIREFRAME_DETECT_MIN_BLOB = 3000   # ที่ scale 2: กล่องสินค้าจริง >> 3000px | ลูกศร/เส้น << 3000px


def _detect_wireframe_pdf(pdf_bytes, max_pages=_WIREFRAME_DETECT_MAX_PAGES):
    """v26.08: True ถ้า PDF นี้เป็นแบบ wireframe (ไม่มีสีสดให้ระบบวิเคราะห์จับได้เลย)
    คืนค่า (is_wireframe: bool, max_vivid_fraction: float)
    ดู docstring เต็มด้านบนสำหรับเหตุผลการเลือกเกณฑ์"""
    doc = None
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        n_check = min(len(doc), max_pages)
        best = 0.0
        for idx in range(n_check):
            try:
                mat = fitz.Matrix(_WIREFRAME_DETECT_SCALE, _WIREFRAME_DETECT_SCALE)
                pix = doc[idx].get_pixmap(matrix=mat)
                img = np.frombuffer(pix.samples, dtype=np.uint8).reshape(
                    pix.height, pix.width, pix.n)
                if pix.n == 4:
                    img = img[:, :, :3]
                img = np.ascontiguousarray(img)
                cargo = (vivid_cargo_mask(img, min_blob_size=_WIREFRAME_DETECT_MIN_BLOB)
                         & (~arrow_mask(img)))
                frac = float(cargo.mean())
                best = max(best, frac)
                del img, cargo, pix
            except Exception as e:
                print(f"[WIREFRAME_DETECT] หน้า {idx} ตรวจไม่สำเร็จ: {e}")
        is_wf = best < _WIREFRAME_MAX_VIVID_FRAC
        print(f"[WIREFRAME_DETECT] สัดส่วนพิกเซลสีสดสูงสุด {best:.4%} "
              f"(เกณฑ์ {_WIREFRAME_MAX_VIVID_FRAC:.1%}) -> "
              f"{'เป็น wireframe (ต้องลงสีก่อน)' if is_wf else 'ไฟล์มีสีอยู่แล้ว (วิเคราะห์ได้เลย)'}")
        return is_wf, best
    except Exception as e:
        print(f"[WIREFRAME_DETECT] ตรวจไม่สำเร็จ ({e}) -> ถือว่าไม่ใช่ wireframe (fail-safe)")
        return False, -1.0
    finally:
        if doc is not None:
            try:
                doc.close()
            except Exception:
                pass


def colorize_wireframe_pdf_bytes(pdf_bytes):
    """v26.08 NEW: ลงสี PDF wireframe แบบทำงานในหน่วยความจำล้วน (ไม่แตะไฟล์บนดิสก์)
    พอร์ตจาก process_pdf() ของต้นฉบับ Colab - ตรรกะเหมือนกันทุกประการ ต่างแค่
    อ่าน/เขียนผ่าน bytes แทน path และตัดส่วนแสดงผล matplotlib ออก
    คืนค่า (pdf_bytes_ใหม่ หรือ None ถ้าทำไม่ได้, info: dict)"""
    if not _CV2_AVAILABLE:
        return None, {"ok": False, "reason": "ไม่มี opencv ติดตั้งอยู่"}
    doc = None
    info = {"ok": False, "views": [], "page2": None}
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        if len(doc) == 0:
            info["reason"] = "PDF ว่างเปล่า"
            return None, info

        # ---- หน้า 1 : front view (บังคับทำเสมอ) ----
        hit = _page1_wireframe(doc, doc[0])
        if hit is None:
            info["reason"] = "ไม่พบภาพ wireframe บนหน้า 1"
            return None, info
        xref, img = hit
        front_shape = img.shape
        out, tr = colorize_v2912(img, "front", trace=True)
        _, enc = cv2.imencode(".jpg", out, [int(cv2.IMWRITE_JPEG_QUALITY), 92])
        front_bytes = enc.tobytes()
        doc[0].replace_image(xref, stream=front_bytes)
        info["views"].append({"view": "front", "regions": tr["regions"],
                              "boxes": tr["final_boxes"]})
        del out, img

        # ---- หน้า 2 : แตะเฉพาะเมื่อเป็น wireframe pair ของจริง ----
        if len(doc) > 1 and PAGE2_MODE != "never":
            page = doc[1]
            imgs = _large_images(page)
            if _is_classic_pair(imgs, front_shape):
                page.replace_image(imgs[0]["xref"], stream=front_bytes)
                raw = doc.extract_image(imgs[1]["xref"])
                img2 = cv2.cvtColor(
                    np.array(Image.open(io.BytesIO(raw["image"]))), cv2.COLOR_RGB2BGR)
                out2, tr2 = colorize_v2912(img2, "back", trace=True)
                _, enc2 = cv2.imencode(".jpg", out2, [int(cv2.IMWRITE_JPEG_QUALITY), 92])
                page.replace_image(imgs[1]["xref"], stream=enc2.tobytes())
                info["views"].append({"view": "back", "regions": tr2["regions"],
                                      "boxes": tr2["final_boxes"]})
                info["page2"] = _pair_layout(imgs)
                del out2, img2
            elif imgs:
                info["page2"] = f"ข้ามหน้า 2 (พบ {len(imgs)} ภาพ ไม่ใช่ wireframe pair)"

        new_bytes = doc.tobytes(garbage=4, deflate=True, clean=True)
        info["ok"] = True
        for v in info["views"]:
            print(f"[COLORIZER] {v['view']:5s} regions={v['regions']:4d} "
                  f"-> boxes={v['boxes']}")
        if info["page2"]:
            print(f"[COLORIZER] หน้า 2: {info['page2']}")
        return new_bytes, info
    except Exception as e:
        print(f"[COLORIZER] ลงสีล้มเหลว: {e}")
        info["reason"] = str(e)
        return None, info
    finally:
        if doc is not None:
            try:
                doc.close()
            except Exception:
                pass
        gc.collect()


def prepare_pdf_for_analysis(pdf_bytes):
    """v26.08 NEW: ด่านหน้าของ pipeline - ตรวจว่าเป็น wireframe ไหม ถ้าใช่ให้ลงสีก่อน
    คืนค่า (pdf_bytes ที่พร้อมวิเคราะห์, info: dict)
    ออกแบบให้ "ไม่มีทางทำให้ระบบล้มเหลว" - ถ้าตรวจไม่ได้/ลงสีไม่สำเร็จ จะคืน bytes เดิม
    เสมอ แล้วปล่อยให้ pipeline เดิมทำงานตามปกติทุกประการ"""
    info = {"wireframe_detected": False, "colorized": False,
            "vivid_fraction": None, "colorizer_version": None, "note": ""}
    try:
        is_wf, frac = _detect_wireframe_pdf(pdf_bytes)
        info["vivid_fraction"] = round(frac, 6) if frac >= 0 else None
        if not is_wf:
            return pdf_bytes, info
        info["wireframe_detected"] = True
        if not _CV2_AVAILABLE:
            info["note"] = "พบไฟล์ wireframe แต่ไม่มี opencv ติดตั้ง จึงลงสีไม่ได้"
            print(f"[COLORIZER] {info['note']}")
            return pdf_bytes, info
        new_bytes, cinfo = colorize_wireframe_pdf_bytes(pdf_bytes)
        if new_bytes is None:
            info["note"] = f"ลงสีไม่สำเร็จ ({cinfo.get('reason', '')}) - ใช้ไฟล์เดิม"
            print(f"[COLORIZER] {info['note']}")
            return pdf_bytes, info
        info["colorized"] = True
        info["colorizer_version"] = COLORIZER_VERSION
        info["views"] = cinfo.get("views", [])
        info["note"] = "ลงสีสำเร็จ - ส่งเข้ากระบวนการวิเคราะห์ตามปกติ"
        print(f"[COLORIZER] {info['note']} ({len(pdf_bytes)} -> {len(new_bytes)} bytes)")
        return new_bytes, info
    except Exception as e:
        info["note"] = f"ด่านเตรียมไฟล์ล้มเหลว ({e}) - ใช้ไฟล์เดิม"
        print(f"[COLORIZER] {info['note']}")
        return pdf_bytes, info


# ============================================================================
# Main HTTP handler (Cloud Function entry point) - คง output contract เดิมของ v24.36
# ============================================================================

def _run_analysis_pipeline(pdf_bytes):
    """v26.10 NEW: รวมขั้นตอน "เลือกหน้า -> render -> วิเคราะห์" ไว้ที่เดียว เพื่อให้เรียกซ้ำได้
    (ครั้งที่ 1 = ไฟล์ดั้งเดิม, ครั้งที่ 2 = ไฟล์ที่ลงสีแล้ว) - ดู docstring ที่ process_request
    สำหรับเหตุผลของการเปลี่ยนสถาปัตยกรรมเป็น "ลองก่อน-ซ่อมทีหลัง" (try-then-fix)
    คืนค่า (result, meta) หรือโยน NoCargoDiagramError ถ้าไฟล์นี้วิเคราะห์ไม่ได้"""
    target = _resolve_diagram_target(pdf_bytes)
    analysis_mode = target["mode"]
    diagram_page_idx = target["page_idx"]
    print(f"Using diagram_page_idx={diagram_page_idx} mode={analysis_mode} "
          f"({target['reason']})")

    full_img, doc, page = render_full_page(pdf_bytes, page_idx=diagram_page_idx, matrix_scale=3)

    if analysis_mode == "dual_view":
        ok_cargo, cargo_reason = _dual_view_regions_have_cargo(full_img, doc, diagram_page_idx)
        if not ok_cargo:
            print(f"[PAGE_VALIDATE] page[{diagram_page_idx}] ผ่าน text-layer แต่ไม่ผ่าน "
                  f"pixel-check: {cargo_reason} -> เปลี่ยนไปใช้หน้าที่ 1 เท่านั้น")
            analysis_mode = "single_view_page1"
            diagram_page_idx = _SINGLE_VIEW_PAGE_IDX
            target["layout"] = "SINGLE_VIEW_PAGE1"
            target["reason"] = f"pixel-check ไม่ผ่าน ({cargo_reason})"
            try:
                doc.close()
            except Exception:
                pass
            full_img, doc, page = render_full_page(
                pdf_bytes, page_idx=diagram_page_idx, matrix_scale=3)

    if analysis_mode == "dual_view":
        front_bb = _word_bbox_rotated(page, "Front")
        back_bb = _word_bbox_rotated(page, "Back")
        if front_bb and back_bb:
            fx0, fy0, fx1, fy1 = front_bb
            bx0, by0, bx1, by1 = back_bb
            f_cx, f_cy = (fx0 + fx1) / 2, (fy0 + fy1) / 2
            b_cx, b_cy = (bx0 + bx1) / 2, (by0 + by1) / 2
            layout = "LEFT_RIGHT" if abs(f_cx - b_cx) > abs(f_cy - b_cy) else "TOP_BOTTOM"
        else:
            layout = "TOP_BOTTOM"
    else:
        layout = "SINGLE_VIEW_PAGE1"

    if analysis_mode == "dual_view":
        result = run_full_analysis_on_image(
            full_img, doc, page_idx=diagram_page_idx, pdf_bytes=pdf_bytes, matrix_scale=3)
    else:
        result = run_single_view_analysis_on_image(
            full_img, doc, page_idx=diagram_page_idx, matrix_scale=3, pdf_bytes=pdf_bytes)

    return result, {
        "full_img": full_img, "doc": doc, "layout": layout,
        "analysis_mode": analysis_mode, "page_idx": diagram_page_idx,
        "reason": target.get("reason", ""),
    }


@functions_framework.http
def process_request(request):
    if request.method == "OPTIONS":
        headers = {
            "Access-Control-Allow-Origin": "*",
            "Access-Control-Allow-Methods": "POST",
            "Access-Control-Allow-Headers": "Content-Type, x-goog-api-key",
            "Access-Control-Max-Age": "3600",
        }
        return ("", 204, headers)
    headers = {"Access-Control-Allow-Origin": "*"}
    try:
        data = request.get_json(silent=True)
        if data is None:
            raw_data = request.get_data(as_text=True)
            data = json.loads(raw_data) if raw_data else {}
        if not data or "base64" not in data:
            print("DEBUG - RECEIVED DATA:", request.get_data(as_text=True)[:500])
            return ({"error": "No base64 data provided"}, 400, headers)
        base64_str = data.get("base64")
        if "," in base64_str:
            base64_str = base64_str.split(",", 1)[1]
        pdf_bytes = base64.b64decode(base64_str)

        # v26.08 NEW: ด่านหน้าสุดของ pipeline - ถ้าเป็นไฟล์ wireframe (ไม่มีสีสดเลย)
        # ให้ลงสีก่อน แล้วส่ง PDF ที่ลงสีแล้วเข้ากระบวนการเดิมทั้งหมด
        # (ดู COLORIZER SECTION ด้านบนสำหรับหลักฐาน+เหตุผล - ผู้ใช้สั่งโดยตรง)
        # ออกแบบให้ fail-safe: ไฟล์ปกติจะผ่านด่านนี้ไปโดยไม่ถูกแตะเลยแม้แต่ byte เดียว
        # v26.10 FIX (ผู้ใช้แจ้ง HTTP 500 จาก Cloud Run log 15-Sep-2026 พร้อมไฟล์จริง 44 SKU):
        # ROOT CAUSE ที่ยืนยันด้วยการจำลองจริง: v26.08/09 ใช้สถาปัตยกรรม "ตรวจก่อนลงสี"
        # (detect-then-fix) โดยวัด "สัดส่วนพิกเซลสีสด" เทียบ threshold - แต่ไฟล์ wireframe จริง
        # มี "ลูกศรกำกับ/เส้นบอกระยะสีแดง" ปนอยู่ตามปกติ ทำให้วัดได้เกิน threshold -> ระบบตัดสิน
        # ผิดว่า "ไฟล์มีสีอยู่แล้ว" -> ข้ามการลงสี -> pipeline เจอไฟล์ไร้สี -> HTTP 500
        # ยืนยันด้วยการจำลอง (เพิ่มลูกศรแดงทีละขั้น): 0 เส้น=0.0000% | 3 เส้น=0.1574% |
        # 8 เส้น=0.4339% (เกินเกณฑ์ 0.2% แล้ว) | 25 เส้น=1.3486% | 40 เส้น=1.8656%
        # ยืนยันซ้ำด้วยเวลาใน log ของผู้ใช้: execution 2,087 ms (การลงสีจริงใช้ 18+ วินาที)
        # = ไม่เคยเรียกโมดูลลงสีเลยแม้แต่ครั้งเดียว
        # ทดลองแก้ด้วยการยกเกณฑ์ขนาด blob (v26.09) แล้วพบว่า "แยกไม่ขาด" เพราะลูกศร/เส้นบอกระยะ
        # ที่ต่อเนื่องกันรวมเป็น blob ใหญ่ได้ (วัดจริง: ลูกศร 40 เส้น -> blob ใหญ่สุด 20,749px
        # เทียบกับไฟล์ที่ลงสีแล้ว blob ใหญ่สุดเพียง 8,191px - คาบเกี่ยวกันจนใช้แยกไม่ได้)
        #
        # FIX (เปลี่ยนสถาปัตยกรรม ไม่ใช่ปรับ threshold): "ลองก่อน-ซ่อมทีหลัง" (try-then-fix)
        #   1. ลองวิเคราะห์ไฟล์ดั้งเดิมก่อนเสมอ
        #   2. ถ้าสำเร็จ -> จบ (ไฟล์ปกติไม่ถูกแตะเลยแม้แต่ byte เดียว เหมือนเดิมทุกประการ)
        #   3. ถ้าล้มเหลวเพราะ "ไม่พบไดอะแกรมสินค้า" -> ลงสีแล้ววิเคราะห์ใหม่อีกครั้ง
        # ข้อดีที่ชี้ขาด: ไม่ต้องพึ่ง threshold ใดๆ เลย - ใช้ "ผลลัพธ์จริงของการวิเคราะห์"
        # เป็นตัวตัดสินแทนการเดาล่วงหน้าจากสีในภาพ จึงไม่มีทางตัดสินผิดได้อีกต่อไป
        # (ไฟล์ที่วิเคราะห์ได้อยู่แล้ว = ไม่ต้องลงสี | ไฟล์ที่วิเคราะห์ไม่ได้ = ต้องลงสีเสมอ
        #  ซึ่งตรงกับนิยามของปัญหาที่ผู้ใช้ระบุไว้ตั้งแต่ต้นพอดี)
        prep_info = {"wireframe_detected": False, "colorized": False,
                     "colorizer_version": None, "note": ""}
        _original_pdf = pdf_bytes
        try:
            result, meta = _run_analysis_pipeline(pdf_bytes)
        except NoCargoDiagramError as _first_err:
            print(f"[RETRY] วิเคราะห์ไฟล์ดั้งเดิมไม่สำเร็จ ({_first_err}) "
                  f"-> ลองลงสีแล้ววิเคราะห์ใหม่")
            prep_info["wireframe_detected"] = True
            if not _CV2_AVAILABLE:
                prep_info["note"] = "ต้องลงสีแต่ไม่มี opencv ติดตั้ง"
                raise
            _colored, _cinfo = colorize_wireframe_pdf_bytes(pdf_bytes)
            if _colored is None:
                prep_info["note"] = f"ลงสีไม่สำเร็จ ({_cinfo.get('reason', '')})"
                print(f"[RETRY] {prep_info['note']}")
                raise
            pdf_bytes = _colored
            prep_info["colorized"] = True
            prep_info["colorizer_version"] = COLORIZER_VERSION
            prep_info["views"] = _cinfo.get("views", [])
            prep_info["note"] = "ลงสีสำเร็จแล้ววิเคราะห์ใหม่"
            print(f"[RETRY] ลงสีสำเร็จ ({len(_original_pdf)} -> {len(pdf_bytes)} bytes) "
                  f"-> วิเคราะห์ใหม่")
            result, meta = _run_analysis_pipeline(pdf_bytes)
        full_img = meta["full_img"]
        doc = meta["doc"]
        layout = meta["layout"]
        analysis_mode = meta["analysis_mode"]
        diagram_page_idx = meta["page_idx"]
        target = {"reason": meta["reason"]}

        sku_list = extract_sku_from_pdf(pdf_bytes, page_idx=None)
        sku_str = ", ".join(sku_list) if sku_list else ""

        risks = result["risks"]

        img = PIL.Image.fromarray(full_img).convert("RGB")
        draw = PIL.ImageDraw.Draw(img)

        # v25.29 FIX (ตามที่ผู้ใช้ระบุ - ตรวจพบว่าเคยถูกลบทิ้งไปโดยไม่ตั้งใจตอนพัฒนาต่อจาก
        # v25.28 เป็น v25.30-36 เพราะใช้ v25.28 เป็นฐานแทนที่จะเป็น v25.29 - กู้คืน fix นี้กลับมา
        # ในรอบนี้): เดิม detected_hazards เก็บ 1 รายการต่อ (risk_type, view, idx) ที่ไม่ซ้ำกัน
        # แล้วพิมพ์ "คำแนะนำวิธีแก้ไข" (generate_action_report) เต็มทุกรายการ - ถ้าพบความเสี่ยง
        # ประเภทเดียวกันหลายจุด (เช่น STEP_DOWN_RISK 3 จุด) รายงานจะพิมพ์คำแนะนำชุดเดิมซ้ำกัน 3
        # รอบ ทำให้ยาวเกินความจำเป็นในการอ่าน (คำแนะนำแก้ไขของแต่ละ risk_type เป็นข้อความคงที่
        # ไม่ได้ขึ้นกับตำแหน่ง/จุดที่พบเลย)
        # FIX: จัดกลุ่มตาม "ประเภทความเสี่ยง" (risk_type) เท่านั้น - พิมพ์หัวข้อ + คำแนะนำ
        # เพียง "ครั้งเดียวต่อประเภท" แล้วต่อท้ายหัวข้อด้วย "จำนวนจุดที่นับได้" ของประเภทนั้น
        # แทนการพิมพ์ซ้ำตามจำนวนจุด - ยังคงวาดกรอบ (marker) บนภาพครบทุกจุดที่ตรวจพบเหมือนเดิม
        # ทุกประการ (ไม่กระทบการแสดงผลภาพ) และยังคงนับ hazardCount = จำนวนจุดทั้งหมดจริง (ไม่ใช่
        # จำนวนประเภท) เพื่อไม่ให้กระทบ WebApp/GAS ฝั่งรับผลที่อาจอ้างอิงค่านี้อยู่แล้ว
        all_hazard_points = []
        risk_type_counts = {}
        risk_type_order = []  # รักษาลำดับการพบครั้งแรกของแต่ละประเภท
         
        for risk in risks:
            risk_type = risk["risk_type"]
            # v25.57 FIX: เดิม print แสดง height_source=None เสมอ (ทุกไฟล์ ทุก subtype) เพราะ
            # key 'height_source'/'gap_px'/'gap_ratio' ไม่เคยถูกใส่ไว้ใน risk dict จริงเลย -
            # ทำให้ debug log ที่ผ่านมาไม่สามารถยืนยันได้ว่า guard ต่างๆ (STEP_DOWN_MIN_RELIABLE_
            # SAMPLES, STEP_DOWN_MAX_CORRECTION_CONFLICT_RATIO ฯลฯ) ทำงานถูกต้องหรือไม่ และไม่เห็น
            # ขนาด gap จริงของ REAR_EMPTY_RISK เลย (พบระหว่างวิเคราะห์ log EA07-01/EB66-01
            # 29-Aug-2026) - ตอนนี้ทุก risk dict ใส่ height_source/n_samples ไว้จริงแล้ว (ดู
            # detect_step_down_pairwise/crossview/tail_stepdown) และเพิ่ม gap_px/gap_ratio ที่
            # REAR_EMPTY_RISK เก็บไว้อยู่แล้วแต่ไม่เคยถูก print ออกมา
            print(f"[RISK] {risk['risk_type']}/{risk.get('subtype')} view={risk.get('mark_view')} "
                  f"idx={risk.get('mark_stack_idx')} pos={risk.get('pos_range')} "
                  f"drop_ratio={risk.get('drop_ratio')} gap_px={risk.get('gap_px')} "
                  f"gap_ratio={risk.get('gap_ratio')} height_source={risk.get('height_source')} "
                  f"n_samples={risk.get('n_samples')} pair_indices={risk.get('pair_indices')}")
            outline_color = RISK_COLORS.get(risk_type, "red")
            # v25.23 FIX: risk บาง subtype (hidden_behind) คำนวณ abs_box ไว้ตรงจุดตรวจจับเลย
            # (ไม่ได้ผูกกับ stack_heights index ปกติ) ใช้ค่านี้ก่อนถ้ามี ไม่งั้น fallback ไป
            # risk_abs_box เดิม
            box = risk.get("abs_box") or risk_abs_box(risk, result)
            if box:
                _draw_single_rectangle(draw, box, outline_color)
            else:
                print(f"Could not compute marker box for {risk_type} (view={risk.get('mark_view')}, "
                      f"idx={risk.get('mark_stack_idx')})")

            all_hazard_points.append(risk)
            if risk_type not in risk_type_counts:
                risk_type_counts[risk_type] = 0
                risk_type_order.append(risk_type)
            risk_type_counts[risk_type] += 1

        if all_hazard_points:
            status_text = f"พบจุดเสี่ยงอันตราย ({len(all_hazard_points)} จุด)"
            sep = "\n\n" + "-" * 50 + "\n\n"
            blocks = []
            for risk_type in risk_type_order:
                count = risk_type_counts[risk_type]
                title = f"ความเสี่ยง: {risk_type} (พบ {count} จุด)"
                detail = generate_action_report(risk_type, "", sku_str)
                blocks.append(f"[{title}]\n{detail}")
            action_text = sep.join(blocks)
        else:
            status_text = "ปลอดภัย (SAFE)"
            action_text = generate_action_report("SAFE", "")

        buffered = io.BytesIO()
        img.save(buffered, format="JPEG", quality=80)
        processed_image_url = f"data:image/jpeg;base64,{base64.b64encode(buffered.getvalue()).decode('utf-8')}"
        gc.collect()
        return ({
            "status": status_text,
            "hazardCount": len(all_hazard_points),
            "layout": layout,
            "actionRequired": action_text,
            "processedImageUrl": processed_image_url,
            "checkerVersion": "V26.21",
            "benchmarkMode": "v26_21_unbroken_isometric_roofline_guard",
            # v25.91 NEW (additive - ไม่กระทบ key เดิมใดๆ ที่ WebApp/GAS ใช้อยู่):
            # บอกโหมดที่ใช้วิเคราะห์จริง เพื่อให้ตรวจสอบย้อนหลังได้ว่าไฟล์ไหนถูกวิเคราะห์ด้วย
            # หน้าที่ 1 หน้าเดียว (และเพราะเหตุใด)
            "analysisMode": analysis_mode,
            "analysisPageIndex": diagram_page_idx,
            "analysisPageReason": target.get("reason", ""),
            # v26.08 NEW (additive - ไม่กระทบ key เดิมที่ WebApp/GAS ใช้อยู่):
            # บอกว่าไฟล์นี้ถูกตรวจพบว่าเป็น wireframe และถูกลงสีก่อนวิเคราะห์หรือไม่
            "wireframeDetected": prep_info.get("wireframe_detected", False),
            "wireframeColorized": prep_info.get("colorized", False),
            "colorizerVersion": prep_info.get("colorizer_version"),
            "colorizerNote": prep_info.get("note", ""),
        }, 200, headers)
    except NoCargoDiagramError as e:
        # v26.09: ไฟล์นี้วิเคราะห์ไม่ได้ (ไม่ใช่บั๊กของโปรแกรม) - คืน HTTP 200 พร้อมคำอธิบาย
        # แทนการ crash เป็น HTTP 500 (ดู docstring เต็มที่ class NoCargoDiagramError)
        print(f"[NO_CARGO] {e}")
        gc.collect()
        return ({
            "status": "วิเคราะห์ไม่ได้ (ไม่พบไดอะแกรมสินค้าที่มีสี)",
            "hazardCount": 0,
            "layout": "UNKNOWN",
            "actionRequired": (
                "ไม่สามารถวิเคราะห์ไฟล์นี้ได้\n"
                f"สาเหตุ: {e}\n\n"
                "แนวทางแก้ไข:\n"
                "  • ถ้าเป็นไฟล์ wireframe (ภาพเส้นขาว-ดำ) ระบบจะลงสีให้อัตโนมัติ - "
                "กรณีนี้อาจลงสีไม่สำเร็จ โปรดตรวจสอบ log ที่ขึ้นต้นด้วย [COLORIZER]\n"
                "  • ตรวจสอบว่าไฟล์มีไดอะแกรมการจัดวางสินค้าอยู่จริง"
            ),
            "processedImageUrl": "",
            "checkerVersion": "V26.21",
            "benchmarkMode": "v26_21_unbroken_isometric_roofline_guard",
            "analysisMode": "failed_no_cargo",
            "analysisPageIndex": -1,
            "analysisPageReason": str(e),
            "wireframeDetected": prep_info.get("wireframe_detected", False) if "prep_info" in dir() else False,
            "wireframeColorized": prep_info.get("colorized", False) if "prep_info" in dir() else False,
            "colorizerVersion": prep_info.get("colorizer_version") if "prep_info" in dir() else None,
            "colorizerNote": prep_info.get("note", "") if "prep_info" in dir() else "",
        }, 200, headers)
    except Exception as e:
        err_trace = traceback.format_exc()
        print("CRITICAL ERROR DETAILS:\n", err_trace)
        gc.collect()
        return ({"error": str(e), "trace": err_trace[-500:]}, 500, headers)

